(window.GioKinhBooks=window.GioKinhBooks||{})["luong-hoang-sam"]={"id":"luong-hoang-sam","title":"Lương Hoàng Sám","by":"Từ Bi Đạo Tràng Sám Pháp · Việt dịch: HT Thích Viên Giác","src":"https://www.daotranglienhoa.com/wp-content/uploads/2025/01/luong_hoang_sam.pdf","srcName":"Đạo Tràng Liên Hoa","chapters":[{"t":"Lời Giới Thiệu","b":[["p","Phàm là người sanh trong cõi Dục này, trừ các bậc đã hoàn toàn giác ngộ, thì không một ai tránh khỏi lỗi lầm, bởi ba nghiệp gây nên."],["p","Các tội lỗi đã từ ba nghiệp phát sanh, nên người muốn dứt trừ hết tội lỗi, tất nhiên phải đem ba nghiệp ấy để sám hối, thì tội lỗi mới được thanh tịnh."],["p","Phật dạy: “Nếu không có phương pháp sám hối thì tất cả các Phật tử không một ai mà được giải thoát”."],["p","Cũng như, nếu không nhờ bộ Lương Hoàng Sám này thì bà Hy Thị là Hoàng hậu của vua Lương không làm sao thoát khỏi khổ nạn được."],["p","Vì thế nên bộ Lương Hoàng Sám này có một hiệu lực mạnh mẽ, làm cho người có tội lỗi được tiêu trừ, phước lành tăng trưởng."],["p","Cảm thấy sự phiên dịch của Đại đức Thích Viên Giác rất dày công phu, nên tôi xin có vài lời giới thiệu đến toàn thể các Phật tử xa gần. Và hy vọng rằng bộ Lương Hoàng Sám này được phổ biến mười phương và sẽ đem lại sự lợi lạc chung cho tất cả; nếu ai có tín tâm thật hành theo."],["v",["Cẩn chí","HT. THÍCH THIỆN HÒA"]]]},{"t":"Lời Tựa Tái Bản","b":[["p","Phật dạy: “Trong tất cả các cách cúng dường, cúng dường Chánh Pháp là hơn hết” (Kinh Hoa Nghiêm)."],["p","Vậy thì tái bản bộ Lương Hoàng Sám này cũng không ngoài mục đích cúng dường Chánh Pháp. Kỳ tái bản này, ngoài việc đính chính các chỗ in sai, sửa lỗi lại lời văn cho thích đáng, chúng tôi còn cho in thêm “NGHI THỨC TỤNG LƯƠNG HOÀNG SÁM” này bằng Hán văn phiên âm. Đồng thời, ở phần đầu và phần cuối mỗi quyển đều có những bài “Cung văn”, bài “Hồi hướng” v.v... tóm lược ý nghĩa trong mỗi quyển. Các bài này cũng dịch âm từ bản chữ Hán."],["p","Thỉnh thoảng, chúng tôi cũng tường thuật những điều cảm ứng do tụng Lương Hoàng Sám này."],["p","Phật dạy chúng ta nên sám cải quá hồi đầu với văn sám này để tự giải thoát tội khiên nhiều đời nhiều kiếp cho mình, cho người, cho bà con quyến thuộc mình và cho tất cả chúng sanh trong lục đạo khắp pháp giới mười phương. Nếu chúng sanh nào còn bị câu lưu trong ngục thất, cũng nhờ thần lực của Sám pháp này, được chư Phật, chư Bồ Tát, phóng đại hào quang phá tan địa ngục, tiếp dẫn các hương hồn đau khổ ấy, về đến đạo tràng này nghe Chánh pháp, hưởng thú tiêu diêu."],["p","Tụng đến các phẩm Giải oan, Xuất ngục v.v... chúng ta cảm thấy tâm hồn thanh thoát vui tươi. Bấy giờ, đối với chúng ta, Diêm vương vắng bóng, đầu trâu mặt ngựa không còn, La sát, Dạ xoa, dầu sôi lửa bỏng v.v... chỉ là duy tâm tạo, như huyễn như hóa. Có hay không đều do chúng ta cả."],["p","Nhưng nghĩ lại mà thương, trên đường đời mấy ai đã sống theo giáo lý Đức Phật, đã biết ăn năn, phần nhiều họ chỉ nghe theo bản ngã, tự kiêu tự đại, chạy theo dục vọng si mê, nên tạo ra nhiều tội lỗi oan khuất. Do đó mà trần gian này vẫn còn đau khổ mãi, địa ngục cứ hành hạ hoài không thôi. Nếu chúng ta biết ăn năn, cải ác tùng thiện, làm phước làm duyên, theo giáo lý từ bi thì đâu đến nỗi lầm than."],["p","Tóm lại, Lương Hoàng Sám là linh đơn diệu dược, Pháp bảo vô giá, cứu chúng ta thoát khổ vĩnh viễn, ra khỏi luân hồi, sanh về Tịnh độ. Trọn bộ mười quyển. Tụng hết một quyển là hướng lên một địa vị."],["p","Bồ Tát qua khỏi mười địa vị này thì thành Phật."],["p","Chúng ta tụng hết mười quyển này thì thấy tinh thần khoan khoái, tâm hồn thánh thọ, đời sống đầy an vui hạnh phúc. Người còn kẻ mất đều được lợi lạc. Oan hồn uổng tử, chiến sĩ trận vong siêu sanh Lạc quốc."],["p","Nhờ đó mà hoàng hậu Hy Thị của vua Lương Võ Đế, sau khi mới nghe tụng được năm quyển đã thoát thân rắn mãng xà, lên trời làm thiên nữ."],["p","Công đức tụng Lương Hoàng Sám vô lượng vô biên, văn từ hữu hạn không thể diễn tả hết. Chúng tôi chỉ xin ghi lại đây vài nét chính hầu mong giới thiệu cùng mười phương Phật tử có lòng ngưỡng mộ sám pháp."],["p","Chúng tôi xin thành tâm cầu nguyện và hồi hướng công đức tái bản này cho tất cả người thấy, người nghe, người đọc tụng, người tùy hỷ, đồng được nhờ ơn Tam Bảo gia hộ, tội nghiệp tiêu trừ, tai qua nạn khỏi, phước thọ tăng long, Bồ đề kiên cố."],["v",["Nam mô Cầu Sám Hối Bồ Tát Ma ha tát","Dịch giả: HT. THÍCH VIÊN GIÁC","Mùa hạ năm Bính Ngọ (1966 – PL.2510)"]]]},{"t":"Thay Lời Tựa","b":[["p","Theo lời tựa trong chánh văn thì bộ Lương Hoàng Sám này do Hòa thượng Chí Công biên tập từ đời vua Lương Võ Đế bên Trung Quốc."],["p","Nguyên vua Lương Võ Đế có một bà Hoàng hậu yêu quý nhất tên là Hy Thị. Vì được vua yêu quý nên lòng đố kỵ của bà ngày càng lên cao. Hy Thị ganh tị các cung phi, độc ác với mọi người và hủy báng Tam Bảo. Trong triều ngoài quận ai cũng biết bà Hy Thị là một “Quái phi”."],["p","Sau bà nhuốm bệnh nặng, các lương y đều thúc thủ, bà phải từ trần. Một hôm vào lúc đêm khuya, đang ngồi trong cung tịch mịch. Vua Lương Võ Đế nghe tiếng người kêu van thảm thiết.(1)"],["p","Dưới ánh đèn mờ, vua Lương Võ Đế lạnh cả người, muốn chạy trốn, nhưng không được. Vua bèn lên tiếng hỏi: “Ngươi là ai mà đêm khuya thanh vắng nghiêm mật thế này lại vào đây được?” – Hoàng đế ơi! Thiếp đây chính là Hy Thị. Vì quá độc ác nên chết rồi thiếp phải đọa làm rắn mãng xà. Ngày đêm đau khổ, thân thể tanh hôi, vi vẩy đều bị sâu trùng rúc rỉa, nhức nhối không thể chịu được. Nhớ lại tình cầm sắc xưa kia nên thiếp đến đây mong nhờ Hoàng đế tìm phương cứu thiếp. Nói rồi biến mất."],["p","Nghe xong, vua Lương Võ Đế như thoát cơn ác mộng và lòng đau như dao cắt! Ngày mai khi lâm Triều, vua kể lại chuyện ấy cho bá quan nghe để tìm phương cứu vớt Hy Thị."],["p","Trong số các quan có người đề nghị: Xin cung thỉnh Hòa thượng Chí Công lo việc này. Vua Lương Võ Đế chấp thuận. Hòa thượng Chí Công là một cao Tăng đắc đạo đương thời. Thể theo lời thỉnh cầu của nhà vua, ngài liền triệu tập các danh Tăng soạn ra Sám Pháp này và lập Đàn tràng làm lễ sám hối cho Hoàng hậu Hy Thị."],["p","Nhà vua chí tâm, thân hành lễ bái. Vài hôm đầu, người ta nghe có mùi hương lạ thơm nức, ngào ngạt khắp cả đạo tràng."],["p","Lễ tụng đến quyển thứ năm, ngay tại chỗ, trên không trung, vua Lương Võ Đế nghe có tiếng của Hy Thị. Bà hiện thân thiên nữ đẹp đẽ, nói tiếng người, tỏ lòng cám ơn Hòa thượng Hoàng đế."],["p","Hy Thị cho biết bà đã thoát nạn và đã sanh lên Đao Lợi Thiên Cung, nhờ công đức sám hối."],["p","Từ đó Sám Pháp này được truyền tụng khắp nơi, rất thịnh hành."],["p","Bản chính bằng Hán văn trọn bộ 10 quyển."],["p","Danh hiệu Phật và lời sám đều rút trong Tam Tạng Thánh giáo Đại thừa."],["p","Năm 1948 – 1950, Bồ Tát giới Tuệ Nhuận và một số đạo hữu khá đông ở Bắc Việt đã dịch âm ra Việt văn, thành 2 tập."],["p","Năm 1952, lúc còn tu học ở Phật học viện Báo Quốc – Huế, tôi bắt đầu dịch nghĩa bộ này ra tiếng Việt, đến nay mới đủ cơ duyên xuất bản."],["p","Tôi nguyện xin nhờ công đức phiên dịch này, hầu mong đền đáp lại bốn ơn muôn một và cứu giúp muôn loài phần nào."],["p","Tôi nguyện xin nhờ công đức phiên dịch này, hầu mong giúp hàng sơ cơ một phương pháp tu hành giản dị để cải ác tùng thiện, để đi Tây phương về Lạc quốc."],["p","Tôi nguyện xin nhờ công đức phiên dịch này làm cho người tu hành ngày càng tinh tiến, nghiệp chướng chóng tiêu trừ, thân tâm thường an lạc và sở cầu được như nguyện."],["p","Tôi cũng xin cầu nguyện cho tất cả người thấy, người nghe, người hủy báng, người tùy hỷ, đều được lợi lạc, thoát khổ não và nguyện xin cho tất cả chúng sanh xả ly tà kiến, biết sám hối."],["h","✵ Sám Hối Nghĩa Là Gì?"],["p","Kinh dạy:"],["p","– Sám giả sám kỳ tiền khiên. – Hối giả hối kỳ hậu quá."],["p","– Sám là ăn năn các việc ác đã làm, thề xin chừa bỏ, không dám tái phạm."],["p","– Hối là hối cải. Những điều ác chưa làm, sau này xin thề nguyện không bao giờ làm nữa. Bao nhiêu điều thiện xin làm hết."],["p","Chữ Phạn gọi là Sám ma, Hán dịch là Hối quá, ghép cả hai chữ lại mà đọc là Sám hối. Sám hối cũng có sự sám và lý sám."],["p","Sự sám tức là thiết lập đàn tràng, trang nghiêm Phật tượng, cúng dường hương hoa, ân cần đảnh lễ, thành khẩn nguyện cầu tam nghiệp như nhất, tỏ bày tội lỗi. Cầu xin chư Phật, chư đại Bồ Tát phóng hào quang, dùng thần lực, gia hộ cho kẻ tu hành mau tiêu trừ nghiệp chướng, chóng thoát oan khiên, sạch hết tội lỗi."],["v",["Lý sám là sám hối tự tâm","Tội thành do tâm tạo","Tội diệt phải do tâm sám","Tâm không thì tội cũng không","Tội diệt thì tâm cũng diệt."]],["p","Tội không, tâm diệt thì không còn gì nữa mà sám hối. Như vậy mới là chơn thật sám hối."],["p","Sau khi lạy một lạy, tụng một câu, người tu hành nên xét lại tự tâm, diệt sạch vọng tưởng, quán lý vô sanh, phải biết tội do nhân duyên mà thành, thì tội cũng do nhân duyên mà diệt. Nhân duyên là những điều kiện tạo nên tội và phương pháp sám hối."],["p","Tội vốn không thật có. Vì không thật có, nên chúng ta có thể chuyển tội thành phước, chuyển khổ thành vui, chuyển mê thành ngộ."],["p","Khi xướng một câu danh hiệu Phật, chúng ta cần phải thật hiểu nghĩa lý danh hiệu ấy. Hiểu để tu tập, để làm theo những đức tính cao đẹp của chư Phật."],["p","Ví như chúng ta xướng câu. “Nam mô Phổ Quang Phật”, thì ít ra chúng ta cũng phải hiểu sơ như thế này:"],["p","Chúng con xin kính lễ (Nam mô) đấng giác ngộ hoàn toàn (Phật) đầy đủ đức tánh cao rộng đẹp đẽ (Phổ) sáng suốt vô biên (Quang)."],["p","Ngoài ra chúng ta cũng cần tìm hiểu thêm bản tâm của chúng ta. Tâm của chúng ta cũng có những đức tính cao rộng đẹp đẽ như thế."],["p","Nam mô – Nghĩa là quy y, kính lễ v.v..."],["p","Phổ – Nghĩa là phổ cập, phổ biến, cùng khắp, không có giới hạn, ngoài thời gian và không gian, không phân biệt người và ta. Trái lại Phổ có nghĩa hàm súc những đức tính từ bi hỷ xả với tất cả mọi loài, mọi vật, mọi chốn, mọi nơi."],["p","Tâm ta cũng có những tánh chất phổ biến như thế. Từ nay ta phải sống theo tiếng gọi của cõi lòng, không tiêu cực mà tích cực, không ích kỷ mà vị tha, không sân hận mà Từ Bi, không xan tham mà bố thí, không tật đố mà hỷ xả, không ngu si mà trí huệ."],["p","Quang – Nghĩa là sáng suốt tuyệt đối, soi khắp mười phương, thông suốt ba đời mà không lìa nơi một niệm. Tội nhân và khổ quả của chúng sanh đã gây tạo và sẽ chịu đền trả, từ bao giờ, ở nơi đâu, nhất nhất đều sáng tỏ, hiểu biết hết."],["p","Tâm ta có tính cách sáng suốt như vậy, từ nay trở đi, ta phải hành động, ăn ở theo tâm tính sáng suốt ấy, không còn ngu si mê mờ mà tạo tội nữa."],["p","Phật – là đấng giác ngộ hoàn toàn, ta đang kính lễ. Phật cũng tức là tâm sáng suốt thanh tịnh, đầy đủ muôn đức tánh tốt đẹp, trùm khắp pháp giới, ra ngoài thời gian."],["p","Tâm ta cũng có những khả năng giác ngộ, những đức tánh như Phật."],["p","Vậy từ nay trở đi ta phải noi gương Phật, sống cách sáng suốt, đầy đủ đức hạnh như Phật, không tạo tội nữa."],["p","Đại khái như thế, cứ theo từng danh hiệu một mà quán sát tự tâm để sám hối."],["p","Lần lần những khả năng tốt đẹp trong tâm ta do sự sám hối sẽ lưu lộ ra, nào là từ bi hỷ xả, trí huệ, phước đức, hạnh phúc dồi dào tuôn ra như nước, mặc sức ta thọ dụng."],["p","Người hiểu được và làm được như thế là người chánh kiến, không còn bôn ba chạy theo ngoại cảnh, không tà kiến, quy y theo quỷ mị tà thần."],["p","Người chánh kiến chỉ biết quy y, lễ bái, tôn thờ đức Phật ở tự tâm, nghe tiếng nói của cõi lòng."],["p","Lễ một đức Phật tức là lễ hết thảy mười phương chư Phật. Đem tâm Từ Bi bình đẳng, sự lý viên dung, trùng trùng vô ngại mà bái sám thì lo gì tội không diệt, phước không sanh."],["p","Nếu người không thông lý, cứ y sự mà tu hành, chí tâm bái sám thì cũng được thần lực của Tam Bảo gia hộ mà tiêu trừ nghiệp chướng, như trong chánh văn đã thuật rõ."],["p","Phật dạy:"],["p","“Có hai hạng người mạnh nhất: một là không tạo tội, hai là biết ăn năn”."],["p","Phật dạy:"],["p","“Nếu không có pháp sám hối thì tất cả đệ tử Phật không thể giải thoát”."],["p","Nhờ sám hối nên vua A Xà Thế phạm tội ngũ nghịch (giết cha) liền được giải thoát."],["p","Ông Trương Thiện Hòa sát sanh vô số cũng không đọa địa ngục, vì biết hối hận."],["p","Có một điều đáng chú ý nhất là thân nghiệp và khẩu nghiệp thô tháo bên ngoài dễ trừ. Duy có ý nghiệp vi tế bên trong, rất khó diệt. Đến quả vị Phật mới hết tham, sân, si."],["p","Do đó người phát đại tâm phải y cứ vào Sám pháp Đại thừa mới mong chóng trừ diệt được ba độc. Ngài Phổ Hiền Bồ Tát là Trưởng tử của Phật trên Hội Hoa Nghiêm còn phải phát đại nguyện."],["p","Ngài nguyện sám hối mãi cho đến cùng tận đời vị lai."],["p","Nếu phiền não và nghiệp chướng của chúng sanh không cùng tận thì sự sám hối của Ngài cũng không bao giờ cùng tận."],["p","Trong Kinh Viên Giác, Phật dạy: “Các vị đại Bồ Tát lúc lập đạo tràng an cư, từ 7 ngày cho đến 21 ngày đầu, sám hối nghiệp chướng”."],["p","Trong Kinh Bảo Tích, Phật dạy: “Hàng ngày nên đảnh lễ danh hiệu 35 vị Phật trong kinh ấy mà sám hối nghiệp chướng”."],["p","Trong Luật thì pháp sám hối là một vấn đề tối quan trọng, không thể bỏ qua."],["p","Trong Luận thì pháp sám hối được giải thích rõ ràng và quyết định sám hối là một việc cần phải có của người chân tu, không thể thiếu sót."],["p","Không sám hối rất có hại: Nghiệp chướng không tiêu trừ, tội lỗi còn mãi, oan khiên nhiều kiếp theo hoài."],["p","Ngài Ngộ Đạt quốc sư mười đời làm cao Tăng mà Triệu Thố vẫn còn theo báo mãi."],["p","Như thế dù cầu hạnh phúc thế gian hay xuất thế gian, việc đời và việc đạo, đều bị trở ngại, tu chứng bất thành."],["p","Kinh sách dùng để sám hối có rất nhiều: Như bộ Vạn Phật, bộ Tam Thiên Phật, bộ Thủy Sám, Hồng Danh sám, Chuẩn Đề sám và Dược Sư sám v.v..."],["p","Nhưng bộ Lương Hoàng Sám này kể rõ tội nhân khổ quả, nghe đến ai cũng phải lạnh mình khiếp sợ mà phát tâm cải ác tùng thiện ngay. Bộ này lại có công năng diệt trừ tiền khiên, oan trái nhiều kiếp, nhiều đời, đọc đến phải cảm rơi nước mắt. Mỗi chữ, mỗi câu đều nhắm mục đích đền trả bốn ơn, cứu thoát ba cõi, thay thế lục đạo mà sám hối, cầu nguyện cho tam đồ thoát khỏi trầm luân. Cuối cùng lại vì tất cả chúng sanh mà phát nguyện, hồi hướng."],["p","Người tu hành đọc đến bộ Lương Hoàng Sám, dù không muốn phát đại tâm cũng phải phát, dù không tin địa ngục cũng phải sợ tam đồ."],["p","Những người tu Tịnh độ phát tâm Bồ đề thường nên tu theo pháp sám này, để mau về Cực Lạc."],["p","Có thể nói bộ Lương Hoàng Sám này là “bửu bối” riêng của những người cầu Vô thượng đạo, phát Bồ đề tâm vậy. Bộ này có năng lực sanh phước diệt tội không thể nghĩ bàn."],["p","Trong chánh văn có bài kệ tán thán công đức sám hối, đại ý như thế này."],["v",["Sám vừa cử lên","Tội lỗi tiêu liền","Giải được oan trái","Trừ được tai ương","Thoát khỏi khổ nạn","Phước đức vô biên","Sanh lên Đạo Lợi","Hoặc về Tây phương."]],["p","Văn Thủy Sám cũng nói: “Lúc nghiệp báo đến, tội nhơn không thể rúc vào núi đá, lặn xuống đáy nước, bay lên không gian hay ẩn núp đâu được. Duy chỉ có nhờ phương pháp sám hối mà thoát được tai nạn mau chóng hơn hết, độc nhất vô nhị”."],["p","Sám hối lợi cho mình, lợi cho người, cho tất cả tam đồ, lục đạo pháp giới chúng sanh."],["p","Công đức sám hối nói không cùng nghĩ không tận. Tôi chỉ xin đốt nén hương lòng cầu xin Tam Bảo gia hộ cho tất cả người thấy, người nghe, người ấn tống đồng phát Bồ đề tâm, đồng cầu sám hối, đồng hồi hướng công đức."],["p","Nam Mô Cầu Sám Hối Bồ Tát Ma ha tát."],["p","Trong lúc phiên dịch văn này, tôi không có hy vọng gì cao xa hơn là giúp cho hàng sơ cơ một phương pháp tu hành thiết thực để về Tây phương Cực Lạc."],["p","Do đó, đầu quyển thứ nhất có nghi thức khai kinh thông thường dễ tụng. Cuối quyển mười có nghi thức Tịnh độ, cầu sanh An Dưỡng làm tiêu chuẩn hồi hướng."],["p","Sau hết tôi xin chân thành cảm tạ chư vị đại thiện tri thức trong hải hội chỉ giáo cho tôi những khiếm khuyết, mong sao kỳ tái bản được hoàn toàn hơn."],["p","Tôi nguyện xin đem công đức này hướng lên cúng dường ngôi Tam Bảo, đức Quán Thế Âm Bồ Tát, đức Vô Biên Thân Bồ Tát, và chư vị Hộ Pháp đã mật thùy gia hộ cho tôi làm một việc mà tôi tưởng tượng tôi không làm được."],["p","Nguyện xin hồi hướng lên chư vị Đại đức Tăng trong hiện tại đã dìu dắt tôi tu hành. Ni chúng bộ V.N. đã phát tâm xuất bản giúp tôi, cùng chư vị thiện nam tín nữ đã ủng hộ tôi nhiều phương diện trong lúc phiên dịch."],["p","Nguyện xin tất cả đều trọn thành Phật đạo."],["v",["Nam mô Cầu Sám Hối Bồ Tát Ma Ha Tát.","Dịch giả: Tỳ Kheo THÍCH VIÊN GIÁC","Viết xong tại Tu viện Giác Hải","Điện Nam Hải Quan Âm ở Vạn Giả, Bắc Nha Trang","ngày mãn hạ, năm Canh Tý 2504 (1960)"]]]},{"t":"Lời Chỉ Dẫn","b":[["p","Vì nhận thấy nhiều Phật tử muốn tụng Lương Hoàng Sám song chưa biết cách lập đàn tràng như thế nào, đọc tụng làm sao cho đúng pháp, có lợi ích nhiều, nên chưa dám tụng tôi xin chỉ dẫn như sau:"],["p","Lập đàn bái sám hoặc ở chùa, tại Niệm Phật đường hay tại nhà Phật tử cũng được. Nhưng cần phải hết lòng thành kính và nghiêm trang thanh tịnh."],["p","Trường hợp thuận tiện, quý vị có thể cung thỉnh chư Tăng, một hay nhiều vị làm lễ khai kinh và hoàn kinh. Nếu không, người tại gia cứ thành tâm đọc tụng, như tụng các kinh khác, không ngại gì."],["p","Trước hết đọc phần “NGHI THỨC TỤNG LƯƠNG HOÀNG SÁM” bằng Hán văn dịch âm, rồi tụng tiếp nghi thức bằng Việt văn, nếu cần. Hết phần nghi thức thì tụng phần chánh văn. Cuối mỗi quyển thì tụng các bài hồi hướng và niệm Phật Di Đà cầu sanh Tịnh độ."],["p","Hoặc mỗi thời tụng hết một quyển. Hoặc một quyển chia làm nhiều thời, tùy theo thời giờ của mỗi người, nhàn rỗi hay bận việc."],["p","Việc ăn chay trường hay chay kỳ để tụng Lương Hoàng Sám, cũng tùy theo gia cảnh của mỗi người, không nên câu chấp. Điều quan trọng là phải quyết chí sám hối, chừa bỏ lỗi lầm, chứ không phải ở nơi điều chay mặn. Nhưng ai trai giới tinh thành, phóng sinh làm phước, càng nhiều càng quý, càng cố gắng càng hay, công đức sám hối càng sâu dày hơn nữa."],["p","Những người già yếu bệnh hoạn không thể lạy được thì ngồi mà vái, lắng tai nghe cho rõ lời lẽ và suy nghĩ cho kỹ ý nghĩa của sám văn cách thành tâm là quý hơn hết."],["p","Có nhiều điểm rất đáng để ý khuyến khích, vì tôi nhận thấy nhiều nơi như ở khuôn Phật giáo An Lạc, ở chùa Châu Lâm, Huế, hoặc ở khuôn Phật giáo Linh Thứu, Nha Trang, các Phật tử cử ra những vị có âm thanh trong trẻo, đọc tụng rõ ràng, khiến người nghe dễ hiểu, dễ phát tâm. Những người này thay nhau tụng còn các người khác ngồi nghe. Nhưng không phải tụng với âm điệu tụng kinh mà nên nhớ đây là cách xưng tội, trước Phật đài, thường thiết cầu Tam Bảo cứu hộ. Những đoạn kể lể tội trạng phải đọc cho rõ ràng, chí thành chí khẩn mà cầu xin sám hối. Những đoạn giảng về lý lẽ, về nhân quả cần phải đọc thong thả, phân câu rành mạch, để cho người nghe dễ nhận nhờ giọng đọc hùng mà đầy thiền vị theo tiếng mõ điểm thưa thưa từng câu một. Thỉnh thoảng điểm một tiếng chuông. Cũng có thể không đánh mõ, chỉ điểm chuông thưa thưa để cho người nghe theo dõi ý nghĩa, suy nghĩ tội tình, trong khung cảnh uy linh nhiệm mầu, khói hương nghi ngút. Những vọng niệm không thể xen vào quấy rối tâm thành của Phật tử. Tiếng chuông cảnh tỉnh đánh tan những gì hắc ám trong lòng, làm cho mọi người đều có một tinh thần siêu thoát."],["p","Đọc tụng như thế, tuy tu hành tập thể, mà không có gì làm loạn trí. Người không biết chữ cũng nhận thức được lý nghĩa, tự thấy tội lỗi của mình, rồi phát tâm Bồ Đề sám hối thế cho người khác trong lục đạo. Trong lúc này, nếu có ống loa phát thanh treo cao và vang dội xa xa, thì những kẻ độc ác phải giật mình mà chừa bỏ những hành vi phi pháp của họ."],["p","Đọc tụng cách này thì khác hẳn lối tụng kinh."],["p","Tụng kinh thì mỗi người một quyển, và ai cũng lớn tiếng đọc theo tiếng mõ của người hướng dẫn. Trái lại, tụng Lương Hoàng Sám, không khác gì chư Tăng tụng Luật trong giờ Bố tát. Một vị ngồi trên cao lớn tiếng đọc tụng, các vị khác im lặng ngồi dưới để nghe. Nếu người nào muốn tụng lớn tiếng theo mõ tùy nguy mình, sau khi đạo tràng hoàn tất, hãy tự tụng một mình cũng được, càng quý lắm. Hoặc tất cả mọi người đều tụng lớn tiếng theo nhịp mõ cũng được."],["p","Những điểm trên đây tuy có phần thiển cận và sơ lược, song cũng nhờ nhiều Phật tử góp ý kiến và kinh nghiệm nên tôi cũng không ngại gì mà không nêu ra. Mong quý vị thiện tri thức có gì sơ sót xin hoan hỷ bổ khuyết và chỉ giáo cho. Tôi rất lấy làm thâm cảm."],["v",["Hiệu Chính: HT. THÍCH TRÍ TỊNH","Dịch Giả: HT. THÍCH VIÊN GIÁC"]],["p","Quyển 1 (Phiên Âm)"],["p","HUÂN TU LƯƠNG HOÀNG SÁM PHÁP"]]},{"t":"Khai Đàn Khoa Nghi","b":[["p","Cử tán:"],["v",["Dương chi tịnh thủy,","Biến sái tam thiên,","Tánh không bát đức lợi nhơn thiên,","Pháp giới quảng tăng diên,","Diệt tội tiêu khiên,","Hỏa diệm hóa hồng liên.","Nam mô Thanh Lương Địa Bồ Tát Ma Ha"]],["p","Tát. (3 lần)"],["p","Cung thỉnh tán:"],["v",["Trí tuệ hoằng thâm đại biện tài,","Đoan cư ba thượng tuyệt trần ai,","Tường quang thước phá thiên sinh"]],["v",["bệnh, Cam lộ năng trừ vạn kiếp tai,","Túy liễu phất khai kim thế giới,","Hồng liên dũng xuất ngọc lâu đài.","Ngã kim khể thủ phần hương thỉnh,","Nguyện hướng nhân gian ứng hiện"]],["v",["lai.","Nam mô Đại Bi Quan Thế Âm Bồ Tát Ma"]],["p","Ha Tát. (3 lần)"],["p","Gia trì pháp thủy:"],["h","Cung Văn"],["p","Viên Thông Giáo Chủ, mãn nguyệt kim dung, thị Di Đà ư Cực Lạc quốc trung, trợ Thích Ca ư Ta Bà giới nội; xử thiên diệp hồng liên chi tọa, cư lưu ly chúng bảo chi sơn; quá khứ Chánh Pháp Minh, hiện tiền Quán Tự Tại. Tam thập nhị ứng, quảng độ quần sanh; thất nạn nhị cầu, đa phương ứng vật; thù thắng diệu lực, tán mạc năng cùng. Ngưỡng khấu hồng từ, phủ chương đổng giám:"],["p","Kim thời phụng vị kiến sám mỗ giáp (tên người lập lễ sám)... bẩm Phật di huấn, kiến sám Tỳ kheo mỗ giáp (tên hiệu vị Tăng chủ lễ)... kỵ lãnh thập phương sĩ thứ nhân dân đẳng... thỉnh mạng tăng chúng tựu vu mỗ xứ... (tịnh lam hay là già xứ) tu lễ Lương Hoàng Bảo Sám, phổ biến đạo tràng. Thượng lai sở kiến chi sơ, cẩn phần tín hương cung thỉnh:"],["p","Bồ Tát thùy dương liễu nhi biến sái cam lồ, trừ nhiệt não dĩ đắc thanh lương; tầm thanh cứu khổ ư tứ sinh, thuyết pháp độ thoát ư lục đạo. Tận văn bất trú, kiên cố chi tâm. Không giác cực viên, cụ tự tại đoan nghiêm chi tướng. Hữu cầu giai ứng, vô nguyện bất tùng. Cố ngã truy lưu, đoan bỉnh tịnh quán, thành tụng mật ngôn gia trì pháp thủy."],["p","Thị thủy giả, phương viên tùy khí, dinh hư nhậm thời, xuân phán đông ngưng, khảm lưu cấn chỉ. Hạo hạo hồ diệu nguyên mạc trắc, thao thao hồ linh phái nan cùng, bích gián tạng long, hàn đàm xâm nguyệt. Hoặc tại quân vương long bút hạ tán tác ân ba, hoặc cư Bồ Tát liễu chi đầu, sái vi cam lộ. Nhất đích tài triêm, thập phương câu tịnh."],["p","Phù thử thủy giả, bát công đức thủy, tự thiên chân, tiên tẩy chúng sanh nghiệp cấu trần, biến nhập Tỳ Lô ba tạng giới. Cá trung vô xứ bất siêu luân. Thủy bất tẩy thủy diệu cực pháp thân. Trần bất nhiễm trần phản tác tự kỹ. Quyên trừ cấu uế, đản địch đàn tràng. Sái khô mộc nhi tác dương xuân; khiết uế ban nhi thành Tịnh độ. Sở vị nội ngoại trung gian vô trước uế, thánh phàm u hiển tổng thanh lương."],["v",["Bồ Tát liễu đầu cam lộ thủy,","Năng linh nhất trích biến thập"]],["v",["phương, Tinh chiên cấu uế tận quyên trừ,","Linh thử đàn tràng tất thanh tịnh.","Giáo hữu mật ngôn cẩn đương trì tụng:"]],["h","Tụng Chú Đại Bi"],["v",["Nam mô Đại Bi Hội Thượng Phật Bồ Tát. (3 lần)","Thiên thủ thiên nhãn vô ngại đại bi tâm đà la ni.","Nam mô hắc ra đát na, đa ra dạ da."]],["p","Nam mô a rị da, bà lô yết đế, thước bát ra da, Bồ đề tát đỏa bà da, ma ha tát đỏa bà da, ma ha ca lô ni ca da. Án, tát bàn ra phạt duệ số đát na đát tỏa."],["p","Nam mô tất kiết lật đỏa y mông a rị da, bà lô kiết đế thất Phật ra lăng đà bà."],["p","Nam mô na ra cẩn trì hê rị, ma ha bàn đa sa mế, tát bà a tha đậu du bằng, a thệ dựng, tát bà tát đa, na ma bà già, ma phạt đạt đậu, đát điệt tha. Án a bà lô hê, lô ca đế, ca ra đế, di hê rị, ma ha bồ đề tát đỏa, tát bà tát bà, ma ra ma ra, ma hê ma hê, rị đà dựng, câu lô câu lô kiết mông, độ lô độ lô, phạt xà da đế, ma ha phạt xà da đế, đà ra đà ra, địa rị ni, thất Phật ra da, dá ra dá ra. Mạ mạ phạt ma ra, mục đế lệ, y hê y hê, thất na thất na a ra sâm Phật ra xá lợi, phạt sa phạt sâm, Phật ra xá da, hô lô hô lô ma ra, hô lô hô lô hê rị, ta ra ta ra, tất rị tất rị, tô rô tô rô, bồ đề dạ bồ đề dạ, bồ đà dạ, bồ đà dạ, di đế rị dạ, na ra cẩn trì địa rị sắc ni na, ba dạ ma na ta bà ha."],["p","Tất đà dạ ta bà ha. Ma ha tất đà dạ ta bà ha. Tất đà du nghệ thất bàn ra dạ ta bà ha."],["p","Na ra cẩn trì ta bà ha. Ma ra na ra ta bà ha. Tất ra tăng a mục khê da, ta bà ha. Ta bà ma ha, a tất đà dạ, ta bà ha. Giả kiết ra a tất đà dạ, ta bà ha. Ba đà ma yết tất đà dạ, ta bà ha. Na ra cẩn trì bàn đà ra dạ, ta bà ha. Ma bà lị thắng yết ra dạ, ta bà ha."],["v",["Nam mô hắc ra đát na, đa ra dạ da.","Nam mô a rị da, bà lô yết đế thước bàng ra dạ, ta bà ha.","Án tất điện đô, mạn đa ra, bạt đà dạ, ta bà ha. (3 lần)"]],["p","Án nại ma ba cát ngỏa đế, a ba ra mật đạp, a ưu rị a nạp, tô tất nể, thiệt chất đạp, điệp tả ra tể giả, đát tháp cả đạt giả, a ra ha đế, tam dược tam bất đạt giả, đát nể giả tháp. Án tát rị ba, tang tư cát rị, bát rị thuật đạp, đạt ra mả đế, cả cả nại tang mả ngột ngỏa đế, tát ba ngỏa tỷ thuật đế, mã hắc nại giả, bát rị ngỏa rị tóa ha. (3 lần)"],["p","Nguyện tương thử thù thắng công đức chúc tán Phật nhật tăng huy, pháp luân thường chuyển, thế giới hòa bình, chúng sanh an lạc."],["p","Phục vị vong linh tiêu tội chướng, tiêu tội chướng sinh Tịnh độ, An dưỡng giới, đồng phó Long Hoa hội."],["p","Nam mô An dưỡng giới, đồng phó Long Hoa hội. (3 lần)"],["p","Dĩ thử kinh chú công đức hồi hướng hộ pháp Long thiên Tam giới, nhạc độc linh thông, thủ hộ đạo tràng chân tể kỳ phước bảo an bình thiện, trang nghiêm hữu vị tiên vong, phổ nguyện pháp giới oan thân, cộng nhập Tỳ Lô tánh hải."],["p","(Tuyên sớ thỉnh Phật nếu có)"],["p","Nam mô Bổn Sư Thích Ca Mâu Ni Phật chứng minh công đức. (3 lần)"],["v",["Huỳnh kim mãn nguyệt tướng,","Tam giới độc xưng tôn,","Hàng phục nhất thế ma","Chư thiên giai cung thủ.","Ngưỡng lao đại chúng tán dương Tam Bảo."]],["p","– Phật Bảo thán nan cùng, công thành vô lượng, vô lượng kiếp trung, nguy nguy trượng lục tử kim dung, giác đạo tuyết sơn phong, mi tế ngọc hào quang xán lạn, chiếu khai lục đạo, lục đạo hôn mong. Long Hoa tam hội nguyện tương phùng, diễn thuyết pháp chánh tông."],["p","Quy y Thường trú Phật Đà da, nguy nguy vạn đức Phật Đà da."],["p","– Pháp Bảo thật nan lường, Như Lai kim khẩu, Kim khẩu tuyên dương, Long cung hải tạng tán thiên hương, giác giả tụng lương hàm ngọc trục hà điều, kim tả tự tợ bài thu nhạn, thu nhạn thành hàng, chỉ nhân Tam tạng thỉnh lai đàn, vạn cổ vĩnh phu dương."],["p","Quy y Thường trú Đạt Mạ da, hạo hạo tam thừa Đạt Mạ da."],["p","– Tăng Bảo bất tư nghì, thân phi tam nhuế, tam nhuế vân y, phù bôi chấn tích sát na thì, phó cảm ứng quần ky, kham tác nhân gian công đức chủ, kiên trì giới hạnh, giới hạnh vô vi, ngã kim khể thủ nguyện diêu tri, chấn tích trượng đề huề."],["p","Quy y thường trú Tăng Già da, minh minh lục thông Tăng Già da."],["p","Nam mô Vân Lai Tập Bồ Tát Ma ha tát. (3 lần)"],["p","(Tán Vi Đà, niệm Thiên nữ chú hoàn tuyên sớ)"],["v",["Vi Đà Thiên Tướng,","Hộ Pháp hóa thân,","Ủng hộ Phật pháp, thệ hoằng thâm,","Bảo xử trấn ma quân,","Công đức nan lường,","Kỳ đảo phó phàm tâm.","Nam mô Phổ Nhãn Bồ Tát Ma Ha Tát. (3 lần)"]],["p","Cử hương tán:"],["v",["Giới định chân hương,","Phần khởi xung thiên thượng,","Trai chủ kiền thành,","Nhiệt tại kim lô phóng,","Khoảnh khắc nhân huân,","Tức biến mãn thập phương,","Tích nhật Gia Du miễn nạn tiêu tai"]],["v",["chướng.","Nam mô Hương Vân Cái Bồ Tát Ma Ha"]],["p","Tát. (3 lần)"],["p","Nguyện khải văn:"],["h","Cung Văn"],["p","Lương hoàng khải kiến, Di Lặc đề danh, Chí Công tập Hoa tạng chi huyền văn, quần kinh lục chư Phật chi thánh hiệu, đại tập Sa môn, hoằng tuyên sám pháp. Sám văn cảm mộng ư Lương triều, thoại khí đằng huy ư Võ Đế. Do thị cảnh cảnh kim quang bất muội, hoàng hoàng bảo diệm phân phương, úc úc hương yên huân nội khuyết, trùng trùng hoa nhụy diệu vương cung. Thanh tiêu vân lý, thiên nhân hiện báo thể chi đoan nghiêm. Bạch ngọc giai tiền, Hy Thị thoát mãng thân chi khổ nạn; dĩ thử tiêu tai, tai tiêu cát chí. Nhân tư diệt tội, tội diệt phước sinh."],["p","Nãi phá ám chi minh đăng, chân cứu bệnh chi diệu dược. Ân triêm cửu hữu, đức bỉ tứ sinh; sám chi công đức tán mạc năng cùng. Tư giả sám văn triệu khởi, ngưỡng khấu Phổ Hiền Hạnh vương, vận tưởng hương hoa cúng dường Thập phương Điều Ngự. Dục nghiêm thanh tịnh chi sám đàn, tiên tụng bí mật chi chương cú. Yếu kỳ thiện quả dĩ châu long, tất xử tội hoa nhi điêu tạ. Ngưỡng khấu Hồng từ đại chương linh ứng."],["p","Phổ Hiền Bồ Tát tượng giá quang lâm."],["p","Hữu nhất Bồ Tát kiết già phu tọa, danh viết Phổ Hiền, thân bạch ngọc sắc, ngũ thập chủng quang, ngũ thập chủng sắc, dĩ vi hạng quang, thân chư mao khổng, lưu xuất kim quang. Kỳ kim quang đoan, vô lượng hóa Phật, chư hóa Bồ Tát, dĩ vi quyến thuộc; an tường từ bộ, vũ đại bảo hoa, chí thành giả tiền. Kỳ tượng khai khẩu, ư tượng nha thượng, chư trì ngọc nữ, cổ nhạc huyền ca, kỳ thanh vi diệu, tán thán Đại thừa, nhất thật chi đạo."],["p","Hành giả kiến dĩ, hoan hỷ kính lễ, phục cánh đọc tụng, thậm thâm kinh điển, biến lễ thập phương, vô lượng hóa Phật, lễ Đa Bảo Phật tháp, cập Thích Ca Mâu Ni; tịnh lễ Phổ Hiền chư đại Bồ Tát; phát thị thệ nguyện; nhược ngã túc phước, ưng kiến Phổ Hiền. Nguyện Tôn giả biến kiết, thị ngã sắc thân."],["p","Nam mô Phổ Hiền Vương Bồ Tát Ma Ha Tát. (3 lần)"],["p","– Nhất tâm đảnh lễ thập phương pháp giới thường trú chư Phật."],["p","– Nhất tâm đảnh lễ thập phương pháp giới thường trú Tôn Pháp."],["p","– Nhất tâm đảnh lễ thập phương pháp giới thường trú Hiền Thánh Tăng."],["p","Chủ lễ xướng:"],["p","(Thị chư chúng đẳng các các hồ quỳ, nghiêm trì hương hoa, như pháp cúng dường)."],["p","Nguyện thử hương hoa biến thập phương, dĩ vi vi diệu quang minh đài. Chư thiên âm nhạc thiên bảo hương. Chư thiên hào thiện thiên bảo y. Bất khả tư nghị diệu pháp trần. Nhất nhất trần xuất nhất thiết trần. Nhất nhất trần xuất nhất thiết pháp. Triển chuyển vô ngại hộ trang nghiêm, biến chí thập phương Tam Bảo tiền. Thập phương pháp giai Tam Bảo tiền, tất hữu ngã thân tu cúng dường."],["p","Nhất nhất giai tất biến pháp giới, bỉ bỉ vô tạp vô chướng ngại. Tận vị lai tế tác Phật sự, phổ huân pháp giới chư chúng sanh."],["p","Mông huân giai phát Bồ đề tâm. Đồng nhập vô sinh chứng Phật trí."],["v",["Nguyện thử hương hoa vân,","Biến mãn thập phương giới.","Cúng dường nhất thiết Phật,","Tôn Pháp, chư Bồ Tát,","Vô biên Thanh văn chúng,","Cập nhất thiết Thánh Hiền,","Duyên khởi quang minh đài,","Quá ư vô biên giới,","Vô biên Phật độ trung,","Thọ dụng tác Phật sự.","Phổ huân chư chúng sanh,","Giai phát Bồ đề tâm,","Dung nhan thậm kỳ diệu,","Quang minh chiếu thập phương,","Ngã Thích tằng cúng dường,","Kim phục hoàn thân cận,","Thánh chúa Thiên trung vương,","Ca Lăng Tần Già thanh,","Ai mẫn chúng sanh giả,","Ngã đẳng kim đỉnh lễ."]],["p","Cung thỉnh:"],["v",["Phật nhiếp kim liên hạ Thứu phong,","Pháp khai Bảo tạng ly Long Cung,","Tăng tùng nội uyển biệt thiền định,","Tam Bảo lâm đàn pháp hội đồng.","Nam mô Thập Phương Thường Trú Tam"]],["v",["Bảo. (3 lần)","Cúng hương:","Hương tài nhiệt, lư phàn bảo đảnh","trung, Chiên đàn trầm nhũ chơn kham"]],["p","cúng, Hương yên liêu nhiễu liên hoa động, Thập phương chư Phật hạ thiên"],["p","cung, Thanh lương sơn La Hán, nạp thọ"],["p","nhân thiên cúng. (2 lần) Nam mô Phổ Hiền Vương Bồ Tát Ma Ha"],["p","Tát. (3 lần) Nhập sám văn:"],["h","Cái Văn"],["p","Nhất thể Hóa thân, phổ ứng thập phương quốc độ. Nhất âm thuyết pháp, Thanh Văn tam giới nhân thiên. Nhất thế Vô Ngại Nhân, giai tùng nhất Đạo, nhất môn, nhi xuất sinh tứ hải. Nhất thừa viên đốn giáo, giai nhân nhất tướng, nhất vị nhi chứng Niết bàn sơn. Tùy cơ như nguyệt ứng thiên gian, ứng vật tợ xuân hồi đại địa, biến duyên pháp giới, phổ tọa đạo tràng. Hy đạo nhãn dĩ chứng tri, giám phàm tình chi vi khổn. Phụng vì kim thời cầu sám hối, đệ tử... đẳng khởi kiến:"],["p","Từ Bi Đạo tràng Sám Pháp, tư đương đệ nhất quyển, nhập đàn duyên khởi. Ngã chư chúng đẳng đoan khác nhất tâm, túc thanh tam nghiệp, y khoa diễn phạm, thiêu hương, tán hoa, cúng dường thập phương Tam Bảo, xưng xướng chư Phật hồng danh. Ngũ thể đầu địa, dĩ quy y phát lộ sám trừ chư nghiệp chướng."],["p","Thiết niệm đệ tử chúng đẳng, tự tùng vô thỉ dĩ lai, chí ư kim nhật, nhân mê nhất tánh, lý muội nhất thừa, nhất ế tại nhãn, thời không hoa nhi loạn trụy."],["p","Nhất âu tài khởi xử huyễn hải dĩ ba phiên."],["p","Nhất chân tam muội quái vi, nhất điểm vô minh tư túng; ý hàm tam độc, nghiệp tạo vạn đoan, khai trần lao bát vạn chi môn, khởi phiền não bách thiên chi chướng. Đam hoan dục cảnh, như cuồng tượng dĩ vô câu. Xu trục vọng duyên tợ phi nga nhi phó hỏa tội, nhược kheo sơn chi chướng, nghiệp như thương hải chi thâm. Ký vi thiểu ư thiện căn, khủng nan đào ư ác quả. Kim tắc ưu cần tại niệm, thoan cách vu tâm. Ngoại thác thắng duyên, nội hoài tàm quý. Tập thử hiện tiền Thánh chúng, phi duyệt sám hối linh văn. Trượng thiên Phật chi oai quang, tẩy đa sinh chi tội cấu."],["p","Ngã nguyện như tư, Phật tức ai lân; ngưỡng khấu hồng từ, minh huân gia bị."],["v",["Thiên thượng thiên hạ vô như Phật,","Thập phương thế giới diệc vô tỷ,","Thế gian sở hữu ngã tận kiến,","Nhất thiết vô hữu như Phật giả."]],["p","Khải vận Từ Bi Đạo tràng Sám Pháp, nhất tâm quy mạng Tam thế chư Phật:"],["v",["Nam mô Quá Khứ Tỳ Bà Thi Phật,","Nam mô Thi Khí Phật,","Nam mô Tỳ Xá Phù Phật,","Nam mô Câu Lưu Tôn Phật,","Nam mô Câu Na Hàm Mâu Ni Phật,","Nam mô Ca Diếp Phật,","Nam mô Bổn Sư Thích Ca Mâu Ni"]],["p","Phật, Nam mô Đương Lai Hạ Sanh Di Lặc"],["p","Tôn Phật."],["p","(Đến đây, nếu muốn nghỉ thì tụng hồi hướng mà ra rồi sẽ vào tiếp tụng quyển thứ nhất. Cũng như lễ khai kinh vừa xong. Nếu không muốn nghỉ, thì tụng quyển thứ nhất)."],["p","Phần nghi thức khai Đạo Tràng Sám Pháp, đầu quyển thứ nhất, phiên âm Hán văn đến đây là hết."]],"p":"Quyển Thứ Nhất"},{"t":"Nghi Thức Tụng Lương Hoàng Sám","b":[["p","(Việt Dịch)"],["p","Sái tịnh:"],["v",["Nhành dương nước tịnh,","Rưới khắp ba ngàn,","Tánh không tám đức lợi trời người,","Thế giới rộng thênh thang,","Diệt sạch tai nàn,","Lửa dữ hóa sen vàng.","Nam mô Thanh Lương Địa Bồ Tát Ma Ha"]],["p","Tát. (3 lần)"],["p","Cung thỉnh:"],["v",["Trí huệ rộng sâu đại biện tài,","Ngồi trên hoa báu tuyệt trần ai.","Hào quang tỏa phá ngàn đời bệnh,","Cam lồ trừ sạch vạn kiếp tai.","Thế giới vàng kim, liễu xanh phất,","Lâu đài châu ngọc, sen hồng khai.","Hương trần cung thỉnh, con xin lễ,","Nguyện Ngài thương xót, hiện lại"]],["v",["đây.","Nam mô Đại Bi Quan Thế Âm Bồ Tát Ma"]],["p","Ha Tát. (3 lần)"],["p","Cúng hương:"],["v",["Nguyện đem lòng thành kính,","Gởi theo đám mây hương,","Phưởng phất khắp mười phương,","Cúng dường ngôi Tam Bảo.","Thề trọn đời giữ đạo,","Theo tự tánh làm lành,","Cùng pháp giới chúng sanh,","Cầu Phật từ gia hộ,","Tâm Bồ Đề kiên cố,","Xa bể khổ nguồn mê,","Chóng quay về bờ giác.","Nam mô Hương Cúng Dường Bồ Tát Ma"]],["p","Ha Tát. (3 lần)"],["p","Tán thán Phật:"],["v",["Đấng Pháp Vương vô thượng,","Ba cõi chẳng ai bằng,","Thầy dạy khắp trời người,","Cha lành cả chúng sanh,","Quy y tròn một niệm,","Dứt sạch nghiệp ba kỳ,","Xưng dương cùng tán thán,","Ức kiếp không cùng tận."]],["v",["Quán tưởng:","Phật, chúng sanh, tánh thường rỗng","lặng, Đạo cảm thông không thể nghĩ bàn,","Lưới Đế châu ví Đạo tràng,","Mười phương Phật bảo hào quang","sáng ngời Trước Bảo tọa thân con ảnh hiện,","Cúi đầu xin thệ nguyện quy y.","Đảnh lễ:"]],["p","Nhất tâm đảnh lễ: Nam mô tận hư không biến pháp giới, quá, hiện, vị lai thập phương Chư Phật, Tôn Pháp, Hiền Thánh Tăng, Thường trú Tam Bảo. (1 lạy)"],["p","Nhất tâm đảnh lễ: Nam mô Ta Bà Giáo Chủ Bổn Sư Thích Ca Mâu Ni Phật, Long Hoa Giáo Chủ Di Lặc Tôn Phật, Đại Trí Văn Thù Sư Lợi Bồ Tát, Đại Hạnh Phổ Hiền Bồ Tát, Hộ Pháp Chư Tôn Bồ Tát, Linh Sơn Hội Thượng Phật Bồ Tát. (1 lạy)"],["p","Nhất tâm đảnh lễ: Tây phương Cực Lạc Thế giới Đại Từ Đại Bi Tiếp Dẫn Đạo Sư A Di Đà Phật, Đại Bi Quán Thế Âm Bồ Tát, Đại Nguyện Địa Tạng Vương Bồ Tát, Thanh Tịnh Đại Hải Chúng Bồ Tát. (1 lạy)"],["p","Kỳ nguyện:"],["p","Đệ tử chúng con tên... Pháp danh... tuổi... hiện trú..."],["p","Nguyện xin ngôi Tam Bảo thường trú trong mười phương, Đức Bổn Sư Thích Ca Mâu Ni Phật, Đức Tiếp Dẫn Đạo Sư A Di Đà Phật, Đương Lai Hạ Sinh Di Lặc Tôn Phật, Biến Pháp Giới Chư Tôn Bồ Tát Ma ha tát và hết thảy Thánh Hiền Tăng, Từ Bi gia hộ, chứng minh cho chúng con."],["p","Chúng con lâu đời lâu kiếp, vì tánh hôn mê, không kể chánh tà, gây nhiều tội ác, tổn người hại vật, hủy báng Phật Pháp Tăng. Hôm nay một dạ chí thành, cầu xin sám hối, tụng trì lễ bái Lương Hoàng Bảo Sám, ăn năn tội lỗi; không dám che giấu, hầu mong nghiệp chướng tiêu trừ, thân tâm an lạc, gia đình cát khánh, hạnh phúc tăng long, Bồ đề kiên cố, hiện tiền phước huệ trang nghiêm. Một hậu được sinh về Cực Lạc quốc, cùng với pháp giới chúng sanh đồng thành Phật đạo. (3 lạy)"],["p","Phát đại nguyện:"],["v",["Chúng sanh vô biên thệ nguyện độ,","Phiền não vô tận thệ nguyện đoạn,","Pháp môn vô lượng thệ nguyện học,","Phật đạo vô thượng thệ nguyện"]],["p","thành."],["p","Tự tánh chúng sanh thệ nguyện độ,"],["p","Tự tánh phiền não thệ nguyện đoạn, Tự tánh pháp môn thệ nguyện học,"],["v",["Tự tánh Phật đạo thệ nguyện thành.","Nam mô Chứng Minh Sư Bồ Tát Ma Ha","Tát. (3 lần)"]],["h","Tụng Chú Đại Bi"],["v",["Nam mô Đại Bi Hội Thượng Phật Bồ Tát. (3 lần)","Thiên thủ thiên nhãn vô ngại đại bi tâm đà la ni.","Nam mô hắc ra đát na, đa ra dạ da."]],["p","Nam mô a rị da, bà lô yết đế, thước bát ra da, Bồ đề tát đỏa bà da, ma ha tát đỏa bà da, ma ha ca lô ni ca da. Án, tát bàn ra phạt duệ số đát na đát tỏa."],["p","Nam mô tất kiết lật đỏa y mông a rị da, bà lô kiết đế thất Phật ra lăng đà bà."],["p","Nam mô na ra cẩn trì hê rị, ma ha bàn đa sa mế, tát bà a tha đậu du bằng, a thệ dựng, tát bà tát đa, na ma bà già, ma phạt đạt đậu, đát điệt tha. Án a bà lô hê, lô ca đế, ca ra đế, di hê rị, ma ha bồ đề tát đỏa, tát bà tát bà, ma ra ma ra, ma hê ma hê, rị đà dựng, câu lô câu lô kiết mông, độ lô độ lô, phạt xà da đế, ma ha phạt xà da đế, đà ra đà ra, địa rị ni, thất Phật ra da, dá ra dá ra. Mạ mạ phạt ma ra, mục đế lệ, y hê y hê, thất na thất na a ra sâm Phật ra xá lợi, phạt sa phạt sâm, Phật ra xá da, hô lô hô lô ma ra, hô lô hô lô hê rị, ta ra ta ra, tất rị tất rị, tô rô tô rô, bồ đề dạ bồ đề dạ, bồ đà dạ, bồ đà dạ, di đế rị dạ, na ra cẩn trì địa rị sắc ni na, ba dạ ma na ta bà ha."],["p","Tất đà dạ ta bà ha. Ma ha tất đà dạ ta bà ha. Tất đà du nghệ thất bàn ra dạ ta bà ha."],["p","Na ra cẩn trì ta bà ha. Ma ra na ra ta bà ha. Tất ra tăng a mục khê da, ta bà ha. Ta bà ma ha, a tất đà dạ, ta bà ha. Giả kiết ra a tất đà dạ, ta bà ha. Ba đà ma yết tất đà dạ, ta bà ha. Na ra cẩn trì bàn đà ra dạ, ta bà ha. Ma bà lị thắng yết ra dạ, ta bà ha."],["v",["Nam mô hắc ra đát na, đa ra dạ da.","Nam mô a rị da, bà lô yết đế thước bàng ra dạ, ta bà ha.","Án tất điện đô, mạn đa ra, bạt đà dạ, ta bà ha. (3 lần)"]],["p","Án nại ma ba cát ngỏa đế, a ba ra mật đạp, a ưu rị a nạp, tô tất nể, thiệt chất đạp, điệp tả ra tể giả, đát tháp cả đạt giả, a ra ha đế, tam dược tam bất đạt giả, đát nể giả tháp. Án tát rị ba, tang tư cát rị, bát rị thuật đạp, đạt ra mả đế, cả cả nại tang mả ngột ngỏa đế, tát ba ngỏa tỷ thuật đế, mã hắc nại giả, bát rị ngỏa rị tóa ha. (3 lần)"],["v",["Đảnh lễ:","Đại từ đại bi mẫn chúng sanh,","Đại hỷ đại xả tế hàm thức,"]],["p","Tướng hảo quang minh dĩ tự nghiêm, Chúng đẳng chí tâm quy mạng lễ."],["p","Nhất tâm đảnh lễ: Nam mô Thập phương tận hư không biến pháp giới vi trần sát độ trung quá, hiện, vị lai, thường trú Phật Pháp Tăng Tam Bảo. (1 lạy)"],["p","Nhất tâm đảnh lễ:"],["v",["Nam mô Quá khứ Tỳ Bà Thi Phật.","Nam mô Thi Khí Phật.","Nam mô Tỳ Xá Phù Phật.","Nam mô Câu Lưu Tôn Phật.","Nam mô Câu Na Hàm Mâu Ni Phật.","Nam mô Ca Diếp Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Di Lặc Tôn Phật."]],["p","Kệ khai kinh:"],["v",["Phật pháp cao siêu, lý ẩn sâu,","Trăm nghìn ức kiếp khó tìm cầu,","Duyên lành nghe thấy xin trì tụng,","Nguyện tỏ Như Lai nghĩa nhiệm"]],["v",["mầu.","Nam mô Khai Bảo Tạng Bồ Tát Ma Ha Tát. (3 lần và 3 lạy)"]],["p","(Tiếp tụng chánh văn quyển thứ nhất)"]],"p":"Quyển Thứ Nhất"},{"t":"Sám Pháp Từ Bi Đạo Tràng","b":[["p","Từ Bi Đạo Tràng, bốn chữ ấy là danh hiệu của pháp Sám hối này."],["p","Nhân vì cảm thấy Đức Phật Di Lặc, rũ lòng từ bi, thương đời hiện tại và đời vị lai, ứng mộng dạy bảo, đặt tên như thế, đúng như sự thật, không dám đổi thay."],["p","Nay vâng lời dạy bảo của Đấng Từ Bi ấy là vì muốn hộ trì Tam Bảo: Làm cho ma quân ẩn hình, khiến người tự cao tự đại và người tăng thượng mạn phải tự chiết phục; khiến người chưa trồng căn lành phải trồng căn lành; người đã trồng rồi, thì làm cho căn lành thêm lớn; khiến người hay chấp lấy chỗ sở đắc đắm trước tà kiến, phải phát tâm xả bỏ chấp trước; khiến người ưa Tiểu thừa không nghi Đại thừa; người ưa Đại thừa sinh tâm hoan hỷ Tiểu thừa."],["p","Vả lại, pháp sám từ bi này lớn hơn tất cả các việc lành khác. Pháp này là chỗ quy y của hết thảy chúng sanh; như mặt trời sáng ban ngày; như mặt trăng chiếu ban đêm. Pháp này là tròng con mắt, là đạo sư, là cha mẹ, là anh em, là chơn thiện tri thức của người tu hành, đồng đi đến đạo tràng."],["p","Pháp sám này thân thích hơn huyết nhục, đời đời theo nhau, dầu đến chết cũng không rời nhau. Vì thế nên gọi Pháp sám này là Từ Bi Đạo Tràng."],["p","Hôm nay đại chúng ẩn thân hay hiện hình trong đạo tràng, lập ra Pháp sám này đều phát đại tâm, vì có mười hai nhân duyên lớn:"],["p","Những gì là mười hai?"],["p","1.- Một là nguyện hóa độ sáu đường chúng sanh không có hạn lượng."],["p","2.- Hai là nguyện báo đáp tứ ân không có hạn lượng."],["p","3.- Ba là nguyện nhờ thần lực của Pháp sám này, khiến chúng sanh thọ cấm giới của Phật, không sinh tâm hủy phạm."],["p","4.- Bốn là nguyện nhờ thần lực của Pháp sám này, khiến các chúng sanh, đối với các bậc tôn trưởng không sinh tâm kiêu mạn."],["p","5.- Năm là nguyện nhờ thần lực của Pháp sám này, khiến các chúng sanh, sinh ra nơi nào cũng không khởi tâm giận hờn."],["p","6.- Sáu là nguyện nhờ thần lực của Pháp sám này, khiến các chúng sanh đối với sắc thân người khác, không khởi tâm ghen ghét."],["p","7.- Bảy là nguyện nhờ thần lực của Pháp sám này, khiến các chúng sanh, đối với các pháp trong thân, ngoài thân, không sinh tâm keo rít, mến tiếc."],["p","8.- Tám là nguyện nhờ thần lực của Pháp sám này, khiến các chúng sanh, hễ làm được phước thiện gì, đều không phải vì mình mà làm, chỉ vì những người không có ai ủng hộ, không có ai giúp đỡ mà làm."],["p","9.- Chín là nguyện nhờ thần lực của Pháp sám này, khiến các chúng sanh không vì mình mà tu pháp tứ nhiếp mà chỉ vì hết thảy chúng sanh."],["p","10.- Mười là nguyện nhờ thần lực của Pháp sám này, khiến các chúng sanh, thấy người cô độc, tù tội, tật bệnh, thì sinh tâm cứu giúp, cho họ an vui."],["p","11.- Mười một là nguyện nhờ thần lực của Pháp sám này, khiến người tu hành, thấy có chúng sanh nào đáng chiết phục thì chiết phục, đáng nhiếp thọ thì nhiếp thọ."],["p","12.- Mười hai là nguyện nhờ thần lực của Pháp sám này, khiến các chúng sanh, sinh ra nơi nào, cũng tự nghĩ nhớ đến sự phát tâm bồ đề hôm nay, làm cho tâm bồ đề tương tục mãi mãi không bị gián đoạn."],["p","Ngưỡng mong đại chúng hoặc phàm hoặc Thánh, hoặc ẩn thân hay hiện hình trong đạo tràng này, đồng gia tâm phù hộ, đồng gia tâm nhiếp thọ, khiến đệ tử chúng con tên... sám hối được thanh tịnh, thệ nguyện được thành tựu, tâm đồng tâm chư Phật, nguyện đồng nguyện chư Phật. Chúng sanh trong bốn loài, sáu đường do đó mà được mãn Bồ đề nguyện."]],"p":"Quyển Thứ Nhất"},{"t":"Chương Thứ Nhất Quy Y Tam Bảo","b":[["p","Hôm nay đại chúng đồng nghiệp trong đạo tràng mọi người đều nên sinh tâm giác ngộ; biết đời là vô thường, thân không sống lâu, trẻ mạnh rồi phải già yếu; chớ ỷ hình dung tốt đẹp mà không tự giữ gìn tịnh hạnh."],["p","Vạn vật cũng vô thường thảy đều tiêu diệt. Trên trời dưới đất, không có vật gì tồn tại mãi mãi. Lúc còn trẻ, nhan sắc tốt đẹp, da thịt mịn màng, thơm tho trong sạch. Nhưng thân này cũng vô thường. Người sống có hợp có tan. Sinh già bệnh chết không hẹn mà đến, ai sẽ trừ khử khổ ấy cho ta. Tai họa thình lình đưa đến biết đâu mà tránh, không thể thoát được. Sang hèn, giàu nghèo, thảy đều nhân vậy mà chết. Chết rồi thân thể sình thối không chịu nổi. Vậy luyến tiếc thân này nào có ích gì. Nếu không lo tu nghiệp lành thù thắng, thì do đâu, mà thoát ly sanh tử."],["p","Đệ tử chúng con tên... tự nghĩ rằng:"],["p","Hình tợ sương mai, mạng như nắng chiều; đời sống mong manh; chưa biết chết lúc nào. Lại thêm nghèo thiếu, không có phước đức đáng xưng; không có trí tuệ sáng suốt, không có hiểu biết như đại nhân thần thánh; lời nói không tốt đẹp, không trung hòa, nhân nghĩa, hạnh kiểm tiến thối không có lễ độ, tôn ty. Nếu lầm lập chí như vậy, càng thêm mệt nhọc cho sự tu hành."],["p","Ngưỡng mong đại chúng sanh lòng hổ thẹn, sợ hãi. Pháp hội này lập có kỳ hạn, nếu không lo sám hối sau luyến tiếc, hối hận cũng không thể được."],["p","Từ nay trở đi nguyện phải nỗ lực, sớm tối chuyên tâm, phụng sự cúng dường càng thêm tinh tấn. Chỉ có việc ấy là khoan khoái, cần làm hơn hết."],["p","Ngưỡng mong đại chúng đồng nghiệp trong đạo tràng, nên phải ân cần, thận trọng. Phát tâm dõng mãnh, tâm không buông lung, tâm an trú, tâm quảng đại, tâm thù thắng, tâm đại từ bi, tâm lạc thiện, tâm hoan hỷ, tâm báo ơn, tâm tế độ, tâm giữ gìn hết thảy chúng sanh; tâm cứu độ hết thảy chúng sanh, tâm đồng tâm Bồ Tát; tâm đồng tâm chư Phật! Nhất tâm nhất ý, chí thành đảnh lễ Tam Bảo."],["p","Nguyện xin thay thế quốc vương, đế chúa, thổ địa, nhân dân, thế cho cha mẹ, sư trưởng thượng, trung, hạ tòa, thiện ác tri thức, chư thiên, chư tiên, hộ thế tứ vương, chủ thiện phạt ác, thủ hộ trì chú, ngũ phương long vương, long thần bát bộ, và hết thảy chúng sanh vô cùng vô tận, trong mười phương, có tâm linh, có thần thức, hoặc ở dưới nước, hoặc ở trên khô, hoặc ở giữa hư không; nguyện thế cho hết thảy chúng sanh ấy mà."],["p","- Quy y mười phương tận hư không giới hết thảy chư Phật. (1 lạy)"],["p","- Quy y mười phương tận hư không giới hết thảy Tôn pháp. (1 lạy)"],["p","- Quy y mười phương tận hư không giới hết thảy Hiền Thánh Tăng. (1 lạy)"],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nên biết vì cớ gì mà phải quy y Tam Bảo."],["p","Vì các Đức Phật, các vị Bồ Tát có lòng đại từ vô lượng độ thoát thế gian, có lòng đại bi vô lượng, an ủi thế gian, thương hết thảy chúng sanh như con đỏ."],["p","Lòng đại từ đại bi ấy thường không biết mỏi mệt, hằng cầu việc lành lợi ích cho tất cả; thề dập tắt lửa tham sân si cho tất cả, giáo hóa khiến cho tất cả đều được quả Vô thượng Bồ đề. Nếu chúng sanh không chứng quả Bồ đề. Phật thề không thành Chánh giác, vì duyên cớ ấy nên đại chúng cần phải quy y Tam Bảo."],["p","Vả lại, các Đức Phật thương xót chúng sanh quá hơn cha mẹ thương con."],["p","Trong kinh dạy rằng: “Cha mẹ thương con chỉ một đời. Phật thương chúng sanh tâm không cùng tận. Lại nữa cha mẹ thấy con vong ân bội nghĩa, thì sinh lòng giận hờn, tình thương giảm xuống. Phật và Bồ Tát thương chúng sanh, lòng không như vậy. Thấy chúng sanh bội nghịch lòng thương của Phật và Bồ Tát càng tăng lên mãi”."],["p","Các Ngài còn vào trong địa ngục Hỏa luân, địa ngục Vô gián mà chịu vô lượng khổ, thế cho chúng sanh."],["p","Vì thế nên biết rằng chư Phật và Bồ Tát thương xót chúng sanh hơn cha mẹ thương con. Vậy mà chúng sanh vì vô minh che lấp trí huệ, phiền não che lấp tâm tánh, đối với Phật và Bồ Tát không biết quay đầu lại mà quy y, không biết ngưỡng mộ. Thuyết pháp giáo hóa, chúng sanh cũng không tin, không chịu mà còn thô lỗ, phỉ báng, chưa từng phát tâm niệm ơn Phật."],["p","Vì chúng sanh không tin nên đọa vào đường ác: Địa ngục, ngạ quỷ, súc sinh; khắp trong ba đường ác ấy, chịu vô lượng khổ."],["p","Tội hết được ra, tạm sinh làm người, tai mắt không đủ, thân thể xấu xa, không tu thiền định, không tu trí huệ."],["p","Chúng sanh có những quả báo chướng ngại như vậy là do không có lòng tin."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng biết tội không tin nặng hơn các tội, khiến người tu hành lâu không thấy Phật."],["p","Hôm nay đại chúng tự phải cùng nhau khắn khái tu hành, chiết ý tỏa tình, sinh tâm tăng thượng, khởi lòng hổ thẹn, cúi đầu cầu xin sám hối tội cũ. Nghiệp lụy hết rồi, trong ngoài thanh tịnh, sau mới vận tâm quay về đức tín, phát lòng tin tưởng Tam Bảo. Nếu không khởi tâm như vậy, vận tưởng như vậy, sợ lòng tin phải cách tuyệt, chướng ngại khó thông. Một khi đã mất nẻo xu hướng, thì mờ mịt không biết về đâu? Vậy thì chúng con không thể không tin mà phải đầu thành đảnh lễ quy y Tam Bảo, không dám nghi ngờ."],["p","Đệ tử chúng con tên... nay nhờ sức từ bi của chư Phật, chư đại Bồ Tát mới mong hiểu biết, rất lấy làm hổ thẹn."],["p","Những tội đã làm nguyện xin trừ diệt."],["p","Những tội chưa làm không dám làm nữa."],["p","Từ nay trở đi, cho đến ngày thành Phật, khởi lòng tin kiên cố, không dám thối lui."],["p","Xả thân này hoặc sinh vào địa ngục, hoặc sinh vào ngạ quỷ, hoặc sinh vào súc sinh, hoặc sinh làm người, hoặc sinh làm trời, ở trong ba cõi, hoặc thọ nam thân, hoặc thọ nữ thân, hoặc thọ phi nam phi nữ thân v.v... hoặc lớn hoặc nhỏ, hoặc lên hoặc xuống, chịu đủ khổ não, không thể chịu nổi, chúng con xin thề: Không vì khổ ấy mà thối mất lòng tin ngày nay."],["p","Thà chịu bao nhiêu khổ lụy trong muôn ngàn ức kiếp, Chúng con xin thề:"],["p","Không vì khổ mà thối mất lòng tin hôm nay."],["p","Nguyện xin chư Phật, chư đại Bồ Tát, đồng gia tâm cứu hộ, đồng gia tâm nhiếp thọ, khiến đệ tử chúng con tên... tín tâm được kiên cố đồng như tâm của chư Phật, đồng như nguyện của chư Phật, tà ma ngoại đạo không thể phá hoại tín tâm của chúng con."],["p","Chúng con cùng nhau chí tâm, một lòng tha thiết, đầu thành đảnh lễ:"],["p","- Quy y mười phương tận hư không giới hết thảy chư Phật."],["p","- Quy y mười phương tận hư không giới hết thảy Tôn Pháp."],["p","- Quy y mười phương tận hư không giới hết thảy Hiền Thánh Tăng."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng hãy lắng lòng mà nghe."],["p","Than ôi! Cõi Trời, cõi người đều huyễn hoặc, thế giới là giả dối."],["p","Do vì huyễn hoặc, không chân thật, nên kết quả cũng không chân thật. Giả dối mong manh nên biến hóa vô cùng."],["p","Kết quả không chơn, sở dĩ phải chìm đắm mãi trong vòng sanh tử. Biến hóa không cùng, sở dĩ phải trôi lăn hoài trong biển ái khổ đau. Thấy chúng sanh đau khổ như vậy, Phật rất thương xót."],["p","Kinh Bi Hoa dạy rằng: “Các vị Bồ Tát thành Phật đều có bổn nguyện”."],["p","Đức Thích Tôn không hiện thân sống ở đời lâu dài, thọ mạng Ngài ngắn ngủi là vì thương chúng sanh cõi này, sống yểu uổng trong nháy mắt rồi chết, như biến hóa, chìm mãi trong biển khổ không ra được. Vì thế nên Phật ở cõi này cứu chúng sanh tệ ác, phải tạm dùng lời cứng rắn khổ khắc, thiết tha mà dạy bảo."],["p","Ngài ở trong biển khổ, cứu độ chúng sanh, chưa từng khi nào không lưu tâm đến sự hoằng hóa, tế độ, lợi ích cho chúng sanh, bằng cách ứng dụng thiện pháp làm phương tiện."],["p","Sở dĩ Kinh Tam Muội dạy rằng: “Tâm chư Phật là tâm Đại từ bi; chỗ tâm từ bi của Phật soi đến là chỗ chúng sanh đau khổ”."],["p","Phật thấy chúng sanh chịu khổ não như tên bắn vào lòng Phật, như phá tròng mắt Phật. Thấy rồi thương xót, tâm không tạm yên. Cho nên Phật muốn diệt khổ ngay cho chúng sanh được an vui."],["p","Lại nữa, trí huệ của chư Phật là trí huệ bình đẳng, nên Phật hóa độ chúng sanh cũng bình đẳng như Đức Thích Tôn ai cũng xưng Ngài là Đấng Bình đẳng."],["p","Ngài dõng mãnh, chịu khổ độ thoát chúng sanh, cho nên biết ân đức Bổn sư rất nặng."],["p","Ngài hay ở trong khổ não thuyết pháp, lợi ích cho hết thảy chúng sanh."],["p","Ngày nay chúng sanh không được giải thoát là vì trước kia không nghe được âm thanh vi diệu của Phật thuyết pháp; về sau không thấy được Phật Niết bàn."],["p","Chúng sanh vì nghiệp chướng ngăn che nên xa cách lòng thương của Phật."],["p","Bây giờ, chúng con hãy cùng nhau sinh tâm thương tiếc. Vì thương tiếc nên thiện tâm nồng hậu, ở trong đau khổ chúng con nhớ ơn chư Phật, kêu cầu thảm thiết, ảo não khóc lóc, chí thành đảnh lễ. Năm vóc sát đất, nguyện vì quốc vương và quyến thuộc của quốc vương, thổ địa, nhân dân, phụ mẫu, sư trưởng, tín thí đàn việt, thiện ác tri thức, chư thiên, chư tiên, thông minh, chánh trực, thiên địa hư không, hộ thế tứ vương, chủ thiện phạt ác, thủ hộ trì chú, ngũ phương long vương, long thần bát bộ, cùng khắp hết thảy chúng sanh vô cùng vô tận trong mười phương mà:"],["p","- Quy y mười phương tận hư không giới hết thảy chư Phật. (1 lạy)"],["p","- Quy y mười phương tận hư không giới hết thảy Tôn pháp. (1 lạy)"],["p","- Quy y mười phương tận hư không giới hết thảy Hiền Thánh Tăng. (1 lạy)"],["p","(Toàn thể đều quỳ chắp tay tâm niệm và tiếp tụng):"],["v",["- Chư Phật đại Thánh tôn,","Thấu rõ hết thảy pháp,","Đạo sư của Trời người,","Cho nên nguyện quy y.","- Tôn Pháp tánh thường trú,","Thanh tịnh Tu đa la","Hay trừ bệnh thân tâm,","Cho nên nguyện quy y.","- Đại địa chư Bồ Tát","Vô trước tứ Sa môn","Hay cứu hết thảy khổ,","Cho nên nguyện quy y.","- Tam Bảo cứu thế gian,","Vì sáu đường chúng sanh,","Con nay xin đảnh lễ,","Quy y thế cho tất cả.","- Từ bi che hết thảy,","Khiến đồng được an vui.","Thương xót cả muôn loài","Chúng con đồng quy y."]],["p","(Mọi người đều đảnh lễ sát đất và tự niệm rằng):"],["p","Nguyện xin hết thảy mười phương Tam Bảo đem từ bi lực, bổn thệ nguyện lực, bất tư nghị lực, vô lượng tự tại lực, độ thoát chúng sanh lực, phù hộ chúng sanh lực, an ủi chúng sanh lực. Đem những năng lực ấy khiến các chúng sanh đều giác ngộ, chúng con tên... ngày nay vì các chúng sanh ấy mà quy y Tam Bảo."],["p","Chúng con xin nhờ công đức này có năng lực khiến các chúng sanh ấy đều được mãn nguyện."],["p","Nếu các chúng sanh ấy hoặc ở trong loài Trời, loài Tiên thì được sạch hết nghiệp hữu lậu."],["p","Nếu các chúng sanh ấy ở trong loài A tu la thì khiến họ xả bỏ tánh kiêu mạn."],["p","Nếu các chúng sanh ấy ở trong loài người thì khiến cho hết khổ đau."],["p","Nếu các chúng sanh ấy ở trong các loài địa ngục, ngạ quỷ, súc sinh thì khiến cho liền được giải thoát."],["p","Lại nữa, ngày nay người nào nghe được danh hiệu của Tam Bảo, và người không nghe được, cũng nhờ thần lực của Phật mà giải thoát, hoàn toàn thành tựu Vô thượng Bồ đề, đồng với các đại Bồ Tát thành bậc Chánh giác."]],"p":"Quyển Thứ Nhất"},{"t":"Chương Thứ Hai Dứt Nghi Ngờ","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lắng lòng mà nghe. Luận rằng:"],["p","Nhân quả ảnh hưởng lẫn nhau, cảm ứng tương sinh; đạo lý tự nhiên như vậy không sai lầm. Nhưng về hạnh nghiệp của chúng sanh, mỗi người một khác không giống nhau, nên quả báo cũng không giống nhau; hoặc tinh thô, hoặc sang hèn, hoặc thiện, hoặc ác sai khác muôn vàn."],["p","Đã có sai khác thì không rõ nguyên nhân sự sai khác ấy do đâu. Vì không rõ nên sinh ra nghi ngờ, lầm lạc. Hoặc nói người tinh tấn tu hành, giữ giới trong sạch, đáng lẽ được sống lâu, sao lại chết sớm."],["p","Người hàng thịt (đồ tể) đáng lẽ chết sớm sao lại sống lâu. Người thanh liêm đáng lẽ được giàu sang, sao lại thấy nghèo thiếu."],["p","Người tham lam trộm cướp, đáng lẽ nghèo thiếu khốn khổ, sao lại giàu có phong lưu!"],["p","Nghi ngờ sai lầm như vậy ai cũng có nghĩ đến không tránh khỏi. Do vì không rõ việc của mình đã làm từ bao kiếp trước, hột giống của mình đã gieo đều không thuần, nên ngày nay đem lại kết quả bất nhất như vậy."],["p","Kinh Bát Nhã dạy rằng: “Nếu người nào đọc tụng kinh này, bị kẻ khác khinh chê, là vì người ấy đời trước có tội nghiệp nặng, đáng đọa vào đường ác. Ngày nay nhờ người khinh chê nên tội nghiệp đời trước được tiêu diệt”."],["p","Bởi chúng sanh không hết lòng thâm tín lời Phật dạy, mới có tâm nghi ngờ."],["p","Chúng sanh bị vô minh mê hoặc, che lấp tâm tánh nên luống sinh tâm nghi ngờ điên đảo như vậy."],["p","Chúng sanh lại cũng không tin: Còn ở trong ba cõi là khổ, ra khỏi ba cõi là vui."],["p","Những người thường say đắm thế gian đều cho đời là vui."],["p","Chúng ta thử hỏi:"],["p","Nếu đời thật là vui, cớ sao trong tâm biết vui ấy lại có tâm biết khổ."],["v",["Ăn uống quá độ liền sinh tật bệnh:","Ban sởi, ho hen, khí tức, cổ trướng, đau đớn, khó chịu.","Nói đến y phục, càng thấy khổ nhiều."]],["p","Lạnh được áo mỏng thì bạc ơn người cho, lòng nghĩ nông nỗi."],["p","Nắng được áo kép, lông chiên, khổ não càng nhiều. Nếu y phục là vui, cớ sao lại sinh khổ não."],["p","Nếu cho gia đình quyến thuộc là vui, lẽ ra cùng nhau vui mãi, hoan lạc ca cười không dứt, cớ sao thoặt vậy vô thường, qua đời trong nháy mắt! Vừa có đó liền không đó. Sớm còn tối mất, kêu trời van đất, can trường đoạn đoạn! Chúng sanh lại cũng không tự biết mình từ đâu đến đây? Chết rồi đi đâu. Người còn khóc kẻ mất, ôm lòng thương xót, tống táng đưa nhau, thẳng đến sơn cùng, chắp tay vĩnh biệt, nhất từ vạn kiếp, đau đớn biết bao!"],["p","Những điều như vậy, sầu khổ vô lượng, chúng sanh mê chấp, cho đó là vui."],["p","Trái lại, gây nhân vui xuất thế, chúng sanh đều cho việc ấy là khổ."],["p","Thấy người trai giới, tương dưa, nuôi thân qua buổi, không mặc lụa là, quen bận phấn tảo ăn mặc nâu sồng, chúng sanh đều cho các việc ấy là tự ép xác, khốn khổ, không biết làm như thế là gây nhân giải thoát, gieo giống an vui."],["p","Hoặc thấy người bố thí, trì giới, nhẫn nhục, tinh tấn, kinh hành, lễ bái, tụng tập chuyên cần, chúng sanh đều cho là khổ; không biết làm như vậy là tu tâm xuất thế, để được an vui."],["p","Thoảng hoặc thấy có người tật bệnh là chết, liền sinh tâm nghi rằng: Người ấy bắt buộc thân tâm này làm việc quá độ, trọn ngày không được tạm nghỉ. Sức lực con người không thể nào kham nổi. Nếu người tu hành không siêng năng khó nhọc thì đâu đến nỗi luống mất thân mạng với việc làm vô ích như vậy."],["p","Hoặc có người chấp chặt lý thuyết của mình, tự cho mình là đúng, chứ không biết suy quả tầm nhân, luống sinh tâm mê chấp, luống làm việc sai lầm."],["p","Nếu may gặp được thiện tri thức thì có thể hết mê lầm. Nếu không may, gặp phải bạn ác thầy tà thì si mê càng lắm."],["p","Nhân vì nghi ngờ mê hoặc nên đọa vào ba đường ác, ở trong ấy, ăn năn không kịp."],["p","Hôm nay đại chúng đồng nghiệp trong đạo tràng nên hiểu rõ."],["p","Phàm nghi ngờ như vậy có vô lượng nhân duyên."],["p","Vả chăng hột giống nghi ngờ lầm lạc ấy, tu hành thoát ra khỏi ba cõi luân hồi còn chưa hết, huống gì thân phàm phu này làm sao trừ ngay cho được. Đời này không lo đoạn trừ, đời sau càng thêm."],["p","Đại chúng cùng nhau vừa mới tu tập, đường hãy còn dài, tự tu khổ hạnh, nên căn cứ vào lời Phật dạy, đúng pháp mà tu, không nên nghi ngờ, từ chối sự mệt nhọc."],["p","Chư Phật Thánh nhân, sở dĩ ra được khỏi sanh tử, đến bờ giải thoát bên kia, là nhờ công tích thiện, nên được quả giải thoát vô ngại tự tại."],["p","Chúng con ngày nay chưa lìa khỏi sanh tử, nghĩ cũng tự đáng thương; làm sao còn ham muốn ở trong đời ác trược này nữa. Nay đây may được tứ đại chưa suy đồi; ngũ phước còn thạnh, tới lui thong thả, động chuyển tự do mà không nỗ lực tu hành, còn đợi gì nữa. Đời trước đã không thấy đạo; đời này cũng luống qua, không chứng ngộ gì, thì đời sau làm sao tế độ chúng sanh."],["p","Xem lại tự tâm, thật cũng đau lòng."],["p","Ngày nay đại chúng chỉ nên khuyên nhau nỗ lực siêng tu, không nên nói rằng, phải có tin tức chứng ngộ gì mới chịu tu tập; vì Phật đạo lâu dài, không thể một mai mà làm xong được. Nếu cứ chờ tin tức, như vậy một mai rồi lại một mai thì biết bao giờ chứng quả."],["p","Nay hoặc có người nhân tụng kinh, ngồi thiền, siêng tu khổ hạnh, hơi có chút tật bệnh liền nói: Vì tụng tập siêng năng khổ hạnh quá nhiều nên sinh bệnh hoạn."],["p","Người nói như thế là vì họ không tự biết."],["p","Nếu họ không làm như vậy thì cũng đã chết sớm mất rồi. Nhờ tu hành có phước đức mới mong sống đến hôm nay."],["p","Vả lại, bốn đại tăng giảm tật bệnh là thường, cho đến già chết còn không thể tránh. Sinh ở thế gian này chung cuộc rồi ai cũng tận số. Nếu muốn được đạo, phải y lời Phật dạy mà tu. Trái lời Phật mà đắc đạo thì không có lẽ ấy."],["p","Chúng sanh vì trái lời Phật nên xoay chuyển trong ba đường chịu đủ thống khổ. Nếu đúng như lời Phật dạy mà tu hành không thôi nghỉ, siêng năng tinh tấn, như cứu lửa cháy đầu, thì đâu đến nỗi một đời luống qua, không có lợi ích gì. Mọi người cùng nhau nhất tâm tha thiết, đầu thành đảnh lễ như Thái Sơn đổ, nguyện vì những người sau đây mà đảnh lễ thế cho họ."],["p","Kể từ khi có tâm thức cho đến ngày nay, cha mẹ nhiều đời, bà con nhiều kiếp, Hòa thượng, A xà lê, đồng đàn tôn chứng, thượng trung hạ tòa, tín thí đàn việt, thiện ác tri thức, chư thiên, chư tiên, hộ thế tứ thiên vương, chủ thiện, phạt ác, thủ hộ trì chú, ngũ phương long vương, long thần bát bộ khắp đến mười phương vô cùng vô tận, hết thảy chúng sanh mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Duy Vệ Phật.","Nam mô Thi Khí Phật.","Nam mô Tùy Diệp Phật.","Nam mô Câu Lưu Tôn Phật.","Nam mô Câu Na Hàm Mâu Ni Phật.","Nam mô Ca Diếp Phật.","Nam mô Thích Ca Mâu Ni Phật","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo, nguyện xin Tam Bảo dùng sức từ bi, đồng gia tâm nhiếp thọ; dùng sức thần thông che chở cứu vớt chúng con; khiến chúng con từ nay trở đi cho đến ngày thành đạo, tứ vô lượng tâm, lục ba la mật thường được hiện tiền, tứ vô ngại trí, lục thần thông lực được như ý tự tại; tu đạo Bồ Tát, vào trí huệ Phật, hóa độ mười phương, thành bậc Chánh giác."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại khéo nhiếp tâm, suy nghĩ cho kỹ: Đã được cùng nhau sinh lòng tin rồi thì nên giữ ý thanh tịnh, lấy điều ấy làm nẻo xu hướng đối với các pháp trong thân ngoài thân chớ cho trở ngại."],["p","Nếu không biết rõ việc lành hay tự mình không thể làm thì lúc thấy người làm việc phước thiện, chỉ nên khuyến khích, chắp tay tán thán công đức của người, không nên sinh tâm trở ngại, khiến người tu hành phải thối chí."],["p","Nếu người không thối chí họ cứ tinh tấn như thường, việc người không giảm, chỉ mình bị tổn phước, luống gây thị phi, đối với bản thân nào có ích gì? Nếu đối với việc lành mình không trở ngại thì có thể gọi là hợp đạo, hữu lực đại nhân. Nếu đời này mình hay trở ngại việc phước thiện của người thì đời sau làm sao thông đạt được Phật đạo."],["v",["Có lý mà suy, tổn hại ấy rất nặng.","Trở ngại thiện căn của người, tội ấy rất lớn.","Như Kinh Hộ Khẩu dạy rằng:"]],["p","Có một Ngạ quỷ thân hình xấu ác, thấy phải rùng mình, không ai không sợ."],["p","Thân xuất lửa dữ như đám cháy lớn."],["p","Trong miệng có sâu dòi rúc ra mãi mãi, máu mủ tanh hôi, đầy cả thân hình, mùi thối bay ra, không ai có thể đến gần."],["p","Miệng khạc ra lửa, thân phần lửa đốt, cất tiếng kêu khóc, tuôn chạy cùng khắp."],["v",["Bấy giờ, có ngài Mãn Túc La Hán hỏi Ngạ quỷ rằng:","- Xưa kia ngươi mắc phải tội gì mà nay chịu khổ như thế?","Ngạ quỷ đáp rằng:"]],["p","- Tôi ngày xưa đã từng làm Sa môn, tham đắm sự nuôi sống, xan tham không bỏ, không giữ oai nghi, nói lời thô ác. Nếu thấy người giữ giới tinh tấn lại liền mắng nhiếc, liếc mắt háy nguýt, ỷ mình giàu mạnh, tưởng sống lâu không chết, tạo ra vô lượng tội ác căn bản. Ngày nay nhớ lại, hối hận cũng không ích gì. Thà cầm dao bén tự cắt lưỡi mình, kiếp này sang kiếp khác, cam tâm chịu khổ, không nên nói một lời phỉ báng việc lành của người."],["p","Nguyện xin ngài trở về dương thế, đem hình trạng xấu ác của tôi răn dạy các thầy Tỳ kheo và các Phật tử, khéo giữ gìn lỗ miệng, chớ buông lời nói ác. Dầu thấy người giữ giới hay không giữ giới cũng nên tuyên dương công đức của người."],["p","Tôi làm quỷ đói đã vài ngàn kiếp, trọn ngày thâu đêm, chịu đủ điều đau khổ. Quả báo này hết rồi lại vào địa ngục."],["p","Bấy giờ, Ngạ quỷ nói lời ấy rồi, cất tiếng kêu khóc, tự gieo mình xuống đất như núi Thái Sơn sụp đổ."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nghe lời kinh dạy như vậy rất đáng sợ hãi."],["p","Chỉ vì lỗi của miệng mà mang tội nhiều kiếp, huống nữa là còn bao nhiêu điều ác khác. Xả thân này thọ thân khác mà chịu khổ đều do nghiệp ác của mình đã làm. Nếu không gây nhân thì làm sao lại có chịu quả. Đã gây nhân quyết định phải chịu trả quả. Tội phước không xa, mình làm mình chịu, như bóng theo hình, không thể rời nhau. Do vô minh mà sinh thì cũng do vô minh mà diệt. Đời này đời sau, bao giờ cũng vậy, chưa từng thấy người tu hành buông lung, lười biếng mà được giải thoát. Trái lại, người hay tinh tấn giữ gìn tu hành, được phước đức vô lượng."],["p","Ngày nay đại chúng đều nên biết hổ thẹn rửa sạch thân tâm, sám hối tội cũ."],["p","Tội cũ hết rồi, không gây thêm tội mới nữa thì được các Đức Phật khen ngợi."],["p","Cùng nhau từ nay trở đi, nếu thấy người làm thiện, chớ nói thành hay không thành, lâu hay không lâu. Dầu cho họ chỉ làm lành trong một niệm, một thời, một khắc, một ngày, một tháng, nửa năm, hay một năm cũng đã hơn người không làm."],["p","Sở dĩ Kinh Pháp Hoa dạy rằng: “Hoặc có người tâm tán loạn vào trong tháp miếu, xưng một câu Nam mô Phật, người ấy cũng đã thành Phật đạo”. Huống nữa có người phát tâm rộng lớn, siêng làm phước thiện. Nếu chúng ta không tùy hỷ thì Thánh nhân rất thương xót."],["p","Chúng con tên... tự nghĩ mình từ vô thỉ trở lại cho đến ngày nay lẽ ra cũng đã có vô lượng ác tâm trở ngại việc lành tốt đẹp của người. Vì sao mà biết? Nếu không như vậy, cớ sao ngày nay việc lành của chúng con phần nhiều hay bị trở ngại."],["p","Thiền định không hay tập, trí huệ không hay tu. Vừa mới lễ bái liền nói khổ lắm."],["p","Vừa cầm đến kinh liền sinh nhàm chán."],["p","Trọn ngày chỉ ưa khó nhọc làm các nghiệp ác khiến cho thân này không được giải thoát, như tằm kéo kén, tự ràng, tự buộc, như phù du vào lửa, tự thiêu tự đốt."],["p","Những chướng ngại ấy vô lượng vô biên, chướng Bồ đề tâm, chướng Bồ đề nguyện, chướng Bồ đề hạnh, chướng ngại như vậy đều do ác tâm, phỉ báng việc thiện của người. Nay mới giác ngộ, rất là hổ thẹn, cúi đầu cầu xin sám hối tội ấy."],["p","Nguyện xin chư Phật, chư Đại Bồ Tát, đem lòng từ bi, đồng gia thần lực khiến đệ tử tên... những điều sám đều được trừ diệt, những điều hối đều được thanh tịnh. Vô lượng chướng ngại, vô lượng tội nghiệp đều nhờ sám hối này mà được sạch hết."],["p","Mọi người cùng nhau nhất tâm thống thiết năm vóc sát đất, quy y thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Thiện Đức Phật.","Nam mô Vô Ưu Đức Phật.","Nam mô Chiên Đàn Đức Phật.","Nam mô Bảo Thí Phật.","Nam mô Vô Lượng Minh Phật.","Nam mô Hoa Đức Phật.","Nam mô Tướng Đức Phật.","Nam mô Tam Thừa Hạnh Phật.","Nam mô Quảng Chúng Đức Phật.","Nam mô Minh Đức Phật.","Nam mô Sư Tử Du Hí Bồ Tát.","Nam mô Sư Tử Phấn Tấn Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại xin quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","(Cùng nhau quỳ gối chắp tay, tâm niệm và tụng tiếp):"],["p","Đệ tử chúng con tên... từ vô thỉ trở lại cho đến ngày nay, chưa thể đắc đạo, thọ lấy báo thân này vì tham bốn món cúng dường chưa từng xả bỏ. Tham sân tật đố, ba độc hừng hẫy sinh ra các ác nghiệp. Thấy người bố thí, trì giới, tự mình không thể làm, không hay tùy hỷ."],["p","Thấy người nhẫn nhục tinh tấn, tự mình không thể làm, không hay tùy hỷ. Thấy người tọa thiền, tu nghiệp trí huệ, tự mình không thể làm, không hay tùy hỷ."],["p","Những tội như vậy, vô lượng vô biên ngày nay sám hối, nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay, thấy người làm lành, tu các công đức không hay tùy hỷ, đi đứng nằm ngồi, trong bốn oai nghi ấy không biết hổ thẹn, không nghĩ vô thường, không biết xả thân này phải vào địa ngục."],["p","Đối với sắc thân người khác, khởi ra điều ác. Chướng ngại người xây dựng và cúng dường Tam bảo, chướng ngại người tu tập hết thảy công đức."],["p","Tội chướng như vậy vô lượng vô biên ngày nay sám hối, nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay không tin Tam Bảo là chỗ quy y, chướng ngại người xuất gia, chướng ngại người trì giới, chướng ngại người bố thí, chướng ngại người nhẫn nhục, chướng ngại người tinh tấn, chướng ngại người tọa thiền, chướng ngại người tụng kinh, chướng ngại người làm chay, chướng ngại người tạo tượng, chướng ngại người cúng dường, chướng ngại người khổ hạnh, chướng ngại người hành đạo, cho đến mảy may việc thiện của người chúng con cũng chướng ngại. Không tin xuất gia là pháp viễn ly, không tin nhẫn nhục là hạnh an lạc, không biết bình đẳng là đạo Bồ đề, không biết xa lìa vọng tưởng là tâm xuất thế. Vì những tội ấy cho nên ngày nay sinh ra nơi nào cũng gặp nhiều chướng ngại. Tội chướng như vậy, vô lượng vô biên, chỉ có chư Phật, chư Đại Bồ Tát mới thấy hết biết hết."],["p","Như chỗ chư Phật và Bồ Tát đã thấy đã biết, tội lượng nhiều ít, ngày nay hổ thẹn, tỏ bày sám hối, tất cả tội nhân, khổ quả, nguyện xin trừ diệt. Từ nay trở đi cho đến ngày thành đạo tu đạo Bồ Tát, không biết nhàm chán. Tài thí, pháp thí không cùng, không tận, trí huệ phương tiện làm gì cũng được. Hết thảy người thấy, người nghe đều được giải thoát."],["p","Chúng con cùng nhau chí tâm, đầu thành đảnh lễ, năm vóc sát đất nguyện xin mười phương hết thảy chư Phật, chư Đại Bồ Tát hết thảy Hiền Thánh, rũ lòng từ bi, đồng gia thần lực, làm cho hết thảy chúng sanh trong sáu đường, nhờ sức sám hối này mà đoạn trừ được hết thảy tội khổ, xa lìa được hết thảy duyên điên đảo, không sinh ác tâm, xả nghiệp bốn thú phát sanh trí huệ, tu đạo Bồ đề không thôi không nghỉ; hạnh nguyện chóng viên mãn, mau lên ngôi Thập địa, vào tâm Kim cang thành Đẳng Chánh giác."]],"p":"Quyển Thứ Nhất"},{"t":"Chương Thứ Ba Sám Hối","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lắng tai nghe kỹ lời kinh dạy sau đây:"],["p","Còn phàm phu thì gọi là buộc. Đã chứng quả Thánh thì gọi là giải."],["p","Buộc tức là kết quả ác do hành động bạo ác của ba nghiệp ác đã gây ra. Giải tức là quả báo lành vô ngại giải thoát của ba nghiệp lành đã gây ra."],["p","Hết thảy Thánh nhân đều để lòng nơi đạo giải thoát, và nhờ thần thông trí huệ, vô lượng pháp môn, nên Thánh nhân thấy hết thảy nghiệp báo thiện hay ác của tất cả chúng sanh."],["p","Các ngài hay dùng một thân hiện ra vô lượng thân, hay dùng một hình hiện ra vô lượng hình; có thể rút ngắn một kiếp làm một ngày; có thể kéo dài một ngày làm một kiếp. Muốn đình thọ mạng thì vĩnh viễn không diệt độ; muốn thị hiện vô thường thì nhập Niết bàn; thần thông trí huệ, vào ra tự tại bay đi tùy ý, ngồi nằm trên không. Đi đứng dưới nước như ở trên khô, không thấy nguy hiểm. Lấy cảnh vắng lặng, viên tịch Niết bàn làm chỗ nghỉ ngơi, thông đạt vạn pháp, có, không đều rõ biết, biện tài thành tựu, trí huệ vô ngại."],["p","Những pháp lành ấy không phải từ trong nghiệp ác mà ra, không phải từ trong tham sân tật đố mà ra, không phải từ trong ngu si tà kiến mà ra, không phải từ trong lười biếng mà ra, không phải từ trong kiêu mạn, tự cao tự đại mà ra. Các pháp lành ấy chỉ trừ trong sự thận trọng không làm ác mà ra, các pháp lành ấy đều do các nghiệp lành mà ra."],["p","Không nơi nào có người tu các nghiệp lành, vâng lời Phật dạy mà mắc phải ác báo, bần cùng xấu xa tàn tật, bệnh hoạn, không được tự do, thấp hèn bị kẻ khác khinh chê, lời nói không ai tin dùng bao giờ."],["p","Nay đem thân tôi để làm chứng (lời tác giả). Nếu có người nào vâng lời Phật dạy, tu các công đức, không ích kỷ hại nhân mà bị quả báo xấu ác thì thà để tôi bị đọa vào A tỳ địa ngục chịu thống khổ, chớ để cho người làm lành kia chịu quả báo xấu ác thì phi lý."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng muốn bỏ phàm làm Thánh thì nên y lời Phật dạy, như lý mà tu hành. Không nên từ chối một việc khổ nhỏ mà sinh tâm lười biếng nên tự nỗ lực cố gắng sám hối cho tiêu tội lỗi."],["p","Trong kinh Phật dạy: “Tội do nhân duyên mà sinh thì cũng do nhân duyên mà diệt”."],["p","Đang còn thân phàm thì gặp cảnh sinh mê tâm. Vậy ngoài phương pháp sám hối ra, không có phương pháp nào hơn nữa để mong giải thoát."],["p","Ngày nay đại chúng phải cùng nhau phát khởi tâm dõng mãnh, phát khởi ý sám hối."],["p","Sức mạnh của pháp sám hối không thể nghĩ bàn. Vì sao mà biết? Vì vua A Xà Thế phạm đại tội ngũ nghịch, nhưng sau vua biết sinh tâm hổ thẹn, tự trách, tự ăn năn, nên tội nặng thành nhẹ."],["p","Vả lại pháp sám hối này khiến người tu hành được an vui. Nếu có người nào tự mình hay định thời khóa, nỗ lực hết lòng, khấu đầu lễ bái, sám hối, quy y cho đến khi hoàn toàn trong sạch mà không cảm được mười phương Phật thì không có lý."],["p","Ác nghiệp và quả báo theo nhau, ảnh hưởng lẫn nhau, không sai mảy may, cho nên phải hết lòng sợ hãi, cố gắng chịu khổ mà sám hối."],["p","Mọi người đều nên một lòng tha thiết gieo mình xuống đất như núi Thái Sơn sụp đổ, tâm niệm miệng nói lời này, để cầu thỉnh mười phương chư Phật gia tâm thương xót."],["p","Nguyện xin chư Phật cứu chúng con ra khỏi khổ ách; rũ lòng đại bi che khắp tất cả. Phóng hào quang thanh tịnh, soi khắp mười phương; diệt sạch mê mờ và trừ si ám. Nghĩ đến chúng con và các chúng sanh đang bị đọa đày trong địa ngục đau khổ. Xin Phật đến đây cứu vớt chúng con. Ban bố hạnh phúc cho chúng con được thoát khổ."],["p","Chúng con nhất tâm đầu thành đảnh lễ đấng Đại Từ bi, nghe tên liền cứu khổ."],["v",["Nay chúng con nhất tâm quy y đấng Thế gian Đại Từ Bi Phụ.","Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Kim Cang Bất Hoại Phật.","Nam mô Bảo Quang Phật.","Nam mô Long Tôn Vương Phật.","Nam mô Tinh Tấn Quân Phật.","Nam mô Tinh Tấn Hỷ Phật.","Nam mô Bảo Hỏa Phật.","Nam mô Bảo Nguyệt Quang Phật.","Nam mô Hiện Vô Ngu Phật.","Nam mô Bảo Nguyệt Phật.","Nam mô Vô Cấu Phật.","Nam mô Ly Cấu Phật.","Nam mô Sư Tử Phan Bồ Tát.","Nam mô Sư Tử Tác Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo, nguyện xin Tam Bảo quyết định đến đây cứu vớt chúng con, đang bị đọa đày bởi tham sân si, làm đau khổ, nguyện cho chúng con được an vui và được đại Niết bàn; nguyện xin lấy nước đại bi tẩy trừ tội lỗi cho chúng con được thanh tịnh mau chứng quả Bồ đề. Bốn loài chúng sanh trong sáu đường, nếu có một chúng sanh nào mắc phải tội lỗi, đều được nhờ Tam Bảo mà thanh tịnh; đều được thành tựu quả Vô thượng bồ đề, thành bậc Chánh giác, hoàn toàn giải thoát."],["p","Đại chúng cùng nhau một lòng tha thiết, đầu thành đảnh lễ, tâm niệm miệng nói lời này:"],["p","Đệ tử chúng con tên... từ vô thỉ trở lại cho đến ngày nay, bị vô minh che lấp tâm tánh, bị ái nhiễm ràng buộc, nên tinh thần sa vào lưới ngu si, loanh quanh ba cõi, cùng khắp sáu đường, chìm đắm bể khổ, không có ngày ra; không thể biết được nghiệp đời trước của mình, không thể hiểu được nhân duyên đã qua. Hoặc mình tự phá tịnh mạng và phá tịnh mạng của người. Mình tự phá phạm hạnh và phá phạm hạnh của người. Mình tự phá tịnh giới và phá tịnh giới của người."],["p","Tội ác như vậy vô lượng vô biên, ngày nay hổ thẹn sám hối nguyện xin trừ diệt."],["p","Đệ tử chúng con tên... lại chí thành đảnh lễ sát đất cầu xin sám hối, những tội lỗi từ vô thỉ trở lại cho đến ngày nay, do thân khẩu ý tạo ra mười ác nghiệp."],["p","Thân sát, đạo, dâm, miệng nói láo, nói lời thêu dệt, nói lời hai lưỡi, nói lời độc ác, ý tham sân si. Mình tự làm mười điều ác, dạy người làm mười điều ác, khen ngợi người làm mười điều ác. Như vậy trong một khoảnh khắc trong một niệm tâm, khởi ra bốn mươi điều ác."],["p","Những tội như thế vô lượng vô biên, ngày nay sám hối, nguyện xin trừ diệt."],["p","Đệ tử chúng con tên... lại chí thành đảnh lễ sát đất cầu xin sám hối những tội từ vô thỉ trở lại cho đến ngày nay."],["p","Nương nơi sáu căn rồi phát ra sáu thức, chấp lấy sáu trần. Mắt đắm sắc, tai ưa tiếng, mũi trước hương, lưỡi ưa vị, thân ưa trơn láng, mịn màng, ý ưa pháp trần. Sáu căn ấy sinh ra bao nhiêu tội nghiệp, mở cửa cho tám vạn bốn ngàn trần lao. Tội ác như vậy vô lượng vô biên ngày nay sám hối nguyện xin trừ diệt."],["p","Đệ tử chúng con tên... lại chí thành đảnh lễ, cầu xin sám hối những tội từ vô thỉ trở lại cho đến ngày nay, do thân, khẩu, ý gây ra nhiều nỗi bất bình, như chỉ biết có thân mình, không biết có thân người, chỉ biết có mình khổ, không biết có người khổ, chỉ biết có mình cầu an vui, không biết có người cầu an vui, chỉ biết có mình cầu giải thoát, không biết có người cầu giải thoát, chỉ biết có gia đình mình, có quyến thuộc mình, không biết có gia đình người, có quyến thuộc người, chỉ biết thân mình hơi ngứa một chút, hơi đau một chút đã chịu không nổi, thế mà khi làm cho thân người khác đau thì sợ họ không đau, ít đau, không thấm thía, chỉ biết sợ khổ một chút nơi đời hiện tại mà không biết sợ khổ vô lượng kiếp nơi đời vị lai. Bởi vì làm ác chết rồi phải đọa vào địa ngục, chịu đủ thống khổ, cho đến không biết sợ khổ vô lượng trong đường ngạ quỷ, trong đường súc sanh, trong đường A tu la."],["p","Cõi người và cõi trời cũng có vô lượng thống khổ mà không tự biết, chỉ vì tâm không bình đẳng, có phân bỉ ngã, có niệm oán thân, làm cho oán thù tràn khắp lục đạo."],["p","Những tội như vậy vô lượng vô biên, ngày nay sám hối, nguyện xin trừ diệt."],["p","Đệ tử chúng con tên... lại chí thành đảnh lễ cầu xin sám hối những tội từ vô thỉ trở lại cho đến ngày nay, do tâm điên đảo, do tưởng điên đảo, thấy biết điên đảo, nên thường xa lìa bạn lành (thiện tri thức) gần gũi bạn ác, trái nghịch bát chánh đạo, tu theo bát tà đạo, phi pháp nói chánh pháp, chánh pháp nói phi pháp, bất thiện nói là thiện, thiện nói là bất thiện, dựng cờ kiêu mạn, giăng buồm ngu si, theo dòng vô minh vào biển sanh tử."],["p","Những tội như vậy vô lượng vô biên ngày nay sám hối nguyện xin trừ diệt."],["p","Đệ tử chúng con tên... lại chí thành đảnh lễ cầu xin sám hối những tội từ vô thỉ trở lại cho đến ngày nay, vì tham sân si khởi ra bốn điên đảo, tạo nên năm tội nghịch, làm đủ mười ác, ba độc hừng hẫy, tâm khổ càng nhiều, gieo giống địa ngục bát hàn, bát nhiệt; gieo giống tám vạn bốn ngàn ngăn cách địa ngục, gieo giống súc sanh, gieo giống ngạ quỷ, gieo giống sinh già bệnh chết, ưu bi khổ não ở cõi trời cõi người để chịu quả báo đau khổ, không thể kể xiết, không thể chịu được, không thể thấy được, không thể nghe được."],["p","Những tội ác như vậy, vô lượng vô biên, ngày nay sám hối, nguyện xin trừ diệt."],["p","Đệ tử chúng con tên... lại chí thành đảnh lễ cầu xin sám hối những tội từ vô thỉ kiếp trở lại cho đến ngày nay, vì ba độc tham sân si ở trong ba cõi, trải khắp hai mươi lăm loài khởi ra các tội ác, cùng khắp mọi nơi, thuận chiều gió nghiệp mà không tự biết. Hoặc chướng ngại người trì giới, tu định, tu huệ, tu các công đức, tu các thần thông. Những tội chướng như vậy vô lượng vô biên, chướng Bồ đề tâm, chướng Bồ đề nguyện, chướng Bồ đề hạnh, ngày nay sám hối nguyện xin trừ diệt."],["p","Đệ tử chúng con tên... lại chí thành đảnh lễ cầu xin sám hối những tội từ vô thỉ kiếp trở lại cho đến ngày nay, vì tâm tham sân si, phát khởi ra sáu thức, duyên theo sáu trần, gây tội cho chúng sanh."],["p","Hoặc đối với chúng sanh mà khởi tội; hoặc đối với phi chúng sanh mà khởi tội; hoặc đối với người vô lậu mà khởi tội; hoặc đối với pháp vô lậu mà khởi tội."],["p","Những tội ác như vậy vô lượng vô biên, ngày nay sám hối nguyện xin trừ diệt."],["p","Lại nữa, chúng con vì tâm ngu si mà khởi hạnh điên đảo, tin theo thầy tà, thọ lời tà giáo, chấp đoạn, chấp thường, trước ngã, trước kiến, làm theo si mê, khởi ra vô lượng tội lỗi."],["p","Những nhân duyên ấy chướng Bồ đề tâm, chướng Bồ đề nguyện, chướng Bồ đề hạnh, ngày nay sám hối nguyện xin trừ diệt."],["p","Đệ tử chúng con tên... lại chí thành đảnh lễ cầu xin sám hối những tội từ vô thỉ kiếp trở lại cho đến ngày nay, thân ba nghiệp ác, miệng bốn nghiệp ác, ý ba nghiệp ác, vô thỉ vô minh trú địa phiền não, hằng sa thượng phiền não, chỉ thượng phiền não, quán thượng phiền não, tứ trú địa phiền não, tam độc, tứ thủ, ngũ cái, lục thọ, thất lậu, bát cấu, cửu kiết, thập sử. Những phiền não ấy vô lượng vô biên, hay chướng Bồ đề tâm, hay chướng Bồ đề nguyện, hay chướng Bồ đề hạnh, ngày nay sám hối, nguyện xin trừ diệt."],["p","Đệ tử chúng con tên... lại chí thành đảnh lễ cầu xin sám hối những tội từ vô thỉ kiếp trở lại cho đến ngày nay, không hay tu tâm từ bi, không hay tu tâm hỷ xả, không hay tu tâm bố thí, không hay tu tâm trì giới, không hay tu tâm nhẫn nhục, không hay tu tâm tinh tấn, không hay tu tâm thiền định, không hay tu tâm trí huệ, không hay tu hết thảy pháp trợ Bồ đề."],["p","Vì thế, nếu không có phương tiện, không có trí huệ, làm chướng ngại Bồ đề tâm, chướng ngại Bồ đề nguyện, chướng ngại Bồ đề hạnh, ngày nay sám hối, nguyện xin trừ diệt."],["p","Đệ tử chúng con tên... lại chí thành đảnh lễ cầu xin sám hối những tội từ vô thỉ kiếp cho đến ngày nay, vì tội nghiệp nên cứ xoay vòng trong ba cõi, trải khắp sáu đường, thọ thân bốn loài, hoặc nam hoặc nữ, hoặc phi nam phi nữ, cùng khắp mọi nơi tạo vô lượng tội. Hoặc làm chúng sanh thân hình to lớn ăn nuốt lẫn nhau; hoặc làm chúng sanh thân hình bé nhỏ ăn nuốt lẫn nhau. Những tội sát hại như vậy vô lượng vô biên hay chướng Bồ đề tâm, hay chướng Bồ đề nguyện, hay chướng Bồ đề hạnh. Ngày nay sám hối nguyện xin trừ diệt."],["p","Đệ tử chúng con tên... lại chí thành đảnh lễ cầu xin sám hối những tội từ khi có tâm thức trở lại cho đến ngày nay, ở trong sáu đường, thọ thân bốn loài. Ở trong bốn loài ấy tạo ra vô lượng vô biên tội ác."],["p","Những tội ác như vậy, chỉ có hết thảy chư Phật, chư đại Bồ Tát trong mười phương mới thấy hết biết hết. Tội lượng nhiều ít hoặc khinh hoặc trọng như chư Phật và Bồ Tát đã thấy đã biết. Ngày nay chí thành cúi đầu đảnh lễ, hổ thẹn cầu xin sám hối."],["p","Những tội đã làm, nguyện tiêu diệt hết, những tội chưa làm, không dám phạm."],["p","Ngày nay chúng con nguyện xin hết thảy chư Phật trong mười phương rũ lòng đại từ cho đệ tử chúng con tên... thành tâm sám hối, nguyện xin đem nước đại bi rửa sạch tội lỗi sai lầm cho chúng con được hoàn toàn thanh tịnh, thẳng đến đạo tràng không bị chướng ngại nữa."],["p","Lại nguyện xin hết thảy mười phương chư Phật dùng bất tư nghị lực, bổn thệ nguyện lực, độ thoát chúng sanh lực, phù hộ chúng sanh lực, khiến đệ tử tên... ngày nay khởi thệ nguyện, phát tâm Bồ đề."],["p","Từ nay trở đi cho đến ngày thành Phật kiến lập đạo tâm được kiên cố, hoàn toàn không trở lại sa đọa nữa."],["p","Những lời thệ nguyện của chúng con cũng đồng như lời thệ nguyện của chư Phật, chư đại Bồ Tát đã thật hành thệ nguyện. Nguyện xin hết thảy mười phương chư Phật, chư đại Bồ Tát đồng rũ lòng từ bi, đồng gia tâm nhiếp thọ cho chúng con tên... được như sở nguyện, mãn Bồ đề nguyện. Hết thảy chúng sanh cũng đều được như sở nguyện, mãn Bồ đề nguyện."]],"p":"Quyển Thứ Nhất"},{"t":"Cuối Quyển Nhất","b":[["v",["Lương Hoàng Bảo Sám,","Võ Đế lưu nhân,","Hy Thị phu nhân đọa xà thân,","Cứu bạt xuất pháp tân,","Thể tập kinh văn,","Khể thủ lễ Năng Nhân."]],["v",["Lương Hoàng Bảo Sám,","Vạn đức hồng danh,","Linh văn nhất quyển tối hoằng thâm, Tự tự miễn tai truân,","Đảnh lễ Phật danh,","Tiêu tai bảo an ninh.","Nam mô Hoan Hỷ Địa Bồ Tát Ma Ha Tát. (3 lần)"]],["h","Cung Văn"],["p","Thiên thượng nhân gian Chánh Biến Tri Giác, quang siêu nhật nguyệt, đức việt thái hư, vô khứ vô lai, ẩn ẩn thường cư hoa tạng giới. Bất sinh bất diệt, nguy nguy tọa đoạn Niết bàn thành. Ứng vật hiện hình, tùy cơ phó cảm, nhược hồng chung chi đại khấu, tợ không cốc dĩ truyền thanh. Nguyện thùy vô cực chi đại bi, giám thử nhất thời chi Phật sự."],["p","Thượng lai phụng vì cầu sám đệ tử... đẳng, tu sùng Từ Bi Đạo Tràng Sám Pháp, kim đương đệ nhất quyển, công đức khắc hài viên mãn ư nội, tu thiết đàn tràng, phô thư cám tượng; đăng nhiên hỏa thọ, hương phún trầm đàn, tán ngũ sắc chi danh hoa, hiến thời tân chi diệu quả. Ca dương phạm bối, xưng tán hồng danh, hành đạo nhập thiền, phúng kinh trì chú, sở tập công đức, chuyên thân hồi hướng:"],["p","Thường Trú Chân Từ Tam Bảo hội hạ, Hộ pháp chư thiên, thượng trung hạ giới thần kỳ, viễn cận vô biên linh huống. Phổ Hiền giám thử công đức, hàm sinh hoan hỷ chi tâm, lưu ân trạch ư thiên thượng nhân gian. Tuyên hóa nhật ư thử phương tha giới; viên mãn đạo tràng, xuất sinh thù lợi."],["p","Thiết niệm kim thời cầu sám, đệ tử... đẳng, sám thích tội khiên, nghinh tường tập phước, cầu sinh Tịnh độ."],["h","Phục Nguyện"],["p","Nhất sinh tội cấu băng tiêu, nhất thế nghiệp duyên tuyết tịnh, nhất tâm giải ngộ, hướng nhất lý chi Chân như. Nhất niệm hồi quang, tháo nhất thừa chi diệu đạo. Chuyển khổ duyên nhi thành lạc cụ, sái nhiệt não dĩ tác thanh lương; tổ nể tôn thân, quyết định vãng sinh ư Tịnh độ."],["p","Hiệp môn nhân quyến, phương đương vĩnh hưởng ư hà linh; đẳng oan thân nhi cộng mộc ân ba, dự phàm Thánh nhi đồng tê Bảo địa."],["p","Kim tắc y văn sám hối, do khủng vi tế tội nghiệp nan đào, tái lao Tôn chúng đồng cầu sám hối."],["p","Nam mô Sám Hối Sư Bồ Tát Ma Ha Tát. (3 lần)"],["p","(Nếu có sớ hay biểu thì hỏa hóa)"],["p","Lương Hoàng Bảo Sám nhất quyển công đức lực, nguyện diệt đệ tử... đẳng nhất thiết tội chướng, thân chứng Bồ Tát Hoan Hỷ Địa."],["v",["Sám văn cử xứ, tội hoa phi,","Giải liễu oan, sám liễu tội,","Tiêu tai tăng phước huệ,","Thoát khổ sinh Đao Lợi.","Giải liễu oan, sám liễu tội,","Tiêu diêu trực nhập Long Hoa hội,","Long Hoa tam hội nguyện tương"]],["v",["phùng, Di Lặc Phật tiền thân thọ ký.","Nam mô Long Hoa Hội Bồ Tát Ma Ha Tát. (3 lần)","Hồi đàn tán:","Lương Hoàng Bảo Sám,","Nhất quyển dĩ toàn châu,","Hồi hướng tứ ân tịnh tam hữu,"]],["p","Bái sám chúng đẳng tăng phước thọ, Nguyện tương pháp thủy tẩy khiên"],["p","vưu, Duy nguyện vong giả vãng Tây du."],["p","Hoan Hỷ Địa Bồ Tát duy nguyện ai"],["v",["nạp thọ.","Nam mô Đăng Vân Lộ Bồ Tát Ma Ha Tát. (3 lần)"]],["p","Hồi hướng Tịnh độ:"],["p","Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh..."],["h","Cảm Rơi Nước Mắt"],["p","Vào khoảng tháng 10 năm 1961, bộ Lương Hoàng Sám dịch nghĩa này về đến Huế, các Phật tử cố đô hân hoan đón mừng như nước ngọc Xá Lợi của chư Phật. Thượng tọa, Tọa chủ chùa Châu Lâm Huế cùng hơn sáu mươi Phật tử tại gia lập đàn bái sám tại chùa ngài. Trong lúc đang tụng, bỗng nhiên mọi người trong đạo tràng lớn tiếng khóc òa, vì không ngăn được nỗi lòng rung cảm. Đọc đến những đoạn văn diễn tả nỗi thăng trầm của chúng sanh chìm đắm vào ra trong lục đạo, chịu đủ khổ não với kiếp luân hồi mà bi tâm xúc động. Khi nghĩ đến bản thân mình, và bà con xa gần trong pháp giới 10 phương đang chịu đọa đày hình phạt, hoặc cảm xúc vì lời Phật dạy thiết tha với giáo lý thâm huyền mà cả đạo tràng không ngăn được dòng lệ."],["p","Sau khi đạo tràng hoàn mãn, các Phật tử cung thỉnh Thượng tọa chứng minh cho họ lập \"Ban Lương Hoàng Sám\" để cùng nhau kết bạn tu hành."],["p","Thường năm đến ngày an cư kiết hạ của chư Tăng, hay lúc nào cần bái sám thì cùng nhau về Chùa Châu Lâm lập đàn tràng tụng niệm."],["p","Đạo hữu PHẠM ĐĂNG TÙNG tường thuật."],["v",["Hiệu Chính: HT. THÍCH TRÍ TỊNH","Dịch Giả: HT. THÍCH VIÊN GIÁC"]]],"p":"Quyển Thứ Nhất"},{"t":"Đầu Quyển Hai","b":[["v",["Hoa phụng hiến Văn Thù cộng Phổ","Hiền, Mẫu đơn thược dược chân kham","tiến, Bách hoa hiến thượng huỳnh kim","điện, Hoa khai hoa tạ đính kim liên,","Thanh y đồng tử đặc thân đổ Từ Tôn"]],["v",["diện.","Nam mô Phổ Hiền Vương Bồ Tát Ma Ha"]],["p","Tát. (3 lần)"],["h","Cung Văn"],["p","Dục đắc nhân pháp chi lưỡng không, tu chứng nhị nghiêm chi cực quả, ký minh chân tục chi nhị đế; tấc liễu sanh tử chi vọng duyên, Long thần bát bộ dĩ tham tùy, u hiển linh thông nhi mật hựu. Hung tạng đề ư vạn tự, túc luân ấn ư thiên hoa."],["p","Duy Phật đức dĩ nan thù, dục tán dương nhi mạc cực. Bất vi bổn thệ phổ lợi hữu tình, cao phu bách bảo chi liên đài, giám thử nhị thời chi Phật sự."],["p","Kim thời sám đệ tử đẳng khởi kiến Từ Bi Đạo tràng Sám Pháp. Kim đương đệ nhị quyển, nhập đàn duyên khởi. Ngã chư chúng đẳng... tuyết thanh tam nghiệp, băng khiết lục căn phần đâu lâu bà, tán phân đà lợi, diện phụng thập phương chí thánh xưng dương chư Phật hồng danh; sái trích trích chi cam tuyền, đản ban ban chi tội cấu."],["p","Thiết niệm cầu sám đệ tử đẳng... viễn tùng khoáng kiếp, chí ư kim sanh, nhị chướng oanh triền, tục chư sanh tử."],["p","Nhị không vị ngộ, bột khởi ái tăng, tùy tà kiến chi nhị biên, tuần khổ lạc chi nhị đạo. Vô minh dón khởi dâm sát đạo vọng nhi niệm niệm thiên lưu. Phiền não nhật tăng, thân khẩu ý nghiệp nhi trùng trùng tạo tội. Huống thăng trầm chi giao báo, tợ cấp tỉnh luân. Duy nghiệp quả chi chiếu nhiên, như ác xoa tụ. Phỉ giả khẩn tu ư sám địch, hà do miễn ly ư khiên vưu. Do thị ý khởi kiền thành, tâm hoài tàm quý."],["p","Dĩ thử hiện tiền chi cảnh phước, vĩnh vi diệt tội chi lương quy, ngã nguyện như tư, Phật tất ai lân, ngưỡng khấu hồng từ, minh huân gia bị."],["v",["Phật diện do như tịnh mãn nguyệt,","Diệc như thiên nhật phóng quang"]],["p","minh, Viên quang phổ chiếu ư thập"],["p","phương, Hỷ xả từ bi giai cụ túc."],["p","Khởi vận Từ Bi Đạo Tràng Sám Pháp, nhất tâm quy mạng Tam thế chư Phật:"],["v",["Nam mô Quá Khứ Tỳ Bà Thi Phật,","Nam mô Thi Khí Phật,","Nam mô Tỳ Xá Phù Phật,","Nam mô Câu Lưu Tôn Phật,","Nam mô Câu Na Hàm Mâu Ni Phật,","Nam mô Ca Diếp Phật,","Nam mô Bổn Sư Thích Ca Mâu Ni"]],["p","Phật, Nam mô Đương Lai Hạ Sanh Di Lặc"],["p","Tôn Phật."]],"p":"Quyển Thứ Hai"},{"t":"Chương Thứ Tư Phát Bồ Đề Tâm","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đã cùng nhau rửa sạch tâm ô uế rồi, thập ác, trọng chướng không còn, nghiệp lụy đã hết, trong ngoài đều thanh tịnh."],["p","Thứ lại xin học các vị Bồ Tát tu hành trực đạo, công đức trí huệ do đó mà sinh."],["p","Bởi vậy, chư Phật thường khen ngợi sự phát tâm là đạo tràng, vì hay thành tựu được đạo quả vậy."],["p","Nguyện xin đại chúng đều nên kiên tâm trì chí, chớ tưởng sống lâu là đợi ngày lậu tận chớ luống qua, sau ăn năn không kịp."],["p","Bây giờ đã cùng nhau gặp thời buổi tốt, ngày đêm chớ để phiền não che lấp tâm tánh, phải nên nỗ lực phát tâm Bồ đề."],["p","Tâm Bồ đề tức là tâm Phật, công đức trí huệ vô lượng, không thể nghĩ bàn."],["p","Phát tâm một niệm còn được công đức như vậy huống gì phát tâm luôn luôn."],["p","Giả sử lịch kiếp tu hành vô lượng phước đức, làm đủ hết thảy việc lành, không bằng một niệm phát tâm Bồ đề trong muôn một. Toán số thí dụ cũng không thể so lường được công đức phát tâm Bồ đề."],["p","Lại như có người chỉ làm việc phước đức chớ không phát tâm Vô thượng Bồ đề; người ấy cũng như kẻ cày ruộng không gieo giống. Mầm mống đã không gieo thì làm sao có lúa thóc."],["p","Vì lý do ấy nên phải phát tâm Bồ đề để làm nhân duyên cho việc chứng quả; trước là báo ơn chư Phật, sau là cứu vớt muôn loài."],["p","Sở dĩ Phật khen ngợi các Thiên tử rằng: “Lành thay! Lành thay! Như lời các ngươi nói là vì muốn lợi ích cho hết thảy chúng sanh”."],["p","Phát tâm Bồ đề là cách cúng dường lớn hơn tất cả."],["p","Phát tâm Bồ đề, không phải chỉ phát qua một phen mà phải phát luôn luôn, làm cho tâm Bồ đề tương tục rộng lớn mãi mãi. Vì thế nên trong kinh Phật dạy rằng:"],["p","“Ở nơi chỗ Na do tha hằng hà sa số Đức Phật phát đại thiện nguyện”."],["p","Vậy nên biết số phát tâm ấy là vô lượng."],["p","Lại nữa tâm Bồ đề chỉ gặp thiện tri thức liền phát, vị tất phải gặp Phật xuất thế."],["p","Như Ngài Văn Thù Sư Lợi Bồ Tát, lúc đầu hướng về Bồ đề là nhờ gặp được nữ nhân mà phát."],["p","Nhưng phát sơ tâm huệ thức không phải kẻ phàm dung, tâm chí hạ liệt mà phát được. Phải là người có thật tâm khát ngưỡng Đại thừa, tham cầu Phật pháp, ỷ y các kinh, xem thường thế sự, oán thân bình đẳng, lục đạo như nhau. Nguyện cho hết thảy chúng sanh nhờ sự phát tâm ấy mà được giải thoát, đều đồng tín giải. Nên biết sự phát tâm không phải là việc nói chơi, người tầm thường mà phát tâm được."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đã phát Bồ đề tâm thì quyết phải quán tưởng. Trước hết tưởng đến thân nhân. Trong lúc trì niệm, chuyên tâm tưởng đến cha mẹ, sư trưởng của mình; rồi niệm tưởng đến địa ngục, ngạ quỷ, súc sinh; lại niệm tưởng đến chư Thiên, chư Tiên, hết thảy thiện thần."],["p","Lại nghĩ đến nhân đạo, hết thảy nhân loại, có người đang chịu khổ làm sao mà cứu."],["p","Thấy rồi lại tưởng, nên nghĩ thế này:"],["p","Chỉ có cách phát tâm rộng lớn, tâm Bồ đề mới có thể cứu được. Nếu tưởng đến một người thành rồi thì nên tưởng đến hai người. Hai người thành rồi thì tưởng đến ba người. Ba người thành rồi thì tưởng đầy một nhà. Một nhà thành rồi thì tưởng đến một do tuần. Một do tuần thành rồi thì tưởng đến đầy cõi Diêm phù đề. Diêm phù đề thành rồi thì tưởng đến cả bốn châu thiên hạ."],["p","Quán tưởng như vậy lần lần rộng khắp mười phương thế giới."],["v",["Thấy chúng sanh ở phương Đông là cha mình.","Chúng sanh ở phương Tây là mẹ mình.","Chúng sanh ở phương Nam là anh mình.","Chúng sanh ở phương Bắc là em mình.","Chúng sanh ở phương dưới là chị em mình.","Chúng sanh ở phương trên là sư trưởng mình.","Chúng sanh ở bốn phương góc kia là Sa môn, Bà la môn.","Thấy rồi nghĩ rằng:"]],["p","“Nếu lúc nào những người ấy chịu khổ, tưởng ta phải đến nơi các người ấy mà thoa bóp thân thể cho họ, thề diệt hết đau khổ cho họ được giải thoát, rồi ta sẽ nói pháp cho họ nghe, bằng cách tán thán công đức của Phật, Pháp, Tăng”."],["p","Tán thán rồi, sinh lòng vui mừng, thấy họ an vui như ta không khác."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng phát Bồ đề tâm đều phải làm như vậy; ở trong đau khổ mà độ chúng sanh. Mọi người đều phải nhất tâm thống thiết, đầu thành đảnh lễ, tâm niệm miệng nói, phát lời thệ nguyện như thế này:"],["p","Đệ tử chúng con tên... từ nay trở đi cho đến ngày thành Phật, trong khoảng thời gian ấy sinh ở chỗ nào, cũng thường gặp được thiện tri thức, phát tâm Vô thượng Bồ đề. Nếu chúng con đọa trong ba đường ác, hay lâm phải tám nạn thường khiến chúng con nhớ tưởng phát tâm Bồ đề; làm cho tâm Bồ đề tương tác không gián đoạn."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nên phát tâm dõng mãnh, tâm ân trọng, tâm Bồ đề; nhất tâm tha thiết, đầu thành đảnh lễ quy y Thế gian Đại Từ Bi Phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Dõng Thí Phật.","Nam mô Thanh Tịnh Phật.","Nam mô Thanh Tịnh Thí Phật.","Nam mô Ta Lưu Na Phật.","Nam mô Thủy Thiên Phật.","Nam mô Kiên Đức Phật.","Nam mô Chiên Đàn Công Đức Phật.","Nam mô Vô Lượng Cúc Quang Phật.","Nam mô Quang Đức Phật.","Nam mô Vô Ưu Đức Phật.","Nam mô Na La Diên Phật.","Nam mô Công Đức Hoa Phật.","Nam mô Kiên Dõng Tinh Tấn Bồ Tát.","Nam mô Kim Cang Huệ Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy, mười phương tận hư không giới hết thảy Tam Bảo."],["p","Đệ tử chúng con tên... ngày nay ở trước mười phương Tam Bảo, phát tâm Bồ đề từ nay trở đi cho đến ngày thành Phật, tu đạo Bồ Tát, thề không thối lui; hằng sinh tâm độ thoát chúng sanh, hằng sinh tâm an lập chúng sanh, hằng sinh tâm che chở chúng sanh, chúng sanh không thành Phật, chúng con xin thề không chịu chứng quả Niết bàn trước chúng sanh."],["p","Nguyện xin hết thảy mười phương chư Phật, chư Đại Bồ Tát, hết thảy Thánh Hiền, hiện tiền chứng minh cho chúng con, khiến chúng con tên... hết thảy hạnh nguyện đều được viên mãn."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng, dầu trải qua nhiều kiếp làm nhiều điều thiện mới được phước báu ở cõi người, cõi trời, chứ chưa chứng được quả xuất thế; chết rồi hết phước, trở lại đọa vào đường ác. Thân hình tan rã, tự mình chưa khỏi khổ não, chưa khỏi bức bách."],["p","Nếu không lập thệ nguyện rộng lớn, không phát tâm Bồ đề thì phước đâu mà trang nghiêm Pháp thân để xa lìa được khổ não."],["p","Ngày nay cùng nhau nhất tâm nhất ý... tưởng nhớ chư Phật, khởi lòng tin kiên cố, phát tâm đại Bồ đề."],["p","Công đức phát tâm rất rộng lớn sâu xa, không thể so lường. Chư Phật và Bồ Tát nói cũng không thể hết. Thiện lực như vậy, vô lượng vô biên không thể nghĩ bàn."],["p","Thế nên chúng con đâu được không hết lòng chuyên tâm chú ý mà phát quảng đại Bồ đề tâm."],["p","Kinh Đại Tập dạy rằng:"],["p","“Ví như trong một cái nhà tối trăm năm, chỉ thắp một ngọn đèn, cũng có thể phá tan mờ ám”. Vậy nên chớ cho một niệm phát tâm là nhỏ, là không quan trọng, mà không nỗ lực."],["p","Đại chúng cùng nhau quỳ gối chắp tay nhất tâm tưởng nhớ đến hết thảy mười phương Tam Bảo tâm niệm miệng nói lời này:"],["p","Đệ tử chúng con tên... nay đối trước hết thảy mười phương chư Phật, trước hết thảy mười phương Tôn Pháp, trước hết thảy mười phương Hiền Thánh, lòng ngay dạ thẳng, khởi tâm ân cần, trịnh trọng, tâm không buông lung, tâm an trú, tâm ưa điều thiện, tâm độ thoát hết thảy, tâm che chở hết thảy, tâm như tâm chư Phật, tâm phát tâm Bồ đề."],["p","Đệ tử chúng con tên... từ nay trở đi cho đến ngày thành Phật tâm không đắm trước cõi trời, cõi người, tâm không cầu chứng tiểu quả Thanh Văn, Duyên Giác mà chỉ phát tâm Đại thừa, phát tâm cầu được nhất thiết chủng trí, tâm cầu thành tựu quả Vô thượng Bồ đề, thành bậc Chánh giác."],["p","Nguyện xin mười phương tận hư không giới hết thảy chư Phật, đại địa Bồ Tát, hết thảy Thánh Hiền, đem sức bổn nguyện hiện tiền chứng giám cho chúng con, đem sức từ bi, gia tâm hộ trợ, nhiếp thọ chúng con, cho chúng con tên... ngày nay phát tâm, tại chỗ sở sinh, kiên cố không thối lui."],["p","Nếu chúng con bị đọa vào ba đường ác, hoặc lâm phải tám nạn, ở trong ba cõi, chịu đủ thân hình, chịu đủ khổ sở không thể chịu được. Chúng con xin thề, không vì khổ ấy mà thối mất tâm Bồ đề ngày nay. Thà chúng con chịu vào trong Đại hỏa luân, Vô gián địa ngục, chịu các thống khổ; chúng con không vì khổ mà thối mất tâm đại Bồ đề ngày nay."],["p","Tâm ấy nguyện ấy đồng với tâm của chư Phật, đồng với nguyện của chư Phật."],["p","Lại xin chí thành đảnh lễ Tam Bảo, chúng con tên... từ nay trở đi cho đến ngày thành Phật không bỏ hai pháp sau đây:"],["p","- Một là biết tự tánh các pháp vốn không."],["p","- Hai là độ thoát hết thảy mười phương chúng sanh."],["p","Cùng nhau chí thành nhất tâm tha thiết năm vóc sát đất, tâm niệm miệng nói:"],["p","Đệ tử chúng con tên... không vì mình mà cầu Vô thượng Bồ đề, chính vì muốn cứu độ hết thảy chúng sanh, cho nên cầu Vô thượng Bồ đề. Từ nay trở đi cho đến ngày thành Đạo, chúng con sẽ nâng đỡ hết thảy vô lượng vô biên chúng sanh; chúng con sinh lòng đại từ bi, cùng tận đời vị lai đối với tất cả chúng sanh. Nếu có chúng sanh nào bị các ách nạn, trọng tội trong ba đường, sáu nẻo, chúng con tên... thề không lánh khổ mà lại đem thân ra cứu hộ, làm cho các chúng sanh ấy được an ổn."],["p","Nguyện xin mười phương cùng tận hư không giới hết thảy Tam Bảo chứng minh cho chúng con."],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Liên Hoa Quang Du Hí Thần"]],["v",["Thông Phật.","Nam mô Tài Công Đức Phật.","Nam mô Đức Niệm Phật.","Nam mô Thiện Danh Xưng Công Đức"]],["v",["Phật.","Nam mô Hồng Diệm Đế Tràng"]],["v",["Vương Phật.","Nam mô Thiện Du Bộ Công Đức"]],["v",["Phật.","Nam mô Bảo Hoa Du Bộ Phật.","Nam mô Bảo Liên Hoa Thiện Trụ Ta"]],["v",["La Thọ Vương Phật.","Nam mô Đấu Chiến Thắng Phật.","Nam mô Thiện Du Bộ Phật.","Nam mô Châu Tráp Trang Nghiêm"]],["v",["Công Đức Phật.","Nam mô Khí Ấm Cái Bồ Tát.","Nam mô Tịch Căn Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Nguyện xin chư Phật, đem đại từ bi lực, hiện tiền chứng giám cho chúng con tên... ngày nay phát tâm Bồ đề, tu đạo Bồ Tát, tại chỗ sở sinh, thành tựu được hết thảy điều thệ nguyện."],["p","Chúng con đi đến đâu hết thảy chúng sanh đều được giải thoát. Chúng con lại xin đầu thành đảnh lễ hết thảy mười phương Tam Bảo."],["p","Chúng con tên... không vì tự thân mà cầu đạo Vô thượng Bồ đề. Chỉ vì hết thảy chúng sanh trong mười phương mà cầu chứng quả Vô thượng bồ đề."],["p","Từ nay trở đi cho đến ngày thành Phật nếu có chúng sanh nào ngu si, ám độn không biết chánh pháp sinh tâm tà kiến và có chúng sanh nào tuy tu đạo hạnh mà không thông đạt pháp tướng."],["p","Những chúng sanh như vậy cho đến cùng tận đời vị lai, chúng con tên... xin thệ nguyện nhờ Phật lực, Pháp lực, Hiền Thánh lực và bao nhiêu phương tiện khác, khiến các chúng sanh ấy đều được nhờ Phật lực hoàn toàn đầy đủ thành tựu Nhất thiết chủng trí."],["p","Chúng con cùng nhau chí tâm, một lòng tha thiết, đầu thành đảnh lễ quy y mười phương tận hư không giới, hết thảy chư Phật."],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Phổ Quang Phật.","Nam mô Phổ Minh Phật.","Nam mô Phổ Tịnh Phật.","Nam mô Đa Ma La Bạt Chiên Đàn"]],["v",["Hương Phật.","Nam mô Chiên Đàn Quang Phật.","Nam mô Ma Ni Tràng Phật.","Nam mô Hoan Hỷ Tạng Ma Ni Bảo"]],["v",["Tích Phật.","Nam mô Nhất Thiết Thế Gian Nhạo"]],["v",["Kiến Thượng Đại Tinh Tấn Phật.","Nam mô Ma Ni Tràng Đăng Quang"]],["v",["Phật.","Nam mô Huệ Cự Chiếu Phật.","Nam mô Hải Đức Quang Minh Phật.","Nam mô Kim Cang Lao Cường Phổ"]],["v",["Tán Kim Quang Phật.","Nam mô Đại Cường Tinh Tấn Dõng"]],["v",["Mãnh Phật.","Nam mô Đại Bi Quang Phật.","Nam mô Từ Lực Vương Phật.","Nam mô Từ Tạng Phật.","Nam mô Huệ Thượng Bồ Tát.","Nam mô Thường Bất Ly Thế Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Nguyện xin chư Phật chư đại Bồ Tát đem đại từ bi lực, đại trí huệ lực, bất tư nghị lực, vô lượng tự tại lực, hàng phục tứ ma lực, đoạn trừ ngũ cái lực, diệt trừ phiền não lực, vô lượng thanh tịnh nghiệp trần lực, vô lượng khai phát quán trí lực, vô lượng khai phát vô lậu huệ lực, vô lượng vô biên thần thông lực, vô lượng độ thoát chúng sanh lực, vô lượng phù hộ chúng sanh lực, vô lượng an ổn chúng sanh lực, vô lượng đoạn trừ khổ não lực, vô lượng giải thoát địa ngục lực, vô lượng tế độ ngạ quỷ lực, vô lượng cứu bạt súc sanh lực, vô lượng nhiếp hóa A tu la lực, vô lượng nhiếp thọ nhân đạo lực, vô lượng tận chư thiên chư tiên lậu lực, cụ túc trang nghiêm thập địa lực."],["v",["Cụ túc trang nghiêm Tịnh độ lực,","Cụ túc trang nghiêm đạo tràng lực,","Cụ túc trang nghiêm Phật quả công đức lực,","Cụ túc trang nghiêm Phật quả trí huệ lực,","Cụ túc trang nghiêm Pháp thân lực,","Cụ túc trang nghiêm Vô thượng Bồ đề lực,","Cụ túc trang nghiêm đại Niết bàn lực,","Vô lượng vô tận công đức lực."]],["p","Nguyện xin mười phương tận hư không giới, hết thảy chư Phật, chư đại Bồ Tát, đem những năng lực vô lượng vô biên tự tại không thể nghĩ bàn ấy, không trái với thề xưa, không trái với nguyện xưa, mà bố thí cho hết thảy chúng sanh trong bốn loài sáu đường cùng khắp mười phương và cho tất cả chúng sanh đồng đang phát tâm hôm nay."],["p","Quyết định khiến cho tất cả chúng sanh ấy hoàn toàn đầy đủ các công đức lực, hoàn toàn thành tựu Bồ đề nguyện lực, hoàn toàn thành tựu Bồ đề hạnh lực."],["p","Ngày nay hết thảy chúng sanh trong mười phương cùng tận đời vị lai, hoặc ẩn, hoặc hiện, hoặc oán hoặc thân, hoặc không phải oán, thân ở trong bốn loài sáu đường có duyên hay vô duyên với Phật pháp, hết thảy đều nhờ pháp sám này hằng được thanh tịnh. Các chúng sanh ấy ở nơi nào cũng đồng được như sở nguyện; một lòng kiên cố, tâm không thối chuyển; đồng như chư Phật, đồng thành Chánh giác; cho đến những chúng sanh đời sau, dầu trái với lời nguyện này cũng đều khiến các chúng sanh ấy được vào trong bể đại nguyện liền được đầy đủ, hoàn toàn thành tựu công đức, trí huệ các chúng sanh ấy đồng với chư vị Bồ Tát, viên mãn hạnh Thập địa hoàn toàn Nhất thiết chủng trí trang nghiêm Vô thượng Bồ đề thành bậc Chánh giác."]],"p":"Quyển Thứ Hai"},{"t":"Chương Thứ Năm Phát Nguyện","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng, đã được cùng nhau phát đại Bồ đề tâm rồi, vui mừng vô lượng. Bây giờ nên phát đại nguyện như sau đây và nhất tâm tha thiết đầu thành đảnh lễ Quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Chiên Đàn Khốt Trang"]],["v",["Nghiêm Thắng Phật.","Nam mô Hiền Thiện Thủ Phật.","Nam mô Thiện Ý Phật.","Nam mô Quảng Trang Nghiêm"]],["v",["Vương Phật.","Nam mô Kim Hoa Quang Phật.","Nam mô Bảo Cái Chiếu Không Tự Tại"]],["v",["Lực Vương Phật.","Nam mô Hư Không Bảo Hoa Quang"]],["v",["Phật.","Nam mô Lưu Ly Trang Nghiêm"]],["v",["Vương Phật.","Nam mô Phổ Hiện Sắc Thân Quang"]],["v",["Phật.","Nam mô Bất Động Trí Quang Phật.","Nam mô Hàng Phục Chúng Ma"]],["v",["Vương Phật.","Nam mô Tài Quang Minh Phật.","Nam mô Trí Huệ Thắng Phật.","Nam mô Di Lặc Tiên Quang Phật.","Nam mô Dược Vương Bồ Tát.","Nam mô Dược Thượng Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Nguyện xin Tam Bảo đem sức bất khả tư nghị lực, gia tâm che chở cho chúng con tên... có những thệ nguyện gì, đều được thành tựu. Chúng con sinh ra ở đâu thường không quên mất các lời nguyện hôm nay và được viên mãn Vô thượng Bồ đề, thành Đẳng chánh giác."],["p","Chúng con tên... từ nay trở đi, nguyện đời đời kiếp kiếp, cùng khắp mọi nơi, thường tưởng nhớ sự phát tâm Bồ đề, khiến tâm Bồ đề tương tục không đoạn."],["p","Đệ tử chúng con tên... từ nay trở đi, nguyện đời đời kiếp kiếp, cùng khắp mọi nơi thường được phụng sự vô lượng vô biên hết thảy Đức Phật, thường được cúng dường chư Phật, lễ phẩm cúng dường đều được đầy đủ."],["p","Đệ tử chúng con tên... từ nay trở đi, nguyện đời đời kiếp kiếp, cùng khắp mọi nơi thường được hộ trì hết thảy kinh điển Đại thừa Phương đẳng, lễ phẩm cúng dường kinh điển, đều được đầy đủ."],["p","Đệ tử chúng con tên... từ nay trở đi nguyện đời đời kiếp kiếp, cùng khắp mọi nơi, thường gặp được hết thảy mười phương vô lượng vô biên chư vị Bồ Tát, lễ phẩm cúng dường đều được đầy đủ."],["p","Đệ tử chúng con tên... từ nay trở đi, nguyện đời đời kiếp kiếp, cùng khắp mọi nơi, thường gặp được hết thảy mười phương vô lượng vô biên Hiền Thánh, lễ phẩm cúng dường đều được đầy đủ."],["p","Đệ tử chúng con tên... từ nay trở đi, nguyện đời đời kiếp kiếp, cùng khắp mọi nơi thường được phụng dưỡng báo bổ ơn sâu của cha mẹ, muốn dâng cúng gì cũng không thiếu."],["p","Đệ tử chúng con tên... từ nay trở đi, nguyện đời đời kiếp kiếp, cùng khắp mọi nơi, cũng thường gặp được hết thảy chư vị Hòa thượng A xà lê và muốn dâng cúng gì cũng có đầy đủ tùy tâm sở nguyện."],["p","Đệ tử chúng con tên... từ nay trở đi, nguyện xin đời đời kiếp kiếp, cùng khắp mọi nơi thường được cung phụng và gặp gỡ hết thảy vị quốc chủ có đại thế lực cùng với chúng con hưng hiển Tam Bảo, làm cho Phật Pháp không đoạn tuyệt."],["p","Đệ tử chúng con tên... từ nay trở đi, nguyện đời đời kiếp kiếp, cùng khắp mọi nơi thường được trang nghiêm cõi nước của chư Phật, các cõi ấy không có những danh từ tam ác, bát nạn."],["p","Đệ tử chúng con tên... từ nay trở đi, nguyện đời đời kiếp kiếp, cùng khắp mọi nơi, bốn vô ngại trí, sáu sức thần thông hằng được hiện tiền, thường không quên mất, dùng để giáo hóa hết thảy chúng sanh."],["p","Chúng con cùng nhau nhất tâm thống thiết năm vóc sát đất, đảnh lễ quy y thế gian Đại Từ Bi phụ."],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Thế Tịnh Quang Phật.","Nam mô Thiện Tịch Nguyệt Âm Diệu"]],["v",["Tôn Trí Vương Phật.","Nam mô Long Chưởng Thượng Tôn"]],["v",["Vương Phật.","Nam mô Nhật Nguyệt Quang Phật.","Nam mô Nhật Nguyệt Châu Quang"]],["v",["Phật.","Nam mô Huệ Tràng Thắng Vương"]],["v",["Phật.","Nam mô Sư Tử Hống Tự Tại Lực"]],["v",["Vương Phật.","Nam mô Diệu Âm Thắng Phật.","Nam mô Thượng Quang Tràng Phật.","Nam mô Quang Thế Đăng Phật.","Nam mô Huệ Oai Đăng Vương Phật.","Nam mô Pháp Thắng Vương Phật.","Nam mô Tu Di Quang Phật.","Nam mô Tu Ma Na Hoa Quang Phật.","Nam mô Ưu Đàm Bát La Hoa Thù"]],["v",["Thắng Vương Phật.","Nam mô Đại Huệ Lực Vương Phật.","Nam mô A Súc Tỳ Hoan Hỷ Quang"]],["v",["Phật.","Nam mô Vô Lượng Âm Thanh Vương"]],["v",["Phật.","Nam mô Sơn Hải Huệ Tự Tại Thông"]],["v",["Vương Phật.","Nam mô Đại Thông Quang Phật.","Nam mô Tài Quang Phật.","Nam mô Kim Hải Quang Phật.","Nam mô Nhất Thiết Pháp Tràng Mãn"]],["v",["Vương Phật.","Nam mô Đại Thế Chí Bồ Tát.","Nam mô Phổ Hiền Vương Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo. Nguyện xin nhờ sức oai đức từ bi của chư Phật, chư đại Bồ Tát và hết thảy Hiền Thánh Tăng khiến chúng con tên... sinh ra nơi nào, những thệ nguyện đã phát ra, đều được tùy tâm tự tại."],["p","Đệ tử chúng con tên... từ nay trở đi lại nguyện đời đời kiếp kiếp, cùng khắp mọi nơi, nếu có chúng sanh nào thấy sắc thân của chúng con liền được giải thoát."],["p","Nếu chúng con vào Địa ngục, hết thảy Địa ngục đều biến thành Tịnh độ; hết thảy khổ não biến thành an vui. Khiến các chúng sanh sáu căn thanh tịnh, thân tâm an lạc, vui như ở đệ tam thiền, dứt sạch nghi ngờ, phát sơ vô lậu huệ."],["p","Đệ tử chúng con tên... từ nay trở đi, nguyện đời đời kiếp kiếp, cùng khắp mọi nơi, nếu có chúng sanh nào nghe được âm thanh của chúng con, tâm liền được an ổn, diệt trừ tội cấu, được đà la ni giải thoát tam muội, đầy đủ đại nhẫn, biện tài vô cùng, vào Pháp vân địa, thành bậc Chánh giác."],["p","Đệ tử chúng con tên... từ nay trở đi, nguyện đời đời kiếp kiếp, cùng khắp mọi nơi hết thảy chúng sanh, nghe được tên chúng con thảy đều hoan hỷ, như được việc chưa từng có."],["p","Nếu chúng con đến tam đồ thì tam đồ dứt hết khổ não; nếu chúng con ở các cõi trời, cõi người thì các cõi ấy dứt hết các pháp hữu lậu, đến đâu cũng được tự do, không có gì ràng buộc, thảy đều được giải thoát."],["p","Đệ tử chúng con tên... từ nay trở đi nguyện đời đời kiếp kiếp, cùng khắp mọi nơi, đối với hết thảy chúng sanh, không có tâm cho và lấy, không có tưởng oán và thân; đoạn trừ tham, sân, si là ba gốc độc ác; lìa ngã và ngã sở, tin ưa pháp Đại thừa, đồng tu hạnh từ bi, hòa hiệp với hết thảy như các Thánh chúng."],["p","Đệ tử chúng con tên... từ nay trở đi, nguyện đời đời kiếp kiếp, cùng khắp mọi nơi, đối với hết thảy chúng sanh tâm thường bình đẳng như hư không, khen chê không động lòng; oán thân như nhau, đi sâu vào tâm địa rộng lớn, học trí huệ chư Phật, xem chúng sanh đồng như La Hầu La, đầy đủ nghiệp thập trú, xa lìa tâm chấp có, xả bỏ tâm chấp không, thường tu theo trung đạo."],["p","Cùng nhau chí tâm một lòng tha thiết đầu thành đảnh lễ, quy y thế gian Đại từ Bi Phụ."],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Bảo Hải Phật.","Nam mô Bảo Anh Phật.","Nam mô Bảo Thành Phật.","Nam mô Bảo Quang Phật.","Nam mô Bảo Tràng Phan Phật.","Nam mô Bảo Quang Minh Phật.","Nam mô A Súc Phật.","Nam mô Đại Quang Minh Phật.","Nam mô Vô lượng Âm Phật.","Nam mô Đại Danh Xưng Phật.","Nam mô Đắc Đại An Ổn Phật.","Nam mô Chánh Âm Thanh Phật.","Nam mô Vô Hạn Tịnh Phật.","Nam mô Nguyệt Âm Phật.","Nam mô Vô Hạn Danh Xưng Phật.","Nam mô Nhật Nguyệt Quang Minh"]],["v",["Phật.","Nam mô Vô Cấu Quang Phật.","Nam mô Tịnh Quang Phật.","Nam mô Kim Cang Tạng Bồ Tát.","Nam mô Hư không Tạng Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Chúng con tên... nguyện xin nhờ công đức nhân duyên phát nguyện sám hối hôm nay, mà bốn loài chúng sanh trong sáu đường, từ nay trở đi cho đến ngày thành Phật, tu đạo Bồ Tát không biết mỏi mệt, nhàm chán; tài thí không cùng, pháp thí không tận, trí huệ phương tiện làm gì cũng được; tùy căn cơ của chúng sanh, cho uống thuốc pháp, người thấy người nghe, đều được giải thoát."],["p","Đệ tử chúng con tên... lại nguyện xin từ nay trở đi cho đến ngày thành Phật, tu đạo Bồ Tát, không bị các chướng nạn trở ngại. Chúng con đến đâu cũng thường kiến lập đạo tràng, làm các đại Phật sự; tâm được tự tại, pháp được tự tại, hay vào được hết thảy các môn thiền định, mở cửa tổng trì, rõ bày Phật quả, ở Pháp Vân địa, rưới nước cam lồ, trừ bốn ma oán cho các chúng sanh; khiến các chúng sanh được Pháp thân thanh tịnh nhiệm mầu."],["p","Đệ tử chúng con tên... xin có bao nhiêu thệ nguyện, nguyện nào cũng như nguyện của mười phương chư Phật, chư Đại Bồ Tát đã phát ra trong lúc tu hành, rộng lớn như pháp tánh, cứu cánh như hư không."],["p","Đệ tử chúng con tên... xin đều được như sở nguyện mãn Bồ đề nguyện."],["p","Nguyện cho hết thảy chúng sanh đều theo đó, đều được như sở nguyện. Nguyện xin mười phương hết thảy chư Phật, hết thảy chư Bồ Tát và hết thảy Thánh Hiền đều đem sức từ bi, hiện tiền chứng giám cho chúng con."],["p","Lại nguyện xin cho chúng sanh, hết thảy thiên chủ, hết thảy tiên chủ, hết thảy thiện thần, hết thảy long thần đem từ thiện căn lực, vì ủng hộ Tam Bảo mà hiện tiền chứng giám cho chúng con, khiến chúng con hết thảy hạnh nguyện đều được viên mãn, tùy theo ý muốn."]],"p":"Quyển Thứ Hai"},{"t":"Chương Thứ Sáu Phát Tâm Hồi Hướng","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng, đã phát Bồ đề tâm rồi, đã phát đại thệ nguyện rồi, bây giờ lại nên phát tâm hồi hướng."],["p","Cùng nhau chí thành đảnh lễ, nhất tâm tha thiết, năm vóc sát đất, quy y Thế gian Đại Từ Bi phụ."],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Nhật Quang Phật.","Nam mô Vô Lượng Bảo Phật.","Nam mô Liên Hoa Tối Tôn Phật.","Nam mô Thân Tôn Phật.","Nam mô Kim Quang Phật.","Nam mô Phạm Tự Tại Vương Phật.","Nam mô Kim Quang Minh Phật.","Nam mô Kim Hải Phật.","Nam mô Long Tự Tại Vương Phật.","Nam mô Thọ Vương Phật.","Nam mô Nhất Thiết Hoa Hương Tự"]],["v",["Tại Vương Phật.","Nam mô Dõng Mãnh Chấp Trì Lao"]],["v",["Trượng Khí Xả Chiến Đấu Phật.","Nam mô Nội Phong Châu Quang"]],["v",["Phật.","Nam mô Vô Lượng Hương Quang"]],["v",["Minh Phật.","Nam mô Văn Thù Sư Lợi Bồ Tát.","Nam mô Diệu Âm Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo, nguyện xin Tam Bảo đem sức từ bi hiện tiền chứng giám cho chúng con."],["p","Chúng con tên... quá khứ đã khởi ra bao nhiêu thiện nghiệp, hiện tại đang khởi ra bao nhiêu thiện nghiệp, và vị lai sẽ khởi ra bao nhiêu thiện nghiệp, hoặc nhiều hoặc ít, hoặc khinh hoặc trọng, thảy đều hồi hướng cho tất cả chúng sanh, trong bốn loài sáu đường, làm cho các chúng sanh ấy đều được đại đạo tâm, không hướng về Nhị thừa, không hướng về ba cõi, cùng nhau hướng về Vô thượng Bồ đề."],["p","Lại nguyện xin cho tất cả chúng sanh ấy đã khởi ra bao nhiêu thiện nghiệp, hoặc quá khứ, hoặc hiện tại, hoặc vị lai đều không hướng về Nhị thừa, đều không hướng về ba cõi, mà cùng nhau hướng về Vô thượng Bồ đề."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đã cùng phát tâm Bồ đề rồi, đã phát đại thệ nguyện rồi, đã phát tâm hồi hướng rồi rộng lớn như pháp tánh, cứu cánh như hư không."],["p","Hết thảy chư Phật, chư Đại Bồ Tát cùng chư vị Thánh Hiền quá khứ, hiện tại và vị lai đều chứng minh cho chúng con."],["p","Chúng con lại chí thành đảnh lễ Tam Bảo. (1 lạy)"],["p","Chúng con tên... phát tâm, phát nguyện việc ấy đã rồi, vui mừng vô lượng."],["p","Nay chúng con lại chí tâm đầu thành đảnh lễ thế cho: Quốc chủ, nhân dân, phụ mẫu, sư trưởng, bà con nhiều đời, quyến thuộc nhiều kiếp, thiện ác tri thức, chư thiên, chư tiên, hộ thế tứ vương, chủ thiện phạt ác, thủ hộ trì chú, ngũ phương long vương, long thần, bát bộ hết thảy linh kỳ, quá khứ, hiện tại cùng vị lai hết thảy người oán kẻ thân và không phải oán thân, hết thảy chúng sanh trong bốn loài, sáu đường mà quy y Thế gian Đại Từ Bi phụ."],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Sư Tử Hưởng Phật.","Nam mô Đại Cường Tinh Tấn Dõng"]],["v",["Lực Phật.","Nam mô Quá Khứ Kiên Trú Phật.","Nam mô Cổ Âm Vương Phật.","Nam mô Nhật Nguyệt Anh Phật.","Nam mô Siêu Xuất Chúng Hoa Phật.","Nam mô Thế Đăng Minh Phật.","Nam mô Hưu Đa Dị Ninh Phật.","Nam mô Bảo Luân Phật.","Nam mô Thường Diệt Độ Phật.","Nam mô Tịnh Giác Phật.","Nam mô Vô Lượng Bảo Hoa Minh"]],["v",["Phật.","Nam mô Tu Di Bộ Phật.","Nam mô Bảo Liên Hoa Phật.","Nam mô Nhất Thiết Chúng Bảo Phổ"]],["v",["Tập Phật.","Nam mô Pháp Quán Chúng Bảo Phổ"]],["v",["Tập Phong Doanh Phật.","Nam mô Thọ Vương Phong Trường"]],["v",["Phật.","Nam mô Vi Nhiễu Đặc Tôn Đức Tịnh"]],["v",["Phật.","Nam mô Vô Cấu Quang Phật.","Nam mô Nhật Quang Phật.","Và Quy y Kính lễ:","Quá khứ vô số kiếp chư Phật. Đại Sư Hải Đức Như Lai."]],["p","Kính lễ vô lượng vô biên tận hư không giới vô sinh pháp thân Bồ Tát."],["p","Kính lễ vô lượng vô biên tận hư không giới vô lậu sắc thân Bồ Tát."],["p","Kính lễ vô lượng vô biên tận hư không giới phát tâm Bồ Tát."],["p","Kính lễ hưng Chánh pháp Mã Minh đại sư Bồ Tát."],["p","Kính lễ hưng tượng pháp Long Thọ đại Sư Bồ Tát."],["p","Kính lễ mười phương tận hư không giới Vô Biên Thân Bồ Tát."],["p","Kính lễ mười phương tận hư không giới cứu khổ cứu nạn Quán Thế Âm Bồ Tát."],["h","Tán Thán Phật và Chú Nguyện"],["v",["Đại Thánh Thế Tôn,","Uy nghiêm rực rỡ,","Thần trí nhiệm mầu,","Lớn hơn các Thánh,","Thân khắp lục đạo,","Thể cùng mười phương,","Đảnh có nhục kế,","Trán tỏa hào quang,","Mặt như trăng tròn,","Thân vàng sắc đẹp,","Nghi dung đĩnh đạc,","Đi đứng khoan thai,","Oai vang pháp giới,","Ma quân kinh hoàng,","Tam đạt sáng tỏa,","Chúng tà tiềm tàng,","Thấy ác liền cứu","Tế khổ tư lương","Độ thoát sanh tử,","Săñ có từ hàng"]],["p","Nên hiệu Như Lai, Ứng Cúng, Chánh Biến Tri, Minh Hạnh Túc, Thiện Thệ, Thế Gian Giải, Vô Thượng Sĩ, Điều Ngự Trượng Phu, Thiên Nhân Sư, Phật Thế Tôn, độ chúng vô lượng diệt khổ sanh tử."],["p","Chúng con nguyện xin nhờ công đức nhân duyên phát tâm này mà quốc chủ hiện tại và gia thân quyến thuộc của người, từ nay trở đi cho đến ngày thành Phật quên mình vì đạo như: Tát Đà Bà Luân Bồ Tát."],["p","Đại Bi diệt tội như:"],["v",["Hư Không Tạng Bồ Tát.","Hay ở xa nghe pháp như:"]],["v",["Lưu Ly Quang Bồ Tát.","Hay khéo giải đáp vấn nạn như:"]],["p","Vô Cấu Tạng Bồ Tát."],["p","Lại nguyện xin cho đệ tử chúng con tên... thân sinh phụ mẫu, nhiều kiếp bà con, xa gần nội ngoại, từ nay trở đi cho đến ngày thành Phật, biến thân ra giữa hư không thế giới như ngài:"],["v",["Vô Biên Thân Bồ Tát","Có đủ mười công đức như:"]],["v",["Ngài Cao Quý Đức Vương Bồ Tát.","Nghe pháp sinh tâm vui mừng như:","Ngài Vô Úy Bồ Tát."]],["p","Lại nguyện xin các Hòa Thượng, A Xà Lê, những bà con đồng tu, đồng học, thượng trung hạ tòa, hết thảy tri thức của chúng con, từ nay trở đi cho đến ngày thành Phật, mọi người đều được pháp vô úy như:"],["v",["Ngài Sư Tử Vương Bồ Tát.","Giáo hóa được ảnh hưởng lớn như:"]],["v",["Ngài Bảo Tích Bồ Tát.","Nghe tiếng liền cứu khổ như:"]],["v",["Ngài Quán Thế Âm Bồ Tát.","Hay khéo thưa thỉnh giáo pháp như:"]],["p","Ngài Đại Ca Diếp Bồ Tát."],["p","Lại nguyện xin những người xuất gia, tại gia, tín thí đàn việt, thiện ác tri thức và quyến thuộc của các người ấy, từ nay trở đi cho đến ngày thành Phật cởi mở ngay được nguy ách, như ngài: Cứu Thoát Bồ Tát."],["p","Tướng mạo trang nghiêm như:"],["v",["Ngài Văn Thù Bồ Tát.","Hay xả nghiệp chướng như:"]],["v",["Ngài Khí Ấm Cái Bồ Tát.","Hiến tối hậu cúng như:"]],["p","Ngài Thuần Đà Bồ Tát."],["p","Lại nguyện xin chư Thiên, chư Tiên, hộ thế tứ vương, thông minh chánh trực, thiên địa hư không, chủ thiện phạt ác, thủ hộ trì chú, ngũ phương Long vương, Long thần Bát bộ, u hiển linh kỳ và bà con quyến thuộc của các vị ấy, từ nay trở đi cho đến ngày thành Phật, có lòng Đại từ che khắp chúng sanh như: Ngài A Dật Đa Bồ Tát."],["v",["Tinh tấn hộ pháp như:","Ngài Bất Hưu Tức Bồ Tát.","Ở xa mà chứng minh cho sự đọc tụng như:"]],["v",["Ngài Phổ Hiền Bồ Tát.","Vì Phật pháp mà thiêu thân như:"]],["p","Ngài Dược Vương Bồ Tát."],["p","Lại nguyện xin hết thảy chúng sanh và quyến thuộc của các chúng sanh, hoặc oán, hoặc thân hay không phải oán thân, trong bốn loài, sáu đường cùng khắp mười phương từ nay trở đi cho đến ngày thành đạo, tâm không ái nhiễm, như:"],["p","Ngài Ly Ý Nữ Bồ Tát."],["p","Nói lời nhiệm mầu khôn khéo như lời của Thắng Man Phu Nhân."],["v",["Tu hành tinh tấn như Đức Thích Ca Văn.","Có thiện nguyện lớn như Phật Vô Lượng Thọ.","Có oai thần như các Thiên Vương."]],["p","Bất khả tư nghị như Ngài Duy Ma Cật. Thành tựu hết thảy chúng sanh, trang nghiêm hết thảy Phật độ."],["p","Nguyện xin mười phương tận hư không giới vô lượng vô biên chư Phật, chư Đại Bồ Tát và hết thảy Hiền Thánh đều đem lòng từ bi, đồng gia tâm che chở phù hộ cứu vớt chúng con và chúng sanh, cho chúng con được mãn nguyện, tín tâm được kiên cố, phước đức ngày một cao dày, có từ tâm, nuôi dưỡng chúng sanh như nuôi đứa con một."],["p","Khiến các chúng sanh ấy được bốn vô lượng tâm, sáu ba la mật, thập thọ tu thiền, tâm nguyện đầy đủ, móng tâm liền được thấy Phật như bà Thắng Man phu nhân. Hết thảy hạnh nguyện hoàn toàn thành tựu, đồng như chư Phật, đồng đến đạo tràng, thành bậc Chánh giác."],["v",["Lương Hoàng Bảo Sám,","Vạn đức hồng danh,","Linh văn nhị quyển tối hoằng thâm,","Tự tự miễn tai truân,","Đảnh lễ Phật danh,","Tiêu tai bảo an ninh."]],["p","Nam mô Ly Cấu Địa Bồ Tát Ma Ha Tát. (3 lần)"],["h","Cung Văn"],["p","Vạn đức trang nghiêm chi diệu thể, vị ly Đâu Suất dĩ giáng hoàng cung. Bách phước tướng hảo chi Từ Tôn, bất khởi thọ vương nhi thăng Đao Lợi; duy nguyện Giác Vương thùy từ lân mẫn. Đại bi khoáng tế, bạt trễ nịch chi trầm lưu."],["p","Pháp nhãn viên minh, giám ngu tình chi khẩn thiết."],["p","Thượng lai phụng vì cầu sám đệ tử... đẳng, tu lễ Từ Bi Đạo Tràng Bảo Sám, kim đương đệ nhị quyển, công đức tương hoàn. Đàn nội thanh chúng, xuất sám nhập sám, hành đạo triền nhiễu, thiêu hương tán hoa, phúng kinh trì trú..."],["p","Nhiên tương nhị quyển chi công huân, tác thử nhị thời chi hồi hướng. Nhất chân chi nội Phật đà, Đạt mạ, Tăng già. Tam giới chi trung thiên nhiên, địa kỳ thủy phủ, hàm sanh hoan hỷ chi tâm, giám thử đầu thành chi chí. Hưng nhất tử chi bi ai, mãn nhị nghiêm chi cụ bị xuất sinh công đức, phụng vì cầu sám đệ tử đẳng... tẩy không tam nghiệp, tăng trưởng nhị nghiêm."],["p","Phục nguyện: Sự chướng, lý chướng dĩ tiêu dung; nhân không pháp không nhi thanh tịnh. Điên đảo nhị tâm bất khởi, phước huệ nhị chủng trang nghiêm; nhập bất nhị chi pháp môn, chứng chân thường chi diệu lý. Phổ triêm tam hữu, pháp giới oan thân. Hoạch nhân pháp chi lưỡng không, đắc vô sinh chi nhị nhẫn. Nhị huệ vô minh, nhị hạnh viên mãn; ưu du ư pháp hải từ hàng; thường lạc ư Tát bà nhã quả."],["p","Tuy tắc uy văn sám hối, do khủng vị tận; kiền thành tái lao Thánh chúng, đồng cầu sám hối."],["p","Nam mô Cầu Sám Hối Bồ Tát Ma ha tát. (3 lần)"],["p","Lương Hoàng Bảo Sám nhị quyển công đức lực. Nguyện diệt ngã đẳng tội chướng, thân chứng Bồ Tát Ly Cấu Địa."],["v",["Sám văn cử xứ, tội hoa phi,","Giải liễu oan, sám liễu tội,","Tiêu tai tăng phước huệ,","Thoát khổ sanh Đao Lợi.","Giải liễu oan, sám liễu tội,","Tiêu diêu trực nhập Long Hoa Hội,","Long Hoa tam hội nguyện tương"]],["v",["phùng, Di Lặc Phật tiền thân thọ ký.","Nam mô Long Hoa Hội Bồ Tát Ma ha tát. (3 lần)","Hồi đàn tán:","Lương Hoàng Bảo Sám,","Nhị quyển dĩ toàn châu,","Hồi hướng tứ ân tịnh tam hữu,"]],["p","Bái sám chúng đẳng tăng phước thọ, Nguyện tương phát thủy tẩy khiên"],["p","vưu, Duy nguyện vong giả vãng Tây du."],["p","Ly Cấu Địa Bồ Tát duy nguyện ai nạp"],["v",["thọ.","Nam mô Đăng Vân Lộ Bồ Tát Ma Ha Tát. (3 lần)"]],["v",["Hồi hướng Tịnh độ:","Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh...","(Tiếp Tịnh độ và hồi hướng)"]],["v",["Hiệu Chính: HT. THÍCH TRÍ TỊNH","Dịch Giả: HT. THÍCH VIÊN GIÁC"]]],"p":"Quyển Thứ Hai"},{"t":"Đầu Quyển Ba","b":[["p","Đăng hoảng diệu,"],["p","Oanh hoàng liệt bảo đài,"],["p","Quang minh biến chiếu châu sa giới, Hôn cử chiếu diệu câu vô ngại."],["v",["Diệm Ma chiêm lễ tử kim đài.","Nhiên Đăng Phật thành đạo,","Tằng thọ nhân thiên bái.","Nam mô Phổ Hiền Vương Bồ Tát Ma Ha","Tát. (3 lần)"]],["h","Cung Văn"],["v",["Tam kỳ quả mãn, hiện xuất thế chi Ưu","đàm, Tam loại hóa thân diễn nan tuyên chi áo","hải, Tam xa dụ dẫn tân lương ư tam giới hàm"]],["p","linh, Tam quán trừng minh tuyên dương ư tam thiên giới nội. Nghịch hạnh thuận hạnh vô phi Phật sự. Cử túc hạ túc tức thị Đạo tràng. Duy nguyện Từ Tôn giám thử đơn thành."],["p","Thượng lai cầu sám đệ tử đẳng... khởi biến Từ Bi Đạo Tràng sám pháp, kim đương đệ tam quyển, nhập đàn duyên khởi ngã chư chúng đẳng... Kiều cần tác lễ, khẩn thiết đầu thành, quán tưởng Tứ Dung, xưng dương Giác hiệu; phụng Hương Tích chi trân tu, hiến danh viên chi hoa quả, vọng chư Phật dĩ thùy từ, xá đa sinh chi tội cấu. Thiết niệm cầu sám đệ tử đẳng... tự tùng vô thỉ đãi chí kim sinh, tam hải mê tâm, tạo tam hữu thăng trầm chi cốt một. Tam không vị ngộ, tác tam đồ khổ thú chi nhân do khởi tam hoặc tâm, nhi tam nghiệp di thâm, trần trần cách ngại; muội tam tu tập nhi tam nghiệp vị tiêu. Niệm niệm phan duyên như tam tác kiển, loại tượng nịch nê, trầm lụy oanh triền, vô do giải thoát."],["p","Kinh tắc thân tâm chi thị khổ, tín nghiệp quả chi nan đào, phát lộ hướng ư chân từ phi thành đầu ư Giác Hải. Nguyện Phật nhật dĩ đương không, chiếu u đồ chi khổ thú. Cưu tam học chi truy lưu, lễ tam thiên chi Đại giác. Ngã tâm cánh cánh, Phật đức nguy nguy, kỳ thấu hồng từ, minh huân gia bị."],["v",["Tam thiên giới nội Từ Bi Chủ,","Bách ức sát trung Đại Pháp Vương","Nguyện khai liên mục giám phàm"]],["p","tình."],["p","Chúng sanh hữu cầu giai cảm ứng."],["p","Khởi vận Từ Bi Đạo Tràng Sám Pháp, nhất tâm quy mạng Tam Thế chư Phật:"],["v",["Nam mô Quá Khứ Tỳ Bà Thi Phật.","Nam mô Thi Khí Phật.","Nam mô Tỳ Xá Phù Phật.","Nam mô Câu Lưu Tôn Phật.","Nam mô Câu Na Hàm Mâu Ni Phật.","Nam mô Ca Diếp Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Đương Lai Hạ Sinh Di Lặc"]],["p","Tôn Phật."]],"p":"Quyển Thứ Ba"},{"t":"Chương Thứ Bảy Nói Rõ Quả Báo","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng trước đã thuật rõ tội báo của ác nghiệp. Vì hoạn lụy của ác báo chỗ nên trái với nghiệp thù thắng tốt đẹp. Vì ác nghiệp nên phải đọa trong ba đường dữ trải khắp ác thú và sinh ra ở nhân gian để chịu trả quả báo đau khổ. Quả báo đau khổ như thế đều do nhân duyên túc đối đời trước đem lại. Bây giờ xả thân này chịu thân khác để chịu trả quả báo mãi mãi không thôi."],["p","Bởi thế chư Phật và chư Đại Bồ Tát dùng sức thần thông thiên nhãn, thấy hết thảy chúng sanh trong ba cõi khi hết phước rồi, có theo nghiệp báo mà đọa vào các chỗ khổ. Thấy chúng sanh từ cõi trời Vô sắc giới, do tâm đắm trước thiền định, hoăc̣ vậy mạng chung, hết phước đọa xuống cõi trời Dục giới. Vì hết phước nên cũng có khi đọa làm cầm thú. Những chúng sanh ở cõi trời Sắc giới, khi hết phước cũng phải sa đọa như vậy. Từ chỗ thanh tịnh đọa xuống Dục giới là chỗ không thanh tịnh vì ở chỗ không thanh tịnh nên trở lại thọ lấy dục lạc. Chúng sanh ở sáu cõi trời Dục giới khi hết phước đọa xuống địa ngục chịu vô lượng khổ."],["p","Chư Phật và Bồ Tát lại thấy chúng sanh ở trong nhân đạo, nhờ sức tu thập thiện được sinh làm người. Ngay trong thân người cũng có lắm khổ, khi mạng chung phần nhiều lại đọa vào các đường ác."],["p","Lại thấy chúng sanh trong đường súc sanh chịu lắm khổ não, bị đánh đập xua đuổi chở nặng, đi xa, đau đớn khốn khổ, trầy vai trợt cổ, sắt nóng thiêu thân."],["p","Lại thấy chúng sanh trong đường ngạ quỷ thường bị đói khát khổ sở, bị lửa thiêu thân như ở thời mạt kiếp. Nếu không nhờ một mảy căn lành để cứu vớt thì vĩnh kiếp không thể giải thoát. Nếu có được chút phước thì được sinh lên làm người, nhưng thân hình ốm yếu, nhiều tật bệnh và sống yểu chết non."],["p","Vậy đại chúng nên biết thiện ác như hai bánh xe theo nhau, chưa từng tạm nghỉ, thì quả báo cũng do đó mà liên tiếp không thôi, xoay vần như sợi dây xích chuyền nối mãi mãi."],["p","Sang hèn giàu nghèo đều tùy hạnh nghiệp của mỗi người mà chịu trả quả báo."],["p","Không phải sang hèn như vậy mà không có nguyên nhân, không lẽ vô cớ mà có quả báo sang hèn như vậy, thì rất phi lý."],["p","Trong Kinh Phật dạy rằng:"],["p","- Làm người giàu sang, quốc vương, trưởng giả là do cái nhân đời trước lễ bái phụng sự Tam Bảo mà ra."],["p","- Làm người giàu có to lớn là do cái nhân đời trước bố thí mà ra."],["p","- Làm người sống lâu là do cái nhân đời trước không sát sanh mà ra."],["p","- Làm người đoan chánh là do cái nhân đời trước nhẫn nhục mà ra."],["p","- Làm người siêng tu là do cái nhân đời trước không biếng nhác mà ra."],["p","- Làm người có tài ba sáng suốt, hiểu rộng thấy xa là do cái nhân đời trước tu trí huệ mà ra."],["p","- Làm người có âm thanh trong trẻo là do cái nhân đời trước ca vịnh tán thán Tam Bảo mà ra."],["p","- Làm người sạch sẽ không tật bệnh là do cái nhân đời trước từ tâm mà ra."],["p","- Làm người thân hình cao lớn tốt đẹp là do cái nhân đời trước kính nhường người mà ra."],["p","- Làm người thân hình thấp hèn nhỏ bé là do cái nhân đời trước khinh khi người mà ra."],["p","- Làm người thân hình xấu xa là do cái nhân đời trước hay giận hờn mà ra."],["p","- Làm người vô tri, không hiểu biết gì hết là do cái nhân đời trước không học hỏi mà ra."],["p","- Làm người ngu xuẩn đần độn là do cái nhân đời trước không dạy bảo người mà ra."],["p","- Làm người câm ngọng là do cái nhân đời trước hay hủy báng người mà ra."],["p","- Làm người hay bị kẻ khác sai khiến là do cái nhân đời trước mắc nợ người không trả mà ra."],["p","- Làm người da đen xấu xí là do cái nhân đời trước che ánh sáng quang minh của Phật mà ra."],["p","- Làm người sinh vào nước lõa hình là do cái nhân đời trước ăn mặc quần áo mỏng manh, suồng sã, cho mình là hơn người mà ra."],["p","- Làm người sinh vào nước móng ngựa là do cái nhân đời trước đi giầy dép tưởng mình là hơn người, giành đi trước mà ra."],["p","- Làm người sinh vào nước xuyên ngực là do cái nhân đời trước bố thí làm phước, rồi sinh tâm hối hận tiếc của mà ra."],["p","- Làm người sinh trong loài hươu nai là do cái nhân đời trước dọa nạt người, làm người khiếp sợ mà ra."],["p","- Làm người sinh trong loài rồng là do cái nhân đời trước ưa giỡn cợt múa nhảy mà ra."],["p","- Làm người thân hình sinh lở ghẻ dữ là do cái nhân đời trước hay đánh đập chúng sanh mà ra."],["p","- Làm người được người thấy mình liền sinh tâm hoan hỷ là do cái nhân đời trước mình thấy người cũng sinh tâm hoan hỷ."],["p","- Làm người hay bị quan bắt giam cầm là do cái nhân đời trước hay bắt giam cầm chúng sanh trong lồng trong chậu mà ra."],["p","- Làm người ngồi nghe thuyết pháp mà nói chuyện làm loạn động tâm người khác, sau sẽ đọa trong loài chó trập tai."],["p","- Làm người ngồi nghe thuyết pháp mà không để ý nghe cho hiểu sau sẽ đọa trong loài lừa dài tai."],["p","- Làm người tham ăn một mình, keo rít, bỏn xẻn, sau sẽ đọa loài quỷ đói. Hết kiếp quỷ đói sinh ra làm người bần cùng đói khát."],["p","- Làm người đem đồ ăn dở cho kẻ khác, sau sinh làm heo lợn, loài bọ hung."],["p","- Làm người hay cướp giựt của kẻ khác, sau đọa làm dê, bị kẻ khác lột da ăn thịt."],["p","- Làm người ưa trộm cướp của kẻ khác, sau đọa làm trâu ngựa, bị người sai khiến."],["p","- Làm người ưa nói vọng ngữ, tuyên truyền điều xấu của kẻ khác, sau đọa địa ngục, bị quỷ sứ rót nước đồng sôi vào miệng, kéo dài lưỡi ra cho trâu cày. Tội hết rồi, người ấy sinh làm chim cù dục, chim cú, người nghe tiếng nó kêu, ai cũng sợ hãi, cho là yêu quái, đều nguyền rủa cho nó chết."],["p","- Làm người ưa uống rượu say, sau đọa vào địa ngục phất xí (nước phẩn sôi trào). Tội hết rồi người ấy sinh vào loài tinh tinh. Hết nghiệp tinh tinh, được sinh làm người, ngoan độn, ngu si, không ai đếm xỉa đến."],["p","- Làm người tham lường sức mạnh của kẻ khác, sau sẽ đọa làm voi."],["p","Than ôi! Ở địa vị giàu sang, làm người trên trước mà đánh đập kẻ dưới. Kẻ dưới không biết thưa kiện với ai. Những người như thế, chết vào địa ngục, kể cả ngàn vạn năm, chịu quả báo đau khổ."],["p","Từ địa ngục ra, lại đọa làm trâu, bị xâu xỏ mũi miệng dắt thuyền kéo xe, roi gậy to lớn đánh đập khổ sở, để đền lại nợ oan trái ngày xưa."],["p","Lại nữa, người ăn ở dơ bẩn là từ trong loài heo mà đầu thai ra."],["p","Người xan tham keo kiết, không tự xét mình là từ trong loài chó mà đầu thai ra."],["p","Những người gầm gừ, tự dụng một mình là từ trong loài dê mà ra."],["p","Người có tánh táo bạo, nóng nảy, không hay nhẫn nhục là từ trong loài khỉ, vượn, hầu mà đầu thai ra."],["p","Người có thân hình tanh hôi là từ trong loài cá trạch mà đầu thai ra."],["p","Người có tâm thâm hiểm, độc ác là từ trong loài rắn độc mà đầu thai ra."],["p","Người không có từ tâm, tàn nhẫn, báo hại, là từ trong loài hổ báo, sài lang mà đầu thai ra."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng, đã sinh ra làm người trong thế gian bị nhiều bệnh, chết sớm, biết bao thống khổ không thể kể xiết, như thế là do ba nghiệp gây ra, nên khiến người “tu hành” phải mắc lấy quả báo trong ba đường dữ."],["p","Sở dĩ có ba đường dữ là vì có tham sân si. Vả lại cũng vì có ba độc tham sân si ấy mà người tự thiêu đốt lấy mình, miệng thường nói ác, tâm thường nghĩ ác, thân thường làm ác."],["p","Do các điều ác ấy làm cho thân người thường chịu các khổ não, không cùng tận."],["p","Đến khi mạng chung, hồn côi bơ vơ."],["p","Mình làm mình chịu, cha mẹ vợ con không thể cứu được."],["p","Thoạt vậy trong nháy mắt, đến chốn Diêm vương, ngưu đầu, ngục tốt ở trong địa ngục không kể tôn ty, chỉ xét sổ tội phước, kiểm điểm nặng nhẹ, thiện ác nhiều ít, trong lúc sinh tiền đã làm thế nào thì thần thức tự thú tội, không dám che giấu. Do vì nhân duyên ấy nên phải theo nghiệp mà chịu trả quả báo, đến chỗ khổ hay vui là do mình làm mình chịu, mờ mờ mịt mịt ly biệt lâu dài, đường ai nấy đi, không bao giờ gặp nhau trở lại."],["p","Vả lại các vị thiên thần ghi chép thiện ác của người không thiếu sót mảy may. Người thiện làm lành được phước thêm tuổi, người ác làm dữ, giảm thọ thêm khổ. Cứ xoay vần như vậy, mãi mãi rồi lại đọa làm quỷ đói. Hết kiếp quỷ đói, thoát ra làm súc sinh. Tội khổ vô lượng không thể chịu nổi, không bao giờ cùng."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đều nên phải tự tỉnh ngộ mà sinh tâm hổ thẹn."],["p","Trong kinh Phật dạy rằng: “Làm lành gặp lành, làm dữ gặp dữ”. Nhưng trong đời ngũ trược ác thế, chúng ta không nên làm ác; làm lành không mất quả lành, làm ác tự rước lấy tai họa."],["p","Chớ cho khinh thoát lập ra pháp sám này."],["p","Kinh dạy rằng: “Chớ khinh điều thiện nhỏ cho là không phước, giọt nước tuy nhỏ, chảy lâu cũng đầy bát to”."],["p","Không chứa thiện nhỏ lấy gì có phước to để thành Thánh thành Phật, chớ khinh ác nhỏ mà nói là không có tội. Ác nhỏ chứa lại lâu ngày cũng đủ mất thân."],["p","Đại chúng nên biết: Lành dữ họa phước đều do tâm tạo. Nếu không tạo nhân thì không có kết quả. “Ương họa chứa lại, tội thành to lớn”. Chúng ta mắt thịt không thể thấy. Đó là lời Phật dạy ai dám không tin."],["p","Chúng con đã cùng nhau vô phước, sinh vào đời mạt pháp, nếu không siêng năng học tập tu hành, không tự sức mình làm lành đến phút cuối cùng, tắt thở, khi ấy ăn năn đã muộn. Tuy vậy bây giờ đã cùng nhau thấy biết hết thảy tội lỗi như trong kinh Đức Phật đã dạy: Người đã biết tội mình há lại không biết bỏ ác theo lành hay sao!”"],["p","Đời nay nếu không dụng tâm xả thân cầu đạo quyết phải đọa địa ngục. Vì sao mà biết?"],["p","Vì trong lúc làm tội ôm lòng độc ác, mạnh mẽ nóng nảy, giận hờn, gắt gao, sâu sắc. Như giận một người nào quyết muốn cho người ấy chết. Nếu ghét một người nào, không ưa thấy điều tốt của người ấy."],["p","Nếu hủy báng một người nào, quyết khiến cho người ấy lâm vào cảnh khổ."],["p","Nếu đánh một người nào, quyết khiến cho người ấy đau đớn thấu trời thấu đất."],["p","Khi giận hờn tàn bạo tai hại thì không kể tôn ty thượng hạ, dùng lời xấu hổ, mắng nhiếc đủ điều; có khi la vang như sấm dậy, mắt như lửa đổ. Còn khi làm phước thì thiện tâm rất yếu ớt. Lúc đầu muốn làm nhiều, sau lần lần giảm ít lại."],["p","Lúc đầu muốn kinh doanh cho mau chóng, sau lại thả lỏng buông trôi."],["p","Tâm đã không chí quyết ngày tháng trôi qua, lần lượt tới lui cho đến khi quên mất việc thiện là xong. Xét như thế thì biết lúc làm tội tâm lực rất mãnh liệt cường thạnh; lúc làm phước thì chí ý bạc nhược yếu hèn."],["p","Nay đem cái nhân làm phước yếu hèn ấy mà cầu xa lìa quả báo làm ác mãnh liệt cương cường kia thì không thể được."],["p","Kinh dạy rằng: “Sám hối thì tội gì cũng tiêu diệt hết”."],["p","Nhưng than ôi! Đến lúc sám hối, quyết phải đầu thành đảnh lễ, năm vóc sát đất như núi Thái Sơn sụp đổ, không tiếc thân mạng mới mong diệt được tội."],["p","Vì diệt được tội nên phải ân cần, thành khẩn cùng nhau xét mình từ khi sinh ra cho đến ngày nay đã gây ra bao nhiêu tội lỗi. Phải tự xét trách như thế mới không tiếc thân mạng, chịu khó nhọc mà sám hối."],["p","Nếu tạm thời nhiễu Phật liền sinh tâm mỏi mệt, chán nản, tạm thời lễ bái liền nói sức lực không kham; hoặc tạm thời ngồi ngay tỉnh niệm, liền nói nên phải có tin tức chứng ngộ gì. Hoặc nói không nên làm cho thân thể quá mỏi mệt, phải cần dưỡng, không được làm khổ thân."],["p","Vừa nằm xuống ngủ liền mê man như chết, không bao giờ tưởng nhớ đến việc ta phải lễ Phật, quét tháp, quét chùa làm những việc khó làm."],["p","Vả chăng, kinh có dạy rõ ràng: “Chưa từng có một mảy may thiện nào từ sự giải đãi lười biếng mà sinh ra; chưa từng có một chút phước nào từ sự kiêu mạn, tự do tự đắc mà được”."],["p","Đệ tử chúng con tên... nay tuy được làm thân người, nhưng tâm hay trái đạo, vì sao mà biết? Vì từ sớm đến trưa, từ trưa đến chiều, từ chiều đến tối, từ tối đến sáng. Cho đến không có một thời một khắc, một niệm, một khoảnh nào mà chúng con để tâm nhớ tưởng Tam Bảo, nghĩ nhớ lý Tứ đế, cũng không có một chút tâm nào nghĩ nhớ báo ơn cha mẹ, cũng không có một chút tâm nào nghĩ nhớ báo ơn Sư trưởng; không có một chút tâm nào muốn bố thí, trì giới, nhẫn nhục, tinh tấn, không có một chút tâm nào muốn học thiền định, muốn tu trí huệ."],["p","Nay thử đem kiểm điểm lại các pháp thanh bạch thì chúng con không có một pháp nào đáng kể."],["p","Trái lại những phiền não trọng chướng thì không biết bao nhiêu mà kể, đầy tai đầy mắt."],["p","Nếu không kiểm soát như thế thì chúng con cũng tự hào rằng: Công đức của chúng con rất nhiều. Nếu có làm được chút việc thiện gì thì nói ta hay làm người khác không hay làm; ta hay tu người khác không hay tu; ý chí cao ngạo, xem như mục hạ vô nhân, quanh mình không còn ai nữa."],["p","Xét lại mà nghĩ, thật là đáng xấu hổ."],["p","Nay đối trước đại chúng, chúng con xin sám hối các tội lỗi ấy, mong đại chúng hoan hỷ bố thí cho, tương lai không còn chướng ngại nữa."],["p","Đại chúng cũng nên tự rửa sạch thân tâm. Theo sự trình bày quả báo như trước đã thuật đủ thì không thể tự khoan dung mà không cầu xả bỏ tội lỗi."],["p","Đại chúng chớ nói ta không có các tội ấy, ta đã vô tội, cần gì sám hối. Nếu đại chúng có nghĩ như thế, nguyện xin từ bỏ ngay tâm niệm ấy đi. Phải chăng bao nhiêu lầm lỗi vi tế đã kết thành tội lớn đại."],["p","Thoạt vậy giận hờn, sân tâm liền khởi, tập thành tánh quen, khó có thể sửa đổi mau chóng, không thể buông tâm phóng ý mà không ngăn ngừa."],["p","Nếu hay đè nén nhẫn nhịn thì phiền não có thể trừ. Người nào giải đãi lười biếng, buông lung thì không thể tế độ được."],["p","Đệ tử chúng con tên... ngày nay mong nhờ sức từ bi hộ niệm của chư Phật, chư đại Bồ Tát, sức bổn thệ nguyện lực mà nói kinh: “TỘI NGHIỆP, BÁO ỨNG, ĐỊA NGỤC” nên chúng con hết lòng lắng nghe."],["p","Ta nghe đức A Nan thuật lại như thế này: “Một hôm Phật ở tại thành Vương xá, trong núi Kỳ Xà Quật, cùng với chư Đại Bồ Tát Ma ha tát, các vị Thanh Văn và quyến thuộc của các ngài đông đủ; cũng có các vị Tỳ kheo, Tỳ kheo ni, Ưu bà tắc, Ưu bà di, chư thiên, quỷ thần, thảy đều đến dự hội đông đủ”."],["p","Lúc bấy giờ có ngài Tín Tướng Bồ Tát bạch Phật rằng:"],["p","“Bạch Đức Thế Tôn! Hôm nay có đủ chúng sanh ở các đường địa ngục, ngạ quỷ, súc sinh, sang, hèn, giàu, nghèo không biết bao nhiêu chủng loại... Phàm có chúng sanh nào nghe được Phật thuyết pháp thì cũng như con thơ gặp mẹ, như bệnh gặp thuốc, như lạnh có áo, như tối có đèn. Thế Tôn thuyết pháp lợi ích cho chúng sanh cũng như thế”."],["p","Lúc bấy giờ Phật thấy thời cơ đã đến; biết các vị Bồ Tát khuyến mời Phật thuyết pháp rất ân cần, Phật liền phóng đạo hào quang trắng giữa hai chân mày, soi khắp mười phương vô lượng thế giới, địa ngục không còn, thống khổ cũng hết."],["p","Lúc bấy giờ, hết thảy chúng sanh đang chịu tội, tìm ánh sáng quang minh của Phật mà tới; nhiễu quanh Phật bảy vòng, nhất tâm lạy Phật khuyến mời Phật thuyết pháp, rộng giáo hóa chúng sanh, khiến chúng sanh mong nhờ nghe pháp mà được giải thoát."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng cũng nên chí thành khuyến mời chư Phật thuyết pháp như vậy; nguyện cho chúng sanh đều được giải thoát."],["p","Chúng con cùng nhau chí tâm, một lòng tha thiết, đảnh lễ Thế Tôn, năm vóc sát đất như núi Thái Sơn sụp đổ mà khuyến thỉnh mười phương tận hư không giới hết thảy chư Phật thuyết pháp."],["p","Nguyện Phật đem sức từ bi, cứu các khổ não cho chúng sanh được an vui."],["p","Lại xin khuyến thỉnh quy y Thế gian Đại Từ Bi Phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Phạm Thiên Phật.","Nam mô Bất Thối Chuyển Luân"]],["v",["Thành Thủ Phật.","Nam mô Đại Hưng Quang Vương"]],["v",["Phật.","Nam mô Pháp Chủng Tôn Phật.","Nam mô Nhật Nguyệt Đăng Minh"]],["v",["Phật.","Nam mô Tu Di Phật.","Nam mô Đại Tu Di Phật.","Nam mô Siêu Xuất Tu Di Phật.","Nam mô Dụ Như Tu Di Phật.","Nam mô Hương Tượng Phật.","Nam mô Vi Nhiễu Hương Huân Phật.","Nam mô Tịnh Quang Phật.","Nam mô Pháp Tối Phật.","Nam mô Hương Tự Tại Vương Phật.","Nam mô Đại Tập Phật.","Nam mô Hương Quang Minh Phật.","Nam mô Hỏa Quang Minh Phật.","Nam mô Vô Lượng Quang Minh"]],["v",["Phật.","Nam mô Sư Tử Du Hí Bồ Tát.","Nam mô Sư Tử Phấn Tấn Bồ Tát.","Nam mô Kiên Dõng Tinh Tấn Bồ Tát.","Nam mô Kim Cang Huệ Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát.","Nam mô Phật Đà.","Nam mô Đạt Mạ.","Nam mô Tăng Già."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo. Nguyện xin Tam Bảo cứu hộ hết thảy chúng sanh, diệt trừ hết thảy khổ não, khiến các chúng sanh liền được giải thoát, bỏ ác theo lành, không làm ác nữa; từ nay trở đi không còn đọa địa ngục, ngạ quỷ, súc sinh nữa; thân khẩu ý đều thanh tịnh; không nghĩ đến việc ác của người; xa lìa các nghiệp chướng; được các nghiệp thanh tịnh; hết thảy tà ma không thể lay chuyển; thường tu bốn món vô lượng tâm; tinh tiến dõng mãnh, trồng các căn lành vô lượng vô biên; xả thân này thọ thân khác đều được thường sinh nơi phước địa; nhớ ba đường khổ, phát tâm Bồ đề tu đạo Bồ Tát không thôi không dứt. Lục độ tứ đẳng thường được hiện tiền. Tam minh lục thông, thường được như ý tự tại. Ra vào cảnh giới của chư Phật chơi giỡn tự do cùng các vị Bồ Tát thành bậc Chánh giác."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nên sinh tâm sợ hãi, sinh tâm từ bi nhất tâm nhất ý, lắng lòng mà nghe và suy nghĩ cho kỹ."],["p","Lúc bấy giờ, Đức Thế Tôn phóng đạo bạch hào tướng quang ở giữa hai chân mày soi sáng khắp hết thảy chúng sanh trong sáu đường. Khi ấy ngài Tín Tướng Bồ Tát vì thương xót hết thảy chúng sanh, liền từ tòa ngồi đứng dậy đến trước Phật quỳ gối chắp tay bạch Phật rằng:"],["p","“Bạch Đức Thế Tôn! Nay có chúng sanh bị các ngục tốt cắt chặt bằm chém thân thể từ đầu đến chân. Chúng sanh ấy bị chặt và chết ngất thì có gió xảo phong thổi sống lại. Sống rồi lại bị chặt, chịu khổ báo như thế vô cùng vô tận không bao giờ ngừng là vì tội gì vậy?”"],["p","Phật bảo: “Những chúng sanh ấy ở các đời trước không tin Tam Bảo, không biết cúng dường, bất hiếu với cha mẹ, sinh tâm ác nghịch; làm nghề hàng thịt, cắt chặt chúng sanh, vì các nhân duyên ấy nên mắc phải tội như vậy”."],["p","- Lại có chúng sanh, thân thể sần sượng tê cứng cả người, mày râu rụng hết, toàn thân bầm đỏ, bạn với chim muông, vắng vẻ bóng người, bà con xa bỏ, không ai muốn thấy. Ác báo như thế là bệnh phong hủi. Vì nhân duyên gì mà mắc Phải tội ấy?"],["p","Phật đáp: “Vì đời trước người ấy không tin Tam Bảo, bất hiếu với cha mẹ, phá tháp hủy chùa, bóc lột của người tu hành, chém bắn Thánh Hiền, tổn thương Sư trưởng, chưa từng biết quấy; vong ơn bội nghĩa, hành động như cẩu khuyển (chó) làm xấu người trên, không kể thân sơ, không biết hổ thẹn, vì nhân duyên ấy nên mắc phải tội như vậy”."],["p","- Lại có chúng sanh thân hình dài lớn, tai điếc, chân không có, quằn quại bò lết mà đi, chỉ ăn đất cát mà sống; bị các sâu trùng nhỏ nhiệm cắn rứt; ngày đêm chịu khổ vô cùng không gián đoạn; vì nhân duyên gì mắc phải tội ấy?"],["p","Phật dạy: “Vì đời trước làm người chỉ biết có mình, không tin lời hay, lời lành của kẻ khác. Bất hiếu với cha mẹ, trái ý phản nghịch, hoặc làm địa chủ hay làm quan to, trấn nhậm bốn phương, hoặc làm châu trưởng, quận trưởng cai trị đốc suất dân chúng mà cậy oai ỷ thế, xâm đoạt của người cách vô lý, không đạo đức, làm cho dân chúng cùng khổ. Vì nhân duyên ấy nên mắc phải tội như vậy.”"],["p","- Lại có chúng sanh đui cả hai mắt, không thấy biết gì, hoặc bị cây đè, hoặc sa hầm hố mà chết, chết rồi sống lại, sống lại rồi chết, cứ như thế mãi. Vì nhân duyên gì, mắc phải tội ấy?"],["p","Phật đáp: “Vì đời trước không tin tội phước, che ánh sáng của Phật, may bít mắt người, giam nhốt chúng sanh, lấy bao lấy đãy bao đầu chúng sanh, không cho trông thấy. Vì nhân duyên ấy nên mắc phải tội như vậy”."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nghe lời kinh dạy như vậy rất đáng sợ hãi."],["p","Chúng con cũng có thể đã làm những tội như thế. Nhưng vì vô minh che lấp tâm tánh nên không tự nhớ biết đó mà thôi."],["p","Những tội như vậy vô lượng vô biên đến đời sau sẽ chịu khổ báo."],["p","Ngày nay chí tâm, một lòng tha thiết, đầu thành đảnh lễ, năm vóc sát đất như núi Thái Sơn sụp đổ, cầu xin sám hối, hổ thẹn ăn năn, cải đổi tâm tánh. Những tội đã làm rồi, nhờ sám hối mà trừ diệt."],["p","Những tội chưa làm, từ nay thanh tịnh."],["p","Nguyện xin quy y hết thảy mười phương chư Phật:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Khai Quang Minh Phật.","Nam mô Nguyệt Đăng Quang Phật.","Nam mô Nhật Nguyệt Quang Phật.","Nam mô Nhật Nguyệt Quang Minh"]],["v",["Phật.","Nam mô Hỏa Quang Minh Phật.","Nam mô Tập Âm Phật.","Nam mô Tối Oai Nghi Phật.","Nam mô Quang Minh Tôn Phật.","Nam mô Liên Hoa Quân Phật.","Nam mô Liên Hoa Hưởng Phật.","Nam mô Đa Bảo Phật.","Nam mô Sư Tử Hống Phật.","Nam mô Sư Tử Âm Vương Phật.","Nam mô Tinh Tấn Quân Phật.","Nam mô Kim Cang Dõng Dược Phật.","Nam mô Độ Nhất Thế Thuyền Tuyệt"]],["v",["Chúng Nghi Phật.","Nam mô Bảo Đại Thị Tùng Phật.","Nam mô Vô Ưu Phật.","Nam mô Địa Lực Trì Dõng Phật.","Nam mô Tối Dõng Dược Phật.","Nam mô Sư Tử Tác Bồ Tát.","Nam mô Khí Ấm Cái Bồ Tát.","Nam mô Tịch Căn Bồ Tát.","Nam mô Thường Bất Ly Thế Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát.","Nam mô Phật Đà.","Nam mô Đạt Mạ.","Nam mô Tăng Già."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo, nguyện xin Tam Bảo rũ lòng đại từ đại bi, gia hộ cứu vớt khiến các chúng sanh liền được giải thoát. Vì các chúng sanh mà diệt trừ những nghiệp địa ngục, ngạ quỷ, súc sinh, khiến các chúng sanh rốt ráo không chịu các quả báo dữ nữa, khiến các chúng sanh bỏ khổ trong ba đường ác, đồng đến chỗ trí huệ, đều được yên ổn, hoàn toàn an vui."],["p","Nguyện xin Tam Bảo đem ánh sáng đại quang minh, diệt trừ mê mờ rất si ám cho chúng sanh; phân biệt rộng rãi, giải thích rõ ràng pháp môn vi diệu, thậm thâm nhiệm mầu cho chúng sanh nghe, khiến chúng sanh đều được chứng quả Vô thượng Bồ đề, thành bậc Chánh giác."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại nên chí thành nhất tâm mà nghe, suy nghĩ cho kỹ."],["p","Tín Tướng Bồ Tát bạch Phật rằng: “Bạch Đức Thế Tôn! Lại có chúng sanh ngọng lịu ấm á, miệng không thể nói, dầu có nói cũng không rõ ràng. Vì nhân duyên gì, mắc phải tội ấy?”"],["p","Phật đáp: “Vì đời trước người ấy phỉ báng Tam Bảo, khinh hủy Thánh đạo, bàn luận việc xấu tốt của người, tìm việc hay dở của người, vu oan cho kẻ lương thiện, ghen ghét người hiền. Vì nhân duyên ấy, nên mắc phải tội như vậy”."],["p","- Lại có chúng sanh bụng lớn như trống, cổ nhỏ như kim, không thể ăn nuốt được. Nếu có đồ ăn, đồ ăn biến thành máu mủ. Vì nhân duyên gì mắc phải tội ấy?"],["p","Phật đáp: “Vì đời trước, người ấy trộm cắp đồ ăn của chúng. Khi có đại hội, sắm các thức ăn ngon, người ấy lấy riêng mà ăn, hoặc lấy mè muối, gạo cơm ra chỗ khuất mà ăn. Lại thêm keo rít, tiếc của mình, tham của người, thường ôm lòng độc ác, cho người uống thuốc độc, nghẹt thở không thông. Vì nhân duyên ấy nên mắc phải tội như vậy”."],["p","- Lại có chúng sanh thường bị ngục tốt thiêu đốt, dội nước sắt nóng vào thân, đóng đinh sắt vào thân, đóng rồi tự nhiên hỏa bốc thiêu cháy thân thể thảy đều phỏng đỏ. Vì nhân duyên gì mắc phải tội ấy?"],["p","Phật đáp: “Vì đời trước làm thầy châm lễ, tổn thương thân thể của người."],["p","Châm chích không lành, gạt người lấy của, làm cho người đau khổ. Vì nhân duyên ấy nên mắc phải tội như vậy”."],["p","Lại có chúng sanh thường ở trong cái vạc (cái chảo nấu) nước sôi, ngưu đầu ngục tốt, tay cầm xoa sắt, móc bỏ vào vạc nấu chín rục, rồi thổi cho sống lại. Sống lại rồi nấu nữa. Vì nhân duyên gì nên mắc phải tội ấy?"],["p","Phật đáp: “Vì đời trước người ấy làm nghề hàng thịt, giết chúng sanh, trụng nước sôi, nhổ sạch lông, giết hại rất nhiều không thể kể xiết. Vì nhân duyên ác nghiệp ấy nên mắc phải tội như vậy”."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nghe lời kinh dạy như vậy rất đáng sợ hãi."],["p","Chúng con không biết ở trong đường ác nào đã từng làm vô lượng tội nghiệp như thế. Đời sau quyết phải mắc quả báo ác nghiệt ấy. Ngay trong đời hiện tại chúng con cũng có thể mắc phải quả báo ác nghiệt ấy. Ấp úng, ngọng lịu, miệng không thể nói, hoặc bụng lớn cổ nhỏ, không thể ăn nuốt, mạng sống vô thường."],["p","Ngày nay tuy an vui, ngày mai thế nào không thể biết được. Thình lình gặp phải quả báo đến, không thể thoát được."],["p","Mọi người đều nên hiểu rõ ý ấy, nhất tâm chánh niệm, chớ tư tưởng gì nữa, chỉ một lòng tha thiết, năm vóc sát đất, đầu thành đảnh lễ, nguyện vì hết thảy chúng sanh ở khắp trong bốn loài sáu đường, ngày nay đang chịu khổ, đã chịu khổ, hay sẽ chịu khổ mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Tự Tại Vương Phật.","Nam mô Vô Lượng Âm Phật.","Nam mô Định Quang Minh Phật.","Nam mô Bảo Quang Minh Phật.","Nam mô Bảo Cái Chiếu Không Phật.","Nam mô Diệu Bảo Phật.","Nam mô Đế Tràng Phật.","Nam mô Phạm Tràng Phật.","Nam mô A Di Đà Phật.","Nam mô Thù Thắng Phật.","Nam mô Tập Âm Phật.","Nam mô Kim Cang Bộ Tinh Tấn"]],["v",["Phật.","Nam mô Tự Tại Vương Thần Thông"]],["v",["Phật.","Nam mô Bảo Hỏa Phật.","Nam mô Tịnh Nguyệt Tràng Xưng"]],["v",["Quang Minh Phật.","Nam mô Diệu Lạc Phật,","Nam mô Vô Lượng Tràng Phan Phật.","Nam mô Vô Lượng Phan Phật.","Nam mô Đại Quang Phổ Chiếu Phật.","Nam mô Bảo Tràng Phật","Nam mô Huệ Thượng Bồ Tát.","Nam mô Thường Bất Ly Thế Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát.","Nam mô Phật Đà.","Nam mô Đạt Mạ.","Nam mô Tăng Già."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo, nguyện xin chư Phật, chư Đại Bồ Tát, đem sức đại từ đại bi, cứu hộ hết thảy chúng sanh đang chịu khổ, dùng sức thần thông diệt trừ ác nghiệp cho các chúng sanh, hoàn toàn không đọa trở lại trong ba đường khổ, đến được chỗ an vui thanh tịnh, sinh ra chỗ nào cũng được thanh tịnh, công đức đầy đủ, không thể cùng tận. Xả thân thọ thân hằng gặp chư Phật, đồng với các vị Đại Bồ Tát thành đẳng Chánh giác."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại gia tâm lực, lắng tai nghe kỹ."],["p","Tín Tướng Bồ Tát lại bạch Phật rằng: “Bạch Đức Thế Tôn! Lại có chúng sanh ở trong hỏa thành tâm can bị thiêu đốt, bốn cửa thành tuy mở, nhưng chạy đến thì cửa liền tự đóng, chạy khắp đông tây cũng không ra được, bị lửa thiêu sạch. Vì nhân duyên gì mà mắc phải tội ấy?”"],["p","Phật đáp: “Vì đời trước làm người thiêu đốt rừng núi, phá vỡ bờ đê, chiên rán các thứ trứng gà vịt làm cho chúng sanh bị thiêu, bị đốt mà chết nên phải mắc tội như vậy”."],["p","- Lại có chúng sanh thường ở núi Tuyết Sơn bị gió lạnh thổi, da thịt nức nở, cầu chết không được, cầu sống không được, khổ sở vô cùng không thể chịu nổi."],["p","Vì nhân duyên gì mà mắc phải tội ấy?"],["p","Phật đáp: “Người ấy đời trước làm giặc, đón đường bóc lột áo quần người khác để tự tư dưỡng; mùa đông giá lạnh, lột truồng hình người khác, làm cho họ phải chết lạnh và lột da xẻ thịt trâu dê, làm cho chúng sanh đau khổ vô lượng. Vì nhân duyên ấy nên mắc phải tội như vậy”."],["p","- Lại có chúng sanh thường ở trên núi dao, rừng kiếm, rờ đụng vào đâu thì liền bị cắt đứt đó, thân thể tay chân đều bị chặt nát, đau đớn khổ sở, không thể chịu nổi. Vì nhân duyên gì mà mắc phải tội ấy?"],["p","Phật đáp: “Vì người ấy đời trước làm nghề sát sinh, phanh thây xẻ thịt chúng sanh, cắt xẻo bóc lột, cốt nhục chia lìa, đầu mình tan rã, treo lên trên cao, cân lường mà bán, hoặc treo sống mà bán đau đớn vô cùng chúng sanh không thể chịu nổi. Vì nhân duyên ác nghiệp ấy nên mắc phải tội như vậy”."],["p","- Lại có chúng sanh tai mắt v.v... năm căn không đủ. Vì nhân duyên gì mắc phải tội ấy?"],["p","Phật đáp: “Vì đời trước nuôi chim bay chó chạy để đi săn bắn. Bắn chim bắn thú, hoặc bắn bể đầu, hoặc bẫy đứt chân, nhổ sống lông cánh, làm chúng sanh đau khổ vô cùng không thể chịu nổi. Vì nhân duyên ấy nên phải mắc tội như vậy”."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nghe lời Kinh dạy như vậy rất đáng sợ hãi. Cùng nhau chí tâm, một lòng tha thiết, năm vóc sát đất, đầu thành đảnh lễ nguyện vì hết thảy chúng sanh trong mười phương, hoặc đã chịu khổ, hoặc đang chịu khổ, hoặc sẽ chịu khổ mà quy y thế gian Đại Từ Bi Phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Tịnh Quang Phật.","Nam mô Bảo Vương Phật.","Nam mô Thọ Căn Hoa Vương Phật.","Nam mô Duy Vệ Trang Nghiêm Phật.","Nam mô Khai Hóa Bồ Tát Phật.","Nam mô Kiến Vô Khủng Cụ Phật.","Nam mô Nhất Thừa Độ Phật.","Nam mô Độc Nội Phong Nghiêm"]],["v",["Vương Phật.","Nam mô Kim Cang Kiên Cường Tiêu"]],["v",["Phục Hoại Tán Phật.","Nam mô Bảo Hỏa Phật.","Nam mô Bảo Nguyệt Quang Minh"]],["v",["Phật.","Nam mô Hiền Tối Phật.","Nam mô Bảo Liên Hoa Bộ Phật.","Nam mô Hoại Ma La Võng Độc Bộ"]],["v",["Phật.","Nam mô Sư Tử Hống Lực Phật.","Nam mô Bi Tinh Tấn Phật.","Nam mô Kim Bảo Quang Minh Phật.","Nam mô Vô Lượng Tôn Phong Phật.","Nam mô Vô Lượng Tôn Ly Cấu"]],["v",["Vương Phật.","Nam mô Độc Thủ Phật.","Nam mô Dược Vương Bồ Tát.","Nam mô Dược Thượng Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo, nguyện xin Tam Bảo đem lòng đại từ, đại bi cứu hộ hết thảy chúng sanh trong mười phương khiến các chúng sanh hiện đang chịu khổ liền được giải thoát; chúng sanh sẽ chịu khổ hoàn toàn đoạn trừ phiền não, rốt ráo không sa đọa trở lại trong ba đường ác nữa."],["p","Từ nay trở đi cho đến ngày thành Phật, trừ sạch ba nghiệp chướng, diệt hết năm sợ hãi; hoàn toàn đầy đủ công đức trang nghiêm; nhiếp hóa hết thảy chúng sanh hướng về Vô thượng đạo, thành bậc Chánh giác."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại lắng lòng mà nghe:"],["p","Tín Tướng Bồ Tát bạch Phật: “Bạch Đức Thế Tôn! Lại có chúng sanh què trệt, lưng cong, tay chân co quắp, không thể cầm nắm, không thể đi đứng. Vì nhân duyên gì mà mắc phải tội ấy?”"],["p","Phật đáp: “Vì đời trước làm người độc ác, để binh khí giữa đường, đặt súng đặt gươm, đào hầm đào hố, hãm hại chúng sanh. Vì ác nghiệp ấy nên mắc phải tội như vậy”."],["p","- Lại có chúng sanh bị các ngục tốt trói buộc thân thể, gông cùm khổ ách, không thể thoát được. Vì nhân duyên gì mà mắc phải tội ấy?"],["p","Phật đáp: “Vì đời trước người ấy chài lưới chúng sanh, buộc nhốt lục súc, hoặc làm chủ tể, quyền hành địa phương, cai trị dân chúng, tham lam vơ vét, giam oan người vô tội, lương thiện oán hận không biết kêu ai. Vì ác nghiệp ấy nên mắc phải tội như vậy”."],["p","- Lại có chúng sanh hoặc điên, hoặc si, hoặc cuồng, hoặc sợ, không phân biệt được tốt xấu. Vì nhân duyên gì mà mắc phải tội ấy?"],["p","Phật đáp: “Vì đời trước làm người uống rượu say sưa, loạn trí loạn tâm, phạm ba mươi sáu lỗi nên đọa làm người ngu si, cũng như người say không phân biệt được tốt xấu, thượng hạ tôn ty. Vì ác nghiệp ấy nên mắc phải tội như vậy”."],["p","- Lại có chúng sanh thân lùn, hình nhỏ, âm tạng rất lớn, thả xuống thì thân đau, phải vắt ra sau lưng mà đi, đi đứng nằm ngồi đều bị trở ngại. Vì nhân duyên gì mắc phải tội ấy?"],["p","Phật đáp: “Vì đời trước buôn bán vàng ngọc, khen vật báu của mình, chê vật báu của người, thay đổi thăng đấu, vặn cân bẻ móc, (gian lận thước tấc). Vì ác nghiệp ấy nên mắc phải tội như vậy”."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nghe lời Phật dạy như vậy rất đáng sợ hãi. Cùng nhau nhất tâm, một lòng tha thiết, năm vóc sát đất, đầu thành đảnh lễ nguyện vì hết thảy chúng sanh đã chịu khổ; hết thảy chúng sanh sẽ phải chịu khổ, hết thảy chúng sanh hiện đang chịu khổ trong sáu đường; và nguyện vì cha mẹ, sư trưởng, tín thí đàn việt, thiện ác tri thức, rộng ra cho đến hết thảy chúng sanh khắp trong mười phương mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Vô Số Tinh Tấn Hưng"]],["v",["Phong Phật.","Nam mô Vô Ngôn Thắng Phật.","Nam mô Vô Ngu Phong Phật.","Nam mô Nguyệt Anh Phong Phật.","Nam mô Vô Dị Quang Phong Phật.","Nam mô Nghịch Không Quang Minh"]],["v",["Phật.","Nam mô Tối Thanh Tịnh Vô Lượng"]],["v",["Phan Phật.","Nam mô Hiếu Đế Trú Duy Vương"]],["v",["Phật.","Nam mô Thành Tựu Nhất Thế Chư"]],["v",["Sát Phong Phật.","Nam mô Tịnh Huệ Đức Phong Phật.","Nam mô Tịnh Luân Phan Phật.","Nam mô Lưu Ly Quang Tối Phong"]],["v",["Phật.","Nam mô Bảo Đức Bộ Phật.","Nam mô Tối Thanh Tịnh Đức Bảo"]],["v",["Trú Phật.","Nam mô Độ Bảo Quang Minh Tháp"]],["v",["Phật.","Nam mô Vô Lượng Tàm Quý Kim Tối"]],["v",["Phong Phật.","Nam mô Văn Thù Sư Lợi Bồ Tát.","Nam mô Phổ Hiền Vương Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Đệ tử chúng con tên... ngày nay mong nhờ Phật lực, Pháp lực, Bồ Tát lực, nguyện vì hết thảy chúng sanh mà đảnh lễ quy y cầu xin sám hối."],["p","Những chúng sanh đã chịu khổ rồi, xin nhờ sức đại từ bi của chư Phật, chư Bồ Tát, liền được giải thoát."],["p","Những chúng sanh chưa chịu khổ, từ nay trở đi cho đến ngày thành đạo, rốt ráo không đọa trở lại trong các đường ác, xa lìa tám nạn khổ, bẩm thọ tám phước sinh; được các căn lành, thành tựu bình đẳng, đầy đủ trí huệ, thành tựu biện tài, thanh tịnh tự tại, cùng với chư Phật thành bậc Chánh giác."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nên biết dụng tâm, lắng lòng mà nghe."],["p","Tín Tướng Bồ Tát bạch Phật rằng: “Bạch Đức Thế Tôn, lại có chúng sanh, hình trạng rất xấu, thân đen như mực, hai tai lại xanh, hai vai nổi lên, mặt phẳng, mũi dẹp, mắt đỏ vàng ngầu, răng nướu thưa sún, hơi miệng tanh hôi, vế ngắn và ung thủng; bụng lớn, lưng nhỏ, tay chân co quắp; xương sườn, xương sống nổi lên, tốn vải, ăn nhiều; ghẻ dữ tanh hôi, máu mủ nhơ nhớp; bệnh thủy thủng, càn tiêu, phung hủi ung thư, bao nhiêu điều ác độc hung dữ đều dồn vào thân. Dầu muốn thân cận, người không để ý. Nếu người khác làm tội, vô cớ mình cũng liên can mang họa. Hằng không được thấy Phật, nghe Pháp, không biết Bồ Tát không biết Thánh Hiền. Ra vào nơi đau khổ, không bao giờ cùng. Vì nhân duyên gì mắc phải tội ấy?”"],["p","Phật dạy: “Vì đời trước làm con bất hiếu với cha mẹ; làm tôi không trung chánh với vua, làm người trên không thương kẻ dưới, làm người dưới không biết kính kẻ trên, không thành thật, không thủ tín với bạn bè, không nhân nghĩa với làng xóm; không chức tước với triều đình; không đạo đức trong sự xử đoán, không có độ lượng mà lòng dạ đảo điên, sát hại quần thần; khinh khi tôn trưởng, bán nước buôn dân, phá thành phá lũy, cướp giựt trộm cắp, ác nghiệp vô lượng."],["p","Lại khen mình chê người, xâm lấn già nua, lấn hiếp cô độc; báng bổ người hiền, khinh mạn sư trưởng; khi dối kẻ hạ tiện."],["p","Tóm lại là phạm hết thảy tội. Vì nhân duyên ấy nên mắc phải ác báo, tội nghiệp như vậy”."],["p","Lúc bấy giờ, những người bị tội nghe Phật dạy như vậy, khóc lóc động địa, nước mắt trào như mưa, bèn bạch Phật rằng: “Nguyện xin Thế Tôn sống mãi ở đời, thuyết pháp giáo hóa cho chúng con mong được giải thoát”."],["p","Phật đáp: “Nếu ta sống mãi ở đời, những người bạc phước, không trồng căn lành. Họ bảo Ta còn sống mà không lo nghĩ đến vô thường, tự do tạo ra vô lượng tội ác, sau ăn năn không kịp."],["p","Thiện nam tử ôi! Ví như con thơ, mẹ thường ở bên mình thì con không nghĩ đến sự gặp mẹ là khó. Lúc nào mẹ đi vắng, con mới liền sinh tâm nhớ tưởng, khao khát luyến mẹ. Lúc ấy mẹ trở lại con mới vui mừng."],["p","Thiện nam tử ôi! Ta nay cũng như vậy. Ta biết chúng sanh không tìm cầu sự thật, thường trú chơn tâm, cho nên Ta nhập Niết bàn."],["p","Lúc bấy giờ, Phật đối trước những chúng sanh đang chịu tội đó mà nói bài kệ rằng:"],["v",["Nước chảy không thường đầy,","Lửa mạnh không thường đốt,","Mặt trời mọc rồi lặn,","Mặt trăng tròn rồi khuyết,","Sự tôn trọng giàu sang,","Càng vô thường hơn nữa,","Nghĩ lại phải siêng năng,","Đảnh lễ ngôi Tam Bảo."]],["p","Lúc bấy giờ, Phật nói lời kệ ấy rồi, các người bị tội kia thảy đều buồn rầu mà bạch Phật rằng: “Hết thảy chúng sanh làm những việc lành gì mà xa lìa được những tội khổ ấy?”"],["p","Phật dạy: “Này thiện nam tử! Phải siêng năng hiếu dưỡng cha mẹ, phụng sự sư trưởng, quy y Tam Bảo, siêng tu hạnh bố thí, trì giới, nhẫn nhục, tinh tấn, thiền định, trí huệ, từ bi, hỷ xả, xem kẻ oán người thân như nhau, không có thân sơ, không khinh người già nua, cô quả, không khinh kẻ nghèo hèn, ủng hộ người như giúp đỡ mình, không có tâm ác đối với người."],["p","Nếu các người hay tu hành được như vậy thời cũng đã là báo được ơn chư Phật; hằng xa lìa ba đường ác, không còn đau khổ nữa”."],["p","Phật dạy kinh này rồi, các vị đại Bồ Tát liền được quả Vô thượng Bồ đề. Các hàng Thanh Văn, Duyên Giác liền chứng được lục thông, tam minh và tám pháp giải thoát."],["p","Còn các đại chúng khác đều được pháp nhãn tịnh."],["p","Nếu có chúng sanh nào, nghe được kinh này thì không đọa vào ba đường ác, và không mắc phải tám nạn, địa ngục trống rỗng, thống khổ không còn."],["p","Tín Tướng Bồ Tát bạch Phật rằng:"],["p","“Bạch Đức Thế Tôn! Kinh này gọi là kinh gì? Bồ Tát Ma ha tát phải phụng trì bằng cách nào?”"],["p","Phật bảo Tín Tướng Bồ Tát: “Thiện nam tử! Kinh này gọi là “Báo ứng giáo hóa Địa ngục kinh”. Các ngươi nên phụng trì, và lưu truyền cùng khắp, công đức vô lượng”."],["p","Bấy giờ, đại chúng nghe Phật dạy lời ấy rồi hết lòng vui mừng, đảnh lễ vâng lời làm theo."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nghe lời Phật dạy như vậy, rất đáng sợ hãi, sinh tâm từ bi, nương nhờ thần lực của chư Phật, tu đạo Bồ Tát nhớ địa ngục khổ, phát tâm Bồ đề, vì hết thảy chúng sanh hiện đang chịu khổ, ở đường địa ngục, hết thảy chúng sanh hiện đang chịu khổ ở đường ngạ quỷ, hết thảy chúng sanh hiện đang chịu khổ ở đường súc sinh; rộng ra cho đến hết thảy chúng sanh cùng khắp mười phương hiện đang chịu khổ trong sáu đường; nhất tâm nhất ý, vì những chúng sanh ấy mà sám hối, khiến chúng sanh được giải thoát."],["p","Nếu đại chúng không siêng làm phương tiện, chuyển họa thành phước, thì ở trong mỗi mỗi địa ngục, đại chúng đều có tội phần."],["p","Cùng nhau chí tâm nghĩ đến cha mẹ, sư trưởng, bà con thân thích, sẽ chịu khổ báo về sau và cũng nghĩ đến tự thân đại chúng hiện tại và vị lai cũng phải chịu khổ báo như vậy. Cho nên đại chúng phải cùng nhau nhất tâm tha thiết, năm vóc sát đất, chí thành ân cần vận dụng tư tưởng, nguyện xin một niệm cảm thấu mười phương Phật; một lạy đoạn trừ vô lượng tội khổ. Những chúng sanh đã chịu khổ trong sáu đường, xin nhờ Phật lực, Pháp lực, Hiền Thánh lực khiến các chúng sanh ấy liền được giải thoát. Nếu trong sáu đường chúng sanh nào chưa chịu khổ, xin nhờ Phật lực, Pháp lực, Hiền Thánh lực làm cho các chúng sanh ấy vĩnh viễn đoạn trừ sáu đường đau khổ."],["p","Từ nay trở đi rốt ráo không đọa trở lại trong các đường ác; trừ ba nghiệp chướng, tùy ý vãng sanh, diệt trừ năm điều sợ hãi, tự tại giải thoát, siêng tu đạo nghiệp, không thôi không nghỉ. Diệu hạnh trang nghiêm quá Pháp Vân địa, vào Kim cang tâm, thành đẳng Chánh giác."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại nhất tâm lưu ý, lắng lòng mà nghe và suy nghĩ cho kỹ:"],["p","Kinh Tạp Tạng chép: Bấy giờ có một con quỷ bạch với ngài Mục Liên rằng:"],["p","“Thân tôi hai vai có mắt, ngực có mũi có miệng mà không có đầu. Vì nhân duyên gì mắc phải tội ấy?”"],["p","Ngài Mục Liên đáp: “Đời trước ngươi làm học trò nhà hàng thịt, khi giết trâu bò thì ngươi vui mừng, lấy dây trói buộc mà lôi kéo. Vì nhân duyên ấy nên mắc phải tội như vậy. Đó là tội báo mới nụ hoa, kết quả sẽ ở địa ngục”."],["p","- Lại có một con quỷ khác bạch ngài Mục Liên rằng: “Thân hình tôi như một khối thịt, không có tay chân, tai, mắt, mũi, lưỡi v.v... Thân thường bị trùng rúc chim mổ, cắn rứt mà ăn, đau đớn vô cùng, không thể chịu nổi. Vì nhân duyên gì mà mắc phải tội ấy?”"],["p","Ngài Mục Liên đáp: “Đời trước ngươi cho người uống thuốc độc đọa thai, phá sản khiến chúng sanh mạng sống không hoàn toàn. Vì nhân duyên ấy nên mắc phải tội như vậy?”"],["p","- Lại có một con quỷ bạch ngài Mục Liên rằng: “Bụng tôi thật lớn, yết hầu như kim. Cùng năm mãn kiếp không thể ăn uống. Vì nhân duyên gì mà mắc phải tội ấy?”"],["p","Ngài Mục Liên đáp: “Đời trước ngươi làm chủ hàng xóm, tự ỷ mình hào quý, say sưa tung hoành, khinh khi kẻ khác, cướp giựt thức ăn uống của người làm cho đói khát, khốn khổ hết thảy nhân dân. Vì nhân duyên ấy nên mắc phải tội như vậy."],["p","Đó là quả báo mới đơm hoa, nó sẽ kết quả ở địa ngục”."],["p","- Lại có một con quỷ bạch ngài Mục Liên rằng: “Tôi một đời lại đây, có hai vành sắt nóng ở dưới hai nách, toàn thân cháy rụi. Vì tội gì đến nỗi như thế?”"],["p","Ngài Mục Liên đáp: “Đời trước ngươi chia bánh cho chúng, ngươi trộm lấy hai cái, kẹp dưới hai nách. Vì nhân duyên ấy nên mắc phải tội như vậy. Đó là tội mới đơm hoa, kết quả sẽ ở địa ngục”."],["p","- Lại có một con quỷ, bạch ngài Mục Liên rằng: “Tôi thường lấy đồ tự bao bọc đầu lại, sợ người đến giết, sinh tâm sợ hãi. Vì tội gì đến nỗi như thế?”"],["p","Ngài Mục Liên đáp: “Đời trước ngươi dâm phạm ngoại sắc, thường sợ người thấy, hoặc sợ chồng con người bắt được trói trăn, đánh giết, thường ôm lòng sợ hãi, cho nên mắc phải tội này. Đó là tội mới đơm hoa, nó sẽ kết quả ở địa ngục”."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nghe lời Kinh dạy, đâu được không sợ hãi."],["p","Từ vô thỉ trở lại cho đến ngày nay chúng con cũng đã làm vô lượng tội ác như thế. Những tội ấy đều do vì không có tâm từ bi, ỷ mạnh hiếp yếu, tổn hại chúng sanh, cho đến tội trộm cắp của người, mê hoăc̣\u0001 vô đạo, nịnh hót, bài báng người hiền lành, gây biết bao tội lỗi."],["p","Những tội báo như vậy ở trong địa ngục, quyết phải chịu thống khổ trong ba đường dữ."],["p","Ngày nay chí tâm một lòng tha thiết, năm vóc sát đất, đầu thành đảnh lễ, thay thế cho hết thảy chúng sanh khắp mười phương, đã chịu khổ báo trong sáu đường, đang chịu khổ trong sáu đường mà cầu xin sám hối."],["p","Cũng nguyện xin thay thế cho cha mẹ, sư trưởng và hết thảy bà con quyến thuộc mà cầu xin sám hối và cũng tự vì bản thân mà cầu xin sám hối."],["p","Những tội đã làm, nguyện xin trừ diệt hết. Những tội chưa làm, không dám làm nữa."],["p","Nguyện xin quy y Thế gian Đại Từ Bi Phụ."],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Liên Hoa Tôn Phong Phật.","Nam mô Tịnh Bảo Hưng Phong Phật.","Nam mô Điện Đăng Phan Vương"]],["v",["Phật.","Nam mô Pháp Không Đăng Phật.","Nam mô Nhất Thế Chúng Đức Thành"]],["v",["Phật.","Nam mô Hiền Phan Tràng Vương"]],["v",["Phật.","Nam mô Nhất Thế Bảo Trí Sắc Trì"]],["v",["Phật.","Nam mô Đoạn Nghi Bạc Dục Trừ"]],["v",["Minh Phật.","Nam mô Ý Vô Khủng Cụ Oai Mao Bất"]],["v",["Thọ Phật.","Nam mô Sư Tử Phật.","Nam mô Danh Xưng Viễn Văn Phật.","Nam mô Pháp Danh Hiệu Phật.","Nam mô Phụng Pháp Phật.","Nam mô Pháp Tràng Phật.","Nam mô Tu Di Đăng Quang Minh"]],["v",["Phật.","Nam mô Bảo Tạng Trang Nghiêm"]],["v",["Phật.","Nam mô Chiên Đàn Ma Ni Quang"]],["v",["Phật.","Nam mô Kim Hải Tự Tại Vương Phật.","Nam mô Đại Bi Quang Minh Vương"]],["v",["Phật.","Nam mô Ưu Bát La Liên Hoa Thắng"]],["v",["Phật.","Nam mô Liên Hoa Tu Trang Nghiêm"]],["v",["Vương Phật.","Nam mô Kim Cang Kiên Cường Tự"]],["v",["Tại Vương Phật.","Nam mô Thù Thắng Nguyệt Vương"]],["v",["Phật.","Nam mô Nhật Nguyệt Quang Vương"]],["v",["Phật.","Nam mô Đại Thế Chí Bồ Tát.","Nam mô Thường Tinh Tấn Bồ Tát.","Nam mô Bất Hưu Tức Bồ Tát.","Nam mô Hư Không Tạng Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo, nguyện xin Tam bảo rũ lòng đại từ đại bi cứu hộ hết thảy chúng sanh, hiện đang chịu khổ, và sẽ chịu khổ trong sáu đường, khiến các chúng sanh ấy liền được giải thoát, đem sức thần thông diệt trừ ba đường ác và nghiệp địa ngục, khiến các chúng sanh ấy từ nay trở đi cho đến ngày thành Phật hoàn toàn không đọa trở lại trong đường ác, xả thân khổ báo, được thân Kim cang, tứ vô lượng tâm, lục ba la mật thường được hiện tiền; tứ vô ngại biện, sáu sức thần thông như ý tự tại, dõng mãnh tinh tấn, không thôi không nghỉ, cho đến khi mãn hạnh Thập Địa, trở lại độ thoát hết thảy chúng sanh."],["v",["Lương Hoàng Bảo Sám,","Võ Đế bi đề,","Xà thần sổ trượng nhiễu đơn trì,","Lưỡng nhãn hỏa quang phi,","Khải cáo Từ Bi,","Độ thoát xuất A tỳ."]],["v",["Lương Hoàng Bảo Sám,","Vạn đức hồng danh,","Linh văn tam quyển tối hoằng thâm, Tự tự miễn tai truân,","Đảnh lễ Phật danh,","Tiêu tai bảo an ninh.","Nam mô Phát Quang Địa Bồ Tát Ma Ha","Tát. (3 lần)"]],["h","Cung Văn"],["p","Phật thân tướng hảo, nguy nguy hoảng nhược tử kim sơn. Pháp hải trừng thanh, kiểu kiểu do như Ngân Hán nguyệt. Bồ Tát Hiền Thánh, ứng cúng ư nhân gian thiên thượng. Bích Chi La Hán, thuyết pháp ư thử giới tha phương. Tam thiên sát hải chi minh đăng; bách ức hôn cù chi nhật nguyệt. Công thâm mạc trắc, đức bất khả lượng. Tác tam giới chi quyện hoành, kiến tam thời chi Phật sự."],["p","Thượng lai phụng vì cầu sám hối đệ tử đẳng... tu sùng Từ Bi Đạo Tràng Sám Pháp, kim đương đệ tam quyển công khóa viên mãn, tam muội hành nhân, xuất nhập tam thời, quy mạng Tam Bảo, đoan bỉnh nhất tâm, nhiệt ngũ phận chi chân hương, tán tam xuân chi hoa nhụy. Bàn trình diệu cúng, âu phiếm tiên trà chung khánh hòa minh, nhi phạm âm thanh diệu."],["p","Phúng kinh hành đạo nhi yến mặc thuyền tư. Sở tác tùng tâm, tổng thân hồi hướng Lạc Bang Vô Lượng Thọ Giáo chủ, Thích Ca Văn, Quan Âm tịnh Địa Tạng, La hán dữ Thanh văn, Thiên Tào cập Địa Phủ. Tam giới chúng cao chơn, hàm sanh hoan hỷ niệm, giám thử thắng công huân."],["p","Bi tâm vô giải quyện, phú hộ ư quần sinh."],["p","Dĩ tư bất tận công đức phụng vì cầu sám đệ tử đẳng... Liệt tam độc căn, việt tam giới võng. Phục nguyện tam nghiệp thanh tịnh, tam giải thoát môn nhi thành tựu."],["p","Tam không đốn ngộ, tam vô lậu học dĩ tuyên minh. Vĩnh thoát tam đồ chi báo, thường sanh Tam Bảo chi gia. Tam không đốn hiệp ư sắc tâm, tam chướng toàn cai ư giải thoát. Tam kỳ quả mãn, tam giác công viên. Tam thừa đắc đạo chi thánh hiền; tam hữu đồng triêm ư lợi lạc. Sám văn tuy diễn, khẩn thiết vị thành, thỉnh chúng kiền cung, tái cầu sám hối."],["p","Nam mô Sám Hối Sư Bồ tát Ma ha tát. (3 lần)"],["p","Lương Hoàng Bảo Sám,"],["p","Tam quyển công đức lực, nguyện diệt đệ tử đẳng tội chướng, thân chứng Bồ Tát Phát Quang Địa."],["v",["Sám văn cử xứ, tội hoa phi,","Giải liễu oan, sám liễu tội,","Tiêu tai tăng phước huệ,","Thoát khổ sanh Đao Lợi.","Giải liễu oan, sám liễu tội,","Tiêu diêu trực nhập Long Hoa hội,","Long Hoa tam hội nguyện tương"]],["p","phùng, Di Lặc Phật tiền thân thọ ký."],["p","Nam mô Long Hoa Hội Bồ tát Ma ha tát. (3 lần)"],["v",["Lương Hoàng Bảo Sám,","Tam quyển dĩ toàn châu,","Hồi hướng tứ ân tịnh tam hữu,","Bái sám chúng đẳng tăng phước thọ;","Nguyện tương pháp thủy tẩy khiên"]],["v",["vưu, Duy nguyện vong giả vãng Tây du.","Ly Cấu Địa Bồ Tát Ma ha tát,","Duy nguyện ai nạp thọ.","Nam mô Đăng Vân Lộ Bồ Tát Ma Ha Tát. (3 lần)","Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh..."]],["v",["Hiệu Chính: HT. THÍCH TRÍ TỊNH","Dịch Giả: HT. THÍCH VIÊN GIÁC"]]],"p":"Quyển Thứ Ba"},{"t":"Đầu Quyển Tư","b":[["v",["Tào Khê Thủy.","Nhất phái hướng Đông Lưu.","Quan Âm bình nội trừ tai cựu.","Đề hồ quán đảnh địch trần cấu.","Dương chi sái xứ nhuận tiêu khô.","Yết hầu trung cam lộ tự hữu quỳnh"]],["v",["tương thấu.","Nam mô Phổ Hiền Vương Bồ Tát Ma Ha"]],["p","Tát. (3 lần)"],["h","Cung Văn"],["p","Tứ trí viên minh chi diệu thể, nghiêm nhược tinh trung chi kiểu nguyệt. Tứ vô ngại biện chi huyền âm, cao siêu kiếp ngoại chi không đàm. Vận tứ tâm ư tứ ác thú trung; ly tứ tướng ư tứ sanh giới nội. Tín Phật ân chi quảng bố."],["p","Ngưỡng Thánh đức chi di cao. Duy nguyện hồng ân giám nạp thành khẩn."],["p","Thượng lai phụng vì kim thời cầu sám đệ tử đẳng... khải kiến Từ Bi Đạo Tràng Sám Pháp, tư đương đệ tứ quyển nhập đàn duyên khởi. Tứ tất đàn nhân tam nghiệp thanh tịnh. Khắc niệm nhiếp niệm dĩ đầu thành, tâm chánh thân chánh nhi tác lễ. Bình trâm tam đảo chi xuân quang, lô nhiệt lục thù chi hương cái. Đăng nhiên huệ cự cúng hiến Thuần Đà, lễ bái truyền nhiễu, phúng vịnh tán dương, phát lộ phi thành, khắc cần sám hối."],["p","Thiết niệm cầu sám đệ tử đẳng... tự tùng vĩnh kiếp, trực chí kim sinh, mê tứ đại chi sắc thân, thọ tứ sanh chi luân chuyển, khởi tứ tướng chi điên đảo, phạm tứ chủng chi oai nghi. Tùng mê chí mê, do khổ nhập khổ, tùy cảnh phong chi nghịch thuận. Nịch ái thủy chi trầm luân."],["p","Vô minh duy trọng duy thâm, phiền não như dao như tất. Bằng đại pháp dĩ hồng tuyên, trượng chân thuyên nhi giải thích."],["p","Kim tắc thốn tâm khánh khoái, khắc cốt minh cơ. Tập đại đức chi cao lưu, vận nhất tâm nhi sám hối. Ngưỡng khấu hồng từ minh huân gia bị."],["v",["Tứ bát đoan nghiêm vi diệu tướng.","Tăng kỳ tam đại kiếp tu lai.","Diện như mãn nguyệt mục như liên.","Thiên thượng nhân gian hàm cung"]],["p","Kỉnh."],["p","Khởi vận Từ Bi Đạo Tràng Sám Pháp, nhất tâm quy mạng tam thế chư Phật:"],["v",["Nam mô Quá Khứ Tỳ Bà Thi Phật.","Nam mô Thi Khí Phật.","Nam mô Tỳ Xá Phù Phật.","Nam mô Câu Lưu Tôn Phật.","Nam mô Câu Na Hàm Mâu Ni Phật.","Nam mô Ca Diếp Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Đương Lai Hạ Sanh Di Lặc"]],["p","Tôn Phật."]],"p":"Quyển Thứ Tư"},{"t":"Chương Thứ Bảy Nói Rõ Quả Báo","b":[["p","(Tiếp Theo)"],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại phải chí thành đảnh lễ, nhất tâm lắng nghe."],["p","Lúc bấy giờ, Phật ở thành Vương Xá, trong vườn trúc Ca Lan Đà, ngài Mục Kiền Liên từ thiền định đứng dậy đi dạo trên bờ sông Hằng thấy các Ngạ quỷ chịu tội không đồng nhau."],["p","Khi ấy các Ngạ quỷ đồng sinh lòng cung kính đến hỏi ngài Mục Liên về nhân duyên đời trước. Một Ngạ quỷ hỏi rằng: “Tôi một đời lại đây, thường bị đói khát, muốn vào nhà xí, lấy phẩn mà ăn; trên nhà xí đã có con đại lực quỷ lấy gậy đánh tôi; tôi không đến gần nhà xí được. Vì cớ gì mà tôi mắc phải tội ấy?”"],["p","Ngài Mục Liên đáp rằng: “Đời trước lúc làm người, ngươi làm chủ chùa, có khách Tỳ kheo đến xin ăn. Ngươi keo kiết không đãi khách ăn. Chờ khách đi rồi ngươi mới cho các thầy thường ở trong chùa ăn."],["p","Vì ngươi vô đạo, tham tiếc của chúng; do nhân duyên ấy nên mắc phải tội như vậy. Đó là hoa báo, quả báo sẽ ở địa ngục”."],["p","- Lại có một Ngạ quỷ hỏi ngài Mục Liên rằng: “Tôi một đời lại đây, trên vai có cái bình đồng lớn, đựng đầy nước sôi."],["p","Tôi tự lấy gáo múc xối từ trên đầu xuống, đau khổ vô cùng, không thể chịu được."],["p","Tôi vì tội gì mà phải như thế?”"],["p","Ngài Mục Liên đáp rằng: “Lúc làm người, ngươi làm Duy na trong chùa, xem việc trong đại chúng. Có một bình sữa, ngươi giấu chỗ kín, đúng giờ không đem chia cho chúng, đợi khách đi rồi, mới đem chia cho các người trong chùa. Sữa là vật chiêu đề, thuộc của chúng Tăng trong mười phương, mọi người đều có phần; vì ngươi vô đạo, tham tiếc của chúng. Do nhân duyên ấy, nên mắc phải tội như vậy."],["p","Đó là hoa báo, quả báo sẽ ở địa ngục”."],["p","- Lại có một Ngạ quỷ hỏi ngài Mục Liên rằng: “Tôi một đời trở lại đây, thường nuốt những hoàn sắt nóng. Vì những tội gì mà phải như vậy?”"],["p","Ngài Mục Liên đáp rằng: “Lúc làm người, ngươi làm một vị Sa di nhỏ, lấy nước trong sạch quấy đường phèn cho chúng. Đường phèn cứng rắn, ngươi sinh tâm trộm cắp, đập nhỏ lấy chút ít. Đại chúng chưa uống, ngươi đã uống trộm trước một hớp. Do vì nhân duyên ấy nên mắc phải tội như vậy. Đó là hoa báo, quả báo sẽ ở địa ngục”."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nghe những việc ngài Mục Liên đã nghe đã thấy, rất đáng sợ hãi."],["p","Chúng con có thể làm những tội ấy."],["p","Vì vô minh ngăn che chúng con không tự nhớ biết. Giả sử như chúng con đã tạo vô lượng tội nghiệp như vậy, đời sau quyết phải thọ lãnh quả báo đau khổ ấy. Vậy nên bây giờ phải chí tâm tha thiết, đầu thành đảnh lễ hổ thẹn cầu xin sám hối."],["p","Nguyện trừ diệt sạch những tội lỗi ấy và nguyện xin sám hối thế cho hết thảy Ngạ quỷ khắp mười phương tận hư không giới."],["p","Lại nguyện xin sám hối thế cho các cha mẹ và các sư trưởng, nguyện xin sám hối thế cho các bậc đồng đàn tôn chứng, thượng trung hạ tòa."],["p","Nguyện xin sám hối thế cho tất cả thiện ác tri thức, rộng ra cho đến khắp cả mười phương, tận hư không giới, vô cùng vô tận hết thảy chúng sanh, trong tứ sinh lục đạo."],["p","Những tội đã làm, nhân nay sám hối mà được trừ diệt. Những tội chưa làm thề không dám làm."],["v",["Nguyện xin mười phương chư Phật chứng biết cho chúng con.","Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Câu Lưu Tôn Phật.","Nam mô Câu Na Hàm Mâu Ni Phật.","Nam mô Ca Diếp Phật.","Nam mô Sư Tử Phật.","Nam mô Minh Viêm Phật.","Nam mô Mâu Ni Phật.","Nam mô Diệu Hoa Phật.","Nam mô Hoa Thị Phật.","Nam mô Thiện Túc Phật.","Nam mô Đạo Sư Phật.","Nam mô Đại Tý Phật.","Nam mô Đại Lực Phật.","Nam mô Túc Vương Phật.","Nam mô Tu Dược Phật.","Nam mô Danh Tướng Phật.","Nam mô Đại Minh Phật.","Nam mô Viêm Kiên Phật.","Nam mô Chiếu Diệu Phật.","Nam mô Nhật Tạng Phật.","Nam mô Nguyệt Thị Phật.","Nam mô Chúng Viêm Phật.","Nam mô Thiện Minh Phật.","Nam mô Vô Ưu Phật.","Nam mô Sư Tử Du Hí Bồ Tát.","Nam mô Sư tử Phấn Tấn Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát.","Nam mô Phật Đà.","Nam mô Đạt Mạ.","Nam mô Tăng Già."]],["p","Lại quy y như vậy, mười phương tận hư không giới hết thảy Tam Bảo. Nguyện xin Tam Bảo rũ lòng đại từ bi cứu vớt hết thảy chúng sanh khắp mười phương hiện đương chịu khổ trong đường Ngạ quỷ."],["p","Lại nguyện xin cứu vớt hết thảy chúng sanh khắp mười phương hiện đương chịu khổ vô lượng trong đường địa ngục; trong đường súc sinh và trong nhân loại; làm cho các chúng sanh ấy liền được giải thoát, đoạn ba nghiệp chướng trừ năm sợ hãi chứng tám giải thoát, dùng bốn hoằng thệ độ thoát chúng sanh, đảnh lễ Thế Tôn, thưa thỉnh giáo lý vi diệu; không rời đương xứ, sạch hết hữu lậu, tùy tâm tự tại, dạo khắp cõi Phật, hạnh nguyện viên mãn, chóng thành Chánh giác."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng, lại chí thành lắng lòng mà nghe."],["p","Lúc bấy giờ, Phật ở thành Vương Xá, phía đông nam có một hồ nước, bao nhiêu tiểu dãi ô uế đều chảy vào hồ ấy, hôi thối không thể đến gần được. Có một con trùng lớn sinh ở trong hồ ấy. Thân dài mấy trượng; không có tay chân, quằn quại lăn lóc, hàng ngàn người đến xem."],["p","Ngài A Nan thấy vậy về bạch Phật. Phật và đại chúng cùng nhau đến hồ ấy xem. Đại chúng nghĩ rằng:"],["p","“Nay đây Đức Như Lai sẽ nói rõ đầu đuôi việc con trùng ấy cho mọi người nghe”."],["p","Phật bảo đại chúng: “Sau khi đức Phật Duy Vệ nhập Niết bàn rồi, có năm trăm thầy Tỳ kheo đi qua một ngôi chùa."],["p","Lúc ghé vào chùa, chủ chùa rất hoan hỷ vui mừng, mời đại chúng ở lại để cúng dường. Ông hết lòng thết đãi không tiếc món gì."],["p","Sau đó có năm trăm người đi buôn vào biển lấy ngọc, lúc về cũng ghé lại chùa. Các người ấy thấy năm trăm thầy Tỳ kheo tu hành tinh tấn liền hân hoan, phát tâm cúng dường, mới cùng nhau nghĩ rằng: “Phước điền khó gặp, chúng ta nên cúng dường lễ mọn”."],["p","Mỗi người cúng một viên ngọc, cộng được năm trăm ma ni châu, đem gởi chủ chùa. Sau đó chủ chùa sinh tâm không tốt, lập mưu muốn đoạt lấy một mình, không đem ra cúng dường chúng Tăng."],["p","Đại chúng mới hỏi: “Ngọc châu của khách buôn bố thí nên đem ra cúng dường đại chúng?”."],["p","Chủ chùa đáp rằng: “Ngọc châu ấy cúng cho ta, nếu các ngươi muốn đoạt, thì có phẩn uế cho các ngươi. Nếu các ngươi không đi ngay bây giờ, ta sẽ chặt tay chân các ngươi quăng vào hầm phẩn”."],["p","Đại chúng nghĩ thương người ấy quá ngu si, bèn làm thinh bỏ đi."],["p","Vì tội ác ấy nên nay chủ chùa kia phải làm thân trùng này, sau sẽ vào địa ngục chịu vô lượng đau khổ."],["p","- Lại nữa, khi ấy Phật ở thành Vương Xá, thấy một chúng sanh có cái lưỡi rất dài lớn. Có đinh sắt đóng vào lưỡi, lửa phát cháy hừng hực, chịu đau khổ suốt ngày đêm. Ngài Mục Liên bèn hỏi Phật: “Chúng sanh ấy vì tội gì mà chịu khổ như vậy?”"],["p","Phật đáp:"],["p","\"Người ấy xưa kia từng làm chủ chùa, hay mắng nhiếc, xua đuổi các thầy Tỳ kheo ở lâu trong chùa hay khách Tăng mới đến cũng vậy mà không cho ăn uống."],["p","Không bình đẳng cúng dường. Vì nhân duyên ấy nên nay mắc phải tội như vậy”."],["p","- Lại có một chúng sanh thân thể dài lớn, trên đầu có cái vạc nước đồng sôi, bốc lửa cháy hừng hực, nước đồng sôi chảy tràn ra tứ phía, chảy khắp thân thể, chúng sanh ấy nương hư không mà đi mãi không nghỉ."],["p","Ngài Mục Liên hỏi Phật: “Chúng sanh ấy vì tội gì mà phải chịu khổ như thế?”."],["p","Phật đáp:"],["p","“Người ấy đời xưa làm Tri sự ở chùa, Đàn việt cúng dầu thắp, Tri sự không chia cho khách Tăng. Đợi các thầy khách Tăng đi rồi sau đó mới chia cho các thầy thường ở trong chùa."],["p","Vì nhân duyên ấy nên nay người ấy mắc phải tội như vậy”."],["p","- Lại có một chúng sanh bị các hoàn sắt cháy đỏ hừng hực, từ trên đầu mà vào, từ dưới chân mà ra, nương hư không mà đi, người ấy đau khổ vô cùng, không thể chịu được."],["p","Ngài Mục Liên hỏi Phật: “Chúng sanh ấy vì tội gì mà phải chịu khổ như vậy?"],["p","Phật đáp rằng:"],["p","“Người ấy đời trước làm ông Sa di có trộm bảy trái me trong vườn chúng Tăng."],["p","Sau khi chết rồi, Sa di ấy đã chịu vô lượng khổ trong địa ngục. Nay nghiệp báo chưa hết, hãy còn dư ươn, nên phải chịu khổ như vậy”."],["p","- Lại có một con cá lớn, một thân trăm đầu, mỗi đầu một khác, bị sa vào lưới người."],["p","Thế Tôn thấy vậy bèn nhập định “Từ tâm Tam muội” gọi con cá ấy. Cá ấy tức thời ứng khẩu trả lời."],["v",["Thế Tôn hỏi cá:","- Mẹ ngươi ở đâu?","- Mẹ tôi làm con trùng rúc trong nhà xí!"]],["p","Phật bảo các Tỳ kheo: “Lúc Phật Ca Diếp ra đời, con cá to lớn này làm vị Tam Tạng Tỳ kheo, vì ác khẩu nên chịu quả báo nhiều đầu. Mẹ nó bấy giờ thọ hưởng lợi dưỡng của nó, nên đọa làm con trùng rúc trong cầu tiêu”."],["p","Phật dạy tiếp rằng: “Mắc phải báo ấy đều do chúng sanh ác khẩu, nói lời thô tháo cứng xăñ g, tuyên truyền bỉ thử, làm cho hai bên tranh đấu loạn lạc lẫn nhau."],["p","Chết rồi vào địa ngục, bị ngục tốt đốt đỏ cái bể sắt trong ngoài nóng đỏ như nước đồng sôi để nung cái lưỡi người có tội."],["p","Quỷ lại đốt đỏ móc sắt, móc có ba lưỡi sắt bén như mũi nhọn để đoạn cái lưỡi của tội nhân. Lại kéo dài cái lưỡi ra như trâu kéo cày."],["p","Lại đốt đỏ cái chày sắt dộng vào yết hầu, trải qua ngàn vạn kiếp. Tội hết mới ra khỏi địa ngục, làm loài chim muông”."],["p","Phật dạy: “Nếu có chúng sanh nào đàm luận việc vua chúa, chính trị, cha mẹ và sư trưởng, thì tội lại còn nặng hơn”."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nghe Phật dạy lời ấy, rất đáng sợ hãi. Bấy giờ đại chúng đã thấy rõ ràng: Thiện ác hai đường không sai, tội phước và quả báo chắc thật, quyết định không còn nghi ngờ gì nữa."],["p","Vậy nên hết lòng hổ thẹn, siêng năng tu hành, cầu xin sám hối. Đại chúng đã cùng nhau xem kinh, đã đồng thấy những việc như trên, nếu không cố gắng, lười biếng muốn thối lui thì việc tu hành không do đâu có kết quả."],["p","Ví như người nghèo thiếu, lòng thèm khát các vị cao lương mà thực tế không có một vị nào thì rốt cuộc cũng không có ích gì cho sự thèm khát khổ não kia."],["p","Cho nên biết rằng: Người nào muốn cầu có pháp môn nhiệm mầu thù thắng, muốn độ thoát hết thảy chúng sanh, người ấy không thể nói suông rằng: Tôi chỉ tu tâm mà được. Người ấy cần phải có tâm mà cũng cần phải thực hành bằng sự tướng nữa mới được. Cần phải có sự có lý."],["p","Sự lý đi đôi công việc mới có kết quả hoàn toàn, thành tựu viên mãn."],["p","Vậy nên đại chúng phải nỗ lực tinh tấn tu hành cầu xin sám hối. Cùng nhau chí tâm tha thiết, đầu thành đảnh lễ Tam Bảo."],["p","Nguyện xin thay thế hết thảy chúng sanh trong đường địa ngục, đường ngạ quỷ, đường súc sinh và đường nhân loại mà cầu xin sám hối."],["p","Lại nguyện vì cha mẹ, sư trưởng, thiện ác tri thức và cùng hết thảy bà con mà cầu xin sám hối. Những tội đã làm rồi nguyện xin trừ diệt. Những tội chưa làm thề không dám làm."],["v",["Nhất tâm đảnh lễ quy y Thế gian Đại Từ Bi Phụ:","Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Đề Sa Phật.","Nam mô Minh Diệu Phật.","Nam mô Trì Man Phật.","Nam mô Công Đức Minh Phật.","Nam mô Thị Nghĩa Phật.","Nam mô Đăng Diệu Phật.","Nam mô Hưng Thịnh Phật.","Nam mô Dược Sư Phật.","Nam mô Thiện Nhu Phật.","Nam mô Bạch Hào Phật.","Nam mô Kiên Cố Phật.","Nam mô Phước Oai Đức Phật.","Nam mô Bất Khả Hoại Phật.","Nam mô Đức Tướng Phật.","Nam mô La Hầu Phật.","Nam mô Chúng Chủ Phật.","Nam mô Phạm Thanh Phật.","Nam mô Kiên Tế Phật.","Nam mô Bất Cao Phật.","Nam mô Tác Minh Phật.","Nam mô Đại Sơn Phật.","Nam mô Kim Cang Phật.","Nam mô Tương Chúng Phật.","Nam mô Vô Úy Phật.","Nam mô Chân Bảo Phật.","Nam mô Sư Tử Phan Bồ Tát.","Nam mô Sư Tử Tác Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy, mười phương tận hư không giới hết thảy Tam Bảo. Nguyện xin Tam Bảo dùng đại từ bi lực, đại trí huệ lực, vô lượng tự tại thần lực, không thể tư nghị; độ thoát nhất thiết chúng sanh lực trong lục đạo, diệt trừ hết thảy đau khổ cho chúng sanh trong lục đạo, khiến các chúng sanh ấy đoạn trừ hết tội nghiệp trong ba đường ác; rốt ráo không tạo năm tội nghịch; không tạo mười ác nghiệp nữa. Từ nay trở đi các chúng sanh ấy không sinh vào chỗ khổ báo, được sinh về Tịnh độ; bỏ mạng sống khổ báo được mạng sống trí huệ; bỏ thân khổ báo được thân Kim cang; bỏ khổ ác thú được vui Niết bàn; nhớ khổ trong ác thú, phát tâm Bồ đề. Bốn vô lượng tâm, sáu ba la mật thường được hiện tiền. Bốn vô ngại biện, sáu sức thần thông được tự tại như ý, dõng mãnh tinh tấn, không thôi không nghỉ, và thắng tấn tu hành đến khi mãn hạnh Thập địa, trở lại độ thoát hết thảy chúng sanh."]],"p":"Quyển Thứ Tư"},{"t":"Chương Thứ Tám Ra Khỏi Địa Ngục","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nên biết rằng: Vạn pháp không đồng, công dụng bất nhất, như sáng và tối đối đãi nhau. Tuy nhiên chỉ có thiện và ác là gồm thâu tất cả."],["p","Làm thiện được quả báo tốt đẹp ở các cõi trời, cõi người. Làm ác thời mắc quả báo xấu xa, đau khổ kịch liệt trong ba đường ác."],["p","Đó là hai sự thật rõ ràng trên đời, không phải giả dối. Những người ngu si lầm lạc phần nhiều sinh tâm nghi ngờ; hoặc cho cõi trời là chuyện bịa đặt; địa ngục là lời nói dối, không có. Những người ấy không biết suy nhân nghiệm quả; không biết xét quả tìm nhân. Người không biết phân biệt nhân quả thì cố chấp lấy sự hiểu biết sai lầm của thế gian."],["p","Không những chấp không, chấp có mà còn làm thơ làm bài để biếm xích. Tâm họ trái với điều thiện lợi mà không hề tự biết sai lầm. Giả như có người chỉ bảo cho thì họ càng chấp chặt lấy thiên kiến; sai lầm còn kiên cố hơn nữa. Những người như thế là họ tự gieo đầu vào đường ác."],["p","Trong nháy mắt liền thẳng xuống địa ngục, từ thân hiếu tử không thể cứu được. Họ đi vào hầm lửa, vạc dầu trước hơn ai hết. Họ đi thiêu thân trong lửa nóng vạc dầu sôi mà không tự biết. Thân tâm tan nát, tinh thần thống khổ, khi ấy ăn năn không kịp."],["p","Ngày nay đại chúng trong đạo tràng thấy rõ thiện ác nương nhau như bóng theo hình, như vang theo tiếng."],["p","Tội phước hai đường tuy khác nhau nhưng cũng phải đợi kỳ trả quả báo nghiêm nhặt, mong sao mọi người đều sáng suốt tin tưởng không sanh tâm nghi ngờ."],["p","Sao gọi là địa ngục?"],["p","Kinh dạy rằng:"],["p","Trong tam thiên đại thiên thế giới, ở giữa khoảng hai núi Thiết Vi, chỗ tối tăm nhất gọi là Địa ngục, thành bằng sắt dài rộng một ngàn sáu trăm vạn dặm. Trong thành chia ra tám vạn bốn ngàn ngăn."],["p","Dưới lấy sắt làm đất, trên lấy sắt làm lưới."],["p","Lửa đốt thành ấy trong ngoài cháy đỏ chảy ra nước. Lửa trên cháy suốt xuống dưới, lửa dưới cháy suốt bốc lên trên."],["v",["Tên riêng của mỗi ngục là:","Ngục nhóm họp,","Ngục tối tăm,","Ngục xe dao,","Ngục rừng kiếm,","Ngục máy sắt,","Ngục rừng gai,","Ngục võng sắt,","Ngục hang sắt,","Ngục hoàn sắt,","Ngục đá nhọn,","Ngục hầm than,","Ngục rừng cháy,","Ngục hổ lang,","Ngục kêu la,","Ngục nước sôi,","Ngục than nóng,","Ngục núi dao,","Ngục rừng kiếm,","Ngục đá mài lửa,","Ngục thành lửa,","Ngục cột trụ đồng,","Ngục giường sắt,","Ngục xe lửa,","Ngục bánh xe lửa,","Ngục uống nước đồng sôi,","Ngục khạc ra lửa,","Ngục hết sức nóng,","Ngục hết sức lạnh,","Ngục rút lưỡi,","Ngục đóng đinh vào thân,","Ngục trâu cày,","Ngục chém chặt,","Ngục đao binh,","Ngục mổ xẻ,","Ngục sông tro,","Ngục tiểu dãi trào lên,","Ngục giá lạnh,","Ngục bùn lầy,","Ngục ngu si,","Ngục khóc lóc,","Ngục đui điếc,","Ngục câm ngọng,","Ngục lưỡi câu sắt,","Ngục mỏ sắt nhọn.","Lại có những đại tiểu nê lê A tỳ địa ngục.","Phật bảo đức A Nan:","Sao gọi là A tỳ địa ngục?","A: nghĩa là vô.","Tỳ: nghĩa là già.","A\u0001 nghĩa là vô.","Tỳ: nghĩa là cứu."]],["p","Nói chung lại: A Tỳ nghĩa là vô già, vô cứu: không ngăn dứt, không cứu vớt được."],["v",["Lại nữa:","A: là không gián đoạn.","Tỳ: là không lay động.","A: là hết sức nóng nhiệt.","Tỳ: là hết sức khổ não.","A: là không an nhàn.","Tỳ: là không an trú."]],["p","Tóm lại: A tỳ là hết sức hành hạ, không tạm nghỉ, không gián đoạn, không lay chuyển; hết sức khổ não, như nung như nấu, không an nhàn, không chấm dứt, cứ hành phạt mãi mãi nên gọi là A tỳ."],["v",["Lại nữa:","A: là đại diệm; là lửa dữ.","Tỳ: là mãnh nhiệt; là nóng dữ.","Lửa dữ nhập tâm, gọi là A tỳ địa ngục."]],["p","Phật dạy ngài A Nan: Địa ngục A tỳ dài rộng bằng nhau ba mươi hai vạn dặm."],["p","Bảy lớp thành sắt, bảy lớp lưới sắt bao bọc ngục A tỳ. Dưới có mười tám ngăn, xung quanh có bảy lớp thành, đều có đặt rừng dao."],["p","Trong bảy lớp thành lại có rừng gươm. Dưới mười tám ngăn, ngăn có tám vạn bốn ngàn lớp. Bốn góc đều có bốn đại đồng cẩu, thân dài lớn đến một vạn sáu ngàn dặm (16.000), mắt như điện chớp, răng như cây gươm, nanh như núi dao, lưỡi như mũi sắt nhọn, toàn thân chân lông phun lửa dữ, hơi bay như khói, hôi thối khó chịu, thế gian không có vật gì thối bằng."],["p","Lại có mười tám ngục tốt đầu như đầu La sát miệng như miệng Dạ xoa. Chó có sáu mươi bốn con mắt, mắt tung ra xa những hoàn sắt nóng, như xe chạy xa mười dặm. Răng phía trên cao một trăm sáu mươi dặm. Trên đầu răng tuôn ra lửa dữ, đốt cháy xe sắt phía trước, làm cho bánh xe kia mỗi lỗ lưới tròn hóa làm một ức con dao lửa, kiếm kích sắc bén; những lưỡi nhọn đều từ trong lửa dữ ấy lưu xuất."],["p","Lửa ra như suối chảy đốt cháy ngục thành A tỳ. Thành cháy đỏ như nước đồng sôi."],["p","Bọn ngục tốt kia đầu có tám đầu trâu, mỗi mỗi đầu đều có mười tám cái sừng. Trên đầu mỗi sừng tuôn ra một đống lửa lớn. Đống lửa lớn lại hóa ra bánh xe dao lớn. Như bao nhiêu bánh xe, mỗi mỗi bánh xe thứ lớp theo nhau chạy trong lửa dữ ghê gớm, đầy cả A tỳ địa ngục."],["p","Ở dưới đất thì có chó đại đồng cẩu há miệng le lưỡi. Lưỡi như đòn xóc nhọn, le ra thì hóa thành vô lượng lưỡi, đầy cả A tỳ địa ngục."],["p","Ở trong bảy lớp thành có bảy lớp cờ."],["p","Ở đầu mỗi cờ, lửa tuôn ra như suối trào vọt, nước sắt chảy đầy cả A tỳ địa ngục."],["p","Bốn cửa thành ngục A tỳ, ở trên mỗi ngưỡng cửa có mười tám chảo nước đồng sôi trào ra rồi chảy tràn đầy cả thành A tỳ."],["p","Trong mỗi ngăn, Địa ngục lại có tám vạn bốn ngàn rắn mãng xà sắt, phun độc, phun lửa, thân hình lớn đầy thành, kêu la như sấm dậy, mưa xuống những hoàn sắt nóng lớn đầy cả thành A tỳ."],["p","Nỗi khổ trong thành kể đến tám vạn ức thiên. Bao nhiêu thống khổ trong những thống khổ đều tích tụ ở trong thành này."],["p","Lại có năm trăm ức con trùng ở trong thành, mỗi con trùng có tám vạn bốn ngàn mỏ nhọn. Đầu mỗi mỏ nhọn có lửa tuôn như mưa xối, đầy cả thành A tỳ."],["p","Mỗi khi trùng ấy rơi xuống thì lửa dữ trong thành A tỳ bốc ngọn lên dữ dội, hừng hực sáng choang. Lửa mạnh ấy chiếu đến ba trăm ba mươi sáu vạn dặm."],["p","Từ A tỳ ngục xông lên biển cả, dưới núi ốc tiêu, nước biển cả giọt xuống, mỗi giọt lớn bằng trục bánh xe to, thành ra những mũi nhọn sắt lớn, đầy cả thành A tỳ."],["p","Phật bảo ngài A Nan: “Như chúng sanh nào giết cha hại mẹ, nhục nhã sáu dòng bà con, người ấy khi mạng chung chó sắt hả miệng, hóa làm mười tám chiếc xe, giống như xe vàng, có bảo cái che trên. Hết thảy mũi lửa nhọn kia hóa làm ngọc nữ. Người có tội kia xa trông thấy, sinh tâm vui mừng. Nghĩ rằng: “Ta muốn đến đó chơi, ta muốn đến đó chơi”."],["p","Khi đến rồi, thì bị gió phong đao xẻ thân, lạnh quá chừng. Tội nhân lại nghĩ: “Há được lửa tốt, ngồi trên xe đốt lên mà hơ”."],["p","Nghĩ như thế rồi thì liền chết. Trong giây phút lại thấy mình ngồi trên xe vàng ngắm xem ngọc nữ. Nhưng bị ngọc nữ cầm búa sắt chém thân. Dưới thân lửa bốc hừng hực, mau như chớp nhoáng, trong nháy mắt lại rơi vào A tỳ địa ngục."],["p","Từ ngăn trên, chớp mắt đọa xuống ngăn dưới. Thân lớn đầy ngăn. Chó đồng cẩu lớn tiếng sủa lên và nhai xương nuốt tủy. Ngục tốt La sát cầm xoa sắt lớn xoa đầu bắt đứng dậy; lửa cháy khắp thân, cháy luôn thành A tỳ. Lưới sắt tuôn mưa dao, dao theo lỗ chân lông vào trong thân thể, hóa làm vua Diêm Vương. Vua lớn tiếng bảo rằng: “Kẻ ngu si, giống ngục tốt kia, ngươi ở dương thế, bất hiếu với cha mẹ, tà mạng không đạo đức nên phải đọa vào chỗ này, gọi là A tỳ Địa ngục. Ngươi là người không biết ơn, không hổ thẹn."],["p","Ngươi chịu khổ não như thế có sướng không?”. Nói rồi, biến mất."],["p","Bấy giờ ngục tốt lại đuổi tội nhân từ ngăn dưới lên ngăn trên. Phải trải qua tám vạn bốn ngàn ngăn giữa mới qua khỏi lớp lưới sắt cuối cùng, một ngày một đêm mới khắp A tỳ địa ngục. Một ngày một đêm ở địa ngục bằng sáu chục tiểu kiếp ở dương gian. Tội nhân sống như vậy trong địa ngục một đại kiếp."],["p","Người phạm tội ngũ nghịch không biết hổ thẹn nên gây tội ấy. Vì tội ngũ nghịch nên lúc lâm chung có mười tám thứ phong đao như xe lửa sắt cắt xẻ thân thể. Tội nhân vì nóng bức nên nói thế này: “Nếu ta có các thứ hoa sắc đẹp ấy, cây đại thọ mát mẻ kia, ở đó dạo chơi há không vui sao!”."],["p","Nghĩ như thế rồi thì có tám vạn bốn ngàn rừng ác kiếm hóa làm cây báu, hoa quả tốt tươi, sắp bày ra trước mắt, lửa nóng hừng hực, hóa làm hoa sen nơi gốc cây kia. Tội nhân thấy vậy liền nghĩ thầm: “Ta đã mãn nguyện”."],["p","Trong nháy mắt, tội nhân liền ngồi trên hoa sen. Trong khoảnh khắc, các trùng mỏ nhọn, từ trong hoa lửa sinh ra rúc ráy cốt tủy, thấu suốt tâm can. Tội nhân phải vịn cây đứng dậy. Các nhành cây hóa thành lưỡi kiếm, róc thịt chẻ xương. Vô lượng rừng đao từ không trung rơi xuống. Những lò hồng, xe lửa, mười tám điều đau khổ nhất thời đưa đến."],["p","Những cảnh tượng này hiện ra thì tội nhân bị hãm xuống địa ngục từng dưới; rồi từ từng dưới lên từng trên. Thân hình lột hết như hoa nở. Trải khắp ngăn dưới, rồi lên ngăn trên, bị lửa mạnh thiêu đốt dữ dội."],["p","Đến ngăn trên rồi, thân hình tràn khắp ngăn ấy, bị khổ não nung nấu vô cùng. Tội nhân phải trợn mắt le lưỡi. Vì phạm tội ngũ nghịch, nên bị vạn ức đồng sôi, trăm ngàn đao luân, từ trên không rơi xuống, vào trên đầu, ra dưới chân; đau khổ còn gấp bội hơn trước nữa một trăm một ngàn vạn phần. Người phạm đủ năm nghịch tội phải chịu tội đủ năm kiếp."],["p","Lại nữa nếu người nào phá cấm giới của Phật, luống ăn dùng của tín thí, phỉ báng Tam Bảo, tà kiến, không biết nhân quả, không học trí huệ Bát Nhã, khinh chê mười phương Phật, trộm cắp của Pháp, làm việc ô uế bất tịnh hạnh, không hổ thẹn, hủy nhục bà con, tạo các điều ác, người ấy khi sắp lâm chung, tội báo bị phong đao xẻ thân, nằm ngửa bất tỉnh, như bị đánh đập."],["p","Tư tưởng hoang mang, si mê lầm lẫn."],["p","Thấy nhà cửa và con cái nam nữ, và lớn nhỏ, cùng tất cả sự vật của mình đều bất tịnh. Tiểu dãi hôi thối, tràn đầy thân thể."],["p","Bấy giờ người ấy nghĩ rằng:"],["p","“Sao đây không có thành quách và núi rừng tốt đẹp, để ta dạo chơi mà lại ở giữa đám bất tịnh ô uế này ư!”."],["p","Nghĩ như thế rồi, liền bị ngục tốt La sát lấy cái xoa sắt lớn đánh ngục A tỳ, các rừng đao hóa làm cây báu, và ao hồ mát mẻ, lửa dữ hóa làm hoa sen lá vàng; những con trùng sắt mỏ nhọn hóa làm chim phù nhạn. Những tiếng thống khổ trong địa ngục như âm thanh ca vịnh."],["p","Tội nhân trông thấy tốt đẹp như vậy liền nghĩ rằng: “Ta mau đến đó dạo chơi”."],["p","Nghĩ xong liền thấy mình ngồi trên hoa sen lửa. Các trùng sắt mỏ nhọn từ các lỗ chân lông trong thân rút ra, cắn rứt thân thể. Trăm ngàn bánh xe sắt từ trên đảnh vào thân, hằng hà sa số xoa sắt, khiêu múc tròng mắt. Chó đồng cẩu trong địa ngục hóa làm trăm ức chó sắt dành nhau cấu xé thân hình tội nhân, lấy trái tim mà ăn. Trong nháy mắt, thân thể đã thành cánh hoa sắt, tràn khắp mười tám ngăn ngục, mỗi mỗi hoa có tám vạn bốn ngàn lá, mỗi mỗi lá, đầu mình tay chân chi tiết đều ở trong một ngăn; địa ngục không lớn, thân này không nhỏ, cho nên biến khắp địa ngục."],["p","Những tội nhân này đọa vào địa ngục ấy tám vạn bốn ngàn đại kiếp. Ngục này tiêu diệt rồi lại vào trong mười tám ngăn ngục khác, chịu khổ như trên. A tỳ ngục này về phương Nam cũng có mười tám ngăn; phương Tây cũng có mười tám ngăn, phương Bắc cũng có mười tám ngăn."],["p","Hủy báng các kinh Phương đẳng Đại thừa tạo đủ năm tội nghịch, phá hoại Hiền Thánh, đoạn các căn lành. Những người như vậy chịu đủ tội lỗi. Thân lớn khắp A tỳ địa ngục; tứ chi trải khắp cả mười tám ngăn. A tỳ địa ngục này chỉ thiêu đốt những chúng sinh tạo giống địa ngục như trên. Khi kiếp địa ngục sắp hết thì thấy cửa địa ngục phương Đông liền mở. Tội nhân nhìn thấy ngoài cửa ấy có dòng nước trong chảy mát mẻ; có rừng cây hoa quả tốt tươi hiện ra, những tội nhân ở ngăn dưới nhìn thấy thì mắt tạm bớt đổ lửa. Từ ngăn dưới vươn mình lên quằn quại bò đi, tuột cả thân hình mà chạy lên ngăn trên, tay vịn bánh xe đao."],["p","Bấy giờ trên không trung mưa xuống những hoàn sắt nóng. Tội nhân chạy đến cửa phương Đông. Vừa đến cổng thì ngục tốt La sát tay cầm xoa sắt đâm ngược vào tròng mắt của tội nhân."],["p","Chó đồng cẩu nhai ngầu trái tim; tội nhân phải chết ngất. Chết rồi sống lại, thấy cửa phương Nam mở như cửa phương Đông trước kia không khác."],["p","Cửa phương Tây, phương Bắc cũng đều như vậy. Trải qua thời gian nửa kiếp, tội nhân phải chết trong A tỳ địa ngục."],["p","Chết rồi sống lại sinh vào địa ngục giá lạnh, rồi chết trong địa ngục hàn băng này."],["p","Chết rồi lại sống, sống rồi lại sinh vào địa ngục hắc ám, một trăm, một ngàn vạn năm, mắt không trông thấy, thân làm con đại trùng, quằn quại bò đi; các căn ám độn, không hiểu biết gì phải quấy; lại bị một trăm một ngàn hổ lang lôi kéo dành ăn. Chết rồi lại sinh vào loài súc sanh, năm ngàn vạn năm làm thân chim muông. Khổ sở như thế cho đến khi hết tội, được sinh làm người. Nhưng lại phải đui, điếc, ngọng, lịu, phong hủi, ung thư, bần cùng hạ tiện. Bao nhiêu suy đồi khổ sở mình phải tự rước lấy. Làm thân hèn hạ như vậy năm trăm lần sống thác. Lại sinh vào loài quỷ đói. Ở trong Ngạ quỷ gặp được thiện tri thức các vị đại Bồ Tát quở trách nói rằng:"],["p","“Ngươi ở trong vô lượng đời về trước đã tạo ra vô lượng tội, phỉ báng Tam Bảo, không tin nhân quả nên đọa trong A tỳ địa ngục, chịu nhiều khổ não không thể kể xiết. Nay ngươi nên phát tâm từ bi”."],["p","Bấy giờ các Ngạ quỷ nghe lời ấy rồi liền xưng Nam mô Phật."],["p","Nhờ sức hồng ân của chư Phật, liền được mạng chung, sinh lên cõi trời tứ thiên. Sinh lên đó rồi, ăn năn tự trách, phát tâm Bồ đề."],["p","Tâm quang của chư Phật không bỏ những người phát tâm này, thâu nhiếp các người phát tâm như vậy và thương mến như La Hầu La. Dạy bảo tránh xa địa ngục, không cho thân sa đọa như quý tròng con mắt."],["p","Phật bảo Đại vương: “Muốn biết hào quang chư Phật thường chiếu nơi nào thì hãy xem hào quang ấy thường chiếu những nơi chúng sinh đau khổ như vậy không gián đoạn, không người cứu vớt."],["p","Tâm Phật thường biết nơi đâu? Thường biết những nơi chúng sinh chịu hành phạt cực hình, cực ác như vậy. Vậy đem tâm Phật mà trau giồi tâm mình, trải qua nhiều số kiếp, khiến các người ác kia phát tâm Bồ đề”."],["p","Hôm nay đại chúng đồng nghiệp trong đạo tràng nghe Phật Thế Tôn nói các thống khổ như trên thì gia tâm giữ ý, chớ sinh lòng buông lung. Nếu đại chúng không siêng năng lập phương tiện tu hành Bồ Tát đạo thì ở trong mỗi địa ngục đều có tội phần."],["p","Ngày nay đại chúng nên vì hết thảy chúng sinh hiện đang chịu thống khổ trong A tỳ địa ngục, vì hết thảy chúng sinh sẽ chịu thống khổ trong A tỳ địa ngục, và rộng ra cho đến hết thảy chúng sanh hiện chịu, và sẽ chịu vô cùng vô tận thống khổ trong hết thảy địa ngục ở mười phương mà đầu thành đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Quá Khứ Thất Phật.","Nam mô Thập Phương Thập Phật.","Nam mô Tam Thập Ngũ Phật.","Nam mô Ngũ Thập Tam Phật.","Nam mô Bách Thất Thập Phật.","Nam mô Trang Nghiêm Kiếp Thiên"]],["v",["Phật.","Nam mô Hiền Kiếp Thiên Phật.","Nam mô Tinh Tú Kiếp Thiên Phật.","Nam mô Thập Phương Bồ Tát Ma Ha"]],["v",["Tát.","Nam mô Thập Nhị Bồ Tát.","Nam mô Địa Tạng Vương Bồ Tát.","Nam mô Vô biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại xin quy y mười phương tận hư không giới vô lượng hình tượng:"],["v",["Tượng vàng và tượng chiên đàn của vua Ưu Điền.","Tượng đồng của vua A Dục.","Tượng đá của Ngô Trung.","Tượng ngọc của nước Sư Tử."]],["p","Tượng vàng, tượng bạc, tượng lưu ly, tượng san hô, tượng hổ phách, tượng xa cừ, tượng mã não, tượng trân châu, tượng ma ni, tượng vàng tử ma thượng sắc diêm phù đàn ở trong các quốc độ. (1 lạy)"],["v",["Lại quy y hết thảy các tháp thờ tóc của mười phương Phật.","Quy y hết thảy các tháp thờ hàm răng.","Quy y hết thảy các tháp thờ răng.","Quy y hết thảy các tháp thờ móng tay.","Quy y hết thảy các tháp thờ xương trên đảnh.","Quy y hết thảy các tháp thờ xá lợi trong thân.","Quy y hết thảy các tháp thờ cà sa.","Quy y hết thảy các tháp thờ muỗng, bình bát.","Quy y hết thảy các tháp thờ bình tắm rửa.","Quy y hết thảy các tháp thờ tích trượng.","Quy y hết thảy các nơi làm Phật sự như vậy. (1 lạy)","Lại quy y nơi tháp Phật giáng sinh.","Quy y tháp Phật đắc đạo.","Quy y tháp Phật chuyển pháp luân.","Quy y tháp Phật nhập Niết bàn."]],["p","Quy y tháp Phật Đa Bửu và tám vạn bốn ngàn tháp của vua A Dục tạo ra. Quy y tháp trên trời, tháp ở nhân gian và tất cả bảo tháp ở trong cung Long Vương. (1"],["p","lạy)"],["p","Lại quy y như vậy mười phương tận hư không giới, hết thảy chư Phật."],["p","Quy y mười phương tận hư không giới hết thảy Tôn Pháp."],["p","Quy y mười phương tận hư không giới hết thảy Hiền Thánh Tăng. (1 lạy)"],["p","Nguyện xin Tam Bảo đồng đem từ bi lực, an ủi chúng sinh lực, vô lượng đại tự tại lực, vô lượng đại thần thông lực, thâu nhiếp thọ lãnh chúng con, ngày nay sám hối thế cho hết thảy chúng sinh đang chịu khổ trong A tỳ đại địa ngục, sám hối thế rộng ra cho đến hết thảy chúng sinh trong tất cả địa ngục ở mười phương, nhiều không thể kể xiết. Sám hối thế cho cha mẹ, sư trưởng và tất cả bà con quyến thuộc. Nguyện xin Tam Bảo dùng nước đại bi tẩy trừ tội lỗi cho hết thảy chúng sinh hiện đang chịu khổ trong A tỳ địa ngục và trong những địa ngục khác, khiến chúng sinh được thanh tịnh."],["p","Nguyện xin Tam Bảo tẩy trừ tội lỗi cho chúng sinh, hiện đồng sám hối trong đạo tràng hôm nay; tẩy trừ tội lỗi cho tất cả cha mẹ, sư trưởng, cho hết thảy bà con quyến thuộc của chúng con, khiến tội lỗi được thanh tịnh."],["p","Lại xin tẩy trừ tội lỗi cho tất cả chúng sinh trong sáu đường, khiến chúng sinh thẳng đến đạo tràng hoàn toàn thanh tịnh. Từ nay trở đi cho đến ngày thành Phật, chúng sinh đều đoạn trừ được hết khổ não trong A tỳ địa ngục."],["p","Rộng ra nữa là đoạn trừ hết thảy thống khổ nhiều không thể nói, không thể nói trong các địa ngục, ở mười phương tận hư không giới. Chúng sinh ấy rốt ráo không còn đọa trở lại trong ba đường ác, rốt ráo không còn đọa trở lại trong các địa ngục."],["p","Rốt ráo không còn tạo trở lại mười ác nghiệp; không còn tạo trở lại năm tội nghịch để chịu khổ não. Tất cả các tội, nguyện đều tiêu diệt, bỏ sống địa ngục, được sống Tịnh độ, bỏ mạng địa ngục, được mạng trí huệ, bỏ thân địa ngục, được thân Kim cang, bỏ khổ địa ngục, được vui Niết bàn; nhớ khổ địa ngục, phát tâm Bồ đề, tứ đẳng lục độ thường được hiện tiền; tứ biện lục thông đều được tự tại như ý; đầy đủ trí huệ tu đạo Bồ Tát, dõng mãnh tinh tấn, không thôi không nghỉ, tu hành mãi lên cho đến mãn hạnh Thập địa vào tâm Kim cang, thành đẳng Chánh giác để trở lại đời này, độ thoát hết thảy chúng sinh trong mười phương."],["p","Hôm nay đại chúng đồng nghiệp trong đạo tràng còn có các địa ngục khác, chịu khổ rất phức tạp, không thể ghi chép. Danh hiệu như vậy, khổ sở vô cùng, đại chúng giở xem trong kinh sẽ thấy rõ việc ấy."],["p","Trong kinh Phật dạy rằng: “Một niệm ác của vua Diêm Vương sinh ra đủ các việc trong địa ngục. Tự thân Diêm Vương chịu khổ cùng không thể kể xiết”."],["p","Diêm La Đại Vương xưa kia là vị Tỳ Sa quốc vương, nhân vì cùng với Duy Đà thủy chúa chiến đấu thất bại, bèn lập thệ nguyện: “Nguyện ta đời sau làm chủ ngục trị tội nhân vậy”."],["p","Mười tám vị đại thần và trăm vạn tùy tùng đồng phát nguyện như vậy."],["p","Tỳ Sa vương ấy nay là Diêm La vương, mười tám vị đại thần kia, nay là mười tám ngục vương vậy."],["p","Trăm vạn chúng tùy tùng nay là ngưu đầu ngục tốt vậy."],["p","Bọn quan thuộc này đều lệ thuộc Bắc phương Tỳ Sa Môn thiên vương."],["p","Kinh Trường A Hàm chép:"],["p","“Chỗ ở của Diêm La Đại vương, tại Diêm phù đề trong núi Kim cang, về phương Nam, vương cung dài rộng sáu ngàn do tuần”. Kinh Đại Địa Ngục dạy rằng: “Thành quách cung vua Diêm vương, ở trong địa ngục rộng dài ba vạn dặm; dùng sắt và đồng mà xây dựng”."],["p","Ngày đêm ba thời có chảo đồng lớn đựng đầy nước đồng sôi, tự nhiên để phía trước vua. Có ngục tốt to lớn nằm trên giường sắt nóng của vua, lấy móc sắt đánh miệng vua, rót nước đồng sôi vào miệng vua. Từ yết hầu trở xuống đều cháy tiêu tan. Các Đại thần kia cũng phải chịu khổ như vậy."],["v",["Mười tám ngục vương ấy tên là:","1. Ca Diên giữ ngục Nê lê.","2. Khuất Tôn giữ ngục Đạo sơn.","3. Phí Thọ giữ ngục Phí sa.","4. Phí Khúc giữ ngục Phất sí.","5. Ca Thế giữ ngục Hắc nhĩ.","6. Hạp Sai giữ ngục Hỏa xa.","7. Than Vị giữ ngục Hoạch than.","8. Thích Ca Nhiên giữ ngục Thiết sàng.","9. Ác Sinh giữ ngục Hạp sơn.","10. Thân Ngâm giữ ngục Hàn băng.","11. Tỳ Ca giữ ngục Bác bì.","12. Diêu Đầu giữ ngục Súc sinh.","13. Đề Bạt giữ ngục Đao binh.","14. Di Đại giữ ngục Thiết ma.","15. Duyệt Đầu giữ ngục Khôi hà.","16. Xuyên Cốt giữ ngục Thiết sách.","17. Danh Thân giữ ngục Thơ trùng.","18. Quán Thân giữ ngục Dương đồng."]],["p","Những ngục như vậy đều có vô lượng địa ngục khác làm quyến thuộc; mỗi ngục đều có chủ ngục. Ngưu đầu ngục tốt tánh tình bạo ngược không có một mảy từ tâm."],["p","Thấy chúng sanh chịu ác báo như vậy chỉ sợ chúng sinh không khổ mà thôi. Nếu hỏi ngục tốt:"],["p","“Chúng sinh chịu khổ như vậy rất đáng thương xót, sao các ngươi thường cứ ôm lòng độc ác khốc liệt, không chút thương tâm?”"],["p","Ngục tốt liền đáp:"],["p","“Những người chịu khổ ấy tội ác như thế này: “Bất hiếu với cha mẹ, bài báng Phật Pháp Tăng, chê bai Thánh Hiền, nhục mạ lục thân, khinh mạn sư trưởng, hủy hoại tất cả, nói lời độc ác, nói lời hai lưỡi, nịnh hót, tật đố, chia rẽ tình cốt nhục của người, giận hờn nóng nảy, sát hại tham dục, dối gạt khinh khi, tà mạng, tà cầu, lại do vì tà kiến, giải đãi buông lung, gây kết nhiều thù oán”."],["p","Những người như vậy, đến đây chịu khổ rồi, mỗi khi được thoát ra chúng tôi thường khuyên bảo rằng: “Ở đây cực khổ lắm, không thể chịu được. Các người nay được ra rồi chớ nên tạo tội mà phải trở vào đây nữa”."],["p","Nhưng các tội nhân ấy không chịu chừa bỏ ăn năn, ngày nay ra rồi thoạt vậy lại vào."],["p","Lần lựa luân hồi, không biết thống khổ, làm cho chúng tôi phải mỏi mệt vì các chúng sinh ấy. Kiếp này kiếp khác, cứ đối đầu nhau mãi. Vì duyên cớ ấy nên chúng tôi đối với tội nhân không có chút thương tâm, mà còn cố ý làm cho khổ sở thêm nữa."],["p","Chúng tôi mong sao họ biết khổ, biết hổ, biết thẹn, không trở lại đây nữa."],["p","Nhưng chúng tôi xem các chúng sinh ấy thật là chỉ khổ mà không chịu tránh, không chí quyết làm lành để vào Niết bàn."],["p","Họ đã là vật vô tri, không biết tránh khổ tìm vui, sở dĩ họ phải chịu đau khổ hơn ở nhân gian, thì làm sao chúng tôi có thể dung thứ mà sinh tâm thương được."],["p","Hôm nay đại chúng đồng nghiệp trong đạo tràng hãy đem việc lao ngục ở thế gian mà so sánh thì có thể biết ngay, tin chắc rằng việc này không phải là luống dối."],["p","Giả sử có người ba phen đến cửa ngục tuy bà con thân tộc nhưng thấy người ấy cứ vào ra cửa ngục mãi cũng đã chán ngán, không có lòng buồn thương."],["p","Huống gì ngưu đầu ngục tốt thấy các chúng sinh đã ra lại vào để chịu thống khổ mãi mãi."],["p","Vậy đã thoát khỏi địa ngục rồi thì nên tu tâm dưỡng tánh, cải cách tập quán. Nếu không chừa bỏ thì nhiều kiếp chìm trong biển khổ. Đã vào trong ấy rồi, cứ thứ lớp mà qua, hết khổ này đến khổ khác, không bao giờ dừng nghỉ."],["p","Vì vậy nên oán thù ba đời, nhân quả theo nhau, hai vừng thiện ác chưa từng tạm nghỉ. Việc báo ứng trình bày rõ ràng rất dễ trông thấy. Làm ác gặp khổ, lấy ác trả ác, ở trong địa ngục cùng năm mãn kiếp, chịu thống khổ đủ điều. Hết tội địa ngục lại làm súc sinh. Hết tội súc sinh lại làm quỷ đói; trải qua vô lượng sanh tử, vô lượng thống khổ."],["p","Như thế đại chúng há có thể không lo tu hành Bồ Tát đạo cho kịp thời sao!"],["p","Chúng con ngày nay, nhất tâm đầu thành đảnh lễ Tam Bảo, nguyện vì hết thảy chúng sinh trong đường địa ngục, ngục vương, đại thần, ngưu đầu, ngục tốt và quyến thuộc của chúng khắp mười phương, nguyện vì hết thảy chúng sinh trong đường ngạ quỷ, ngạ quỷ vương, ngạ quỷ thần v.v... và quyến thuộc của ngạ quỷ ở khắp mười phương; nguyện vì hết thảy chúng sinh trong đường súc sinh, súc sinh thần v.v... và quyến thuộc của súc sinh khắp mười phương; rộng ra nguyện vì hết thảy chúng sinh vô cùng vô tận trong mười phương mà cầu xin sám hối, cải vãng tu lai, không làm ác nữa. Những tội đã làm nguyện xin diệt trừ, những tội chưa làm thề không dám làm."],["p","Nguyện xin hết thảy chư Phật trong mười phương dùng bất khả tư nghị tự tại thần lực gia tâm cứu hộ thương xót nhiếp thọ, khiến tất cả chúng sinh tức thời giải thoát."],["v",["Nguyện xin quy y thế gian Đại Từ Bi phụ:","Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Hoa Nhật Phật.","Nam mô Quân Lực Phật.","Nam mô Hoa Quang Phật.","Nam mô Nhơn Ái Phật.","Nam mô Đại Oai Đức Phật.","Nam mô Phạm Vương Phật.","Nam mô Vô Lượng Minh Phật.","Nam mô Long Đức Phật.","Nam mô Kiên Bộ Phật.","Nam mô Bất Hư Kiến Phật.","Nam mô Tinh Tấn Đức Phật.","Nam mô Thiện Thủ Phật.","Nam mô Hoan Hỷ Phật.","Nam mô Bất Thối Phật.","Nam mô Sư Tử Tướng Phật.","Nam mô Thắng Tri Phật.","Nam mô Pháp Thị Phật.","Nam mô Hỷ Vương Phật.","Nam mô Sa Ngự Phật.","Nam mô Ái Tác Phật.","Nam mô Đức Tý Phật.","Nam mô Hương Tượng Phật.","Nam mô Quán Thị Phật.","Nam mô Vân Âm Phật.","Nam mô Thiện Tư Phật.","Nam mô Sư Tử Phan Bồ Tát.","Nam mô Sư Tử Tác Bồ Tát.","Nam mô Địa Tạng Vương Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo. Nguyện xin Tam Bảo rũ lòng từ bi, tự tại thần lực cứu vớt chúng sinh trong đường địa ngục, ngục vương, đại thần và quyến thuộc của các vị ấy cùng mười tám địa ngục."],["p","Mười tám ngăn địa ngục này đều có nhiều địa ngục khác làm quyến thuộc."],["p","Nguyện xin Tam Bảo cứu vớt hết thảy ngưu đầu ngục tốt và tất cả chúng sinh chịu khổ trong đường địa ngục, khiến các chúng sinh ấy đều được giải thoát. Tội nhân khổ quả đồng thời tiêu diệt. Từ nay trở đi, rốt ráo vĩnh viễn đoạn trừ hết nghiệp địa ngục, rốt ráo không đọa trong ba đường ác, bỏ sống địa ngục, được sống Tịnh độ, bỏ mạng địa ngục, được mạng trí huệ, bỏ thân địa ngục, được thân Kim cang, bỏ khổ địa ngục được vui Niết bàn. Nhớ khổ địa ngục, phát tâm Bồ đề; tứ đẳng lục độ thường được hiện tiền. Tứ biện lục thông như ý tự tại."],["p","Dõng mãnh tinh tấn, không thôi không nghỉ, tiến lên cho đến mãn hạnh thập địa, trở lại độ thoát hết thảy chúng sinh, đồng nhập Kim cang, thành đẳng Chánh giác."],["v",["Lương Hoàng Bảo Sám,","Sắc mạng Sa môn,","Huỳnh kim điện thượng diễn huyền"]],["v",["văn, Cung các ái tường vân,","Pháp võ tân phân,","Trần thế cảm hoàng ân."]],["v",["Lương Hoàng Bảo Sám,","Vạn đức hồng danh,","Linh văn tứ quyển tối hoằng thâm,","Tự tự miễn tai truân,","Đảnh lễ Phật danh,","Tiêu tai bảo an ninh."]],["p","Nam mô Diệm Huệ Địa Bồ Tát Ma Ha Tát. (3 lần)"],["h","Cung Văn"],["p","Thiên thượng thiên hạ duy Phật độc tôn, thế xuất thế gian, thử pháp tối thắng. Cam lộ phổ triêm ư sa giới, Bồ Đề hương tán ư nhân gian. Đảnh thư bạch ngọc chi hào quang. Thể lộ huỳnh kim chi diệu tướng. Phàm tình khẩn đảo, đẳng niệm hiện tiền. Duy nguyện Hồng từ ai lân nhiếp thọ."],["p","Thượng lai phụng vì cầu sám đệ tử đẳng... tu sùng Từ Bi Đạo Tràng Sám Pháp, kim đương đệ tứ quyển, lễ tụng tương hoàn, công huân cáo tất. Bi tâm trùng vận khắc niệm kiền thành. Hương đàm trầm thủy chi tường vân, chúc thổ ưu đàm chi hoa nhụy. Hiến thiên trù chi diệu cúng, liệt thiền duyệt chi tô đà."],["p","Chung khánh tiếp thiên nhạc chi tề minh; phạm âm hòa diệu âm chi diễn xướng. Tập tư thiện lợi phổ ích hữu tình."],["p","Hồi hướng Giác Thiên kim tướng, mãn nguyệt Năng Nhân. Mãn bán mãn chi chân thuyên, học vô học chi Thượng sĩ, thiên địa minh dương linh triết, nhân gian, liệt miếu âu cơ, giám thử quỳ hoạt chi tâm, phổ giáng ân quang chi tỳ. Xuất sinh công đức, phụng vì cầu sám đệ tử đẳng..."],["p","Sám trừ tà chủng chi thâm khiên, đắc nhập tứ không chi Chánh định. Phục nguyện tứ sanh căn bổn nhân do, như than ốc tuyết; tứ trú phiền não chướng cấu, tợ nhật dung sương. Hành xuất tứ lưu, ly ái hà chi cốt một; tốc thành tứ đức, thú lạc độ chi huyền do. Tứ an lạc hạnh dĩ hiện tiền, tứ hoằng thệ nguyện nhi kiên cố."],["p","Đa sinh phụ mẫu đồng đăng giải thoát chi môn. Lụy kiếp oan thân, cộng chứng Bồ đề chi quả. Thị tắc y văn sám hối, thành khẩn túc nghiệp vị trừ; tái lao tôn chúng, đồng cầu sám hối."],["p","Nam mô Sám Hối Sư Bồ Tát Ma Ha Tát. (3 lần)"],["p","Lương Hoàng Bảo Sám, tứ quyển công đức lực, nguyện diệt đệ tử đẳng tội chướng, thân chứng Bồ Tát Diệm Huệ Địa."],["v",["Sám văn cử xứ, tội hoa phi,","Giải liễu oan, sám liễu tội,","Tiêu tai tăng phước huệ,","Thoát khổ sanh Đao Lợi.","Giải liễu oan, sám liễu tội,","Tiêu diêu trực nhập Long Hoa hội,","Long Hoa tam hội nguyện tương"]],["p","phùng, Di Lặc Phật tiền thân thọ ký."],["p","Nam mô Long Hoa Hội Bồ Tát Ma Ha Tát. (3 lần)"],["v",["Lương Hoàng Bảo Sám,","Tứ quyển dĩ vân châu,","Hồi hướng tứ ân tịnh tam hữu,","Bái sám chúng đẳng tăng phước thọ.","Nguyện tương pháp thủy tẩy khiên"]],["v",["vưu, Duy nguyện vong giả vãng Tây du.","Diệm Huệ Địa Bồ Tát,","Duy nguyện ai nạp thọ.","Nam Mô Đăng Vân Lộ Bồ Tát Ma Ha Tát. (3 lần)","Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh..."]],["v",["Hiệu Chính: HT. THÍCH TRÍ TỊNH","Dịch Giả: HT. THÍCH VIÊN GIÁC"]]],"p":"Quyển Thứ Tư"},{"t":"Đầu Quyển Năm","b":[["v",["Kỳ viên quả tư vị thậm kham","thường, Thanh qua, hồng thị, a lê dạng,","Hiệp chi, long nhãn kham cúng"]],["v",["dường.","Yêm ma la quả thế vô song,","Bà la môn, tiên, nhân,","Thân hiến Liên đài thượng.","Nam mô Phổ Hiền Vương Bồ Tát Ma Ha"]],["p","Tát. (3 lần)"],["h","Cung Văn"],["p","Tịnh ngũ nhãn chi Từ Tôn, hách hách hiện quang minh chi diệu tướng, khai ngũ thừa chi giáo hải lảng lảng tuyên Bát Nhã chi huyền âm. Ngũ thập ngũ vị chi Thánh Hiền, niệm niệm Bồ đề quả mãn. Ngũ căn ngũ lực chi Đại sĩ, trần trần giải thoát nhân duyên. Quy y tắc tăng trưởng phước điền, lễ niệm tắc năng tiêu tội cấu. Tịch nhiên bất động, cảm nhi toại tướng. Nguyện tứ Từ quang chứng minh tu phụng."],["p","Thượng lai phụng vì cầu sám đệ tử đẳng... tu kiến Từ Bi Đạo Tràng Sám Pháp, kim đương đệ ngũ quyển, nhập đàn duyên khởi. Cẩn bị hương đăng quả bình, phỉ cúng trân tu. Phổ phụng chư Phật Thánh Hiền, xưng dương hồng danh bảo hiệu. Khể tảng, lễ bái, phát lộ, đầu thành."],["p","Thiết niệm cầu sám đệ tử đẳng... tùng tích lụy kiếp, trực chí kim sanh, mê ngũ uẩn chi khứ lai, tùy ngũ trược chi lưu chuyển. Ngũ dục oanh triền, ngũ trần giao tế. Ngũ nghịch vị trừ, khởi nhân ngã ái tắng chi niệm. Ngũ pháp vị ngộ, tăng tự tha phiền não chi tình. Nhân duyên ký dĩ vô sai, quả báo thật nan đào tị. Kim tắc pháp chúng kiền thành chi chí, các khai giải thoát chi môn. Quy y ư Đại viên cảnh trung, tẩy địch ư Bồ đề hải nội. Tình ý như tư, Phật tất ai lân. Ngưỡng khấu Hồng từ, minh huân gia bị."],["v",["Phật thân thanh tịnh tợ lưu ly,","Phật diện do như mãn nguyệt huy.","Phật tại thế gian thường cứu khổ,","Phật tâm vô xứ bất Từ Bi."]],["p","Khải vận Từ Bi Đạo Tràng Sám Pháp, nhất tâm quy mạng Tam thế chư Phật:"],["v",["Nam mô Quá Khứ Tỳ Bà Thi Phật,","Nam mô Thi Khí Phật,","Nam mô Tỳ Xá Phù Phật,","Nam mô Câu Lưu Tôn Phật,","Nam mô Câu Na Hàm Mâu Ni Phật,","Nam mô Ca Diếp Phật,","Nam mô Bổn Sư Thích Ca Mâu Ni"]],["p","Phật, Nam mô Đương Lai Hạ Sanh Di Lặc"],["p","Tôn Phật."]],"p":"Quyển Thứ Năm"},{"t":"Chương Thứ Chín Giải Oan Thích Kiết","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng hiểu rõ tất cả chúng sinh đều có oán thù với nhau."],["p","Vì sao mà biết?"],["p","Vì không có oán thù thì không có ác đạo. Nay ác đạo không dứt, ba đường còn mãi, nên biết oán thù không bao giờ cùng tận."],["p","Kinh dạy rằng:"],["p","“Hết thảy chúng sanh đều có tâm. Vì có tâm nên đều được làm Phật”."],["p","Nhưng chúng sanh tâm tưởng điên đảo, tham đắm thế gian, không biết lối ra, cứ vun trồng gốc khổ não, bồi đắp cội oán thù. Sở dĩ phải luân hồi ba cõi qua lại sáu đường, xả thân lại thọ thân không bao giờ cùng tận."],["p","Vì sao vậy?"],["p","Vì hết thảy chúng sanh từ vô thỉ trở lại cho đến ngày nay, mê muội mãi mãi, vô minh che lấp, nước ái nhận chìm, nên khởi ra ba độc căn, khởi ra bốn điên đảo."],["p","Từ ba độc căn ấy sinh ra mười phiền não."],["p","Y nơi thân kiến khởi ra ngũ kiến. Y nơi ngũ kiến khởi ra sáu mươi hai kiến. Y nơi thân, khẩu, ý khởi ra mười hạnh ác. Thân, sát, đạo, dâm; miệng vọng ngôn, ỷ ngữ, lưỡng thiệt, ác khẩu; ý tham, sân, si."],["p","Tự mình làm mười điều ác, dạy người làm mười điều ác, khen ngợi người làm mười điều ác. Như vậy, y nơi thân, khẩu, ý khởi ra bốn chục điều ác."],["p","Lại y nơi sáu căn tham đắm sáu trần, hơn nữa là mở rộng cửa ác cho tám vạn bốn ngàn trần lao xâm nhập. Trong khoảng một niệm, khởi ra sáu mươi hai kiến chấp."],["p","Trong khoảng một niệm, tạo đủ bốn chục điều ác. Trong khoảng một niệm, mở cửa cho tám vạn bốn ngàn trần lao, huống nữa trong khoảng một ngày, thì khởi ra biết bao tội ác; huống nữa trong khoảng một tháng, khởi ra biết bao tội ác; huống nữa trong khoảng một năm, khởi ra biết bao tội ác; huống nữa chung thân lịch kiếp khởi ra biết bao tội ác."],["p","Tội ác như vậy, vô lượng vô biên, oán thù theo nhau không bao giờ cùng tận."],["p","Nhưng chúng sanh đồng sinh với ngu si, vô minh che lấp trí huệ, phiền não che lấp tâm tánh, chúng sanh không tự hiểu biết."],["p","Tư tưởng điên đảo, không tin lời kinh, không tin lời Phật, không biết giải oan, không trông giải thoát."],["p","Chúng sanh tự gieo mình vào đường ác, như phù du tự gieo mình vào đèn sáng, nhiều kiếp mê muội, chịu vô lượng khổ."],["p","Giả sử nghiệp báo hết rồi, được trở lại làm người, thì người ác như thế, trọn không cải cách, nên Thánh nhân phải sinh tâm thương xót. Như vậy cũng chỉ vì chúng sanh có oán thù với nhau mà ra."],["p","Chúng con nay đã phát tâm Bồ đề, tu Bồ Tát đạo, thấy Bồ Tát Ma ha tát, lấy việc cứu khổ làm tư lương, lấy việc giải oan kiết làm yếu hạnh. Bồ Tát không xả bỏ chúng sanh mà lấy việc cứu khổ, chịu khổ thế cho chúng sanh làm nền tảng."],["p","Chúng con ngày nay cũng phải như vậy; phải khởi tâm dõng mãnh, khởi tâm từ bi, tâm đồng như tâm Phật, nương nhờ Phật lực, dựng phan đạo tràng, đánh trống cam lồ, cầm cung trí huệ, nắm tên kiên cố, nguyện vì hết thảy tứ sinh, lục đạo, oán thù ba đời, cha mẹ, sư trưởng, lục thân quyến thuộc mà cởi mở oán thù."],["p","Những oán thù đã kết đều xả bỏ, những oán thù chưa kết, rốt ráo không kết nữa."],["p","Nguyện xin chư Phật, chư Đại Bồ Tát, dùng từ bi lực, dùng bổn nguyện lực, dùng thần thông lực, đồng gia tâm che chở, chiết phục, nhiếp thọ, làm cho vô lượng oán thù ba đời từ nay trở đi cho đến ngày thành Phật cởi mở sạch hết, không còn kết oán thù trở lại, hết thảy khổ não hoàn toàn đoạn trừ."],["p","Cùng nhau chí tâm, một lòng tha thiết, đầu thành đảnh lễ Tam Bảo, nguyện xin thế cho hết thảy chúng sanh trong bốn loài sáu đường, oán thù ba đời; nguyện xin thế cho cha mẹ, sư trưởng và hết thảy bà con quyến thuộc mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Thiện Ý Phật.","Nam mô Ly Cấu Phật.","Nam mô Nguyệt Tướng Phật.","Nam mô Đại Danh Phật.","Nam mô Châu Kế Phật.","Nam mô Oai Mãnh Phật.","Nam mô Sư Tử Bộ Phật.","Nam mô Đức Thọ Phật.","Nam mô Hoan Thích Phật.","Nam mô Huệ Tụ Phật.","Nam mô An Trú Phật.","Nam mô Hữu Ý Phật.","Nam mô Ương Già Đà Phật.","Nam mô Vô Lượng Ý Phật.","Nam mô Diệu Sắc Phật.","Nam mô Đa Trí Phật.","Nam mô Quang Minh Phật.","Nam mô Kiên Giới Phật.","Nam mô Cát Tường Phật.","Nam mô Bảo Tướng Phật.","Nam mô Liên Hoa Phật.","Nam mô Na La Diên Phật.","Nam mô An Lạc Phật.","Nam mô Trí Tích Phật.","Nam mô Đức Kỉnh Phật.","Nam mô Kiên Dõng Tinh Tấn Bồ Tát.","Nam mô Kim Cang Huệ Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Tất cả oán thù như vậy nay ở trong lục đạo những người đã chịu trả oán rồi, nguyện xin nhờ Phật lực, Pháp lực, Hiền Thánh lực, khiến các chúng sanh ấy đều được giải thoát. Hoặc có chúng sanh nào ở trong lục đạo đang chịu trả oán, hoặc chưa chịu trả oán, nguyện xin nhờ Phật lực, Pháp lực, Hiền Thánh lực, khiến các chúng sanh ấy hoàn toàn không trở lại trong các đường ác nữa, hoàn toàn không còn ác tâm đến với nhau nữa, hoàn toàn không làm độc hại khổ sở nhau nữa; tất cả đều xả bỏ, không còn phân biệt oán thân nữa. Tất cả tội lỗi đều được tiêu trừ."],["p","Tất cả oán thù đều được giải thoát, cùng nhau đồng tâm, hòa hiệp như nước với sữa, tất cả đều được hoan hỷ như ở Sơ địa."],["p","Thọ mạng vô cùng, thân tâm an lạc mãi, tùy ý sinh lên Thiên cung hay vãng sinh về Tịnh độ. Tưởng ăn có ăn, tưởng mặc có mặc, không còn nghe tiếng oán thù đấu tranh nữa."],["p","Thân không bị sự biến diệt xâm lăng, tâm không bị ngoại trần mê hoặc nhiễm trước. Điều lành tranh nhau nhóm họp, điều ác tranh nhau tiêu tan; phát tâm Đại thừa tu đạo Bồ Tát. Tứ đẳng lục độ đầy đủ, xả bỏ quả báo sanh tử, đồng đăng đạo tràng, thành bậc Chánh giác."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng biết cái gì là nguồn gốc của oán thù đau khổ?"],["p","Chính vì mắt tham sắc, tai tham tiếng, mũi tham hương, lưỡi tham vị, thân tham xúc tế nhị, nên chúng sanh thường bị năm ngoại trần ràng buộc, nhiều kiếp ở trong đêm dài mờ mịt, không được giác ngộ và giải thoát."],["p","Lại nữa, sáu dòng bà con, tất cả quyến thuộc đều là nguồn gốc oán thù ba đời của chúng ta vậy."],["p","Tất cả oán thù đều do thân nhân khởi ra. Nếu không có thân thì không có oán. Vậy ly thân tức là ly được oán."],["p","Vì cớ gì vậy?"],["p","Mỗi người ở một xứ, xa cách tha hương, như thế thì trọn không thể sinh tâm oán hận. Tâm oán hận sinh ra được đều do thân cận với nhau."],["p","Vì gốc ba độc tham, sân, si nên xúc não nhau; vì xúc não nhau nên phần nhiều hay sinh tâm oán hận."],["p","Sở dĩ bà con thân thích hay trách lẫn nhau. Hoặc cha mẹ trách con, hoặc con trách cha mẹ; anh em chị em hết thảy đều hay trách lẫn nhau, và hiềm hận lẫn nhau."],["p","Có chút gì không bằng lòng liền sinh tâm giận dữ."],["p","Nếu giàu sang phú quý thì nhìn bà con, đua nhau đến xin; khi nghèo thiếu thì không ai để ý."],["p","Lại nữa, càng xin càng lấy làm thiếu, càng được càng lấy làm không đủ. Trăm lần xin, trăm lần được cũng không lấy làm ơn, hơi không vừa lòng trở lại giận hờn. Từ đó đã bắt đầu lòng ôm ác niệm, nghĩ tìm cách cố ý kết thù liên họa, đời đời không thôi."],["p","Suy ra mà biết, oán thù ba đời, thật không ai xa lạ, đều là bà con thân thích, quyến thuộc chúng ta cả."],["p","Vậy nên biết, quyến thuộc là nhóm oan gia, chúng con không thể không hết lòng ân cần sám hối, chí tâm đầu thành đảnh lễ Tam Bảo. Nguyện vì từ khi có thần thức trở lại cho đến ngày nay, cha mẹ nhiều đời, bà con nhiều kiếp, ở trong sáu đường, đã kết oán thù cùng nhau, hoặc là oán thù hay không phải oán thù, hoặc khinh hoặc trọng, hôm nay hoặc ở trong đường địa ngục, đường ngạ quỷ, đường súc sinh, đường A tu la, hay ở trong nhân đạo; hoặc ở trên các cõi Trời, hoặc ở trong các loài Tiên hay ở trong vòng bà con quyến thuộc của chúng con; như thế những người oán thù và quyến thuộc của các người ấy trong ba đời, ngày nay chúng con tên... xin đem tâm từ bi, tâm không phân biệt oán thân, tâm như tâm Phật, nguyện như nguyện Phật, xin thay thế hết thảy chúng sanh ấy mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Phạm Đức Phật.","Nam mô Bảo Tích Phật.","Nam mô Hoa Thiên Phật.","Nam mô Thiện Tư Nghị Phật.","Nam mô Pháp Tự Tại Phật.","Nam mô Danh Văn Ý Phật.","Nam mô Lạc Thuyết Tụ Phật.","Nam mô Kim Cang Tướng Phật.","Nam mô Cầu Lợi Ích Phật.","Nam mô Du Hí Thần Thông Phật.","Nam mô Ly Ám Phật.","Nam mô Đa Thiên Phật.","Nam mô Di Lâu Tướng Phật.","Nam mô Chúng Minh Phật.","Nam mô Bảo Tạng Phật.","Nam mô Cực Cao Hạnh Phật.","Nam mô Đề Sa Phật.","Nam mô Châu Giác Phật.","Nam mô Đức Tán Phật.","Nam mô Nhật Nguyệt Minh Phật.","Nam mô Nhật Minh Phật.","Nam mô Tinh Tú Phật.","Nam mô Sư Tử Tướng Phật.","Nam mô Vi Lam Vương Phật","Nam mô Phước Tạng Phật.","Nam mô Khí Ấm Cái Bồ Tát.","Nam mô Tịch Căn Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo, nguyện xin nhờ Phật lực, Pháp lực, Đại địa Bồ Tát lực, hết thảy Hiền Thánh lực, khiến cho cha mẹ, bà con chúng con ở trong sáu đường, nếu người nào có oán thù và quyến thuộc các người ấy đều đồng thời vân tập đến đạo tràng này, cùng nhau sám hối tội đời trước, giải các oán thù đã kết. Nếu người nào thân hình bị câu thúc, trở ngại không thể đến được, ngày nay xin nhờ thần lực của Tam Bảo, thâu nhiếp tinh thần của các người ấy, khiến họ đến được đạo tràng, đem lòng từ bi thọ lãnh sự sám hối của chúng con ngày nay, nguyện mong giải thoát hết thảy oán thù."],["p","Đại chúng trong đạo tràng đều nên tâm niệm, miệng nói lời này:"],["p","Chúng con tên... từ vô thỉ, khi có thần thức trở lại cho đến ngày nay, đối với cha mẹ nhiều đời, bà con nhiều kiếp, chú bác cô dì, quyến thuộc nội ngoại, vì gốc ba độc khởi ra mười nghiệp ác, hoặc vì không biết, hoặc vì không tin, hoặc vì không tu, bởi vô minh che lấp trí huệ nên sinh ra oán kết, đối với cha mẹ, bà con cho đến cả trong lục đạo cũng có oán thù."],["p","Những tội như vậy vô lượng vô biên, ngày nay sám hối nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay, hoặc vì giận hờn, hoặc vì tham ái, hoặc vì ngu si, do gốc ba độc mà tạo ra các tội. Tội ác như vậy, vô lượng vô biên, hổ thẹn, sám hối, nguyện xin xả thí hết."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay, hoặc vì ruộng vườn, hoặc vì nhà cửa, hoặc vì tiền của mà sinh ra nghiệp oán thù, đối với bà con, cha mẹ đem tâm sát hại đủ điều. Những tội sát ấy không thể kể xiết, sinh ra oán thù không bao giờ hết. Ngày nay hổ thẹn, tỏ bày sám hối, nguyện xin cha mẹ, sáu dòng bà con, hết thảy quyến thuộc, đem lòng từ bi cho chúng con sám hối, xả bỏ tất cả tội lỗi, không còn tâm oán hận nữa. Cho đến trộm cắp, tà dâm, vọng ngữ, thập ác, ngũ nghịch, chúng con đều có làm cả; vì vọng tưởng điên đảo, phan duyên các cảnh, tạo ra hết thảy tội."],["p","Những tội như vậy vô lượng vô biên, hoặc đối với cha mẹ mà khởi ra, hoặc đối với anh em, chị em mà khởi ra, hoặc đối với cô dì, chú bác mà khởi ra, từ khi có thần thức trở lại cho đến ngày nay, đối với lục thân quyến thuộc mà khởi ra oán thù."],["p","Những tội như vậy vô lượng vô biên."],["p","Tội nhân khổ quả như thế phải trả báo, chịu hành phạt, kiếp số lâu mau, oán kết nhiều ít, chỉ có hết thảy chư Phật, chư Đại Bồ Tát trong mười phương mới thấy hết, biết hết."],["p","Như chỗ chư Phật và Bồ Tát đã thấy, đã biết, tội lượng nhiều ít, oán thù bao nhiêu, thời gian dài ngắn, đến đời vị lai mới thọ lãnh sự trả thù ấy; ngày nay chúng con rất hổ thẹn, nghẹn ngào, đau khổ, tự trách tự hối, xin cải ác tùng thiện, không dám làm nữa."],["p","Nguyện xin cha mẹ, bà con quyến thuộc, tất cả thân nhân, đem tâm nhu nhuyến, tâm điều hòa, tâm lạc thiện, tâm hoan hỷ, tâm phò hộ, tâm như tâm Phật, cho chúng con tên... sám hối; xả bỏ tất cả tội lỗi cho chúng con, không tưởng đến oán thân nữa."],["p","Lại nguyện xin cho cha mẹ bà con tất cả quyến thuộc, nếu có bị ai oán thù trong lục đạo, cũng nguyện xin tất cả chúng sanh trong lục đạo, đồng chung xả bỏ oán thù."],["p","Hết thảy oán thù trong ba đời nhất thời sạch hết. Từ nay trở đi cho đến ngày thành đạo, vĩnh biệt tam đồ, tuyệt bốn ác thú; tất cả đều hòa hiệp như nước và sữa, tất cả đều không chướng ngại, như hư không rộng rãi, hằng làm bà con Phật pháp, quyến thuộc Từ bi. Mọi người đều tu tập vô lượng trí huệ, thành tựu tất cả công đức, dõng mãnh tinh tấn, không thôi không nghỉ, tu Bồ Tát đạo không biết mỏi mệt. Tâm đồng như tâm Phật, nguyện đồng như nguyện Phật, được pháp Tam mật của chư Phật, đủ năm phần Pháp thân, cứu cánh Vô thượng Bồ đề, thành bậc Chánh giác."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng, đã giải oán kết với cha mẹ rồi, thứ lại nên giải oán kết với Sư trưởng."],["p","Từ bậc Đại thánh trở xuống, tâm thể chưa được hoàn toàn viên tịch, vô sanh Pháp nhẫn, còn bị ba tướng thiên diệt."],["p","Ở địa vị Đẳng giác rồi, Phật còn phương tiện dùng lời khổ khắc, để cho những chúng sanh ác độc nhân đó mà ngộ đạo."],["p","Bậc Minh đức giáo hóa quần sinh còn nhờ lời khổ khắc ấy, huống gì phàm phu, cách tuyệt cảnh thanh tịnh, làm sao khỏi oán."],["p","Nay thiện ác còn phức tạp, minh bạch chưa phân, làm sao tránh khỏi sự sai lầm của tam nghiệp, cho nên nghe lời này phải hổ thẹn."],["p","Đối với ơn đức Sư trưởng phải tự trách mình, lòng nên hổ thẹn, không nên nghi ngờ mà sinh ác tâm."],["p","Trong kinh Phật dạy: “Tuy xuất gia, nhưng chưa được giải thoát, dầu được xuất gia cũng không nên tự phụ mình không có điều ác; người tại gia cũng không nên tự cho mình hoàn toàn không có điều thiện”."],["v",["Vả thôi, không nên nói việc ấy nữa.","Hãy nghe lời Phật dạy trong kinh:"]],["p","Phật bảo đại chúng: “Các ngươi nên tưởng nhớ ơn Sư trưởng. Cha mẹ tuy sinh thân này, nuôi dưỡng, dạy bảo, nhưng không thể làm cho thân này ra khỏi ba đường ác. Lòng từ của Sư trưởng rất lớn, khuyến dụ, dẫn dắt kẻ sơ cơ, cho được xuất gia, rồi truyền trao cho đại giới (giới Tỳ kheo). Đó tức là kẻ sơ cơ đã hoài thai La hán, sẽ sinh quả La hán, xa lìa đau khổ sanh tử và được yên vui Niết bàn. Sư trưởng có ơn đức xuất thế ấy, ai hay báo đáp. Nếu người nào chung thân hành đạo, đó chỉ là tự lợi, chớ chưa phải là báo đáp ơn thầy”."],["p","Phật dạy: “Bạn lành trong thiên hạ không ai bằng Sư trưởng”."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nghe Phật dạy ơn đức Sư trưởng nặng như thế, nhưng chúng con chưa từng khi nào phát tâm nghĩ đến."],["p","Trái lại, có khi Sư trưởng dạy bảo còn không tin, không lãnh, cho đến còn nói lời thô tháo sinh tâm phỉ báng ngang ngược thị phi, làm suy đồi Chánh pháp."],["p","Những tội lỗi như thế làm sao thoát được Tam đồ. Khổ báo ấy không ai thay thế! Đến lúc chết rồi, vui đi khổ đến; tinh thần thảm não, tâm ý hôn mê, tinh thần không sáng suốt, năm căn tán loạn, muốn đi chân không thể bước; muốn ngồi thân không thể yên; giả sử muốn nghe thuyết pháp tai không thể nghe; muốn xem cảnh đẹp, mắt không thể thấy. Ngay lúc bấy giờ muốn nhớ lại sự lễ sám hôm nay cũng không được, chỉ có những cảnh tượng rùng rợn hung ác trong địa ngục hiện ra mà thôi."],["p","Sở dĩ trong kinh Phật dạy: “Người ngu si tự thị không tin tội phước, hủy báng Sư trưởng, ghen ghét tật đố. Những người như vậy là Ma vương trong Phật pháp, là dòng giống địa ngục, tự kết oán thù, chịu quả đau khổ vô cùng”."],["p","Như Hoa Quang Tỳ kheo khéo thuyết pháp bí yếu, có một đệ tử thường ôm lòng kiêu mạn, Hòa thượng dạy bảo không tin, không nghe, lại nói thế này: “Đại Hòa thượng của tôi không có trí huệ, thường hay tán thán những việc trống rỗng như hư không. Tôi nguyện đời sau không thấy ngài nữa”."],["p","Người đệ tử ấy, từ ngày đó pháp nói phi pháp, phi pháp nói là pháp. Tuy trì cấm giới không hủy phạm, nhưng vì hiểu lầm lời thầy nên sau chết rồi, trong một nháy mắt, liền đọa A tỳ địa ngục, tám mươi ức kiếp, thường chịu đại thống khổ."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nghe lời Kinh dạy thế ấy, mọi người há không sợ hãi sao!"],["p","Chỉ đối với Hòa thượng sinh một lời ác, còn đọa xuống A tỳ địa ngục tám chục ức kiếp, huống nữa từ khi xuất gia trở lại cho đến ngày nay, tội lỗi đối với Hòa thượng đã sinh ra ác nghiệp vô lượng vô biên. Quyết định bỏ thân này sẽ đồng tội với người đệ tử kia, sa xuống địa ngục, không còn nghi gì nữa."],["p","Vì sao vậy? Vì Hòa thượng và A xà lê thường đem tâm dạy bảo, nhưng chúng con chưa từng đúng như pháp mà tu hành. Đối với các bậc Sư trưởng phần nhiều chúng con hay sinh lòng trái nghịch, hoặc các ngài cung cấp cho mà không tự biết chán, biết đủ, hoặc thầy giận đệ tử, hoặc đệ tử giận thầy, trong ba đời, sự hỷ nộ vô lượng. Những tội như vậy không thể kể xiết."],["p","Trong kinh Phật dạy: “Sinh một lòng sân, oán thù vô lượng”."],["p","Những oán thù ấy không những trong sáu dòng bà con, mà sư đồ, đệ tử cũng hiềm hận lắm lắm."],["p","Lại còn những lúc đồng phòng chung ở, đối với các bậc thượng tọa, trung tọa, hạ tọa, chúng con không thâm tín sự xuất gia là pháp viễn ly sanh tử, không biết nhẫn nhục là hạnh an lạc, không biết bình đẳng là đường vào Bồ đề, không biết xa lìa vọng tưởng là tâm xuất thế, thầy trò đồng phòng chung ở, vì kết sự phiền não, nghiệp chướng chưa hết nên hay trái chống nhau, tâm phân biệt đột nhiên loạn khởi, nên tranh cãi nhau, sở dĩ vì vậy mà đời đời không hòa hiệp."],["p","Lại nữa, người xuất gia, hoặc là đồng học nghiệp, hoặc là đồng sư chung học trong những ngày ấy, thấy người thắng tấn, chúng con liền ôm lòng độc hại, sân hận vì ganh tị mà không tự biết đó là sức trí huệ đời trước, cho nên người có phước đức, chúng con không có thiện căn, tâm hữu lậu của chúng con hay sinh cao hạ, hay khởi đấu tranh, ít khi hòa hiệp, không thể nhường nhịn người dày đức, chúng con bạc phước, bèn hiềm hận nhau, mình quấy, chỉ nói xấu người, hoặc vì ba độc mà sàm báng nhau, không có tâm trung tín, không có ý cung kỉnh, không khi nào nghĩ lại điều trái của chúng con. Cho đến cao tiếng lớn lời nói điều thô lỗ là điều Phật cấm; những điều Sư trưởng dạy bảo cũng không tin. Các bậc thượng, trung, hạ tòa, ai cũng ôm lòng phẫn hận chúng con cả. Vì phẫn hận nên lại thị phi nhau, thành ra trong ba đường ác phần nhiều đều có oán thù."],["p","Thị phi oán thù như thế đều do thầy trò đệ tử chúng con gây ra."],["p","Trong lúc đồng học, chung ở, thượng, trung, hạ tòa, khởi lên một niệm tâm sân hận, oán thù đã vô lượng."],["p","Sở dĩ trong kinh Phật dạy: “Đời nay có ý giận nhau, ghen ghét nhau, tật đố nhau một chút, đời sau các xấu ấy càng thêm kịch liệt, thành ra oán thù lớn, huống nữa ác ý đã phát ra trọn đời thì nghiệp báo ấy kể sao cho xiết”."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đều không tự biết trong lục đạo đã gây thù kết oán với các bậc Sư trưởng, thượng, trung, hạ tòa. Oán thù ấy không có ngày cùng tận."],["p","Sự oán thù này không có hình tướng; thời gian chịu khổ không có kỳ hạn, không có kiếp số, không thể chịu được."],["p","Vậy nên Bồ Tát Ma ha tát xả tâm oán thân, dùng tâm từ bi, tâm bình đẳng mà thâu nhiếp tất cả chúng sanh. Ngày nay đại chúng đã cùng nhau phát Bồ đề tâm, phát Bồ đề nguyện nên phải tập tu hạnh Bồ Tát, Tứ vô lượng tâm, Lục ba la mật, Tứ hoằng thệ nguyện, Tứ nhiếp pháp. Đó là sự tu hành căn bản của chư Phật và Bồ Tát đã làm."],["p","Như chư Phật và Bồ Tát đã làm, chúng con ngày nay cũng tập làm, oán thân bình đẳng, hết thảy không ngại nhau."],["p","Từ nay trở đi cho đến ngày thành Phật, thề phải cứu hộ hết thảy chúng sanh, khiến các chúng sanh đều được giải thoát."],["p","Cùng nhau chí tâm đầu thành đảnh lễ Tam Bảo, chúng con nguyện vì hết thảy chúng sanh, kể từ khi có thần thức trở lại đây, trải qua bao nhiêu đời xuất gia, đối với các bậc Hòa thượng, A xà lê, mà có oán thù, đối với các bậc đồng đàn tôn chứng, mà có oán thù, đối với quyến thuộc đồng học, thượng, trung, hạ tòa, mà có oán thù, hoặc đối với người có duyên hay vô duyên với Phật pháp mà có oán thù; rộng ra cho đến oán thù ba đời, trong tứ sanh lục đạo, khắp cùng mười phương, hoặc có oán thù hay không phải oán thù hoặc khinh hoặc trọng; đối với quyến thuộc của các người oán thù ấy, đệ tử chúng con tên... nếu có oán thù với tất cả chúng sanh trong lục đạo đến đời vị lai hay trong hiện tại, chúng con chịu trả quả báo, hôm nay chúng con nguyện xin sám hối trừ diệt hết."],["p","Nếu tất cả chúng sanh trong lục đạo, mỗi mỗi đều oán thù với nhau, ngày nay đệ tử chúng con tên... xin đem lòng từ bi, không phân biệt oán thân, khắp vì oán thù ba đời mà cầu xin sám hối. Nguyện xin cho các chúng sanh ấy xả bỏ oán thù, không còn nghĩ đến điều ác độc để hại nhau nữa, không còn ôm lòng độc ác đến với nhau nữa. Nguyện xin hết thảy chúng sanh, trong lục đạo cũng đồng xả bỏ oán thù, hết thảy đều hoan hỷ với nhau. Từ nay đã giải oán thù rồi, không còn sân hận nhau, mà cung kỉnh nhau, tâm nghĩ báo ơn nhau, như tâm chư Phật, như nguyện chư Phật; mọi người đều nhất tâm đảnh lễ quy y thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Kiến Hữu Biên Phật.","Nam mô Điện Minh Phật.","Nam mô Kim Sơn Phật.","Nam mô Sư Tử Đức Phật.","Nam mô Thắng Tướng Phật.","Nam mô Minh Tán Phật.","Nam mô Kiên Tinh Tấn Phật.","Nam mô Cụ Túc Tán Phật.","Nam mô Ly Úy Sư Phật.","Nam mô Ứng Thiên Phật.","Nam mô Đại Đăng Phật.","Nam mô Thế Minh Phật.","Nam mô Diệu Âm Phật.","Nam mô Trì Thượng Công Đức Phật.","Nam mô Ly Ám Phật.","Nam mô Bảo Tán Phật.","Nam mô Sư Tử Giáp Phật.","Nam mô Diệt Quá Phật.","Nam mô Trì Cam Lồ Phật.","Nam mô Nhơn Nguyệt Phật.","Nam mô Hỷ Kiến Phật.","Nam mô Trang Nghiêm Phật.","Nam mô Châu Minh Phật.","Nam mô Sơn Đảnh Phật.","Nam mô Danh Tướng Phật.","Nam mô Pháp Tích Phật","Nam mô Huệ Thượng Bồ Tát.","Nam mô Thường Bất Ly Thế Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo, nguyện xin nhờ Phật lực, Pháp lực, hết thảy Hiền Thánh lực khiến vô lượng oán thù ba đời, hoặc oán thù hay không phải oán thù và hết thảy chúng sanh trong hư không pháp giới, đều phát tâm sám hối, cởi mở oán kết; tất cả oán thù đều xả bỏ, không còn phân biệt oán thân, tất cả đều hòa hiệp như nước với sữa, tất cả đều hoan hỷ như ở Sơ địa, tất cả đều vô ngại như hư không. Từ nay cho đến ngày thành Phật hằng làm bà con Phật pháp, quyến thuộc từ bi, như chư Bồ Tát."],["p","Lại nữa, chúng con xin nhờ công đức nhân duyên lễ bái sám hối hôm nay để cởi mở oán kết. Nguyện xin chư vị Hòa thượng, các bậc A xà lê, đồng đàn Tôn chứng, các vị đồng học và hết thảy quyến thuộc của các bậc thượng, trung, hạ tòa, có oán thù, cho đến các chúng sanh trong bốn loài sáu đường, mỗi mỗi đều có oán thù ba đời, chưa được giải thoát, ngày nay hoặc còn ở trong thiên đạo, ở trong tiên đạo, còn ở trong a tu la đạo, còn ở trong địa ngục đạo, còn ở trong ngạ quỷ đạo, còn ở trong súc sinh đạo, còn ở trong nhân đạo hay còn ở trong bà con quyến thuộc, mười phương ba đời oán thù như vậy, hoặc oán thù hay không phải oán thù, mỗi người ấy và bà con quyến thuộc của các người ấy, từ nay trở đi cho đến ngày thành Phật, tất cả tội chướng, nguyện đều tiêu diệt, tất cả oán thù hoàn toàn giải thoát, kiết tập phiền não hằng được thanh tịnh, tránh xa bốn ác thú, tự tại thọ sinh, niệm niệm giải thoát, tâm tâm tự tại, sáu ba la mật đầy đủ trang nghiêm, hạnh nguyện Thập địa, hoàn toàn viên mãn, được mười trí lực của Phật, thần thông vô ngại, chứng quả Bồ đề thành bậc Chánh giác."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng, biết rõ trên đây đã vì oán thù ba đời mà giải oan thích kết rồi."],["p","Từ đây trở xuống, riêng từng cá nhân phải tự trong sạch, phải hết lòng cùng nhau tự xét. Vì sao mà không được giải thoát?"],["p","Nghĩ về trước, không thấy được Đức Phật đối diện thọ ký cho mình, suy về sau cũng không nghe được một pháp âm của Phật phô diễn. Bởi vì tội nghiệp sâu dày, oán kết kiên cố cho nên không những không thấy được Phật đời trước, Phật đời sau, các vị Bồ Tát và Hiền Thánh, mà còn sợ e không nghe được âm thanh truyền hưởng, vang dội của Tam Tạng kinh điển nữa là khác. Xa cách Phật pháp thì ác đạo và thù oán không do đâu mà giải thoát."],["p","Bỏ thân mạng này rồi chìm xuống biển khổ luân chuyển ba đường, trải khắp ác thú, biết bao giờ trở lại được thân người!"],["p","Suy nghĩ như vậy mới thật là đau lòng, tâm tư như vậy mới thật là khổ trí."],["p","Chúng con được hạnh phúc may mắn, mong nhờ thuần phong của Phật, nên cát ái từ thân, xả gia ly tục, không còn tưởng nhớ gì nữa, há lại không tranh thủ thời gian, để cầu giải thoát! Nếu ý chí không kiên cường, quyết liệt chịu khổ, không lòng lo sợ, thoạt vậy thân lâm trọng bệnh, thân trung ấm hiện ra, thì ngưu đầu, ngục tốt, la sát, a bàng, hình tướng dễ sợ, thình lình tìm đến, gió phong đao xẻ thân, tinh thần sợ hãi, tán loạn, bà con khóc lóc cũng không hay biết. Ngay lúc bấy giờ sinh một niệm thiện tâm, cầu lễ sám như ngày nay cũng không thể được, chỉ thấy vô lượng đau khổ trong ba đường ác hiện ra."],["p","Ngày nay đại chúng đều phải nỗ lực tu tập cho kịp thời, nếu cứ tùy ý phóng túng thì ý chí hướng thượng phải chậm trễ, cho nên phải cố gắng chịu khổ mà dõng mãnh tiến lên."],["p","Vì thế trong kinh có dạy: “Từ bi là đạo tràng vì nhẫn nhục chịu khổ vậy."],["p","Phát tâm tu theo đạo tràng này thì mọi việc đều xong xuôi”."],["p","Vậy nên biết rằng: Vạn thiện được trang nghiêm đều nhờ sự cố gắng nhẫn nại, cũng như muốn qua bể cả, phải nương nhờ ghe thuyền. Nếu có tâm cầu an vui mà không làm việc gây nhân cầu an vui thì không thể có kết quả an vui. Lý và sự phải đi đôi với nhau. Người hết lương thực mà chỉ mơ tưởng cao lương mỹ vị, tưởng suông như vậy nào có ích gì cho sự đói khát, cần phải làm thế nào cho có cao lương mỹ vị thật sự mới được."],["p","Vậy muốn cầu có quả tốt đẹp nhiệm mầu quyết phải lý và sự đồng hành, không thể thiếu một."],["p","Đại chúng phải cùng nhau sinh tâm tăng thượng, phát ý hổ thẹn mà sám hối diệt tội giải các oán kết. Trái lại cứ mê mờ theo thói cũ thì chưa biết ngày nào tỏ ngộ. Nếu mọi người đều giải thoát mà ta còn trầm luân thì ăn năn không kịp."],["p","Đại chúng nhất tâm đầu thành đảnh lễ quy y Thế gian Đại Từ Bi phụ."],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Định Nghĩa Phật.","Nam mô Thí Nguyện Phật.","Nam mô Bảo Chúng Phật.","Nam mô Chúng Vương Phật.","Nam mô Du Bộ Phật.","Nam mô An Ổn Phật.","Nam mô Pháp Sai Biệt Phật.","Nam mô Thượng Tôn Phật.","Nam mô Cực Cao Đức Phật.","Nam mô Thượng Sư Tử Âm Phật.","Nam mô Lạc Hý Phật.","Nam mô Long Minh Phật.","Nam mô Hoa Sơn Phật.","Nam mô Long Hỷ Phật.","Nam mô Hương Tự Tại Vương Phật.","Nam mô Đại Danh Phật.","Nam mô Thiền Lực Phật.","Nam mô Đức Man Phật.","Nam mô Long Thủ Phật.","Nam mô Thiện Hành Ý Phật.","Nam mô Nhân Trang Nghiêm Phật.","Nam mô Trí Thắng Phật.","Nam mô Vô Lượng Nguyệt Phật.","Nam mô Thực Ngữ Phật.","Nam mô Nhật Minh Phật.","Nam mô Dược Vương Bồ Tát.","Nam mô Dược Thượng Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo, đệ tử chúng con tên... tích tập tội chướng sâu dày hơn đại địa, bị vô minh che lấp tâm tánh, trong đêm dài mù mịt, do ba độc mà tạo nhân thù oán, nên mê muội, chìm sâu trong ba cõi không có ngày ra."],["p","Ngày nay nhờ sức từ bi của chư Phật, chư đại Bồ Tát mới mong giác ngộ, sinh tâm hổ thẹn, chí thành cầu xin tỏ bày sám hối. Nguyện xin chư Phật, chư đại Bồ Tát rũ lòng từ bi thâu nhiếp chúng con, đem sức đại trí huệ, sức bất tư nghì, sức vô lượng tự tại, sức hàng phục tứ ma, sức diệt trừ phiền não, sức giải oan kết, sức độ thoát chúng sanh, sức an ổn chúng sanh, sức giải thoát địa ngục, sức tế độ ngạ quỷ, sức cứu vớt súc sinh, sức nhiếp hóa a tu la, sức nhiếp thọ nhân đạo, sức tận chư Thiên chư Tiên hữu lậu, sức vô lượng vô biên công đức, vô lượng vô tận trí huệ, nhờ những sức lực ấy khiến các chúng sanh có oán thù trong bốn loài sáu đường, đồng đến đạo tràng thọ lãnh sự sám hối của chúng con hôm nay."],["p","Chúng con tên... xả bỏ tất cả sự thù oán, không còn tư tưởng oán thù. Những nghiệp oán thù đã kết đều được giải thoát. Hằng lìa tám nạn khổ, không còn bốn ác thú, thường gặp được chư Phật, nghe Pháp, ngộ Đạo, phát tâm Bồ đề, tu nghiệp xuất thế. Tứ Vô lượng tâm, sáu Ba la mật hết lòng tu tập, tất cả hạnh nguyện đều được viên mãn, đồng lên Thập địa, đồng vào Kim cang, đồng thành Chánh giác."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nên nhận thấy rằng: Oán thù theo nhau đều do ba nghiệp đày đọa con người tu hành phải chịu khổ báo, khó chứng đạo quả."],["p","Đã biết nguồn gốc đau khổ, đều do ba nghiệp thì phải dõng mãnh diệt trừ ba nghiệp. Điều kiện thiết yếu dùng để diệt khổ, duy chỉ có phương pháp sám hối."],["p","Cho nên trong kinh Phật khen ngợi rằng: “Ở đời chỉ có hai hạng người mạnh nhất:"],["p","Một là hạng người không tạo tội, hai là người tạo tội rồi mà biết ăn năn, sám hối”."],["p","Ngày nay đại chúng muốn sám hối, thân tâm đều phải trong sạch, y phục chỉnh tề, sinh lòng hổ thẹn, buồn thảm ảo não, sinh hai niệm tâm thì tội gì cũng diệt, phước gì cũng sinh."],["p","Những gì là hai?"],["p","Một là biết hổ, hai là biết thẹn. Hổ là xấu hổ với trời. Thẹn là thẹn thùng với người. Hổ là tự mình hay sám hối, diệt trừ các oán thù. Thẹn là hay dạy bảo người cởi mở các sự trói buộc. Hổ là hay làm các điều thiện. Thẹn là hay tùy hỷ các việc thiện của người. Hổ là tự xấu hổ trong tâm. Thẹn là phát lồ, tỏ bày tội lỗi với người."],["p","Nhờ hai pháp ấy mà người tu hành được pháp an vui vô ngại."],["p","Ngày nay đã sinh tâm đại hổ thẹn, làm lễ đại sám hối, nên phải hết lòng cầu xin tứ sinh lục đạo. Vì sao vậy?"],["p","Vì trong kinh Phật dạy rằng: “Tất cả chúng sanh đều là bà con quyến thuộc với nhau, hoặc đã từng làm cha mẹ, hoặc đã từng làm Sư trưởng, cho đến hoặc đã từng làm anh em chị em với nhau. Hết thảy chúng sanh đều như thế. Bởi vô minh che lấp chơn tánh nên không biết nhau. Vì không biết nên hay sinh ra xúc não và oán thù nhau mãi mãi”."],["p","Ngày nay đại chúng đã hiểu biết ý ấy, nên phải hết lòng thành khẩn tha thiết dụng tâm, quyết khiến một niệm tâm cảm mười phương Phật, một lạy đoạn trừ vô lượng oán thù."],["p","Đại chúng nhất tâm đầu thành đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Định Ý Phật.","Nam mô Vô Lượng Hình Phật.","Nam mô Minh Chiếu Phật.","Nam mô Bảo Tướng Phật.","Nam mô Đoạn Nghi Phật.","Nam mô Thiện Minh Phật.","Nam mô Bất Hư Bộ Phật.","Nam mô Giác Ngộ Phật.","Nam mô Hoa Tướng Phật.","Nam mô Sơn Chủ Vương Phật.","Nam mô Đại Oai Đức Phật.","Nam mô Biến Kiến Phật.","Nam mô Vô Lượng Danh Phật.","Nam mô Bảo Thiên Phật.","Nam mô Trú Nghĩa Phật.","Nam mô Mãn Ý Phật.","Nam mô Thượng Tán Phật.","Nam mô Vô Ưu Phật.","Nam mô Vô Cấu Phật.","Nam mô Phạm Thiên Phật.","Nam mô Hoa Minh Phật.","Nam mô Thân Sai Biệt Phật.","Nam mô Pháp Minh Phật.","Nam mô Tận Kiến Phật.","Nam mô Đức Tịnh Phật.","Nam mô Văn Thù Sư Lợi Bồ Tát.","Nam mô Đại Hạnh Phổ Hiền Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo đồng gia tâm nhiếp thọ chúng con."],["p","Chúng con tên... cầu xin: Những điều sám hối đều được diệt trừ, đều được thanh tịnh."],["p","Lại nguyện xin cho những người đồng sám hối hôm nay từ nay trở đi cho đến ngày thành Phật, tất cả oán thù đều được giải thoát, tất cả thống khổ đều được tiêu diệt hoàn toàn; kiết tập phiền não hằng được thanh tịnh. Xa lìa bốn ác thú, tự tại thọ sinh, đích thân hầu hạ chư Phật, được Phật thọ ký, lục độ, tứ đẳng, nhất thời đồng tu, đủ bốn biện tài, được mười trí lực, tướng tốt nghiêm thân, thần thông vô ngại, vào Kim cang tâm, thành bậc Chánh giác."],["v",["Lương Hoàng Bảo Sám,","Chí Công tuyên dương,","Cửu trùng cung điện phóng hào"]],["v",["quang, Hy Thị miễn tai ương,","Cảm tạ quân vương,","Thoát khổ thượng thiên đường.","Lương Hoàng Bảo Sám,","Vạn đức hồng danh,","Linh văn ngũ quyển tối hoằng thâm, Tự tự miễn tai truân,","Đảnh lễ Phật danh,","Tiêu tai bảo an ninh.","Nam mô Nan Thắng Địa Bồ Tát Ma Ha","Tát. (3 lần)"]],["h","Cung Văn"],["p","Diệu tướng nguy nguy, lệ trung thiên chi cảo nhật. Từ phong đản đản chấn đại địa chi xuân lôi. Sái cam lộ ư trần tâm, quán đề hồ ư sa giới. Hữu cầu giai ứng, vô nguyện bất tòng. Như Lai thư ngũ nhãn chi quang minh, dung hội tác ngũ thời chi Phật sự."],["p","Thượng lai phụng vì cầu sám hối đệ tử đẳng... tu sùng Từ Bi Đạo Tràng Sám Pháp, kim đương đệ ngũ quyển, lễ tụng cáo chung, công huân tương bị. Tập ngũ đức chi cao lưu, chiêm ngũ thiên chi diệu tướng, nhiên ngũ phận chi chơn hương, điểm ngũ phương chi huệ cự. Kệ tán nhất âm, hoa phi ngũ sắc, cúng bỉnh gia vi cần hiến, lễ Phật hiệu ư quy khuynh. Tác quán, tụng kinh, thù công, dị đức; tiên thân hồi hướng Phật Bồ đề, nhiên hậu phổ huân châu sa giới, xuất sanh thù lợi, phụng vì cầu sám đệ tử đẳng... Sám vị sám chi tội cấu, tập vị chi thắng nhân."],["p","Phục nguyện ngũ uẩn chi vân tự không, ngũ suy chi tướng bất hiện. Ngũ căn ngũ lực nhi cụ túc. Ngũ cái ngũ triền dĩ tiêu dung. Phát minh ngũ chủng chi tâm hoa."],["p","Trì thủ ngũ chi chi tịnh giới. Hiện tồn quyến thuộc hy ngũ phước dĩ hàm trân."],["p","Quá khứ tôn thân đắc ngũ minh nhi thành tựu. Minh minh u trầm chi loại khổ luân tác, nhi cộng chứng Bồ đề. Cừu thù chấp đối chi đồ, oan nghiệp giải nhi đồng sanh thiện đạo."],["p","Lược lược vi vân hối quá, tế tế nghiệp quả nan trừ. Nhất nhất ngưỡng ư truy lưu, trùng trùng cầu ư sám hối."],["p","Nam mô Sám Hối Sư Bồ Tát Ma Ha Tát. (3 lần)"],["p","Lương Hoàng Bảo Sám."],["p","Ngũ quyển ngũ công đức lực, nguyện diệt đệ tử đẳng... ngũ chướng tội, thân chứng Bồ Tát Nan Thắng Địa."],["v",["Sám văn cử xứ, tội hoa phi.","Giải liễu oan, sám liễu tội.","Tiêu tai tăng phước thọ.","Thoát khổ sanh Đao Lợi.","Giải liễu oan, sám liễu tội.","Tiêu diêu trực nhập Long Hoa hội.","Long Hoa tam hội nguyện tương"]],["v",["Phùng.","Di Lặc Phật tiền thân thọ ký.","Nam mô Long Hoa Hội Bồ Tát Ma Ha Tát. (3 lần)"]],["v",["Lương Hoàng Bảo Sám.","Ngũ quyển ngũ toàn châu.","Hồi hướng tứ ân tịnh tam hữu.","Bái sám chúng đẳng tăng phước thọ.","Nguyện tương pháp thủy tẩy khiên"]],["v",["vưu.","Duy nguyện vong giả vãng Tây du.","Nan Thắng Địa Bồ Tát.","Duy nguyện ai nạp thọ.","Nam mô Đăng Vân Lộ Bồ Tát Ma Ha Tát. (3 lần)"]],["p","Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh..."],["v",["Hiệu Chính: HT. THÍCH TRÍ TỊNH","Dịch Giả: HT. THÍCH VIÊN GIÁC"]]],"p":"Quyển Thứ Năm"},{"t":"Đầu Quyển Sáu","b":[["p","Xuân tiền nhụy bách thảo tham kỳ, thanh trà nha điểm xuất hình hương."],["p","Phún ngọc bàn nội tuyết hoa nhuận."],["p","Triệu Châu công án hựu trùng tân. Thụy ma vương năng thối kỷ huỳnh hôn tận."],["p","Nam mô Phổ Hiền Vương Bồ Tát Ma Ha Tát. (3 lần)"],["h","Cung Văn"],["p","Thích Ca thị lục niên chi khổ hạnh, đạo quả viên thành, phá lục dục chi thiên ma. Thần Quang thiểm thước, Bồ Tát tề tu ư lục độ, vi quyến thuộc chi trang nghiêm. Thanh Văn giai chứng ư lục thông, tác tiền hậu chi vi nhiễu. Thọ ký tắc lục hiệp càn khôn chấn động, thuyết pháp tắc lục thời hoa võ tân phân. Diệu đức nan tư, ân quang phổ bị. Nguyện thùy ai mẫn, giám thử vi thành."],["p","Thượng lai phụng vì cầu sám đệ tử đẳng... khải kiến Từ Bi Đạo Tràng Sám Pháp, tư đương đệ lục quyển, nhập đàn duyên khởi, hương phún lục thù, đăng nhiên lục địa, lục hoa phi lục hiệp chi càn khôn, lục vị cúng lục thiên chi cam tượng. Khể tạng đầu thành, ân cần hối quá. Thiết niệm cầu sám đệ tử đẳng... nhân tùng khoáng kiếp, quả cập kim sanh, tùy trục lục căn phóng dật, lương do lục thức phan duyên, tham lục trần chi huyễn hóa, tạo lục thú chi luân hồi."],["p","Võng tu lục niệm chi chánh nhân, vị tu lục độ chi phạm hạnh; sanh sanh chi nội khổ quả vô cùng, thế thế chi trung vọng duyên bất tuyệt. Kim tắc tâm hoài hối quá, ý kiệt tinh thành, mạng lục hòa chi đại đức, tu lục độ chi sám văn, bằng lục thời chi khẩn thiết, giải lục thú chi tội khiên. Ngưỡng khấu Hồng từ, minh huân gia bị."],["p","Đại từ đại bi mẫn chúng sanh,"],["p","Đại hỷ đại xả tế hàm thức,"],["p","Tướng hảo quang minh dĩ tự nghiêm, Chúng đẳng chí tâm quy mạng lễ."],["p","Khải vận Từ Bi Đạo Tràng Sám Pháp, nhất tâm quy mạng tam thế chư Phật:"],["v",["Nam mô Quá Khứ Tỳ Bà Thi Phật.","Nam mô Thi Khí Phật.","Nam mô Tỳ Xá Phù Phật.","Nam mô Câu Lưu Tôn Phật.","Nam mô Câu Na Hàm Mâu Ni Phật.","Nam mô Ca Diếp Phật.","Nam mô Bổn Sư Thích Ca Mâu Ni"]],["v",["Phật.","Nam mô Đương Lai Hạ Sanh Di Lặc"]],["p","Tôn Phật."]],"p":"Quyển Thứ Sáu"},{"t":"Chương Thứ Chín Giải Oan Thích Kiết","b":[["p","(Tiếp Theo)"],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng trước hết là hướng về nơi tứ sinh lục đạo mà sám hối ác nghiệp của thân."],["v",["Kinh dạy rằng:","“Có thân thời có khổ, không thân thời không khổ”.","Thế thì thân này là nguồn gốc của khổ."]],["p","Những ác báo khốc liệt trong ba đường dữ đều do thân mà có. Chứ chưa thấy việc gì người làm mình chịu, hay mình làm người chịu. Mình làm mình chịu, mình gây nhân mình tự chịu quả."],["p","Nếu tạo thành một nghiệp, tội đã không bờ bến, huống nữa chung thân làm ác, tội biết bao nhiêu!"],["p","Nay ta chỉ biết có thân ta, không biết có thân người, chỉ biết có ta đau khổ, không biết có người đau khổ."],["p","Chỉ biết có ta cầu an vui, không biết người cũng cầu an vui."],["p","Vì ngu si nên chúng ta sinh tâm bỉ ngã, sinh tưởng oán thân, nên có oán thù cùng khắp lục đạo."],["p","Nếu không giải oán kiết thì biết lúc nào ra khỏi lục đạo; cứ ở mãi trong ấy kiếp này sang kiếp khác, há không đau lòng sao!"],["p","Hôm nay đại chúng khởi tâm dõng mãnh sinh đại hổ thẹn, làm lễ đại sám hối, quyết lòng khiến một niệm cảm mười phương Phật, một lạy đoạn trừ vô lượng oán kiết."],["p","Đồng nhau một lòng tha thiết đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Nguyệt Diện Phật.","Nam mô Bảo Đăng Phật.","Nam mô Bảo Tướng Phật.","Nam mô Thượng Danh Phật.","Nam mô Tác Danh Phật.","Nam mô Vô Lượng Âm Phật.","Nam mô Vi Lam Phật.","Nam mô Sư Tử Thân Phật.","Nam mô Minh Ý Phật.","Nam mô Vô Năng Thắng Phật.","Nam mô Công Đức Phẩm Phật.","Nam mô Nguyệt Tướng Phật.","Nam mô Đắc Thế Phật.","Nam mô Vô Biên Hạnh Phật.","Nam mô Khai Hoa Phật.","Nam mô Tịnh Cấu Phật.","Nam mô Kiến Nhất Thế Nghĩa Phật.","Nam mô Dõng Lực Phật.","Nam mô Phú Túc Phật.","Nam mô Phước Đức Phật.","Nam mô Tùy Thời Phật.","Nam mô Quảng Ý Phật.","Nam mô Công Đức Kỉnh Phật.","Nam mô Thiện Tịch Diệt Phật.","Nam mô Tài Thiên Phật.","Nam mô Khánh Âm Phật.","Nam mô Đại Thế Chí Bồ Tát.","Nam mô Thường Tinh Tấn Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin nhờ Phật lực, Pháp lực, Bồ Tát lực và hết thảy Hiền Thánh lực, khiến tất cả chúng sanh có oán thù trong tứ sinh lục đạo đồng đến đạo tràng. Mọi người trong đại chúng đều sám tạ, tâm niệm miệng nói lời như thế này:"],["p","Chúng con tên... từ vô thỉ vô minh trú địa trở lại cho đến ngày nay, do vì nhân duyên ác nghiệp của thân, hoặc đối với các cõi trời, cõi người mà gây thù kết oán, hoặc đối với loài a tu la, loài địa ngục mà gây thù kết oán, nguyện nhờ Phật lực, Pháp lực, Bồ Tát lực và hết thảy Hiền Thánh lực, khiến các chúng sanh có tâm oán hận ba đời, ở trong tứ sinh lục đạo, hoặc có oán thù hay không phải oán thù, hoặc khinh hoặc trọng, nhờ sự sám hối hôm nay mà tội lỗi đều tiêu diệt, thân tâm được thanh tịnh, không còn chịu đau khổ trong ba cõi. Sinh ra nơi nào cũng thường gặp được chư Phật."],["p","Lại nữa, những người hiện đồng sám hối hôm nay, từ vô thỉ sinh tử trở lại cho đến ngày nay, vì nhân duyên ác nghiệp của thân mà gây oán kết thù với hết thảy chúng sanh trong ác đạo; hoặc do vì sân hận, hoặc do vì tham ái, hoặc do vì ngu si, từ ba độc căn ấy mà sinh ra mười ác nghiệp: ưa giết hại cầm thú, đoạn mạng trâu dê v.v... hoặc vì ruộng vườn, hoặc vì nhà cửa, hoặc vì tiền tài, trở lại giết hại lẫn nhau. Lại nữa, từ vô thỉ trở lại cho đến ngày nay hoặc vì lợi dưỡng mà giết lầm chúng sanh, hoặc giả làm thầy thuốc châm chích bách tính, những tội như vậy, oán thù vô lượng, ngày nay sám hối, nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ cho đến ngày nay, hoặc làm chúng sanh đói khát, hoặc giựt lương thực của người, hoặc bức ép chúng sanh uống mặn, nuốt đắng, hoặc đoạn nước uống của người; bao nhiêu nghiệp ác như vậy, sinh ra oán thù, ngày nay sám hối nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay, xa lìa minh sư, thân cận bạn ác, do thân ba nghiệp tạo bao nhiêu tội, buông lòng giết hại người vô tội cách yểu uổng; hoặc phá triệt ao hồ, bít lấp ngòi rãnh, não hại các loài lớn bé dưới nước, hoặc thiêu đốt núi rừng, hoặc bủa giăng chài lưới sát hại tất cả chúng sanh dưới nước. Oán thù như vậy vô lượng vô biên ngày nay sám hối nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay, tâm không từ bi, hạnh không bình đẳng, vặn cân bẻ móc, vào già ra non (đong đầy gạt lưng), xâm lấn người hèn hạ, hoặc phá hoại làng xóm của người, giành giựt cướp đoạt, cắp trộm của người để cung cấp cho mình, thiếu lòng thành tín, sát hại lẫn nhau. Những oán thù như vậy vô lượng vô biên, ngày nay sám hối nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay, tâm không từ bi, hạnh không từ bi, đối với chúng sanh trong sáu đường làm đủ mọi điều khổ sở, hoặc đánh đập bà con, không kể đạo tình quyến thuộc, hoặc trói buộc giam cầm ngục tối, hoặc tra khảo ngửa nghiêng, đâm bắn thương tích, hủy hoại thân thể, chém chặt tàn hại, lột da xẻ thịt, nấu nướng chiên xào. Những oán thù như vậy vô lượng vô biên, ngày nay sám hối nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay, do ba ác nghiệp của thân, bốn ác nghiệp của miệng, ba ác nghiệp của ý, tạo ra những tội tứ trọng, ngũ nghịch bao nhiêu điều ác đều làm hết."],["p","Tự ỷ mình tuổi cao mạng lớn, không sợ quỷ thần, chỉ sợ mình không hơn người, sợ người hơn mình, hoặc ỷ thế cao dòng lớn họ mà khinh người ngạo vật, gây ra oán thù như vậy, hoặc ỷ mình nghe nhiều hiểu rộng mà khinh người ngạo vật, gây ra oán thù như vậy hoặc vì văn chương, kỹ nghệ mà khinh người ngạo vật, gây ra oán thù như vậy, hoặc vì khoe giàu, xa xỉ mà khinh người ngạo vật, gây ra oán thù như vậy, hoặc vì ăn nói sắc sảo mà khinh người ngạo vật, gây ra oán thù như vậy."],["p","Những oán thù ấy hoặc đối bên hình tượng Phật Thánh không tâm cung kỉnh mà sinh ra, hoặc đối với Hòa thượng, A xà lê mà sinh ra, hoặc đối với các bậc thượng tọa, trung tọa, hạ tọa chung ở với nhau mà sinh ra, hoăc̣ với quyến thuộc của những người đồng tu học mà sinh ra, hoặc đối với cha mẹ bà con thân thích mà sinh ra."],["p","Những oán thù như vậy vô lượng vô biên, ngày nay sám hối, nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại đến ngày nay, hoặc đối với các loài trời, loài người mà sinh thù kết oán, hoặc đối với loài a tu la, loài địa ngục mà sinh thù kết oán, hoặc đối với các loài súc sanh, loài ngạ quỷ mà sinh thù kết oán, rộng ra cho đến đối với hết thảy các loài chúng sanh trong mười phương mà gây thù kết oán."],["p","Những tội ác ấy vô lượng vô biên, ngày nay sám hối, nguyện xin trừ diệt."],["p","Lại nữa, chúng con tên... từ vô thỉ trở lại cho đến ngày nay, hoặc vì tật đố, hoặc vì siểm khúc để cầu cho mình hơn người, hoặc vì danh dự, hoặc vì quyền lợi mà theo ngoại đạo tà kiến không biết hổ thẹn. Gây thù kết oán như vậy, hoặc nặng hoặc nhẹ, tội nhân khổ quả, số lượng nhiều ít, chỉ có chư Phật, chư đại Bồ Tát mới thấy hết, biết hết."],["p","Nguyện xin chư Phật, chư đại Bồ Tát rũ lòng thương xót chúng con. Như chúng con từ vô thỉ trở lại đây đã tạo ra bao nhiêu tội lỗi, hoặc tự làm, hoặc dạy người làm, hoặc thấy người làm sinh tâm tùy hỷ, hoặc chúng con tự lấy của Tam Bảo, hoặc dạy người lấy của Tam Bảo, hoặc thấy người lấy mà sinh tâm tùy hỷ, hoặc có che giấu, hoặc không che giấu các tội nói trên. Như chỗ chư Phật, chư đại Bồ Tát đã thấy, đã biết, tội lượng nhiều ít, đáng đọa địa ngục, ngạ quỷ, súc sanh, sa vào các đường ác, biên địa hạ tiện để chịu oán thù, ngày nay chúng con sám hối nguyện xin trừ diệt hết."],["p","Thần lực của chư Phật không thể nghĩ bàn, xin Phật rũ lòng từ bi cứu vớt hết thảy chúng sanh."],["p","Chúng con tên... nay hướng về tứ sinh lục đạo, cha mẹ, Sư trưởng, hết thảy bà con quyến thuộc mà sám hối tội đã làm, cởi mở oán thù. Nguyện xin Tam Bảo khiến hết thảy chúng sanh trong lục đạo, có tâm oán thù chúng con, đều hoan hỷ xả bỏ tất cả oán thù, không còn sinh tâm phân biệt oán thân, đối với nhau đều vô ngại, như hư không."],["p","Nguyện xin từ nay trở đi cho đến ngày thành Phật, đoạn trừ hết kiết tập phiền não."],["p","Ba nghiệp thanh tịnh không còn oán hận, tùy ý sinh lên thiên cung bảo điện."],["p","Tứ vô lượng tâm, lục ba la mật, thường hay tu hành trăm phước nghiêm thân, vạn thiện đầy đủ, an trú vào nơi đại định Thủ lăng nghiêm, chứng thân Kim cang."],["p","Trong khoảng một niệm, hiện thân khắp sáu đường, tế độ hết thảy chúng sanh, đồng lên đạo tràng thành bậc Chánh giác."],["p","Hôm nay đại chúng đồng nghiệp trong đạo tràng đã sám hối được thân tội, thì thân nghiệp được thanh tịnh. Còn lỗi của khẩu nghiệp nay phải sám hối. Khẩu nghiệp là cái họa môn của hết thảy oán thù. Cho nên các Đức Phật đều dạy không được nói hai lưỡi, nói lời hung ác, nói dối, nói thêu dệt. Nên biết lời nói dua nịnh quanh co, hoa mỹ hay đem lại thị phi, tai họa, không phải là ít, mắc phải quả báo rất nặng."],["p","Than ôi! người đời, tâm ôm lòng ác độc, miệng nói lời ác độc, thân làm việc ác độc. Do ba điều ấy mà hại chúng sanh, chúng sanh bị độc hại liền kết oán hận, thề quyết báo thù hoặc đời này toại nguyện, hoặc chết rồi mang theo. Chúng sanh kết oán như vậy khắp cả lục đạo để báo thù nhau, không bao giờ cùng tận."],["p","Báo thù nhau như vậy đều do túc nghiệp đời trước đã gây ra, chớ không phải vô cớ, không có nguyên nhân."],["p","Thân ba nghiệp, miệng bốn nghiệp."],["p","Những nghiệp ấy mới thật là nguồn gốc của tội ác."],["p","Người tại gia không trung hiếu, chết vào núi Thái Sơn, chịu sự thảm khốc của lửa nóng, nước sôi. Người xuất gia không vì Phật pháp, sau sẽ sinh về chỗ của người ác thường ở để chịu oán thù. Oán thù theo nhau như thế đều do ba nghiệp."],["p","Trong ba nghiệp ấy khẩu nghiệp nặng nhất, cho nên phải mắc đủ thứ quả báo đau khổ, trong đêm dài mù mịt mà không hay không biết."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng biết rằng chúng ta sở dĩ luân hồi mãi trong lục đạo đều do khẩu nghiệp, hoặc buông lời khinh khi thô tháo, miệng nói sắc sảo, biện bác xảo lanh, nói lời phù phiếm, dối trá quỷ quyệt, lời nói không đi đôi với việc làm, nên mắc phải ác báo nhiều kiếp không thôi. Vậy đại chúng đâu có thể không sợ hãi, không hết lòng sám hối, không tẩy trừ tội lỗi ấy đi."],["p","Chúng con từ khi có thần thức trở lại cho đến ngày nay, khẩu nghiệp bất thiện, không tốt đối với tứ sinh lục đạo, cha mẹ, Sư trưởng, tất cả bà con, không có điều ác gì của các người ấy mà chúng con không tuyên truyền. Chúng con nói lời thô xẵng, phát tiếng bạo hoạnh, hủy báng chê bai, bạn bè chơi nhảy, nhóm họp mà nói xấu, nói lời vô nghĩa. Chỉ không nói có, chỉ có nói không, thấy nói không thấy, không thấy nói thấy, nghe nói không nghe, không nghe nói nghe, làm nói không làm, không làm nói làm."],["p","Nói ngược nói xuôi như vậy, đảo lộn trời đất, để lợi mình hại người, dèm chê lẫn nhau."],["p","Nói đến mình thì bao nhiêu phước đức đều quy tụ về cho mình. Nói đến người thì bao nhiêu đều ác độc đều đổ xô về cho người. Cho đến khen chê tố cáo Thánh Hiền, so lường vua tôi, cân nhắc cha con, cơ hiềm Sư trưởng, hủy báng thiện tri thức, vô đạo, vô nghĩa, không ngó lại tai nạn u ách ở đời, tán hình mất mạng, đời sau thống khổ vĩnh kiếp mắc phải quả báo ác."],["p","Vả chăng vừa cười giỡn đó, trong khoảnh khắc liền chịu vô lượng trọng tội, huống nữa, dùng lời ác mà làm hại cho tất cả."],["p","Đệ tử chúng con, cùng nhau từ vô thỉ trở lại cho đến ngày nay do khẩu ác nghiệp, đối với các loài trời, loài người mà có oán thù, đối với loài a tu la, loài địa ngục mà oán thù, đối với loài ngạ quỷ, loài súc sinh mà có oán thù, đối với cha mẹ, Sư trưởng và tất cả bà con mà có oán thù, đệ tử chúng con tên... do lòng từ bi, đồng tu như Bồ Tát, đồng nguyện như Bồ Tát, xin thay thế cho tất cả chúng sanh mà đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Tịnh Đoạn Nghi Phật.","Nam mô Vô Lượng Trì Phật.","Nam mô Diệu Lạc Phật.","Nam mô Bất Phụ Phật.","Nam mô Vô Trú Phật.","Nam mô Đắc Xoa Ca Phật.","Nam mô Chúng Thủ Phật.","Nam mô Thế Quang Phật.","Nam mô Đa Đức Phật.","Nam mô Phất Sa Phật.","Nam mô Vô Biên Oai Đức Phật.","Nam mô Nghĩa Ý Phật.","Nam mô Dược Vương Phật.","Nam mô Đoạn Ác Phật.","Nam mô Vô Nhiệt Phật.","Nam mô Thiện Điều Phật.","Nam mô Danh Đức Phật.","Nam mô Hoa Đức Phật.","Nam mô Dõng Đức Phật.","Nam mô Kim Cang Quân Phật.","Nam mô Đại Đức Phật.","Nam mô Tịch Diệt Ý Phật.","Nam mô Hương Tượng Phật.","Nam mô Na La Diên Phật.","Nam mô Thiện Trú Phật.","Nam mô Bất Hưu Tức Bồ Tát.","Nam mô Diệu Âm Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin nhờ Phật lực, Pháp lực, Bồ Tát lực, Hiền Thánh lực, khiến tất cả chúng sanh trong tứ sinh lục đạo, giác ngộ trở lại mà đến đạo tràng."],["p","Nếu người nào có thân hình bị câu thúc trở ngại, có tâm mà không đến được, nguyện xin nhờ Phật lực, Pháp lực, Bồ Tát lực, Hiền Thánh lực thâu nhiếp tinh thần của những người ấy, khiến tất cả đều đến được đạo tràng này, thọ lãnh sự sám hối khẩu nghiệp của chúng con; từ vô thỉ vô minh trú địa trở lại cho đến ngày nay vì nhân duyên của nghiệp ác khẩu, đối với chúng sanh trong lục đạo, tạo ra đủ mối oán thù, nguyện xin nhờ sức oai thần của Tam Bảo khiến cho tất cả oán thù kết lại trong ba đời của tứ sinh lục đạo, nhân sám hối này mà được trừ diệt."],["p","Chúng con tên... từ vô thỉ trở lại cho đến ngày nay hoặc vì sân nhuế, hoặc vì tham ái, hoặc vì ngu si, từ ba độc căn, tạo mười ác hạnh, do bốn ác nghiệp của miệng tạo ra vô lượng tội. Hoặc do ác khẩu mà não loạn cha mẹ, Sư trưởng, quyến thuộc, và tất cả chúng sanh; hoặc đối với cha mẹ, khởi ra nghiệp nói dối; hoặc đối với Sư trưởng, khởi ra nghiệp nói dối; hoặc đối với quyến thuộc, khởi ra nghiệp nói dối; hoặc đối với tất cả chúng sanh, khởi ra nghiệp nói dối; hoặc thấy nói không thấy, không thấy nói thấy; hoặc nghe nói không nghe, không nghe nói nghe; hoặc biết nói không biết, không biết nói biết; hoặc vì kiêu mạn; hoặc vì tật đố khởi ra nghiệp nói dối."],["p","Những tội ác như vậy vô lượng vô biên, ngày nay sám hối, nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay khởi ra nghiệp hai lưỡi, thọ lãnh lời ác của người khác không thể che giấu; đến người này nói người kia, đến người kia nói người này; làm cho người này chia rẽ người kia, làm cho người kia đau khổ; hoặc vì cười giỡn, làm cho hai bên đấu tranh nhau, cốt nhục chia lìa; phá quyến thuộc của người, sàm loạn quần thần nhiễu hại tất cả."],["p","Những tội ác như vậy vô lượng vô biên, ngày nay sám hối, nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay, tạo tội ỷ ngữ, nói lời vô nghĩa, lời không lợi ích hoặc làm phiền não cha mẹ; hoặc làm phiền não Sư trưởng; hoặc làm phiền não bạn đồng học; cho đến đối với hết thảy chúng sanh trong lục đạo khởi tâm não hại."],["p","Như vậy khẩu nghiệp khởi ra oán thù vô lượng vô biên, ngày nay sám hối, nguyện xin trừ diệt."],["p","Nguyện nhờ Phật lực, Pháp lực, Bồ Tát lực và hết thảy Hiền Thánh lực, ngày nay chúng con sám hối, khiến cho tất cả oán thù ba đời trong bốn loài sáu đường, hết thảy sự gây thù kết oán hoàn toàn giải thoát, bao nhiêu tội nghiệp đều tiêu trừ, hoàn toàn không trở lại gây thù kết oán nữa, không đọa trở lại trong ba đường ác nữa, rốt ráo không trở lại trong lục đạo hòng làm khổ sở độc hại nhau nữa."],["p","Từ nay trở đi xả bỏ tất cả oán thù không còn phân biệt oán, thân, tất cả đều hòa hiệp như nước với sữa, tất cả đều hoan hỷ như ở Sơ địa, hằng làm pháp thân, từ bi quyến thuộc."],["p","Từ nay trở đi cho đến ngày thành Phật, không còn trở lại chịu quả báo trong ba cõi, đoạn ba nghiệp chướng, trừ năm bố úy, tứ vô lượng tâm, lục ba la mật tăng tấn, thâm tu, hành đạo Đại thừa, vào trí huệ Phật. Hết thảy hạnh nguyện đầy như biển cả. Lục thông, Tam minh, thảy đều thông suốt, chứng pháp Tam mật, đủ năm phần Pháp thân, phát Kim cang huệ, thành quả chủng trí."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đã được sám hối thân nghiệp rồi, khẩu nghiệp rồi; thứ lại sám hối ý nghiệp cho được thanh tịnh."],["p","Hết thảy chúng sanh luân hồi sinh tử, không được giải thoát đều do ý nghiệp."],["p","Thập ác ngũ nghịch kiết tập kiên cố quyết định đều do ý nghiệp. Cho nên Phật dạy rằng: “Không đoạn được tham dục, sân nhuế và ngu si tà kiến, thì sau phải đọa địa ngục chịu khổ vô cùng”."],["p","Ngày nay đại chúng đã cùng nhau nhận thấy rằng: “Cái tâm nó thúc đẩy cái thức làm việc cũng như vua chỉ huy tất cả đình thần”."],["p","Miệng nói lời ác, thân làm việc ác, nên hay chiêu tập quả báo đau khổ kịch liệt trong sáu đường."],["p","Nên biết rằng: Thân bị hủy diệt tan mất, việc ấy là do tâm tạo. Nay muốn sám hối trước phải đoạn trừ cái tâm, sau mới đánh dẹp cái ý. Vì cớ gì vậy? Kinh dạy rằng: “Chế ngự tâm lại một chỗ thì việc gì cũng xong”."],["p","Vậy thì tâm trong sạch, đó là nguồn gốc của giải thoát; ý thanh khiết, đó là nền tảng của tiến hóa."],["p","Được như thế, thì quả báo kịch liệt nơi tam đồ không lại, mà thống khổ vô cùng trong ác đạo cũng chẳng qua."],["p","Nhưng thân nghiệp, khẩu nghiệp, thô thiển bên ngoài dễ trừ. Ý nghiệp rất vi tế bên trong thật là khó trừ. Như Lai là bậc Đại Thánh, Nhất thế trí. Nhân đối với thân, khẩu, ý mới không cần giữ gìn, phàm phu ngu muội mê lầm, dám không cẩn thận hay sao!"],["p","Nếu không đánh dẹp ba nghiệp làm cho ba nghiệp thanh tịnh thì chưa thấy được điều lành của ba nghiệp."],["p","Vì thế nên kinh dạy rằng: “Phòng ngừa cái ý như canh gác cửa thành, giữ gìn cái miệng như bưng kín miệng bình”."],["p","Như thế, chúng con đâu dám không giữ gìn ba nghiệp hay sao. Chúng con từ vô thỉ trở lại cho đến ngày nay, thọ thân này do vô minh phát khởi ra ái dục, làm cho thêm lớn đường sinh tử và cũng hay làm đầy đủ mười hai điều đau khổ, tám tà, tám nạn, luân hồi lưu chuyển trong tam đồ lục đạo, không có chỗ nào là không trải qua. Chịu vô lượng khổ trong những chỗ như vậy đều do ý nghiệp cấu tạo, sinh ra oán thù. Ý nghiệp niệm niệm phan duyên, chưa từng tạm xả, kích động lục căn, chạy khắp ngũ thể. Những ác nghiệp nặng hay nhẹ đều do ý tạo ra cả."],["p","Nếu thân và khẩu chưa vừa ý thì tâm càng thêm giận dữ độc ác, bèn sát hại nhau, không thương xót."],["p","Như chúng con hơi có chút ghẻ ngứa đã không thể chịu được, giả sử việc ấy ở nơi người khác thì cho sự đau khổ không bao nhiêu."],["p","Thấy lỗi của người lòng muốn tuyên truyền nói ra, tự mình có lỗi không muốn người khác nghe biết. Có tâm niệm như vậy thật là xấu hổ."],["p","Lại nữa, ý khởi sân hận là mở đường rộng lớn, rước oán tặc vào tâm. Sở dĩ trong kinh Phật dạy rằng: “Giặc cướp công đức không gì hơn sân nhuế”."],["p","Lại nữa, kinh Hoa Nghiêm dạy rằng: “Phật tử khởi lên một niệm sân tâm, thì trong tất cả ác tâm không có tâm nào ác hơn nữa”."],["p","Vì sao vậy?"],["p","Vì khởi lên một niệm sân thì phải chịu một trăm ngàn vạn sự chướng ngại."],["v",["Chướng không thấy Bồ đề.","Chướng không nghe được Chánh"]],["v",["pháp.","Chướng làm cho sinh vào đường ác.","Chướng sinh ra nhiều tật bệnh.","Chướng bị người hủy báng.","Chướng sinh ra ám độn.","Chướng làm mất chánh niệm.","Chướng làm cho ít trí huệ.","Chướng làm cho gần ác tri thức.","Chướng không ưa việc hiền lành.","Chướng làm cho xa chánh kiến."]],["p","Cho đến xa lìa chánh giáo của Phật, vào cảnh giới của ma, trái với thiện tri thức, các căn khiếm khuyết, sinh vào các nhà làm nghiệp ác, ở nơi biên địa."],["p","Những chướng như vậy đều do sân hận, nhiều không thể kể xiết."],["p","Chúng con từ vô thỉ trở lại cho đến ngày nay, lẽ ra cũng có vô lượng vô biên ác tâm sân hận, cho đến khởi sân hận không kể gì bà con họ hàng, huống nữa là đối với các chúng sanh trong lục đạo. Cho đến do sân hận mà gây ra phiền não mãnh liệt độc ác, mà mình không tự biết."],["p","Chỉ về phần sự tướng bên ngoài không thực hiện được như ý muốn, chớ về tâm tưởng thì không có việc gì tâm không nghĩ đến."],["p","Giá như điều ác gì tâm đã nghĩ được, đã thực hiện được như ý muốn thì không ai là không khỏi bị khốn khổ."],["p","Bởi thế cho nên một phen thiên tử (vua) nổi giận thì thây phơi đầy đường ngàn dặm."],["p","Từ vua trở xuống thì tự do ngang tàng quấy nhiễu chúng sanh, đánh đập, trói buộc những người có tội. Ngay lúc bấy giờ thì không thể chỉ vào đâu mà nói rằng: “Ta làm lành được, chỉ sợ đánh người không đau, không nặng, không khốc liệt mà thôi”. Đó là sự ác độc của ý nghiệp chung cho tất cả loài hữu tình, trí ngu đều không khỏi. Giàu sang nghèo hèn như nhau mà chưa có một ngày nào biết hổ thẹn ăn năn. Ngày nay đại chúng đồng nghiệp trong đạo tràng nhận thấy phiền não sân hận của ý nghiệp rất sâu kín. Dầu chúng ta có muốn xả bỏ, nhưng gặp cảnh nó cũng sinh tâm, cùng với ác ý hoạt động, niệm niệm xúc chạm nhau, biết lúc nào thoát ly được khổ não ấy. Đại chúng đã biết tội này không thể để yên vậy mà không lo sám hối, thì ngày nay phải khấu đầu lễ bái, tỏ hết lòng thành sám hối tội sân hận, nguyện xin trừ diệt."],["p","Mọi người phải đầu thành đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Vô Sở Phụ Phật.","Nam mô Nguyệt Tướng Phật.","Nam mô Điện Tướng Phật.","Nam mô Cung Kỉnh Phật.","Nam mô Oai Đức Thủ Phật.","Nam mô Trí Nhật Phật.","Nam mô Thượng Lợi Phật.","Nam mô Tu Di Đảnh Phật.","Nam mô Trị Oán Tặc Phật.","Nam mô Liên Hoa Phật.","Nam mô Ứng Tán Phật.","Nam mô Trí Thứ Phật.","Nam mô Ly Kiêu Phật.","Nam mô Na La Diên Phật.","Nam mô Thường Lạc Phật.","Nam mô Bất Thiểu Quốc Phật.","Nam mô Thiên Danh Phật.","Nam mô Kiến Hữu Biên Phật.","Nam mô Thậm Lương Phật.","Nam mô Đa Công Đức Phật.","Nam mô Bảo Nguyệt Phật.","Nam mô Sư Tử Tướng Phật.","Nam mô Nhạo Thuyền Phật.","Nam mô Vô Sở Thiểu Phật.","Nam mô Du Hí Phật.","Nam mô Sư Tử Du Hí Bồ Tát.","Nam mô Sư Tử Phấn Tấn Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo. Nguyện xin Tam Bảo đem từ bi lực, vô lượng vô biên tự tại lực; nạp thọ chúng con tên... ngày nay hướng về tứ sinh lục đạo, cha mẹ, Sư trưởng, hết thảy bà con mà sám hối bao nhiêu oán thù do ý nghiệp đã kết lại, hoặc có oán thù hay không phải oán thù, hoặc khinh hoặc trọng, những oán đã kết rồi, nguyện xin sám hối trừ diệt, những oán chưa kết quyết không dám kết."],["p","Nguyện xin nhờ sức Tam Bảo đồng gia tâm nhiếp thọ, thương xót, che chở cho chúng con được giải thoát."],["p","Đệ tử chúng con tên... từ vô thỉ trở lại cho đến ngày nay, do vì nhân duyên ác nghiệp của ý, nên đối với tứ sinh lục đạo, cha mẹ, Sư trưởng và tất cả bà con, mà kết các oán thù, hoặc khinh, hoặc trọng, ngày nay hổ thẹn, tỏ bày sám hối, nguyện xin trừ diệt tất cả oán thù."],["p","Lại từ vô thỉ trở lại cho đến ngày nay, y nơi gốc ba độc, khởi ra tâm tham, nhân nơi tham sử, khởi ra tham nghiệp, hoặc u ẩn hay hiển hiện, cùng tận hư không giới hễ nơi nào, lúc nào thấy người có của thì sinh tâm ác, nghĩ rằng: “Ta sẽ lấy của ấy, cho đến của cha mẹ, của Sư trưởng, của bà con, của hết thảy chúng sanh, của chư Thiên, của chư Tiên, những của ấy đều cho là thuộc về ta cả”."],["p","Tội ác như thế vô lượng vô biên, ngày nay sám hối, nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay, khởi ra sân nghiệp, ngày đêm luôn luôn thiêu đốt thân tâm không có một giờ phút nào tạm thời dừng nghỉ. Có chút gì không bằng lòng, liền nổi giận đùng đùng, đem chúng sanh ra mà não hại đủ điều, hoặc roi gậy đánh đập, hoặc nhận chìm xuống nước, cho đến dùng cách xua đuổi (bức bách), bỏ đói khát, trói buộc treo lên trên cao, hay nhốt vào phòng tối cho đến chết."],["p","Những tội sân hận như thế vô lượng vô biên, gây ra oán thù không thể kể xiết, ngày nay sám hối, nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay, tùy thuận vô minh, làm những việc ngu si tạo tất cả điều ác; không có trí huệ chân chính, tin theo lời tà, thọ lãnh pháp tà, những nghiệp si mê như vậy tạo ra oán thù vô lượng vô biên, ngày nay sám hối, nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay, làm mười tà đạo, kết hết thảy oán thù, tạo tất cả ác nghiệp, niệm niệm phan duyên, chưa từng tạm xả, kích động sáu căn, khởi các kiết nghiệp, hoặc thời thân khẩu chưa thỏa mãn thì tâm càng thêm độc ác, cho đến giỡn cười, gây ra thị phi. Không dùng tâm ngay thẳng làm việc theo người, thường ôm lòng siểm khúc, không biết hổ thẹn."],["p","Những tội như vậy, vô lượng vô biên, ở trong lục đạo, chịu đại khổ não, ngày nay sám hối, nguyện xin trừ diệt."],["p","Đệ tử chúng con tên... từ vô thỉ trở lại cho đến ngày nay, thân nghiệp bất thiện, khẩu nghiệp bất thiện, ý nghiệp bất thiện. Những ác nghiệp như vậy đối với Phật khởi ra tất cả tội chướng, đối với Pháp khởi ra tất cả tội chướng, đối với Bồ Tát Hiền Thánh khởi ra tất cả tội chướng."],["p","Những tội chướng như vậy vô lượng vô biên, ngày nay chí thành cầu xin sám hối, nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay, thân ba ác nghiệp, miệng bốn ác nghiệp, ý ba ác nghiệp, tạo ra tất cả tội ngũ nghịch, tứ trọng, ngày nay sám hối, nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay, sáu căn, sáu trần, sáu thức, vọng tưởng điên đảo, phan duyên các cảnh, tạo ra tất cả các tội, ngày nay sám hối, nguyện xin trừ diệt."],["p","Lại nữa, từ vô thỉ trở lại cho đến ngày nay, đối với nhiếp oai nghi giới, nhiếp thiện pháp giới, nhiếp chúng sanh giới, phần nhiều có hủy phạm, sau này thân hoại mạng chung, phải đọa ba đường ác, ở trong địa ngục chịu vô lượng vô biên hằng sa thống khổ. Sau lại đọa vào ngạ quỷ sẽ ngu si, không hiểu biết gì, thường bị đói khát, chịu các nhiệt não, rồi lại đọa làm súc sinh, chịu vô lượng khổ, ăn uống vật bất tịnh, cơ hàn khốn khổ. Tội hết, được sinh làm người, đọa vào nhà tà kiến, tâm thường siểm khúc, tin lời tà, mất chánh đạo, chìm vào biển sinh tử không hẹn ngày ra."],["p","Tất cả tội ác, oán thù ba đời như thế nói không thể xiết, chỉ có chư Phật mới thấy hết, biết hết. Như chỗ chư Phật đã thấy đã biết, tội báo nhiều ít, ngày nay sám hối, nguyện xin trừ diệt."],["p","Nguyện xin chư Phật, chư đại Bồ Tát đem đại từ bi lực, đại thần thông lực, như pháp điều phục chúng sanh lực, khiến chúng con tên... ngày nay sám hối, tất cả oán thù liền được trừ diệt. Hết thảy chúng sanh trong lục đạo đã chịu trả oán thù rồi, hay chưa chịu trả oán thù, nguyện xin nhờ sức đại từ bi lực của chư Phật, chư đại Bồ Tát và tất cả Hiền Thánh, khiến hết thảy kẻ oán thù ấy hoàn toàn giải thoát. Từ nay trở đi cho đến ngày chứng quả Bồ đề, tất cả tội chướng hoàn toàn thanh tịnh, không sinh vào đường ác, sinh về Tịnh độ, bỏ sống oán thù, được sống trí huệ, bỏ thân oán thù, được thân kim cang, bỏ ác đạo khổ, được Niết bàn vui, nhớ ác đạo khổ, phát Bồ đề tâm, tứ đẳng lục độ thường được hiện tiền, tứ biện lục thông được tự tại như ý, dõng mãnh tinh tấn, không thôi không nghỉ, tu lên cho đến mãn hạnh Thập địa, trở lại độ thoát vô biên chúng sanh."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nguyện xin cho tất cả chúng sanh đời quá khứ, đời hiện tại và cùng tận đời vị lai trong bốn loài, sáu đường, đều được nhờ sự sám hối hôm nay mà thanh tịnh, đồng được giải thoát, đồng đủ trí huệ, thần thông tự tại."],["p","Nguyện xin cho các chúng sanh ấy từ nay trở đi cho đến ngày thành Phật, thường thấy được Pháp thân của chư Phật khắp mười phương, tận hư không giới, thường thấy thân tử ma kim sắc, ba mươi hai tướng tốt và tám mươi vẻ đẹp của chư Phật, phân tán ra khắp mười phương cứu độ chúng sanh; thường thấy chư Phật phóng bạch hào tướng quang ở giữa hai chặn mày, tế độ chúng sanh đau khổ trong địa ngục."],["p","Lại nguyện xin cho đại chúng đồng nghiệp trong đạo tràng, nhờ công đức nhân duyên sám hối thanh tịnh hôm nay, mà từ nay trở đi bỏ thân này thọ thân khác, cũng không vào trong địa ngục để chịu những thống khổ, tiêu hình hoại thể, trong vạc nước sôi, lò lửa nóng, không trải qua đường ngạ quỷ mà chịu các thống khổ đói khát; cổ nhỏ bằng kim, bụng to bằng trống chầu; không trải qua đường súc sinh để đền nợ cũ, trả mạng xưa, chịu các sự phanh thây xẻ thịt, lôi kéo khốn khổ."],["p","Nếu ở trong loài người, thì thân không mắc phải bốn trăm lẻ bốn bệnh khổ não, không chịu khổ đại hàn, đại nhiệt khó nhẫn nại; không chịu khổ vì đao gươm, roi gậy đánh đập, thuốc độc, não hại khốn khổ; không gặp phải tai nạn đói khát khốn khổ."],["p","Lại nguyện xin đại chúng, từ nay trở đi giữ giới trong sạch, không làm ô uế đạo tâm, thường tu nhân nghĩa, niệm tưởng báo ơn, cúng dường cha mẹ như cúng dường Phật không khác, phụng sự Sư trưởng như đối chư Phật, kỉnh trọng quốc chủ như thường trú Pháp thân, đối với mọi người như mình không khác."],["p","Lại nguyện xin đại chúng, từ nay trở đi cho đến ngày thành Phật, hiểu thấu nghĩa lý sâu mầu của chư Phật, tâm trí không sợ hãi, rõ thông Đại thừa, thấy suốt chánh pháp liền tự khai giải, không phải nhờ ai chỉ bày, một lòng kiên cố cầu đạo Bồ đề trở lại hóa độ vô biên chúng sanh, đồng như chư Phật, thành bậc Chánh giác."],["p","Ngày nay đại chúng ẩn thân hay hiện thân trong đạo tràng xin chứng minh cho lời phát nguyện mảy mọn sau này:"],["p","Chúng con tên... chánh nguyện:"],["p","Nguyện sinh về cảnh của Thánh nhân ở, thường hay kiến lập đạo tràng, hưng hiển cúng dường, làm lợi ích rộng lớn cho tất cả chúng sanh. Nguyện thường được Tam Bảo từ bi nhiếp thọ, thường có thế lực giáo hóa dìu dắt được dễ dàng, thường tu hành tinh tấn, không say đắm dục lạc ở đời; thường biết các pháp đều không có tự tánh; đối với người oán kẻ thân đều đem điều lành bình đẳng hóa độ cho đến Bồ đề tâm không thối chuyển."],["p","Từ nay trở đi, một mảy thiện tâm nào cũng nhờ thiện lực này mà thành tựu."],["p","Lại nguyện sinh trong loài người, sinh vào nhà từ thiện; lại lập từ bi đạo tràng, cúng dường Tam Bảo, điều thiện nhỏ nhiệm nào cũng đem bố thí hồi hướng cho tất cả chúng sanh. Nguyện cùng với Hòa thượng, A Xà Lê chung lo tu hành, không xa lìa nhau, trường trai khổ hạnh, tâm không ái nhiễm, không lập gia đình, trung tín thanh bạch, nhân nhượng hòa bình, tổn mình lợi người, không cầu danh lợi."],["p","Lại nguyện xin xả thân này, không mong giải thoát, sinh trong loài quỷ thần; nguyện làm vị đại lực Hộ pháp thiện thần, tế khổ thiện thần, không cần cơm áo, tự nhiên đầy đủ."],["p","Lại nguyện xin xả thân này, không mong giải thoát, sinh trong loài súc sanh, thường ở núi sâu hang thẳm ăn cỏ uống nước, không thấy thống khổ, khi ra khỏi rừng thì được an lành, không bị bắt nhốt trói buộc."],["p","Lại nguyện xin xả thân này, không mong giải thoát, sinh trong loài quỷ đói nguyện thân tâm an vui, không có các điều khổ não, giáo hóa những ngạ quỷ đồng khổ, sám hối tội lỗi phát tâm Bồ đề."],["p","Lại nguyện xin xả thân này, không mong giải thoát, sinh vào địa ngục, tự biết đời trước của mình, giáo hóa những người đồng khổ sám hối tội lỗi phát tâm Bồ đề."],["p","Đệ tử chúng con tên... nguyện thường tự nhớ sự phát tâm Bồ đề, làm cho tâm Bồ đề tương tục không gián đoạn."],["p","Nguyện xin hết thảy chư Phật, chư Đại Bồ Tát và hết thảy Thánh Hiền cùng khắp mười phương, rũ lòng từ bi chứng giám cho chúng con."],["p","Lại nguyện cho chư Thiên, chư Tiên, hộ thế tứ vương, chủ thiện phạt ác, thủ hộ trì chú, ngũ phương long vương, long thần bát bộ, chứng giám cho chúng con chí thành đảnh lễ quy y mười phương Tam Bảo."],["h","✵ Tán Thán Phật và Chú Nguyện"],["v",["Đại Thánh Thế Tôn,","Nguy nga rực rỡ.","Tam đạt chiếu suốt,","Vua trong các Thánh.","Phân thân tế vật,","Hiện tọa đạo tràng.","Trời người chiêm ngưỡng,","Thọ pháp vô cùng","Bát âm vang dội","Ma quân kinh hoàng","Oai chấn Đại thiên,","Từ hóa lưu phương.","Bi lực độ khắp,","Thâu nhiếp mười phương,","Từ hẳn tám khổ","Đến Bồ đề hương."]],["p","Cho nên gọi là Như Lai, Ứng Cúng, Chánh Biến Tri, Minh Hạnh Túc, Thiện Thệ, Thế Gian Giải, Vô Thượng Sĩ, Điều Ngự Trượng Phu, Thiên Nhân Sư, Phật, Thế Tôn, độ người vô lượng, hết khổ sinh tử."],["p","Nay chúng con xin nhờ công đức nhân duyên sám hối thanh tịnh và tán thán chư Phật nguyện cho tất cả chúng sanh trong tứ sinh lục đạo, từ nay trở đi cho đến ngày thành Phật đều nhờ thần lực của Phật mà được tùy tâm tự tại."],["v",["Lương Hoàng Bảo Sám,","Vạn đức hồng danh,","Linh văn lục quyển tối hoằng thâm,","Tự tự miễn tai truân,","Đảnh lễ Phật danh,","Tiêu tai bảo an ninh."]],["p","Nam mô Hiện Tiền Địa Bồ Tát Ma Ha Tát. (3 lần)"],["h","Cung Văn"],["p","Như lai vãng tích nhất niệm trung, đại từ bi môn bất khả thuyết, như thị tu hành vô hữu dĩ, cố đắc kiên lao bất hoại thân. Từ bi quảng đại, trí dụng nan lương."],["p","Tăng tấn lục thời, viên minh lục độ."],["p","Ngưỡng duy, Đại Giác, tốc tứ cảm thông."],["p","Thượng lai phụng vì cầu sám đệ tử đẳng... tu sùng Từ Bi Đạo Tràng Sám Pháp, kim đương đệ lục quyển, công khóa viên mãn. Hương phần hải ngạn, chúc bỉnh phong phòng. Bàn liệt thất trân chi diệu cúng. Trà chưng thượng uyển chi tiên xuân. Cúng dường Pháp hội chi Thánh Hiền, Hộ Pháp Giám Đàn chi chủ tể. Tập tư thiện lợi, phổ ích hữu tình."],["p","Phụng vì cầu sám đệ tử đẳng... tẩy địch tích thế chi chướng duyên, tăng trưởng lục thiên chi khoái lạc. Phục nguyện lục căn thanh tịnh như cảo nhật dĩ đương không; lục thức viên minh tợ thu thiềm nhi ánh thủy. Lục xúc lục thọ câu thừa Bát Nhã chi nhân. Lục ái lục trần đẳng nhập viên minh chi quả. Hoạch lục thù thắng ư thử giới tha phương, viên lục độ hạnh ư nhân gian thiên thượng. Tứ sinh cửu hữu đồng đăng giải thoát chi môn."],["p","Lục đạo tam đồ hàm xuất mê luân chi khổ. Tình đương vị bị, quá trọng nan ngôn, tái lao tôn chúng đồng cầu sám hối."],["p","Nam mô Sám Hối Sư Bồ Tát Ma Ha Tát. (3 lần)"],["p","Lương Hoàng Bảo Sám, lục quyển công đức lực, nguyện diệt đệ tử đẳng tội chướng, thân chứng Bồ Tát Hiện Tiền Địa."],["v",["Sám văn cử xứ, tội hoa phi,","Giải liễu oan, sám liễu tội,","Tiêu tai tăng phước thọ,","Thoát khổ sinh Tịnh độ,","Giải liễu oan, sám liễu tội,","Tiêu diêu trực nhập Long Hoa Hội.","Long Hoa tam hội nguyện tương"]],["v",["phùng.","Di Lặc Phật tiền thân thọ ký.","Nam mô Long Hoa Hội Bồ Tát Ma Ha Tát. (3 lần)"]],["v",["Lương Hoàng Bảo Sám","Lục quyển dĩ toàn châu,","Hồi hướng tứ ân tịnh tam hữu,","Bái sám chúng đẳng tăng phước thọ.","Nguyện tương pháp thủy tẩy khiên"]],["v",["vưu, Duy nguyện vong giả vãng Tây Du.","Hiện Tiền Địa Bồ Tát,","Duy nguyện ai nạp thọ.","Nam mô Đăng Vân Lộ Bồ Tát Ma Ha Tát. (3 lần)","Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh..."]]],"p":"Quyển Thứ Sáu"},{"t":"Kiết Thất Bảy Ngày","b":[["p","Năm 1961, tôi thỉnh Lương Hoàng Sám về Huế ấn tống, tại khuôn Phật giáo An lạc, số bảy đường Hồ Xuân Hương, Huế, gia đình đạo hữu Tôn Thất Hàng, cùng các hội hữu trong khuôn thỉnh tôi đến chứng minh khai đàn bái sám. Ở đây cũng như ở chùa Châu Lâm, Huế, các Phật tử cử một Phật tử tụng đọc, các người khác ngồi lắng tai nghe. Đọc đến quyển thứ năm trở đi, các Phật tử khuôn an lạc cảm xúc thế nào tôi không rõ, mà lúc đầu nghe tiếng thút thít rồi khóc òa lên giữa đạo tràng. Sau tôi hỏi thì các hội hữu thưa thiệt là vì quá cảm xúc khi nghĩ đến ơn Phật, ơn cha mẹ. Có người cha mẹ mất sớm tủi cho phận côi cúp của mình, không thể giấu được nỗi u hoài thương tưởng mà phải rơi nước mắt. Cũng có người nghe đọc đến lời cảnh tỉnh vô thường của sám văn, nghĩ đến cuộc đời giả tạm, mạng sống tợ sương mai, không biết mình sẽ về đâu sau khi tắt thở, ngậm ngùi cho những cảnh thê lương khốn khổ trong địa ngục."],["p","Các hội hữu tụng xong bộ Lương Hoàng Sám rồi thì toàn thể gia đình đạo hữu Tôn Thất Hàng nguyện kiết thất một tuần để bái sám một phen nữa."],["p","Dịch giả tự thuật."],["v",["Hiệu Chính: HT. THÍCH TRÍ TỊNH","Dịch Giả: HT. THÍCH VIÊN GIÁC"]]],"p":"Quyển Thứ Sáu"},{"t":"Đầu Quyển Bảy","b":[["p","Thiên trù cúng, Thuần Đà tối hậu lai."],["p","Cơ xan ma mạch sung bì đãi. Tiên nhân hưu hiến trai thực tại. Song song mục nữ hiến hương mai. Tứ thiên vương bổng bát, diêu vọng Linh Sơn bái."],["p","Nam mô Phổ Hiền Vương Bồ Tát Ma Ha Tát. (3 lần)"],["h","Cung Văn"],["p","Thất Phật Thế Tôn tác chứng minh sám ma chi chủ. Thất dụ diệu điển nhập Bồ đề giải thoát chi môn. Phú hữu thất thánh Pháp tài. Cụ túc thất Bồ đề phận."],["p","Chiên đàn lâm dĩ chiên đàn vi nhiễu. Sư tử vương nhi sư tử tần thân. Vô nguyện bất tùng, hữu cầu giai ứng. Ngưỡng Từ vân nhi quảng bố, đồng thủy nguyệt dĩ hàm dung. Khế thủ vu tiền, chứng minh sám pháp."],["p","Thượng lai phụng vì cầu sám đệ tử đẳng... khải kiến từ Bi Đạo Tràng Sám Pháp, tư đương đệ thất quyển, nhập đàn duyên khởi. Đàn tín chuyển gia ân trọng, truy lưu như pháp tu trì. Ngưỡng quán thiết tượng dĩ trang nghiêm. Hoa quả hương đăng giáng liệt. Tinh thành cúng dường, bách bái kiền cung. Nhất tâm cầu sám đệ tử đẳng... đa sinh phụ mẫu, lụy kiếp oan thân, tại thất thú chi trầm luân, cố vô ác nhi bất tạo. Túng thất tình chi vọng tưởng, nãi mị sở nhi bất vi. Khởi thất mạnh chi cao sơn, khi hiền võng Thánh, mê thất lậu chi phiền não, bội giác hiệp trần. Thất tụ tỳ ni nhi thất thủ; thất già nghịch tội dĩ nan đào."],["p","Tưởng tất kinh hoàng, vị kinh sám hối. Kinh sinh khánh hạnh đắc ngộ Phật thừa, phát lộ hướng chư Phật tượng tiền, địch tội ư Đại viên kỉnh lý. Mạng ngã hiện tiền chúng đẳng phi duyệt sám hối linh văn. Duyên khởi hữu nhai, bi tâm vô cực, vọng Phật ai lân, minh huân gia bị."],["p","Sở hữu thập phương thế giới trung, tam thế nhất thiết Nhân Sư Tử, ngã dĩ thanh tịnh thân ngữ ý, nhất thiết biến lễ tận vô dư."],["p","Khải vận Từ Bi Đạo Tràng Sám Pháp, nhất tâm quy mạng Tam thế chư Phật."],["v",["Nam mô Quá Khứ Tỳ Bà Thi Phật.","Nam mô Thi Khí Phật.","Nam mô Tỳ Xá Phù Phật.","Nam mô Câu Lưu Tôn Phật.","Nam mô Câu Na Hàm Mâu Ni Phật.","Nam mô Ca Diếp Phật.","Nam mô Bổn Sư Thích Ca Mâu Ni"]],["v",["Phật.","Nam mô Đương Lai Hạ Sinh Di Lặc"]],["p","Tôn Phật."]],"p":"Quyển Thứ Bảy"},{"t":"Lời Thuật Khuyến của Sám Chủ","b":[["p","Ngày nay, đại chúng đồng nghiệp trong đạo tràng hết lòng lắng nghe:"],["p","Luận rằng: Chỗ chí đức nhiệm mầu trạm tịch, vốn không thể nói; không thể nghĩ bàn. Nhưng phải tạm dùng lời để diễn tả trình bày chỗ chí đức không thể trình bày diễn tả ấy."],["p","Lời nói là con đường tắt, là phương tiện dắt người vào đạo. Lời nói là cấp bậc, là thềm thang tạm mượn để đi đến chỗ chí lý, chí đức ấy. Lời nói là phương tiện của Thánh nhân tạm dùng để giáo hóa chúng sanh."],["p","Sở dĩ vì vậy nên tạm mượn lời nói để tả rõ chân lý. Khi chân lý đã được diễn tả rõ ràng rồi thì chân lý hẳn không phải là lời nói. Nhưng chân lý đã do lời nói mà hiểu rõ được thì lời nói không ra ngoài chân lý."],["p","Tuy lời nói và chân lý hai điều trái nhau nhưng mà ảnh hưởng lẫn nhau, chưa từng sai lầm."],["p","Đối với người sơ cơ hữu học cần phải nhân nơi lời nói để hiểu đạo; đến địa vị vô học, thể nhập chân lý rồi thì lời nói trở nên vô dụng."],["p","Chỉ vì phàm ngu mê muội, nghiệp chướng sâu dày nên đối với mọi việc không thể không dùng lời nói."],["p","Hiện tại trí thức thô thiển, không hiểu thấu được lý nhiệm mầu; kiến giải cạn cợt không thông đạt được lẽ cùng cực."],["p","Nhưng nói thì dễ, làm thật khó. Chỉ có Thánh với Thánh mới được hoàn toàn."],["p","Nay có lời vấn nạn rằng: “Tự mình không chân chính làm sao khiến người chân chính được”. Ba nghiệp của mình uế trược, làm sao khuyên người thanh tịnh được? Tự mình không thanh tịnh, muốn khiến người thanh tịnh thì không có lý."],["p","Tự mình không kiên cố, lấy gì khuyên người kiên cố. Lời nói và việc làm khác nhau càng làm cho người sinh phiền não."],["p","Đã làm cho người sinh phiền não, thì không nói còn hơn. Nghĩ cho kỹ, tự mình há không sinh tâm hổ thẹn sao! Tôi là thiện tri thức nên phát ra lời ấy."],["p","Đến đây thì nên sửa sang y phục, thúc liễm dung nghi, không nên nói một lời gì nữa. Nay tôi là tác giả nghe thiện tri thức nói như trên, lòng tôi rất hổ thẹn; tự biết mình có lỗi nhiều, không dám khinh Thánh nhân mà tự che giấu tội lỗi."],["p","Nay tôi muốn bỏ qua không nói pháp sám này nữa, nhưng sợ có người nhân nghe lời tôi mà thêm phước. Nếu tôi không bỏ qua, cứ giữ ý kiến này lại, thì sợ có người nhân đó mà sinh tội khinh chê hủy báng."],["p","Tấn thối lưỡng nan, tôi không biết làm thế nào nên mới lập ra pháp sám này."],["p","Tâm đã thiện thì đối các thiện pháp đều vô ngại. Đại chúng nên nỗ lực mà sám hối, không nên chấp trước các lời vấn nạn trên kia, mà phải một lòng nhờ đấng Đại Từ Bi phụ che chở nhiếp thọ cho."],["p","Đã có lời như thế thì không thể bỏ qua mà không sám hối; cần phải sinh tâm hổ thẹn."],["p","Nguyện xin đại chúng chớ xúc não nhau. Như lời tôi có chút hợp lý thì cùng nhau nhân đó mà cải ác tùng thiện, làm thiện tri thức với nhau. Nếu lời tôi không hợp ý đại chúng thì xin đại chúng hoan hỷ bố thí, đừng trở lại làm ác tri thức mà nên cùng nhau kết thành Bồ đề quyến thuộc."]],"p":"Quyển Thứ Bảy"},{"t":"Chương Thứ Mười Tự Vui Mừng","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng, từ khi quy y trở lại đây, biết chỗ chí đức là nơi nương tựa của tất cả."],["p","Đoạn nghi, sám hối thì tội ác mê lầm đều tiêu diệt. Tiếp đến phát tâm dìu dắt nhau tu hành thì cởi mở được oán thù, tiêu diêu tự tại."],["p","Như thế thời đại chúng há lại không hớn hở vui mừng hay sao?"],["p","Nay nói ý nghĩa những điều đáng vui mừng sung sướng thì trong kinh chép rằng:"],["p","Có tám nạn khổ: Một là Địa ngục, hai là Ngạ quỷ, ba là Súc sinh, bốn là Biên địa, năm là Trường Thọ Thiên, sáu là tuy được thân người mà câm điếc, ngọng liệu, tàn tật; bảy là sinh vào nhà Tà kiến, tám là sinh trước Phật hay sau Phật."],["p","Vì có tám nạn ấy nên chúng sanh cứ chìm đắm mãi trong biển luân hồi sinh tử, không thể ra được."],["p","Nay chúng con sinh nhằm đời tượng pháp tuy không gặp Phật, nhưng sự vui mừng còn nhiều."],["p","Phàm có nạn là tại tâm, nếu tâm sinh nghi ngờ thì không phải nạn cũng thành nạn."],["p","Nếu tâm không sinh nghi ngờ thì nạn gì cũng thành ra phi nạn."],["p","Vì sao biết được?"],["p","Ví như nạn thứ tám, nói rằng sinh trước Phật hoặc sinh sau Phật là nạn."],["p","Nhưng bà già ở thành Đông, đồng sinh với Phật một thời, đồng ở với Phật một xứ mà bà già ấy không thấy Phật. Cho nên biết rằng tâm nghi ngờ là nạn, vị tất không đồng thời với Phật mà cho là nạn."],["p","Ma Ba Tuần ôm lòng ác độc trong khi còn sống đã đọa vào địa ngục."],["p","Rồng nghe thuyết pháp còn ngộ được đạo Bồ đề. Vậy chắc gì ở nhân gian hay thiên thượng mà liền cho không có nạn. Tâm nếu biết điều thiện thì quả báo bình đẳng."],["p","Cõi trời Lục dục là cao quý mà đọa địa ngục, súc sinh là thấp hèn mà lên được đạo tràng."],["p","Thế nên tâm tà thì khinh nạn thành trọng, tâm chánh thì trọng nạn thành vô ngại."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng vì tâm nghi nên gặp việc không phải nạn thành ra nạn. Nếu tâm chánh thì nạn thành phi nạn."],["p","Nay chỉ cứ ra một điều ấy cũng đủ hiểu rõ; trước Phật hay sau Phật đều là Chánh pháp; biên địa súc sinh đều là đạo tràng."],["p","Nếu tâm chánh thì không còn nạn nữa, bằng tâm còn nghi ngờ thì nạn thành ra vô lượng."],["p","Những điều vui mừng như thế sự thật không phải là ít, trong nhật dụng hằng ngày đại chúng không tự biết công đức của mình. Nay tôi sơ lược trình bày qua sự vui mừng theo thiển kiến của tôi để đại chúng tự suy nghĩ."],["p","Nếu biết được sự vui mừng của mình thì cần phải tu tâm xuất thế."],["p","Tự vui mừng những gì?"],["p","Phật dạy: “Địa ngục khó thoát khỏi”."],["p","Nay chúng ta đã cùng nhau xa lìa được khổ Địa ngục. Đó là sự vui mừng thứ nhất."],["p","- “Ngạ quỷ khó thoát được”. Nay chúng ta đã thoát được những thống khổ đói khát của Ngạ quỷ. Đó là sự vui mừng thứ hai."],["p","- “Súc sinh khó xả bỏ”. Nay chúng ta đã thoát được quả báo súc sinh. Đó là sự vui mừng thứ ba."],["p","- “Sinh ở biên địa, không biết nhân nghĩa”. Nay chúng ta đồng được chung ở giữa quốc độ có Phật, Pháp lưu hành; đích thân thừa hưởng được giáo lý nhiệm mầu của chư Phật. Đó là sự vui mừng thứ tư."],["p","- “Sinh lên cõi trời trường thọ, không biết trồng cội phúc”. Nay chúng ta ở đây đều được trồng căn lành. Đó là sự vui mừng thứ năm."],["p","- “Thân người khó được, một phen mất khó có trở lại”. Nay chúng ta đều được làm người. Đó là sự vui mừng thứ sáu."],["p","- “Sáu căn không đầy đủ thì không trồng được căn lành”. Nay chúng ta đều được thanh tịnh, hướng về pháp môn thâm diệu của Phật. Đó là sự vui mừng thứ bảy."],["p","- “Có Thế trí biện thông tức là không phải nạn mà thành nạn”. Nay chúng ta nhất tâm nương về Chánh pháp. Đó là sự vui mừng thứ tám."],["p","- “Trước Phật sau Phật đều là nạn”, hoặc cho rằng mắt mình không thấy Phật là đại nạn. Nay chúng ta đã cùng nhau phát đại thiện nguyện, thề độ hết thảy chúng sanh cùng tận đời vị lai; không chấp việc không thấy Phật là nạn. Chỉ một phen thấy hình tướng Phật, một phen nghe được Chánh pháp, cũng tự cho đồng như ngày xưa được thấy nghe Đức Phật thuyết pháp đầu tiên tại vườn Lộc Uyển. Việc làm của chúng ta mục đích là diệt được tội, sinh được phước là quý; chứ không phải vì không thấy Phật mà cho là nạn."],["p","- Phật dạy: “Thấy được Phật là khó”."],["p","Nay chúng ta đã cùng nhau chiêm ngưỡng được hình tướng Phật. Đó là sự vui mừng thứ chín."],["p","- Phật dạy: “Nghe được pháp Phật là khó”. Nay chúng ta đã cùng nhau hưởng được Cam lồ pháp vị của Phật. Đó là sự vui mừng thứ mười."],["p","- Phật dạy: “Xuất gia được là khó”."],["p","Nay chúng ta được từ thân cát ái trở về với Đạo. Đó là sự vui mừng thứ mười một."],["p","- Phật dạy: “Lợi cho mình là dễ, lợi cho người là khó”. Nay chúng ta một lạy, một bái đều vì tất cả chúng sanh khắp mười phương mà hồi hướng công đức. Đó là sự vui mừng thứ mười hai."],["p","- Phật dạy: “Chịu khổ, chịu cực được là khó”. Nay chúng ta, mọi người đều kiều cần, siêng năng làm lành không nghỉ, không biếng nhác. Đó là sự vui mừng thứ mười ba."],["p","- Phật dạy: “Đọc tụng kinh điển được là khó”. Nay chúng ta giờ phút này đang đọc tụng kinh điển của Phật. Đó là sự vui mừng thứ mười bốn."],["p","- Phật dạy: “Tọa thiền là khó”. Nay chúng ta có người tức tâm định ý. Đó là sự vui mừng thứ mười lăm."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng thấy có nhiều sự vui mừng như vậy vô lượng vô biên, không phải bấy nhiêu lời đó mà có thể kể hết được."],["p","Phàm người ở đời vui ít khổ nhiều."],["p","Được một điều vui mừng còn hớn hở thay, huống gì nay chúng ta có nhiều điều vui vô ngại."],["p","Được vô ngại này đều nhờ sức oai thần của mười phương Tam Bảo. Chúng ta mọi người đều nên nhớ tưởng ơn đức Phật, Pháp, Tăng. Đại chúng nên tha thiết đầu thành đảnh lễ Tam Bảo, nguyện xin thay thế hết thảy Quốc vương, Đế chúa, Thổ cảnh, nhân dân, cha mẹ, Sư trưởng, thượng, trung, hạ tòa, tín thí đàn việt, thiện ác tri thức, chư Thiên, chư Tiên, hộ thế Tứ vương, thông minh chính trực, Thiên địa, hư không, chủ thiện phạt ác, thủ hộ trì chú, ngũ phương Long vương, Long thần, Bát bộ, chư đại Ma vương, ngũ đế Đại ma, nhất thiết Ma vương, Diêm la vương, Thái sơn Phủ quân, ngũ đạo, Đại thần, Thập bát Ngục vương và các quan thuộc trong địa ngục; rộng ra cho đến vô cùng vô tận các loài hữu tình, có thần thức, có Phật tánh trong ba cõi sáu đường; nguyện vì các chúng sanh ấy mà quy y tận hư không giới hết thảy mười phương Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, đồng gia tâm nhiếp thọ, đồng đem thần lực tự tại bất khả tư nghị mà che chở cứu vớt, làm cho hết thảy chư Thiên, chư Tiên, hết thảy Thần vương, Thần tướng, rộng ra cho đến hết thảy chúng sanh trong sáu đường, từ đây trở đi vượt khỏi biển sinh tử, đến bờ giải thoát bên kia, hạnh nguyện sớm viên mãn, đồng lên Thập địa vào Kim cang tâm, thành bậc Chánh giác."]],"p":"Quyển Thứ Bảy"},{"t":"Chương Thứ Mười Một Tưởng Nhớ Ơn Tam Bảo","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đều nên nhớ tưởng ơn Tam Bảo."],["p","Vì sao vậy?"],["p","Bởi vì, giả sử như không biết Tam Bảo, thì làm sao sinh khởi từ tâm, thương xót chúng sanh. Giả sử không biết Tam Bảo thì làm sao sinh khởi bi tâm, cứu hộ nhiếp thọ hết thảy chúng sanh. Giả sử không biết Tam Bảo, thì làm sao sinh khởi tâm bình đẳng quán sát oán thân như nhau. Giả sử không biết Tam Bảo, thì làm sao có được diệu trí chứng đạo Vô thượng. Giả sử không biết Tam Bảo, thì làm sao hiểu rõ được lý nhị không (Nhân không, Pháp không) là chân không chân thật, vô tướng mà tu hành."],["p","Phật dạy:"],["p","“Thân người khó được, nay đã được, lòng tin khó sinh, nay đã sinh”."],["p","Chúng con ngày nay nhờ quy y Tam Bảo, mắt không thấy sắc lửa phun, cảnh rút lưỡi ở địa ngục, ngạ quỷ; tai không nghe tiếng kêu la nhiệt não, khổ sở ở cảnh địa ngục, ngạ quỷ; mũi không ngửi mùi máu mủ tanh hôi, lột da xẻ thịt ở cảnh địa ngục, ngạ quỷ; lưỡi không nếm mùi hôi thối, hư nát; thân không xúc chạm cảnh giá lạnh, lò than hồng, vạc dầu sôi ở địa ngục; ý thường biết Phật là đấng Cha lành, từ bi vô thượng, là đấng Đại y vương; ý biết tất cả Phật pháp, là thuốc hay để trị bệnh cho tất cả chúng sanh; biết các vị Hiền Thánh là từ mẫu săn sóc bệnh hoạn cho tất cả chúng sanh. Ý thường biết nghĩ tưởng Tam Bảo là ba ngôi báu ủng hộ thế gian; ý thường tưởng nghĩ gì chúng ta đều biết được hết."],["p","Chúng con ngày nay tuy sinh ra không gặp Phật, nhằm đời mạt pháp, nhưng không có đủ tín tâm, sáu căn thanh tịnh, không có suy não, đi lại vừa ý, đứng ngồi tự do, vô ngại. Những quả báo tốt đẹp ấy đều do duyên lành đời trước, nhờ ơn Tam Bảo khiến phát tâm Bồ đề."],["p","Những lợi ích như thế vô lượng vô biên, không thể kể xiết. Vậy chúng con há lại không lo báo ân, cúng dường Tam Bảo hay sao?"],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nên biết rằng: “Cúng dường là công đức lớn hơn hết thảy trong tất cả các công đức”."],["p","Trong kinh Phật dạy: “Nhớ lại đời quá khứ chỉ cúng dường Tam Bảo một mảy may, nhờ phước báo ấy, nay gặp được Phật Thế Tôn”."],["p","Lại nữa, trong kinh cũng chép rằng: “Nếu muốn được quả báo tốt mà xây tháp, lập tịnh xá, cúng dầu đèn, tràng phan, bảo cái, hoa hương, nệm gối và bao nhiêu thứ cúng dường khác v.v... cũng chưa phải là báo ơn Đức Phật”."],["p","Muốn báo ơn Đức Phật, cần phải phát tâm Bồ đề, lập bốn lời thệ nguyện rộng lớn, tạo vô lượng duyên lành, trau giồi thân tâm, tu hạnh Tịnh độ. Ấy là kẻ trí biết báo ơn Đức Phật vậy."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nhận thấy ân đức từ bi vô lượng của Đức Phật không thể báo đáp."],["p","Các vị đại Bồ Tát nghiền thân cúng dường mà còn chưa thể báo ơn Đức Phật muôn một, huống gì chúng con là phàm phu mà có thể báo ơn Đức Phật được sao? Đại chúng chỉ y theo lời Kinh dạy mà làm việc lợi ích cho người là hơn hết. Mọi người nên hết lòng đầu thành đảnh lễ Tam Bảo khắp vì hết thảy chúng sanh, vô cùng, vô tận trong bốn loài sáu đường mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Đức Bảo Phật.","Nam mô Ứng Danh Xưng Phật.","Nam mô Hoa Thân Phật.","Nam mô Đại Âm Thanh Phật.","Nam mô Biện Tài Tán Phật.","Nam mô Kim Cang Châu Phật.","Nam mô Vô Lượng Thọ Phật.","Nam mô Châu Trang Nghiêm Phật.","Nam mô Đại Vương Phật.","Nam mô Đức Cao Hạnh Phật.","Nam mô Cao Danh Phật.","Nam mô Bách Quang Phật.","Nam mô Hỷ Diệt Phật.","Nam mô Long Bộ Phật.","Nam mô Ý Nguyện Phật.","Nam mô Bảo Nguyệt Phật.","Nam mô Diệt Kỷ Phật.","Nam mô Hỷ Vương Phật.","Nam mô Điều Ngự Phật.","Nam mô Hỷ Tự Tại Phật.","Nam mô Bảo Kế Phật.","Nam mô Ly Úy Phật.","Nam mô Bảo Tạng Phật.","Nam mô Nguyệt Diện Phật.","Nam mô Tịnh Danh Phật.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam bảo."]],"p":"Quyển Thứ Bảy"},{"t":"Chương Thứ Mười Hai Chủ Sám Lễ Tạ Đại Chúng","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đã cùng nhau sinh lòng tin kiên cố, phát tâm Bồ đề, thề không thối chuyển. Đó là một chí khí có năng lực mạnh không thể nghĩ bàn. Tâm ấy, chí ấy chư Phật rất ngợi khen."],["p","Ngày nay tác giả tôi cũng hết lòng tùy hỷ và nguyện đời sau sẽ được gặp nhau lại. Xả thân này thọ thân khác nguyện không rời nhau, cho đến ngày thành Phật, hằng làm bà con Phật pháp, quyến thuộc từ bi."],["p","Ngày nay nếu tôi lập ra Pháp Sám này như giả dối; trí không sáng suốt, thân trái với hạnh, khinh suất tỏ bày ý ấy. Thật đáng lo sợ, đối với sự thấy nghe của người."],["p","Sức người hữu hạn mong manh, công việc thì quan trọng rộng lớn, như nước lửa trái nhau, nên tôi rất ngại ngùng. Nếu không nương nhờ một nguyên nhân cường tráng thì không thể có kết quả thắng diệu. Thành thật, tôi biết có sai lầm, nhưng lòng tôi không quên việc thiện. Mong nhờ sức hộ niệm của đại chúng đồng làm từ thân. Ngưỡng xin đại chúng giáng đức xuống đạo tràng."],["p","Thời giờ mau chóng thoạt vậy trôi qua, nếu để duyên nghiệp lôi cuốn thì khó gặp thắng hội."],["p","Vậy tự mình nên phải cố gắng siêng năng khóa lễ, lợi mình lợi người, chớ hiên ngang bài xích, sau không hối hận kịp."],["p","Pháp âm của Phật một phen lọt vào tai, thì công đức phước báo vĩnh kiếp vẫn còn hoài; một niệm thiện tâm, lợi ích cho thân tâm mãi mãi."],["p","Nếu người nào có chí hướng cương quyết thì không có nguyện gì mà không thành tựu viên mãn."],["p","Đại chúng cùng nhau chí tâm đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Oai Đức Tịch Diệt Phật.","Nam mô Thọ Tướng Phật.","Nam mô Đa Thiên Phật.","Nam mô Tu Diệm Ma Phật.","Nam mô Thiên Ái Phật.","Nam mô Bảo Chúng Phật.","Nam mô Bảo Bộ Phật.","Nam mô Sư Tử Phận Phật.","Nam mô Cực Cao Hạnh Phật.","Nam mô Nhân Vương Phật.","Nam mô Thiện Ý Phật.","Nam mô Thế Minh Phật.","Nam mô Bảo Oai Đức Phật.","Nam mô Đức Thừa Phật.","Nam mô Giác Tưởng Phật.","Nam mô Hỷ Trang Nghiêm Phật.","Nam mô Hương Tế Phật.","Nam mô Hương Tượng Phật.","Nam mô Chúng Diệm Phật.","Nam mô Từ Tướng Phật.","Nam mô Diệu Hương Phật.","Nam mô Kiên Khải Phật.","Nam mô Oai Đức Mãnh Phật.","Nam mô Châu Khải Phật.","Nam mô Nhân Hiền Phật.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."]],"p":"Quyển Thứ Bảy"},{"t":"Chương Thứ Mười Ba Tổng Phát Đại Nguyện","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại cùng nhau nhờ công đức nhân duyên sám hối, phát tâm, nguyện cho mười phương tận hư không giới hết thảy Thiên chủ, hết thảy chư Thiên, quyến thuộc của chư Thiên; nguyện cho Tiên chủ, hết thảy chơn Tiên, quyến thuộc của chơn Tiên; nguyện cho Phạm vương, Đế Thích, hộ thế Tứ thiên vương, Thần vương, Thần tướng và quyến thuộc của các vị ấy; nguyện cho các vị thông minh chính trực, thiên địa hư không, chủ thiện phạt ác, thủ hộ trì chú, hết thảy Thần vương, hết thảy Thần tướng và quyến thuộc của các vị ấy; nguyện cho các vị Diệu Hóa Long vương, Đầu Hóa Đề Long vương, Ngũ phương Long vương, Long thần bát bộ, bát bộ Thần vương, bát bộ Thần tướng và quyến thuộc của các vị ấy; nguyện cho A tu la vương, hết thảy Thần vương, hết thảy Thần tướng và quyến thuộc của vị ấy, nguyện cho nhân đạo, hết thảy nhân vương, thần dân, tướng soái và quyến thuộc của các vị ấy; lại nguyện cho mười phương Tỳ kheo, Tỳ kheo ni, Thức xoa ma na, Sa di, Sa di ni và quyến thuộc của các vị ấy; nguyện cho Diêm La vương, Thái Sơn phủ quân, ngũ đạo Đại thần, mười tám ngục vương, hết thảy Thần vương, hết thảy Thần tướng và quyến thuộc của các vị ấy; lại nguyện cho hết thảy chúng sanh trong đường địa ngục, hết thảy chúng sanh trong đường ngạ quỷ, hết thảy chúng sanh trong đường súc sinh và quyến thuộc của mỗi loài ấy; lại nguyện cho hết thảy chúng sanh hoặc lớn, hoặc nhỏ, cùng tận đời vị lai trong mười phương, tận hư không giới và quyến thuộc của các chúng sanh ấy; lại nguyện cho hết thảy chúng sanh đời sau này nếu trái với lời đại nguyện hôm nay, tất cả đều được trở lại trong bể đại nguyện này, mỗi mỗi đều đầy đủ công đức trí huệ."],["p","Những chúng sanh như vậy vô cùng vô tận, ở trong ba cõi hay ngoài ba cõi, nhiếp thuộc vào danh sắc và có Phật tánh thì ngày nay đệ tử tên... mong nhờ sức đại từ đại bi của mười phương tận hư không giới hết thảy chư Phật, mong nhờ bổn thệ nguyện lực, vô lượng vô tận trí huệ lực, vô lượng vô tận công đức lực, vô lượng vô tận tự tại thần thông lực, mong nhờ phù hộ chúng sanh lực, an ủi chúng sanh lực, tận chư Thiên chư Tiên lậu lực; nhiếp hóa nhất thiết thiện thần lực, cứu bạt nhất thiết địa ngục lực, tế độ nhất thiết ngạ quỷ lực, độ thoát nhất thiết súc sinh lực của chư Phật, chư Đại Bồ Tát và hết thảy Thánh Hiền, mong nhờ những năng lực ấy làm cho hết thảy chúng sanh đều được như nguyện."],["p","Ngày nay đệ tử tên... lại mong nhờ năng lực của Từ Bi Đạo tràng, năng lực quy y Tam Bảo, năng lực đoạn nghi sinh tín, năng lực sám hối phát tâm, năng lực giải oan thích kiết, năng lực tự khánh hoan hỷ, năng lực hớn hở chí tâm, năng lực phát nguyện hồi hướng thiện căn, làm cho hết thảy chúng sanh đều được như nguyện."],["p","Ngày nay đệ tử chúng con... lại mong nhờ năng lực đại từ tâm của bảy Đức Phật, năng lực đại bi tâm của mười phương chư Phật, năng lực diệt trừ phiền não của ba mươi lăm Đức Phật, năng lực hàng phục ma quân của năm mươi ba đức Phật, năng lực độ sinh của một trăm bảy mươi Đức Phật, năng lực nhiếp thọ chúng sanh của một ngàn Đức Phật, năng lực che chở chúng sanh của mười hai vị Bồ Tát, năng lực lưu thông Sám pháp của Vô Biên Thân Bồ Tát và của Quán Thế Âm Bồ Tát; nguyện khiến cho tất cả chúng sanh ở trong mười phương, ba cõi, sáu đường, cùng tận đời vị lai, hoặc lớn hoặc nhỏ, hoặc thăng hoặc giáng, nhiếp thuộc vào danh sắc có Phật tánh, sau ngày sám hối này rồi đều được thân như thân chư Phật, chư đại Bồ Tát, thân có trí huệ rộng lớn, không thể nghĩ bàn; thân có vô lượng thần lực tự tại, thân lục độ chánh hướng Bồ đề, thân tứ nhiếp, nhiếp thọ hết thảy chúng sanh, thân đại bi diệt trừ tất cả tội khổ, thân đại từ cho tất cả an vui, thân công đức lợi ích cho tất cả, thân trí huệ thuyết pháp không cùng tận, thân kim cang vật không thể phá hoại, thân thanh tịnh xa lìa sinh tử, thân phương tiện, hiện thần lực tự tại, thân Bồ đề tùy hết thảy thời gian mà hiện ra ba thân Bồ đề."],["p","Nguyện cho tất cả chúng sanh trong tứ sinh lục đạo đều được đầy đủ thân như vậy, thành tựu hoàn toàn thân vô thượng đại trí huệ của chư Phật."],["p","Lại nguyện cho hết thảy chúng sanh trong mười phương từ nay trở đi, sinh ra nơi nào cũng như chư Phật và Bồ Tát đều được miệng có công đức bất khả tư nghị; miệng nói lời nhu nhuyến, làm an vui tất cả chúng sanh; miệng như nước cam lồ, làm mát mẻ hết thảy chúng sanh; miệng không nói lời hư dối, nói lời chân thật, miệng nói lời uyển chuyển đúng như sự thật, dầu trong mộng cũng không có nói lời hư dối; miệng được tôn trọng, Phạm vương, Đế Thích, Tứ thiên vương đều cung kỉnh tôn trọng; miệng nói pháp thậm thâm, giải rõ pháp tánh; miệng nói lời kiên cố, nói pháp bất thối; miệng nói lời ngay thẳng, đầy đủ tài hùng biện; miệng trang nghiêm, hay tùy thời, tùy nghiệp mà thị hiện cùng khắp; miệng của đấng Nhất thiết trí hay tùy theo tất cả chúng sanh đáng độ thoát, thì độ thoát ngay."],["p","Nguyện cho tất cả chúng sanh trong bốn loài, sáu đường đều được khẩu nghiệp hoàn toàn thanh tịnh như chư Phật và Bồ Tát."],["p","Lại nguyện cho tất cả chúng sanh trong mười phương, từ nay trở đi, sinh ra nơi nào đều được như chư Phật và Bồ Tát; có tâm đại sáng suốt, trí huệ không thể nghĩ bàn; tâm thường nhàm chán phiền não, xa lìa phiền não; tâm mãnh lợi, tâm kiên cường, tâm kim cang, tâm bất thối, tâm thanh tịnh, tâm minh liễu, tâm cầu thiện, tâm trang nghiêm, tâm quảng đại, có sức đại trí huệ, nghe được chánh pháp liền tự hiểu rõ; tâm hiền từ đến với người, đoạn trừ oán kết, thường biết sỉ nhục, thường biết hổ thẹn, không chấp nhân ngã, đồng xem nhau như thiện tri thức."],["p","Tâm thấy có người tu bố thí, trì giới, nhẫn nhục, tinh tấn, thiền định, trí huệ đều sinh tâm hoan hỷ; oán thân bình đẳng, tâm không kiêu mạn, không nói việc thiện ác, xấu tốt của người; không tuyên truyền bỉ thử hòa hiệp phân ly của người; lời nói mềm mỏng không ác độc, tán thán công đức của Phật; ưa học kinh điển cao sâu, thương xót che chở chúng sanh như thương mình không khác; thấy người làm phước không phỉ báng; tâm nhân từ hòa hiệp như các Thánh nhân, đồng với Bồ Tát, thành bậc Chánh giác."]],"p":"Quyển Thứ Bảy"},{"t":"Chương Thứ Mười Bốn Lễ Phật Thế các Cõi Trời","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng biết rằng chư Thiên, chư Tiên, hết thảy Thiện thần đối với chúng sanh có vô lượng ơn đức, không thể nghĩ bàn; các ngài muốn cho chúng sanh an vui mãi mãi, thương xót chúng sanh, ân cần, phù hộ, chỉ biết làm lành cho chúng sanh mà thôi."],["p","Vì sao mà biết?"],["p","Vì theo sắc lệnh của Phật, thì Phật dạy các vị: Đề Đầu Lại Tra Tứ Thiên Vương nên có từ tâm ủng hộ người trì kinh, khiến người nghe danh hiệu Đấng Từ Bi, như quần thần hộ Thiên tử vậy."],["p","- Lại sắc Hải Long Y Bạt La nên có từ tâm ủng hộ người trì kinh như giữ tròng mắt, thương con đỏ, ngày đêm sáu thời không xa lìa."],["p","- Lại sắc Diêm Bà La Sát Tử vô số độc long và long nữ nên có từ tâm ủng hộ người trì kinh, như quý đầu não không dám động chạm."],["p","- Lại sắc Tỳ Lưu Lặc Ca Vương nên có từ tâm ủng hộ người trì kinh, như mẹ hiền thương con lòng không chán, ngày đêm ủng hộ, đứng ngồi như nhau."],["p","- Lại sắc Nan Đà, Bạt Nan Đà, Ta Già La Vương, Ưu Ba Đà, nên có từ tâm ủng hộ người trì kinh, cung kính cúng dường, đảnh lễ sát đất; cũng như chư Thiên thờ Đế Thích; cũng như con thảo thờ cha mẹ."],["p","Đạo tràng Từ Bi thí an vui, dạy chúng sanh thân cận Phật pháp, đời sau ở trước Phật nhập Tam muội quyết định được pháp bất thối chuyển. Nếu nghe được danh hiệu Đức Phật và của các ngài Vô Biên và Quán Thế Âm thì ba chướng đều tiêu trừ, ác nghiệp cũng hết, ngũ nhãn đầy đủ, chứng quả Bồ đề. Các Thiên vương, Thần vương thương tất cả và thường hay ủng hộ, giúp oai thần."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng, biết chư Thiên, Thần Vương có ơn đức che chở như vậy mà chúng sanh chưa từng phát tâm nhớ tưởng báo đáp ơn đức ấy."],["p","Cổ nhân còn có thể xả thân chỉ vì nhớ ơn của một bữa cơm no lòng. Huống gì chư Thiên, chư Thần, bát bộ Thần vương, bát bộ Thần tướng đối với chúng sanh có ơn đức thế ấy! Công đức ơn huệ này rộng lớn vô cùng, không bờ bến."],["p","Chúng con ngày nay sám hối phát tâm v.v... đều nhớ ơn các vị Thiên vương ấy thầm gia hộ thần lực giúp đỡ cho kẻ tu hành, khiến thiện tâm được thành tựu."],["p","Nếu các ngài không hộ trợ thì những thiện tâm ấy đã thối chuyển sớm mất rồi."],["p","Bởi thế nên các vị đại Bồ Tát Ma ha tát thường tán thán thiện tri thức là nhân duyên rất lớn, hay khiến chúng con thẳng đến đạo tràng. Nếu không có thiện tri thức chúng con làm sao thấy được chư Phật, vậy nên dù tan xương nát thịt cũng không thể báo đáp lòng từ rộng lớn ấy; cũng không thể báo đáp thâm ơn cao cả ấy."],["p","Các vị đại Bồ Tát Ma ha tát còn tỏ lời cám ơn như vậy, huống gì những hạng dưới hàng Bồ Tát, thấp kém hơn mà không biết lo báo ơn sao? Chúng con cùng nhau hết sức vận tâm tri ân báo ân, không thể bỏ qua sau ăn năn không kịp."],["p","Như trong phần tự vui mừng ở đoạn trước đã nói rằng: Được tái ngộ trùng phùng là khó, khó được kết quả như ngày nay, còn muốn đợi gì nữa mà không lo báo ơn."],["p","Như hội sám hối này mất rồi thì biết hội nào gặp lại."],["p","Vậy nên dõng mãnh hy sinh vì người; sự thành có bại, xuân qua đông về, thời gian biến chuyển, không chờ đợi một ai. Nhân mạng vô thường, chỉ sống trong hơi thở đâu có lâu dài! Nghĩ lại, một phen này xa nhau, biết bao giờ gặp lại."],["p","Mọi người nên tự nỗ lực, nhất tâm tha thiết năm vóc sát đất, đầu thành đảnh lễ, nguyện xin thay thế hết thảy Thiên chủ, hết thảy chư Tiên, và quyến thuộc của các vị ấy khắp mười phương, tận hư không giới mà quy y kính lễ Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Thiện Thệ Nguyệt Phật.","Nam mô Phạm Tự Tại Vương Phật.","Nam mô Sư Tử Nguyệt Phật.","Nam mô Phước Oai Đức Phật.","Nam mô Chánh Chủ Phật.","Nam mô Vô Thắng Phật.","Nam mô Nhật Quang Phật.","Nam mô Bảo Danh Phật.","Nam mô Đại Tinh Tấn Phật.","Nam mô Sơn Quang Vương Phật.","Nam mô Thí Minh Phật.","Nam mô Điện Đức Phật.","Nam mô Đức Tụ Vương Phật.","Nam mô Cúng Dường Danh Phật.","Nam mô Pháp Tán Phật.","Nam mô Bảo Ngữ Phật.","Nam mô Cứu Mạng Phật.","Nam mô Thiện Giới Phật.","Nam mô Thiện Chúng Phật.","Nam mô Định Ý Phật.","Nam mô Hỷ Thắng Vương Phật.","Nam mô Sư Tử Quang Phật.","Nam mô Phá Hữu Ám Phật.","Nam mô Chiếu Minh Phật.","Nam mô Thượng Danh Phật.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, đồng gia tâm nhiếp thọ; nguyện cho mười phương tận hư không giới hết thảy Thiên chủ, hết thảy chư Tiên và quyến thuộc của các vị ấy, hiện tiền thường được không huệ bình đẳng, được sức trí huệ phương tiện khai thác vô lậu đạo; hạnh nguyện thập địa đều được ngày càng sáng tỏ; tâm tu lục độ, tứ đẳng, thực hành Bồ Tát đạo, vào Phật hành xứ do tứ hoằng thệ nguyện, không bỏ chúng sanh, biện tài vô ngại, lạc thuyết vô cùng quyền xảo hóa độ, lợi ích chúng sanh, đồng lên Pháp vân, chứng quả thường trú."]],"p":"Quyển Thứ Bảy"},{"t":"Chương Thứ Mười Lăm Lễ Phật Thế các Vị Tiên","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đều nên chí tâm một lòng tha thiết đầu thành đảnh lễ Tam Bảo, nguyện vì hết thảy Tiên chủ, hết thảy Chơn Tiên và quyến thuộc của Tiên, cùng khắp mười phương tận hư không giới mà quy mạng đảnh lễ Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Lợi Huệ Vương Phật","Nam mô Châu Nguyệt Quang Phật.","Nam mô Oai Quang Vương Phật","Nam mô Bất Phá Luận Phật.","Nam mô Quang Minh Vương Phật.","Nam mô Châu Luân Phật.","Nam mô Thế Sư Phật.","Nam mô Các Thủ Phật.","Nam mô Thiện Nguyệt Phật.","Nam mô Bảo Diệm Phật.","Nam mô La Hầu Thủ Phật.","Nam mô Lạc Bồ Đề Phật.","Nam mô Đẳng Quang Phật.","Nam mô Chí Tịch Diệt Phật.","Nam mô Thế Tối Diệu Phật.","Nam mô Vô Ưu Phật.","Nam mô Thập Thế Lực Phật.","Nam mô Hỷ Lực Vương Phật.","Nam mô Đức Thế Phật.","Nam mô Đại Thế Lực Phật.","Nam mô Công Đức Tạng Phật.","Nam mô Chơn Hạnh Phật.","Nam mô Thượng An Phật.","Nam mô Đề Sa Phật.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy, mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, đồng gia tâm nhiếp thọ, nguyện cho các Tiên chủ, hết thảy Chơn Tiên và quyến thuộc của Tiên đều được giải thoát, khách trần phiền não đều được thanh tịnh, hết các duyên chướng ngại, đều được diệu sắc trạm nhiên như thân tướng của Phật; tứ vô lượng tâm, lục Ba la mật thường được hiện tiền, tứ vô ngại trí, lục thần thông lực, đều được tự tại như ý; ra vào, dạo chơi cảnh giới Bồ Tát, lên Pháp vân địa, vào Kim cang tâm; dùng sức thần thông bất khả tư nghị, trở lại độ thoát hết thảy sáu đường chúng sanh."]],"p":"Quyển Thứ Bảy"},{"t":"Chương Thứ Mười Sáu Lễ Phật Thế các Vị Trời Phạm Vương, Đế Thích V.v...","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại chí thành đảnh lễ Tam Bảo, nguyện vì các vị trời Phạm vương, trời Đế Thích, Hộ thế Tứ Thiên vương và quyến thuộc của các vị trời ấy mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Đại Quang Phật.","Nam mô Điện Minh Phật.","Nam mô Quảng Đức Phật.","Nam mô Trân Bảo Phật.","Nam mô Phước Đức Minh Phật.","Nam mô Tạo Khải Phật.","Nam mô Thành Thủ Phật.","Nam mô Thiện Hoa Phật.","Nam mô Tập Bảo Phật.","Nam mô Đại Hải Phật.","Nam mô Trì Địa Phật.","Nam mô Nghĩa Ý Phật.","Nam mô Thiện Tư Duy Phật.","Nam mô Đức Luân Phật.","Nam mô Bảo Quang Phật.","Nam mô Lợi Ích Phật.","Nam mô Thế Nguyệt Phật.","Nam mô Mỹ Âm Phật.","Nam mô Phạm Tướng Phật.","Nam mô Chúng Sư Thủ Phật.","Nam mô Sư Tử Hạnh Phật.","Nam mô Nan Thí Phật.","Nam mô Ứng Cúng Phật.","Nam mô Minh Oai Đức Phật.","Nam mô Đại Quang Vương Phật.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo dũ lòng từ bi, đồng gia tâm nhiếp thọ, nguyện cho các vị Trời Phạm vương, Đế Thích, Hộ thế tứ Thiên vương và quyến thuộc của các vị ấy được các pháp lục độ, tứ đẳng, ngày càng sáng tỏ, tứ vô ngại biện lạc thuyết vô cùng, được bát tự tại, đủ lục thần thông tam muội và tổng trì móng tâm liền có, từ bi bủa khắp, bách phước trang nghiêm, vạn thiện viên mãn, tam đạt sáng suốt, ngũ nhãn hoàn toàn, làm Chuyển luân pháp vương nhiếp hóa lục đạo chúng sinh."],["v",["Lương Hoàng Bảo Sám,","Vạn đức hồng danh,","Linh văn thất quyển tối hoằng thâm, Tự tự miễn tai truân,","Đảnh lễ Phật danh,","Tiêu tai bảo an ninh.","Nam mô Viễn Hành Địa Bồ Tát Ma Ha","Tát. (3 lần)"]],["h","Cung Văn"],["p","Thất Phật từ nhân quy y giả, bất đọa thập bát chi địa ngục. Thất tụ tịnh giới thọ trì giả, cánh sinh Hóa lạc chi thiên cung. Duy nguyện Từ Bi chứng minh đơn khổn."],["p","Cứu thất thú chi dị loại, tọa thất bảo chi hoa đài, nguyện thùy vô cực chi đại bi, giám sát hữu tình chi vi ý."],["p","Thượng lai phụng vì cầu sám đệ tử đẳng... tu sùng Từ Bi Đạo Tràng Sám Pháp, kim đương đệ thất quyển, công khóa viên mãn, ngã chư chúng đẳng, nhập sám, xuất sám, niệm tự tại tư. Đăng nhiên huệ cự, cúng liệt Thần Đà. Kim lô đằng khác khác chi tường vân, ngọc chúc thổ hoàng hoàng chi thoại khí. Chung khánh hưởng kiên kiên chi pháp vận. Hoa quả trần phẩm phẩm chi gia trân. Cung hiến tần phiền hoa trình táo bặc, cúng dường nguy nguy chi Thiện Thệ, tuyên dương cú cú chi già đà. Xướng lạc lạc chi huyền âm, tán hùng hùng chi Thánh đức."],["p","Nhập mặc mặc chi thiền quán, tập chủng chủng chi thù huân. Tiên thân hồi hướng Phật Bồ Đề, Thập Thánh, Tam Hiền đồng chứng giám. Nhiên hậu phổ huân châu sa giới, tứ sinh lục đạo tận triêm ân."],["p","Xuất sinh công đức, phụng vì cầu sám đệ tử đẳng... tịnh chư nghiệp chướng, hoạch đại cát tường. Phục nguyện thất lậu tận nhi thất giác viên minh, tánh thiên lãng diệu. Thất giới tịnh nhi thất già thanh tịnh. Khổ hải ba trừng, tồi thất mạn chi cao sơn; liễu thất tình chi vọng tưởng, hoạch thất tài chi pháp tạng. Độ thất thú chi hữu tình. Hóa kiếm thọ vi thất bảo chi hương lâm. Biến nghiệp cấu, tác thất trân chi Thánh địa. Dư nghiệp quả dĩ nan đào, khuất chúng từ nhi sám hối."],["p","Nam mô Sám Hối Sư Bồ Tát Ma Ha Tát. (3 lần)"],["p","Lương Hoàng Bảo Sám, thất quyển công đức lực, nguyện diệt đệ tử đẳng... thất mạn tội sơn, thân chứng Bồ Tát Viễn Hành Địa."],["v",["Sám văn cử sứ, tội hoa phi.","Giải liễu oan, sám liễu tội,","Tiêu tai tăng phước thọ,","Thoát khổ sinh Đao Lợi.","Giải liễu oan, sám liễu tội.","Tiêu diêu trực nhập Long Hoa Hội.","Long Hoa tam hội nguyện tương"]],["v",["phùng.","Di Lặc Phật tiền thân thọ ký.","Nam mô Long Hoa Hội Bồ Tát Ma Ha Tát. (3 lần)"]],["v",["Lương Hoàng Bảo Sám,","Thất quyển dĩ toàn châu,","Hồi hướng tứ ân tịnh tam hữu,","Bái sám chúng đẳng... tăng phước"]],["v",["thọ.","Nguyện tương pháp thủy tẩy khiên"]],["v",["vưu.","Duy nguyện vong giả vãng Tây du.","Viễn Hành Địa Bồ Tát","Duy nguyện ai nạp thọ.","Nam mô Đăng Vân Lộ Bồ Tát Ma Ha Tát. (3 lần)"]],["p","Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh..."],["v",["Hiệu Chính: HT. THÍCH TRÍ TỊNH","Dịch Giả: HT. THÍCH VIÊN GIÁC"]]],"p":"Quyển Thứ Bảy"},{"t":"Đầu Quyển Tám","b":[["p","Thế gian bảo, lịch đại cổ kim truyền."],["p","San hô, hổ phách kim ngân tuyến, xa cừ, mã não, liên châu quán. Cấp Cô trưởng giả xả Kỳ Viên. Kim luân vương thuyết pháp, vĩnh trấn Long cung tạng."],["p","Nam mô Phổ Hiền Vương Bồ Tát Ma Ha Tát. (3 lần)"],["h","Cung Văn"],["p","Như Lai hiện bát tướng chi thành Đạo, như bảo nguyệt huyền ư thái hư. Thị bát chủng chi hóa nghi, tợ pháp võ triêm ư sa giới. Tứ sinh thất thú tận sinh thiên, bát bộ Long thần hàm cung kỉnh. Bát vạn Đại sĩ tất trợ tuyên dương. Bát đại Bồ Tát giai hằng ủng hộ. Bát thời đắc bát cát tường. Bát giải cụ bát công đức. Thần cơ diệu dụng phổ ứng quần tình. Duy nguyện thùy từ chứng minh Phật sự."],["p","Thượng lai phụng vì cầu sám đệ tử đẳng... tu sùng Từ Bi Đạo Tràng Sám Pháp, kim đương đệ bát quyển, nhập đàn duyên khởi, như pháp huân tu, chuyển gia tinh tấn lô phần giới hương, giải thoát hương. Chúng tán kim hoa, ngân hoa, mạn thù hoa. Đăng nhiên lục thọ, quả hiến kim bàn. Đầu thành bách bái ư kim dung. Khẩn thiết nhất tâm ư bảo tướng."],["p","Trần lộ đa sinh tội cấu, tiêu trừ lụy thế chi khiên vưu."],["p","Thiết niệm cầu sám đệ tử đẳng... tự tùng hữu thức dĩ chí kim sinh, bội bát chánh nhi hướng bát tà. Dẫn khởi tam thiên hình thích. Tuần bát tham nhi mê bát giải, hoành sinh biên giới không hoa."],["p","Vị bát thức chi sở duyên, tùy bát phong chi sở chuyển. Tà bát cấu chi dị nhiễm, khủng bát nạn chi nan đào. Kim tắc hối quá vô môn, muộn tâm hữu quý, tu phiến thiện ư nhất thừa giáo nội, bảo thốn thành ư chư Phật tượng tiền. Nhưng phát lộ như tội khiên, nãi phi thành nhi hối quá. Ứng niệm như tư, tình đương hiệp thích. Cung khấu Hồng Từ minh huân gia bị."],["p","Sát trần tâm niệm khả số tri. Đại hải trung thủy khả ẩm tận. Hư không khả lượng, phong khả kế, vô năng thuyết Phật tận công đức."],["p","Khải vận Từ Bi Đạo Tràng Sám Pháp, nhất tâm quy mạng tam thế chư Phật:"],["v",["Nam mô Quá Khứ Tỳ Bà Thi Phật.","Nam mô Thi Khí Phật.","Nam mô Tỳ Xá Phù Phật.","Nam mô Câu Lưu Tôn Phật.","Nam mô Câu Na Hàm Mâu Ni Phật.","Nam mô Ca Diếp Phật.","Nam mô Bổn Sư Thích Ca Mâu Ni"]],["v",["Phật.","Nam mô Đương Lai Hạ Sinh Di Lặc"]],["p","Tôn Phật."]],"p":"Quyển Thứ Tám"},{"t":"Chương Thứ Mười Bảy Lễ Phật Thế A Tu La và Hết Thảy Thiện Thần","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại chí thành đảnh lễ Tam Bảo, năm vóc sát đất, nguyện xin thay thế hết thảy A tu la vương, hết thảy A tu la và quyến thuộc của A tu la, khắp mười phương tận hư không giới, lại nguyện vì hết thảy các vị thông minh, chánh trực, thiên địa hư không, chủ thiện, phạt ác, thủ hộ trì chú, bát bộ thần vương, bát bộ thần tướng, rộng ra cho đến, hoặc trong hoặc ngoài, hoặc xa hoặc gần, đông tây nam bắc, tứ duy thượng hạ, cùng khắp pháp giới, các vị có sức đại thần thông, có sức đại oai đức như vậy, chúng con nguyện thay thế cho tất cả các vị ấy mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Bảo Danh Phật.","Nam mô Chúng Thanh Tịnh Phật.","Nam mô Vô Biên Danh Phật.","Nam mô Bất Hư Quang Phật.","Nam mô Thánh Thiên Phật.","Nam mô Trí Vương Phật.","Nam mô Kim Cang Chúng Phật.","Nam mô Thiện Chướng Phật.","Nam mô Kiến Từ Phật.","Nam mô Hoa Quốc Phật.","Nam mô Pháp Ý Phật.","Nam mô Phong Hành Phật.","Nam mô Thiện Tư Danh Phật.","Nam mô Đa Minh Phật.","Nam mô Mật Chúng Phật.","Nam mô Công Đức Thủ Phật.","Nam mô Lợi Ý Phật.","Nam mô Vô Cụ Phật.","Nam mô Kiên Quán Phật.","Nam mô Trú Pháp Phật.","Nam mô Châu Túc Phật.","Nam mô Giải Thoát Đức Phật.","Nam mô Diệu Thân Phật.","Nam mô Thiện Ý Phật.","Nam mô Phổ Đức Phật.","Nam mô Quang Vương Phật.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, đồng gia tâm ủng hộ che chở, nguyện A tu la vương, hết thảy A tu la và quyến thuộc của A tu la. Lại xin nguyện cho các vị thông minh chính trực, thiên địa hư không, chủ thiện phạt ác, thủ hộ trì chú, bát bộ Thần vương, bát bộ Thần tướng và quyến thuộc của các vị ấy, thoát được khách trần phiền não, thanh tịnh được các chướng duyên, phát tâm Đại thừa, tu đạo vô ngại, tứ vô lượng tâm, lục ba la mật thường được hiện tiền, tứ vô ngại biện, sáu sức thần thông đều được như ý muốn, hằng đem từ bi cứu độ chúng sanh, tu đạo Bồ Tát, vào trí huệ Phật, chứng tâm Kim cang thành bậc Chánh giác."]],"p":"Quyển Thứ Tám"},{"t":"Chương Thứ Mười Tám Lễ Phật Thế các Long Vương","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại chí thành đảnh lễ, năm vóc sát đất, nguyện vì mười phương tận hư không giới hết thảy Long Vương nhiều không thể nghĩ bàn: Diệu Hóa Long Vương, Đầu Hóa Đề Long Vương, Ngũ Phương Long Vương, Thiên Long Vương, Địa Long Vương, Sơn Long Vương, Hải Long Vương, Nhật Cung Long Vương, Nguyệt Cung Long Vương, Tinh Cung Long Vương, Tuế Thời Long Vương, Thanh Hải Long Vương, Hộ Hình Mạng Long Vương, Hộ Chúng Sinh Long Vương."],["p","Rộng ra cho đến mười phương Long vương, hoăc̣ xa hoặc gần, hoăc̣ trong hoăc̣ ngoài, đông tây nam bắc, tứ duy thượng hạ, cùng hư không, tận pháp giới, có sức đại thần thông, có sức đại oai đức, nguyện vì tất cả những Long vương, tất cả những Long thần như vậy và quyến thuộc của các vị ấy mà quy y kỉnh lễ hết thảy Thế gian đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Diệu Trí Phật.","Nam mô Phạm Tài Phật.","Nam mô Thật Âm Phật.","Nam mô Chánh Trí Phật.","Nam mô Lực Đắc Phật.","Nam mô Sư Tử Ý Phật.","Nam mô Hoa Tướng Phật.","Nam mô Trí Tích Phật.","Nam mô Hoa Xỉ Phật.","Nam mô Công Đức Tạng Phật.","Nam mô Danh Bảo Phật.","Nam mô Hy Hữu Danh Phật.","Nam mô Thượng Giới Phật.","Nam mô Vô Úy Phật.","Nam mô Nhật Minh Phật.","Nam mô Phạm Thọ Phật.","Nam mô Nhất Thiết Thiên Phật.","Nam mô Nhạo Trí Phật.","Nam mô Bảo Thiên Phật.","Nam mô Châu Tạng Phật.","Nam mô Đức Lưu Bố Phật.","Nam mô Trí Vương Phật.","Nam mô Vô Phược Phật.","Nam mô Kiên Pháp Phật.","Nam mô Thiên Đức Phật.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, đồng gia tâm nhiếp thọ, nguyện cho các Long Vương và quyến thuộc của Long vương, hào quang ngày càng thêm sáng, thần lực tự tại, dùng vô ngại giải đoạn trừ chướng duyên, hằng xa lìa ác thú, thường được sinh về Tịnh Độ; tứ vô lượng tâm, lục ba la mật thường được hiện tiền, tứ vô ngại trí, lục thần thông lực, tùy tâm tự tại, đem tâm từ bi, tiếp độ chúng sanh, diệu hạnh trang nghiêm vào Pháp vân địa, nhập Kim Cang tâm, thành bậc Chánh giác."]],"p":"Quyển Thứ Tám"},{"t":"Chương Thứ Mười Chín Lễ Phật Thế Ma Vương","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại chí thành đảnh lễ, năm vóc sát đất, nguyện vì đại ma vương, ngũ đế đại ma, cho đến đông tây nam bắc, tứ duy thượng hạ, tận hư không giới, hết thảy ma vương và bà con của ma mà quy y kính lễ... Nhất thiết Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Phạm Mâu Ni Phật.","Nam mô An Tường Hạnh Phật.","Nam mô Cần Tinh Tấn Phật.","Nam mô Diệm Kiên Phật.","Nam mô Đại Oai Đức Phật.","Nam mô Chiêm Bặc Hoa Phật.","Nam mô Hoan Hỷ Phật.","Nam mô Thiện Chúng Phật.","Nam mô Đế Tràng Phật.","Nam mô Đại Ái Phật.","Nam mô Tu Mạn Sắc Phật.","Nam mô Chúng Diệu Phật.","Nam mô Khả Lạc Phật.","Nam mô Thiện Định Nghĩa Phật.","Nam mô Ngưu Vương Phật.","Nam mô Diệu Tý Phật.","Nam mô Đại Xa Phật.","Nam mô Mãn Nguyện Phật.","Nam mô Đức Quang Phật.","Nam mô Bảo Âm Phật.","Nam mô Kim Cang Quân Phật.","Nam mô Phú Quý Phật.","Nam mô Thế Lực Hạnh Phật.","Nam mô Sư Tử Lực Phật.","Nam mô Tịnh Mục Phật.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo. Nguyện xin Tam Bảo rũ lòng từ bi, đồng gia tâm che chở, nguyện cho đại ma vương, ngũ đế đại ma, hết thảy ma vương và quyến thuộc của ma, từ vô thỉ trở lại cho đến ngày nay, bao nhiêu chướng duyên thảy đều thanh tịnh, bao nhiêu tội nghiệp thảy đều tiêu trừ, tất cả khổ não đều được giải thoát, bốn vô lượng tâm, sáu ba la mật thường được hiện tiền, bốn vô ngại trí, sáu sức thần thông, như ý tự tại, tu đạo Bồ Tát không thôi không nghỉ, trước độ chúng sanh sau thành Phật đạo."]],"p":"Quyển Thứ Tám"},{"t":"Chương Thứ Hai Mươi Lễ Phật Thế cho Nhân Đạo Quốc Vương V.v...","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đã cùng nhau nguyện vì chư Thiên, chư Tiên, Long thần bát bộ mà lễ Phật rồi."],["p","Nay đây nguyện vì nhân đạo, hết thảy nhân vương, lễ Phật mà báo ơn nhân loại."],["p","Lại nguyện cha mẹ, Sư trưởng và hết thảy nhân dân mà lễ Phật. Vì sao vậy?"],["p","Vì nếu không có quốc chủ thì hết thảy chúng sanh không biết nương nhờ vào đâu. Nhờ có quốc chủ nên tất cả mọi người đều an cư lạc nghiệp, đi lại trên đất quốc chủ, sống trên đất quốc chủ, và được nhiều lợi ích khác không kể xiết; cho nên đại chúng phải có lòng biết ơn và báo ơn."],["p","Kinh dạy rằng:"],["p","“Nếu người nào, ngày đêm sáu thời hay chịu khổ, vì muốn lợi ích nên nguyện báo ơn, thì phải phát tâm nghĩ như thế ấy để tu tập hạnh từ bi”."],["p","Do nguyện lực ấy, nên nghĩ báo ơn che chở của quốc chủ, nghĩ báo ơn cung cấp của thí chủ, nghĩ báo ơn sinh thành của cha mẹ, nghĩ báo ơn dạy bảo của Sư trưởng, nghĩ báo ơn tế độ của chư Phật."],["p","Nếu người nào hay chí tâm thường niệm tưởng như vậy, người ấy nhập đạo rất mau."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nhận thấy ơn lành của chư Phật Đại thánh khai hóa dạy dỗ chúng ta, ân cần như thế, khiến chúng ta phải biết báo ơn."],["p","Ngày nay chúng ta sinh vào đời mạt pháp, mong nhờ ơn quốc chủ mà hưng hiển được Phật pháp; nhờ quốc chủ cúng dường đầy đủ, không tiếc của báu, làm cho khắp cả nhân dân đều noi gương quốc chủ và sinh tâm quy kỉnh Phật Pháp Tăng."],["p","Lại nữa, người xuất gia được an thân hành đạo, đi đứng nằm ngồi được tự do, không bị trở ngại; quốc chủ không cho người xuất gia tham dự việc đời, chỉ lo khuyên người làm lành, nguyện cho chúng sinh mau thoát khỏi sanh tử khổ đau, chỉ lo xiển dương vô lượng Pháp môn, chỉ bày đường chơn nẻo chánh cho trời và người. Nhờ ơn quốc chủ nhiều như vậy thì chúng ta đâu được không hết lòng lễ Phật để báo ơn quốc chủ, phải cùng nhau chí thành đảnh lễ nguyện vì quốc chủ mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Ca Diếp Phật.","Nam mô Tịnh Ý Phật.","Nam mô Tri Thức Đệ Phật.","Nam mô Mãnh Oai Đức Phật.","Nam mô Đại Quang Minh Phật.","Nam mô Nhật Quang Diệu Phật.","Nam mô Tịnh Tạng Phật.","Nam mô Phân Biệt Oai Phật.","Nam mô Vô Tổn Phật.","Nam mô Mật Nhật Phật.","Nam mô Nguyệt Quang Phật.","Nam mô Trì Minh Phật.","Nam mô Thiện Tịch Hạnh Phật.","Nam mô Bất Động Phật.","Nam mô Đại Thỉnh Phật.","Nam mô Đức Pháp Phật.","Nam mô Trang Nghiêm Vương Phật.","Nam mô Cao Xuất Phật.","Nam mô Diệm Xí Phật.","Nam mô Hoa Đức Phật.","Nam mô Bảo Nghiêm Phật.","Nam mô Thượng Thiện Phật.","Nam mô Bảo Thượng Phật.","Nam mô Lợi Huệ Phật.","Nam mô Nghiêm Độ Phật.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, gia tâm nhiếp thọ, nguyện cho quốc chủ hiện tại thân thể khang kiện, oai đức vang lừng, sự nghiệp vĩnh viễn, huệ mạng vô cùng, từ tâm vô tận, hữu tình quy tâm, Bồ Tát thạnh hóa, trời người ngợi khen, ngưỡng mộ. Tứ đẳng lục độ, ngày càng thêm sáng, tứ vô ngại biện lạc thuyết vô cùng; được tâm tự tại, đủ sáu thần thông, tam muội tổng trì, móng tâm liền có, từ bi thương đời, ân khắp lục đạo, vạn hạnh sớm viên, Phật đạo chóng thành."]],"p":"Quyển Thứ Tám"},{"t":"Chương Thứ Hai Mươi Mốt Lễ Phật Thế Quyến Thuộc của Quốc Chủ","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại đầu thành đảnh lễ Tam Bảo, nguyện vì quyến thuộc của quốc chủ và bá quan cùng quyến thuộc của bá quan mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Hải Đức Phật.","Nam mô Phạm Tướng Phật.","Nam mô Nguyệt Cái Phật.","Nam mô Đa Diệm Phật.","Nam mô Vi Lam Vương Phật.","Nam mô Trí Xưng Phật.","Nam mô Giác Tưởng Phật.","Nam mô Công Đức Quang Phật.","Nam mô Thanh Lưu Bố Phật.","Nam mô Mãn Nguyện Phật.","Nam mô Hoa Quang Phật.","Nam mô Thiện Giới Phật.","Nam mô Đăng Vương Phật.","Nam mô Điện Quang Phật.","Nam mô Quang Vương Phật.","Nam mô Quang Minh Phật.","Nam mô Cụ Túc Tán Phật.","Nam mô Hoa Tạng Phật.","Nam mô Phất Sa Phật.","Nam mô Thân Đoan Nghiêm Phật.","Nam mô Tịnh Nghĩa Phật.","Nam mô Oai Mãnh Quân Phật.","Nam mô Phước Oai Đức Phật.","Nam mô Lực Hành Phật.","Nam mô La Hầu Thiện Phật.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, đồng gia tâm phù hộ, nguyện cho quyến thuộc của quốc chủ, bá quan và quyến thuộc của các vị ấy thân tâm an lạc, sống lâu vô cùng, tu đạo Đại thừa, vào trí huệ Phật; giữ bốn hoằng thệ, không xả bỏ chúng sinh, tứ vô lượng tâm, lục ba la mật, thường được hiện tiền; lục thông tam đạt, thấu rõ căn tánh, đủ nhị trang nghiêm, thần lực tự tại; từ tâm như Phật nhiếp hóa chúng sanh."]],"p":"Quyển Thứ Tám"},{"t":"Chương Thứ Hai Mươi Hai Lễ Phật Thế Cha Mẹ","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng kế lại nên nhớ nghĩ công ơn sinh thành dưỡng dục của cha mẹ, hoài thai bú mớm, ái trọng tình thâm, thà cha mẹ chịu nguy thân để con được yên ổn. Đến khi con khôn lớn, cha mẹ lại lo dạy bảo cho con biết nhân biết lễ, hết lòng cầu thầy dạy bảo cho con học hành, nguyện cho con thông đạt nghĩa lý, thấy rộng hiểu sâu, luôn luôn mong muốn cho con theo kịp với người. Con muốn gì cha mẹ cũng cung cấp không tiếc gia bảo."],["p","Ngày đêm lo âu, có khi vì con mà cha mẹ phải sinh bệnh khổ, ngủ không yên giấc. Khi con đi xa, cha mẹ càng trông tưởng."],["p","Trong thiên hạ, ơn cha mẹ là nặng hơn hết. Sở dĩ Phật dạy: “Trong thiên hạ, không có ơn nào bằng ơn cha mẹ”."],["p","Than ôi! Người xuất gia và tại tục chưa thể đắc đạo, phải siêng lo tu học, làm lành không nghỉ, chứa đức không thôi, mới mong báo đáp ơn đức cù lao của cha mẹ."],["p","Đại chúng cùng nhau chí thành đảnh lễ Tam Bảo, mỗi người tự mình nguyện vì từ khi có thần thức trở lại cho đến ngày nay, cha mẹ nhiều đời bà con nhiều kiếp và hết thảy quyến thuộc mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Trí Tụ Phật.","Nam mô Điều Ngự Phật.","Nam mô Như Vương Phật.","Nam mô Hoa Tướng Phật.","Nam mô La Hầu La Phật.","Nam mô Đại Dược Phật.","Nam mô Túc Vương Phật.","Nam mô Dược Vương Phật.","Nam mô Đức Thủ Phật.","Nam mô Đắc Xoa Ca Phật.","Nam mô Lưu Bố Vương Phật.","Nam mô Nhật Quang Phật.","Nam mô Pháp Tạng Phật.","Nam mô Diệu Ý Phật.","Nam mô Đức Chủ Phật.","Nam mô Kim Cang Chúng Phật.","Nam mô Huệ Đảnh Phật.","Nam mô Thiện Trú Phật.","Nam mô Ý Hạnh Phật.","Nam mô Phạm Âm Phật.","Nam mô Sư Tử Phật.","Nam mô Lôi Âm Phật.","Nam mô Thông Tướng Phật.","Nam mô An Ổn Phật.","Nam mô Huệ Long Phật.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, đồng gia tâm nhiếp thọ, nguyện cho cha mẹ bà con chúng con và quyến thuộc của cha mẹ bà con chúng con, từ nay trở đi cho đến ngày thành Phật, hết thảy tội chướng đều được tiêu trừ, hết thảy thống khổ đều được giải thoát, kiết tập phiền não hằng được thanh tịnh, từ rày tự thú, tự tại vãng sinh; thân cận chư Phật, được Phật thọ ký, tứ Vô lượng tâm, lục Ba la mật thường được hiện tiền, tứ Vô ngại biện, lục Thần thông lực, tự tại như ý, được mười trí lực, tướng tốt nghiêm thân, đồng lên đạo tràng, thành bậc Chánh giác."]],"p":"Quyển Thứ Tám"},{"t":"Chương Thứ Hai Mươi Ba Lễ Phật Thế Cha Mẹ các Đời Trước","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng hoặc có người cha mẹ mất sớm, không thể gặp lại, luống tưởng vậy thôi."],["p","Khi chưa được thần thông thiên nhãn, không biết cha mẹ sau khi mất rồi thần hồn sinh về đâu?"],["p","Chỉ nên vội nhờ sức phước đức truy niệm vói tưởng mà báo ơn, làm lành không nghỉ, lâu ngày thành công thì quyết được toại nguyện."],["p","Kinh dạy rằng: “Vì vong nhân mà làm phước cũng như gởi lương hướng cho người đi xa. Nếu người ấy đã sinh lên trời thì công đức của người ấy ngày càng lợi ích."],["p","Nếu người ấy đọa lạc tam đồ ác đạo, hoặc mắc phải tám nạn thì được vĩnh viễn xa lìa khổ não. Nếu các người ấy sinh ra gặp Phật, thọ lãnh Chánh pháp thì liền được siêu thoát tỏ ngộ”."],["p","Cha mẹ bảy đời, bà con nhiều kiếp thì trừ hết những điều lo sợ, đồng được giải thoát."],["p","Đó là cách báo ơn tối tôn tối thượng, chí từ chí hiếu của người con trí thức vậy."],["p","Ngày nay đại chúng nên phải cùng nhau đau thương hoài niệm, áo não khóc lóc, nghẹn ngào, gieo mình xuống đất, nguyện vì cha mẹ nhiều đời, bà con nhiều kiếp mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Phạm Vương Phật.","Nam mô Ngưu Vương Phật.","Nam mô Lợi Đà Mục Phật.","Nam mô Long Đức Phật.","Nam mô Thật Tướng Phật.","Nam mô Trang Nghiêm Phật.","Nam mô Bất Một Âm Phật.","Nam mô Hoa Đức Phật.","Nam mô Âm Đức Phật.","Nam mô Sư Tử Phật.","Nam mô Trang Nghiêm Từ Phật.","Nam mô Dõng Trí Phật.","Nam mô Hoa Tích Phật.","Nam mô Hoa Khai Phật.","Nam mô Lực Hành Phật.","Nam mô Đức Tích Phật.","Nam mô Tượng Hình Sắc Phật.","Nam mô Minh Diệu Phật.","Nam mô Nguyệt Đăng Phật.","Nam mô Oai Đức Vương Phật.","Nam mô Bồ Đề Vương Phật.","Nam mô Vô Tận Phật.","Nam mô Bồ Đề Nhãn Phật.","Nam mô Thân Sung Mãn Phật.","Nam mô Huệ Quốc Phật.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, cứu vớt tiếp độ cha mẹ và bà con chúng con nhiều đời nhiều kiếp về quá khứ, từ nay trở đi cho đến ngày thành Phật, hết thảy tội nhân đều được tiêu trừ, tất cả khổ quả đều được sạch hết, phiền não kết nghiệp hoàn toàn thanh tịnh, đoạn ba chướng duyên, trừ năm bố úy, tu đạo Bồ Tát, rộng độ chúng sanh, bát giải tu tâm, tu hoằng lợi vật, thân cận Như Lai, được Phật thọ ký, không rời đổi chỗ, chứng quả vô sinh, tùy niệm tiêu diêu, dạo khắp cõi Phật, hạnh nguyện chóng thành, mau chứng Chánh giác."]],"p":"Quyển Thứ Tám"},{"t":"Chương Thứ Hai Mươi Bốn Lễ Phật Thế Sư Trưởng","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đã vì cha mẹ và bà con mà lễ Phật rồi. Thứ lại nên nghĩ đến ơn đức Sư trưởng. Vì sao vậy?"],["p","Vì cha mẹ tuy có công sinh thành dưỡng dục chúng con, nhưng không thể làm thế nào cho chúng con mau xa lìa đường ác. Cho nên Sư trưởng đối với chúng con có ơn đức vô lượng. Sư trưởng có lòng đại từ dìu dắt khuyên dỗ, hằng dạy chúng con tu thiện, muốn chúng con ra khỏi biển sinh tử, đến bờ giải thoát bên kia. Mọi điều lợi ích đều khiến chúng con thấy Phật, trừ hết phiền não kiết tập, an trú vào đạo vô vi."],["p","Ơn đức như vậy, ai hay báo đáp cho cùng tận. Dầu trọn đời tu hành, đó chỉ là tự lợi chớ chưa phải báo đáp ơn Sư trưởng."],["p","Sở dĩ Phật dạy: “Thiện tri thức trong thiên hạ, không ai hơn Sư trưởng, đã tự độ mình lại hay độ người”."],["p","Chúng con ngày nay được xuất gia thọ đại giới, hạnh phúc này là nhờ ơn Sư trưởng mà được. Như thế, mọi người há lại không lo đền đáp nhớ tưởng ơn thầy sao?"],["p","Vậy đại chúng cùng nhau chí tâm một lòng tha thiết, năm vóc sát đất, nguyện vì Hòa thượng, A xà lê, đồng đàn tôn chứng thượng, trung, hạ tòa và quyến thuộc của các vị ấy mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Tối Thượng Phật.","Nam mô Thanh Tịnh Chiếu Phật.","Nam mô Huệ Đức Phật.","Nam mô Diệu Âm Thanh Phật.","Nam mô Đạo Sư Phật.","Nam mô Vô Ngại Tạng Phật.","Nam mô Thượng Thí Phật.","Nam mô Đại Tôn Phật.","Nam mô Trí Thế Phật.","Nam mô Đại Diệm Phật.","Nam mô Đế Vương Phật.","Nam mô Chế Lực Phật.","Nam mô Oai Đức Phật.","Nam mô Thiện Minh Phật.","Nam mô Danh Văn Phật.","Nam mô Đoan Nghiêm Phật.","Nam mô Vô Trần Cấu Phật.","Nam mô Oai Nghi Phật.","Nam mô Sư Tử Quân Phật.","Nam mô Thiên Vương Phật.","Nam mô Danh Thanh Phật.","Nam mô Thù Thắng Phật.","Nam mô Đại Tạng Phật.","Nam mô Phước Đức Quang Phật.","Nam mô Phạm Văn Phật.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, đồng gia tâm nhiếp thọ, nguyện Hòa thượng, A xà lê, đồng đàn tôn chứng, thượng, trung, hạ tòa và quyến thuộc của các vị ấy, từ nay trở đi cho đến ngày thành Phật, tất cả tội chướng đều được thanh tịnh, tất cả thống khổ đều được giải thoát, tất cả phiền não đều được đoạn trừ; tùy ý sanh về Tịnh độ của chư Phật, hạnh nguyện Bồ Tát đều được hoàn toàn, tài thí vô tận, pháp thí vô tận, phước đức vô tận, an lạc vô tận, thọ mạng vô tận, trí huệ vô tận, tứ vô lượng tâm, lục ba la mật thường được hiện tiền, tứ vô ngại trí, lục thần thông lực, tự tại như ý, vào định Lăng Nghiêm, được tâm Kim cang, không bỏ thề xưa, trở lại đời này, hóa độ chúng sanh."]],"p":"Quyển Thứ Tám"},{"t":"Chương Thứ Hai Mươi Lăm Lễ Phật Thế Mười Phương Tỳ Kheo và Tỳ Kheo Ni","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đã vì Hòa thượng, A xà lê v.v... mà lễ Phật rồi, sau đây lại phải chí thành đảnh lễ Tam Bảo, khắp vì mười phương tận hư không giới, hiện tại và vị lai hết thảy Tỳ Kheo, Tỳ Kheo ni, Thức xoa ma na, Sa di, Sa di ni cùng quyến thuộc của các vị ấy mà lễ Phật, lại nguyện vì mười phương, tận hư không giới hết thảy Ưu bà tắc, Ưu bà di và quyến thuộc của các vị ấy mà lễ Phật; lại nguyện vì từ xưa đến nay hết thảy các nhà tín thí đàn việt, thiện ác tri thức, với những người có duyên hay vô duyên với Phật pháp, cùng quyến thuộc của các vị ấy mà lễ Phật."],["p","Như thế, hết thảy nhân loại trong nhân đạo và quyến thuộc của nhân đạo, ngày nay đại chúng do từ bi tâm, khắp vì hết thảy mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Đăng Vương Phật.","Nam mô Trí Đảnh Phật.","Nam mô Thượng Vương Phật.","Nam mô Địa Vương Phật.","Nam mô Chí Giải Thoát Phật.","Nam mô Kim Kế Phật.","Nam mô La Hầu Nhật Phật.","Nam mô Mạc Năng Thắng Phật.","Nam mô Mâu Ni Tịnh Phật.","Nam mô Thiện Quang Phật.","Nam mô Kiên Tề Phật.","Nam mô Chủng Đức Thiên Vương"]],["v",["Phật.","Nam mô Pháp Cái Phật.","Nam mô Đức Tý Phật.","Nam mô Ương Già Đà Phật.","Nam mô Mỹ Diệu Huệ Phật.","Nam mô Vy Ý Phật.","Nam mô Chư Oai Đức Phật.","Nam mô Sư Tử Kế Phật.","Nam mô Giải Thoát Tướng Phật.","Nam mô Oai Tướng Phật.","Nam mô Đoạn Lưu Phật.","Nam mô Huệ Tạng Phật.","Nam mô Trí Tụ Phật.","Nam mô Vô Ngại Tán Phật.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, đồng gia tâm che chở, nguyện cho mười phương tận hư không giới hết thảy Tỳ Kheo, Tỳ Kheo ni, Thức xoa ma na, Sa di, Sa di ni và quyến thuộc của các vị ấy; lại nguyện cho mười phương hết thảy Ưu bà tắc, Ưu bà di và quyến thuộc của các vị ấy, lại nguyện cho từ xưa đến nay hết thảy các nhà tín thí, đàn việt, thiện hữu, ác hữu, cùng các người có duyên hay vô duyên với Phật pháp và quyến thuộc của các vị ấy, rộng ra cho đến nhân loại, hết thảy nhân đạo từ vô thỉ trở lại cho đến ngày nay, bao nhiêu phiền não đều được đoạn trừ, bao nhiêu duyên chướng đều được thanh tịnh, bao nhiêu tội nghiệp đều được sạch hết, bao nhiêu thống khổ đều được giải thoát, xa lìa ba nghiệp, trừ năm sợ hãi, bốn vô lượng tâm, sáu ba la mật thường được hiện tiền; bốn vô ngại trí, sáu sức thần thông đều được tự tại, tu Bồ Tát hạnh, vào đạo Nhất thừa, độ thoát chúng sanh."]],"p":"Quyển Thứ Tám"},{"t":"Chương Thứ Hai Mươi Sáu Lễ Phật Thế Tứ Chúng Quá Khứ","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại hết lòng đảnh lễ Tam Bảo, nguyện vì mười phương tận hư không giới hết thảy Tỳ kheo, Tỳ kheo ni, Thức xoa ma na, Sa di, Sa di ni đã qua đời rồi; hết thảy Ưu bà tắc, Ưu bà di, rộng ra cho đến mười phương hết thảy nhân đạo, hết thảy nhân đạo đã qua đời rồi và quyến thuộc của các vị ấy, ngày nay đại chúng do tâm từ bi, đồng như tâm của chư Phật, đồng như nguyện của chư Phật, khắp vì các người ấy mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Bảo Tụ Phật.","Nam mô Thiện Âm Phật.","Nam mô Sơn Vương Tướng Phật.","Nam mô Pháp Đảnh Phật.","Nam mô Giải Thoát Đức Phật.","Nam mô Thiện Đoan Nghiêm Phật.","Nam mô Cát Thân Phật.","Nam mô Ái Ngữ Phật.","Nam mô Sư Tử Lợi Phật.","Nam mô Hòa Lâu Na Phật","Nam mô Sư Tử Pháp Phật.","Nam mô Pháp Lực Phật.","Nam mô Ái Nhạo Phật.","Nam mô Tán Bất Động Phật.","Nam mô Chúng Minh Vương Phật.","Nam mô Giác Ngộ Phật.","Nam mô Diệu Minh Phật.","Nam mô Ý Trú Nghĩa Phật.","Nam mô Quang Chiếu Phật.","Nam mô Hương Đức Phật.","Nam mô Linh Hỷ Phật.","Nam mô Bất Hư Hạnh Phật.","Nam mô Diệt Khuể Phật.","Nam mô Thượng Sắc Phật.","Nam mô Thiện Bộ Phật.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, cứu hộ nhiếp thọ, nguyện cho hết thảy Tỳ kheo, Tỳ kheo ni, Thức xoa ma na, Sa di, Sa di ni và quyến thuộc của các vị ấy trong đời quá khứ; và nguyện cho hết thảy Ưu bà tắc, Ưu bà di cùng quyến thuộc của các vị ấy trong đời quá khứ; nếu có người nào bị thống khổ trong đường địa ngục, ngày nay liền được giải thoát; hoặc có người nào bị thống khổ trong đường ngạ quỷ, ngày nay liền được giải thoát; hoặc có người nào bị thống khổ trong đường súc sinh, ngày nay liền được giải thoát; ra khỏi tám nạn, sinh vào tám phước, hằng xa đường ác, hằng sinh Tịnh độ; tài thí vô tận, pháp thí vô tận, phước đức vô tận, an lạc vô tận, thọ mạng vô tận, trí huệ vô tận, tứ vô lượng tâm, lục ba la mật, thường được hiện tiền, tứ vô ngại trí, lục thần thông lực, như ý tự tại; thường được thấy Phật, nghe pháp, tu Bồ Tát đạo, dõng mãnh, tinh tấn, không thôi không nghỉ, tiến lên cho đến địa vị Vô thượng Chánh đẳng Chánh giác, rộng độ hết thảy chúng sanh."],["v",["Lương Hoàng Bảo Sám,","Vạn đức hồng danh,","Linh văn bát quyển tối hoằng thâm,","Tự tự miễn tai truân,","Đảnh lễ Phật danh,","Tiêu tai bảo an ninh."]],["p","Nam mô Bất Động Địa Bồ Tát Ma Ha Tát. (3 lần)"],["h","Cung Văn"],["p","Bát đức trì trung dũng hiện thiên hoa chi diệu tướng. Bát khổ giới nội, ngưỡng đầu Vạn đức chi Từ Tôn. Hoằng tuyên phát âm, bát nhẫn chi diệu pháp."],["p","Phổ cứu bát hàn bát nhiệt chi nghiêm hình. Đại thùy huệ giám, lân mẫn hữu tình. Ân triêm hữu lậu nhân thiên, phước lợi vô biên quốc độ. Nguyện gia ai mẫn, giám thử thắng nhân."],["p","Thượng lai phụng vì cầu sám đệ tử đẳng... tu kiến Từ Bi Đạo Tràng Sám Pháp, kim đương đệ bát quyển, phi tụng dĩ hoàn. Ư kỳ đàn nội thiêu hương tịnh thất, tán hoa trang nghiêm. Đăng nhiên hỏa thọ quả hiến thời tân. Trà chưng dương tiên xuân tiền, cúng liệt Thuần Đà tối hậu. Phụng trần Đại giác kim tiên bàn liệt tam đảo, vãng cổ minh vương, đế chúa, trung thần, liệt tiên."],["p","Tam giới, thập phương, tứ sinh cửu hữu, câu thừa vô giá chi thiện lợi, tận thoát hữu lậu chi phàm lung, xuất sinh thù lợi."],["p","Phụng vì cầu sám đệ tử đẳng... sám trừ tội cấu, hoạch đại cát tường. Phục nguyện xả bát tà kiến ư hữu tình giới nội."],["p","Hành bát chánh đạo ư vô lậu vị trung. Bát khổ bát nạn chi dư ương, trượng Từ Quang chi đốn thích. Bát thời bát chủng chi phước điền, giả tu trì nhi chứng nhập."],["p","Trần trần tự tại, pháp pháp viên dung. Ba trừng đại hải, nguyệt ấn thiên gian. Dư ám vị không, đồng cầu sám hối."],["p","Nam mô Sám Hối Sư Bồ Tát Ma Ha Tát. (3 lần)"],["p","Lương Hoàng Bảo Sám bát quyển công đức lực, nguyện diệt đệ tử đẳng nghiệp chướng, thân chứng Bồ Tát Bất Động Địa."],["v",["Sám văn cử xứ, tội hoa phi,","Giải liễu oan, sám liễu tội,","Tiêu tai tăng phước thọ,","Thoát khổ sinh Đao Lợi.","Giải liễu oan, sám liễu tội,","Tiêu diêu trực nhập Long Hoa hội,","Long Hoa tam hội nguyện tương"]],["v",["phùng.","Di Lặc Phật tiền thân thọ ký.","Nam mô Long Hoa Hội Bồ Tát Ma Ha Tát. (3 lần)"]],["v",["Lương Hoàng Bảo Sám,","Bát quyển dĩ toàn châu,","Hồi hướng tứ ân tịnh tam hữu,","Bái sám chúng đẳng tăng phước thọ.","Nguyện tương pháp thủy tẩy khiên"]],["v",["vưu.","Duy nguyện vong giả vãng Tây du.","Bất Động Địa Bồ Tát,","Duy nguyện ai nạp thọ.","Nam mô Đăng Vân Lộ Bồ Tát Ma Ha Tát. (3 lần)"]],["p","Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh..."],["v",["Hiệu Chính: HT. THÍCH TRÍ TỊNH","Dịch Giả: HT. THÍCH VIÊN GIÁC"]]],"p":"Quyển Thứ Tám"},{"t":"Đầu Quyển Chín","b":[["p","Nhất bách bát trì Kinh mãn tạng đồ."],["p","Tiêu tai diên thọ Dược Sư Phật, Tỳ Lô tâm nội Du Già bộ. Đại thừa kinh điển cộng Di Đà. Nam phương Long Nữ trực chứng Bồ đề lộ."],["p","Nam mô Phổ Hiền Vương Bồ Tát Ma Ha Tát. (3 lần)"],["h","Cung Văn"],["p","Đạo việt ư cửu thiên, Thích Phạm hiệu viết Thế Hùng, công siêu ư cửu hữu hàm linh; danh xưng Điều Ngự, hoặc bạt khổ ư cửu u giới nội, hoặc nhiếp sinh ư cửu phẩm trì trung. Cửu thứ đệ định nhất niệm năng siêu cửu giới sắc thân. Tùy duyên thị hiện, quang hàm pháp giới đạo việt quần sinh. Nguyện thùy vạn hạnh chi trang nghiêm, giám thử cửu thời chi Phật sự."],["p","Thượng lai phụng vì cầu sám đệ tử đẳng... tu kiến Từ Bi Đạo Tràng Sám Pháp, kim đương đệ cửu quyển, nhập đàn duyên khởi. Nghiêm liệt hương đăng chi hoa quả, bàn trình phỉ cúng chi trân tu."],["p","Biểu thử nhất tâm cúng dường Tam Bảo, tẩy tâm, địch lự, phát lộ, kiền thành. Pháp thân bất động, Pháp tánh trạm nhiên."],["p","Pháp hóa biến châu, pháp âm phổ bị."],["p","Hiện tử ma chi kim tướng, diêu bạch ngọc chi minh đài. Lễ bái quy y, lân mẫn nhiếp thọ; trừ vị trừ chi tội cấu; sám vị sám chi khiên vưu. Thiết niệm cầu sám đệ tử đẳng... trần kiếp dĩ lai, mê lưu kim nhật; thường muội cửu giới chi quả nhân."],["p","Vô minh tự phú; bất tín cửu tuyền chi khổ báo, tà kiến hoạnh sinh, khinh miệt cửu bộ chi Tôn kinh. Tứ tình tạo tội, oanh triền cửu kiết chi phiền não. Túng ý vọng vi tự tán hủy tha, tổn nhân lợi kỷ. Hoặc nhân đấu xứng nhi khi cuống, hoặc nhân tửu sắc dĩ hoang mê. Vị tham trần thế chi tạm hoan, nan miễn u đồ chi cực khổ."],["p","Kim tắc triền chi hối quá, hạnh khởi kỉnh tâm; quy y chơn tịnh chi phước điền, đại vị y văn nhi sám hối. Cung khấu Hồng Từ, minh huân gia bị."],["p","Phật thân sung mãn ư pháp giới. Phổ hiện nhất thiết quần sinh tiền. Tùy duyên phó cảm mị bất châu. Nhi hằng xứ thử Bồ đề tọa."],["p","Khải vận Từ Bi Đạo Tràng Sám Pháp, nhất tâm quy mạng tam thế chư Phật:"],["v",["Nam mô Quá Khứ Tỳ Bà Thi Phật.","Nam mô Thi Khí Phật.","Nam mô Tỳ Xá Phù Phật.","Nam mô Câu Lưu Tôn Phật.","Nam mô Câu Na Hàm Mâu Ni Phật.","Nam mô Ca Diếp Phật.","Nam mô Bổn Sư Thích Ca Mâu Ni"]],["v",["Phật.","Nam mô Đương Lai Hạ Sinh Di Lặc"]],["p","Tôn Phật."]],"p":"Quyển Thứ Chín"},{"t":"Chương Thứ Hai Mươi Bảy Lễ Phật Thế các Chúng Sanh trong Địa Ngục A Tỳ","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nhận thấy từ phần quy y trở đi cho đến phần này về sau đều trình bày vạn pháp sai biệt, tội phước bất nhất, nhưng cũng rõ ràng như sáng và tối, tóm lại mà nói thì chỉ có thiện và ác mà thôi."],["p","Thiện là con đường tốt đẹp, đi lên các cõi trên, ác là nẻo xấu xa, đọa xuống các cõi dưới, trong ba đường ác. Tu nhân nghĩa thì đi về cảnh giới an vui tốt đẹp, gây tàn hại thì đọa xuống cảnh giới khổ đau hạ tiện. Người ở cảnh thù thắng an vui là do nghiệp thù thắng an vui mà được quả báo tốt đẹp, chứ không phải do sự tranh đua vô đạo, tàn ác bất nhân mà được."],["p","Người ở cảnh thù thắng, thọ hưởng vui thú nhiệm mầu, tự nhiên, tiêu diêu tự tại, thẳng đến đạo Bồ đề giác ngộ. Người ở cảnh hạ liệt đau khổ là do nghiệp xấu xa, hạ liệt, tàn ác bất nhân gây ra."],["p","Người ấy ở trong hỏa thành, lưới sắt, ăn thời ăn hoàn sắt nóng mãnh liệt, uống thời nước đồng sôi dữ dội. Thọ mạng vô tận, kiếp số vô cùng chịu đủ thống khổ."],["p","Thống khổ trong địa ngục không thể kể xiết, không thể chịu nổi. Tinh thần lìa khỏi thân mạng này liền sa vào địa ngục hỏa thành. Quả báo thì có đao luân gia hình, đền nợ thì có đá lửa mài thân. Mạng sống kéo dài, ôm khổ mà chịu. Dầu thoát khỏi địa ngục cũng đọa vào ngạ quỷ. Thân hình tiều tụy, ôm lòng đói khát, miệng khạc ra lửa, mạng sống mong manh. Chết rồi lại đọa làm súc sinh chịu bao khổ sở."],["p","Da thịt dùng làm đồ ăn, thân hình bị chia xẻ nấu nướng, yến tiệc linh đình. Hoặc là chở nặng đi xa, làm việc nguy hiểm. Đó là một nỗi khổ nặng nhất trong ba đường ác."],["p","Đau đớn thay cho những kẻ ở trong đêm dài của dục vọng mờ mịt không có ngày ra mà không tự biết!"],["p","Vui khổ rõ ràng như vậy, mà nói không ai tin. Cũng chỉ vì chúng sanh hay chấp lấy cái bản ngã nhỏ nhen của mình nên không tin, lại nghi ngờ mê muội."],["p","Bởi nghi ngờ mê muội nên có lắm người không ưa điều lành. Sở dĩ Phật dạy: “Đời có mười việc, chết đọa địa ngục:"],["v",["1) Là ý không chuyên làm lành, không tu công đức.","2) Là tham ăn như cọp đói kia không khác.","3) Là say mê tửu sắc, ôm lòng độc hại.","4) Là thường tập ngu si, không nghe lời can gián.","5) Là tự ỷ sức mình, làm các việc ác.","6) Là ưa giết chúng sanh, lấn hiếp người cô quả.","7) Là thường làm bạn với kẻ ác.","8) Là xâm lấn phạm vi của người.","9) Là lời nói không chơn thật.","10) Là không thương mọi loài, làm các nghiệp ác."]],["p","Những người như thế, không thể sống lâu, chết vào đường ác”."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nhận thấy: Theo lời Phật dạy, mấy ai thoát được. Nếu không thoát được thì ở trong địa ngục đều có tội phần."],["p","Đại chúng mọi người đều đã lãnh hội được ý ấy, thì tự mình không nên buông lung, phải gấp tu Bồ Tát đạo; cần cầu Phật pháp, lợi ích chúng sanh. Trước là tự diệt tội cho mình, sau là sinh phước cho người."],["p","Đó là tự lợi, lợi tha, mình và người không khác."],["p","Ngày nay cùng nhau khởi tâm dõng mãnh, tâm kiên cố, tâm từ bi, tâm độ hết thảy, tâm cứu hết thảy. Phát tâm như vậy cho đến khi thành Phật, không quên bổn nguyện."],["p","Nguyện xin mười phương tận hư không giới hết thảy chư Phật, chư đại Bồ Tát, đem đại thần thông lực, đại từ bi lực, đại giải thoát địa ngục lực, tế độ ngạ quỷ lực, cứu tế chúng sanh lực, đại thần chú lực, đại oai mãnh lực, khiến chúng con tên... việc làm đều được kết quả lợi ích, lời nguyện đều được thành tựu viên mãn."],["p","Chúng con một lòng tha thiết đầu thành đảnh lễ Tam Bảo, nguyện vì hết thảy chúng sanh đang chịu khổ trong địa ngục A tỳ, cho đến hết thảy chúng sanh đang chịu khổ trong hắc ám địa ngục, trong mười tám địa ngục lạnh, trong mười tám địa ngục nóng, trong mười tám địa ngục đao luân, địa ngục rừng kiếm, địa ngục hỏa xa, địa ngục phất xí, địa ngục hầm than mà quy y Tam Bảo."],["p","Những địa ngục ấy lại có tám vạn bốn ngàn địa ngục khác làm quyến thuộc."],["p","Trong ấy có bao nhiêu chúng sanh chịu khổ, chúng con nguyện do Bồ đề tâm, Bồ đề hạnh, Bồ đề nguyện, xin vì hết thảy chúng sanh ấy mà đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Đại Âm Tán Phật.","Nam mô Tịnh Nguyện Phật.","Nam mô Nhật Thiên Phật.","Nam mô Lạc Huệ Phật.","Nam mô Nhiếp Thân Phật.","Nam mô Oai Đức Thế Phật.","Nam mô Sát Lợi Phật.","Nam mô Đức Thừa Phật.","Nam mô Thượng Kim Phật.","Nam mô Giải Thoát Kế Phật.","Nam mô Nhạo Pháp Phật.","Nam mô Trú Hạnh Phật.","Nam mô Xả Kiêu Mạn Phật.","Nam mô Trí Tạng Phật.","Nam mô Phạm Hạnh Phật.","Nam mô Chiên Đàn Phật.","Nam mô Vô Ưu Danh Phật.","Nam mô Đoan Nghiêm Thân Phật.","Nam mô Tướng Quốc Phật.","Nam mô Liên Hoa Phật.","Nam mô Vô Biên Đức Phật.","Nam mô Thiên Quang Phật.","Nam mô Huệ Hoa Phật.","Nam mô Tần Đầu Ma Phật.","Nam mô Trí Phú Phật.","Nam mô Sư Tử Du Hý Bồ Tát.","Nam mô Sư Tử Phấn Tấn Bồ Tát.","Nam mô Địa Tạng Vương Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi cứu độ tiếp dẫn các chúng sanh chịu khổ trong A tỳ địa ngục, cho đến trong hắc ám địa ngục, đao luân địa ngục, hỏa xa địa ngục, phất xí địa ngục và trong các địa ngục quyến thuộc v.v... Xin nguyện nhờ Phật lực, Pháp lực, Bồ Tát lực, nhất thiết Thánh Hiền lực, khiến các chúng sanh hiện đang chịu khổ, ngày nay liền được giải thoát, hoàn toàn không đọa trở lại trong các địa ngục, hết thảy tội chướng đều được tiêu trừ, rốt ráo không tạo nghiệp địa ngục, không sinh vào địa ngục, sinh về Tịnh độ, bỏ sống địa ngục, được sống trí huệ, bỏ thân địa ngục được thân Kim cang, bỏ khổ địa ngục, được vui Niết bàn, nhớ địa ngục khổ, phát Bồ đề tâm; tứ vô lượng tâm, lục ba la mật thường được hiện tiền, bốn vô ngại trí, sáu thức thần thông tự tại như ý. Đầy đủ trí huệ, tu đạo Bồ Tát, dõng mãnh tinh tấn không thôi không nghỉ, tiến đến hạnh Thập địa vào tâm Kim cang, thành bậc Chánh giác."]],"p":"Quyển Thứ Chín"},{"t":"Chương Thứ Hai Mươi Tám Lễ Phật Thế các Chúng Sanh trong Địa Ngục Khôi Hà, Địa Ngục Thiết Hoàn V.v...","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại chí thành đảnh lễ Tam Bảo nguyện xin vì những chúng sanh trong:"],["v",["Địa ngục khôi hà,","Địa ngục rừng kiếm,","Địa ngục rừng gai,","Địa ngục cột đồng,","Địa ngục máy sắt,","Địa ngục lưới sắt,","Địa ngục hang sắt,","Địa ngục hoàn sắt,","Địa ngục đá nhọn."]],["p","Những địa ngục như vậy đầy khắp mười phương tận hư không giới."],["p","Ngày nay chúng con nguyện vì hết thảy chúng sanh hiện đang chịu khổ trong các địa ngục ấy, phát tâm Bồ đề mà quy y đảnh lễ Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Phạm Tài Phật.","Nam mô Bảo Thủ Phật.","Nam mô Tịnh Căn Phật.","Nam mô Cụ Túc Luận Phật.","Nam mô Thượng Luận Phật.","Nam mô Phất Sa Phật.","Nam mô Đề Sa Phật.","Nam mô Hữu Nhật Phật.","Nam mô Xuất Nê Phật.","Nam mô Đắc Trí Phật.","Nam mô Mô La Phật.","Nam mô Thượng Cát Phật.","Nam mô Pháp Lạc Phật.","Nam mô Cầu Thắng Phật.","Nam mô Trí Huệ Phật.","Nam mô Thiện Thánh Phật.","Nam mô Võng Quang Phật.","Nam mô Lưu Ly Tạng Phật.","Nam mô Danh Văn Phật.","Nam mô Lợi Tịch Phật.","Nam mô Giáo Hóa Phật.","Nam mô Nhật Minh Phật.","Nam mô Thiện Minh Phật.","Nam mô Chúng Đức Thượng Minh"]],["v",["Phật.","Nam mô Bảo Đức Phật.","Nam mô Sư Tử Phan Bồ Tát.","Nam mô Sư Tử Tác Bồ Tát.","Nam mô Địa Tạng Vương Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy, mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo, dùng sức từ bi, đồng gia tâm cứu hộ, cho các chúng sanh hiện đang chịu khổ trong những địa ngục khôi hà, địa ngục rừng kiếm v.v... liền được giải thoát, hết thảy khổ quả đều được tiêu trừ. Những nghiệp địa ngục rốt ráo thanh tịnh, bỏ thân địa ngục được thân Kim cang, bỏ khổ địa ngục, được vui Niết bàn; nhớ địa ngục khổ, phát Bồ đề tâm, đồng ra khỏi nhà lửa, thẳng đến đạo tràng; cùng với các vị Bồ Tát thành bậc Chánh giác."]],"p":"Quyển Thứ Chín"},{"t":"Chương Thứ Hai Mươi Chín Lễ Phật Thế Chúng Sanh trong những Địa Ngục Uống Nước Đồng Sôi, Địa Ngục Hầm Hố V.v...","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại chí thành đảnh lễ Tam Bảo, nguyện khắp vì hết thảy chúng sanh đọa địa ngục trong mười phương tận hư không giới."],["v",["Địa ngục uống nước đồng sôi,","Địa ngục chúng hiệp,","Địa ngục khiếu oán,","Địa ngục đại khiếu oán,","Địa ngục nóng,","Địa ngục đại nóng,","Địa ngục hầm than,","Địa ngục rừng cháy, v.v..."]],["p","Những địa ngục ấy có vô lượng vô biên địa ngục khác làm quyến thuộc."],["p","Trong các địa ngục ấy chúng sanh đang chịu khổ, chúng con nguyện xin đem sức Bồ đề tâm, thay thế hết thảy chúng sanh ấy mà đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Nhơn Nguyệt Phật.","Nam mô La Hầu Phật.","Nam mô Cam Lồ Minh Phật.","Nam mô Diệu Ý Phật.","Nam mô Đại Minh Phật.","Nam mô Nhất Thế Chủ Phật.","Nam mô Lạc Trí Phật.","Nam mô Sơn Vương Phật.","Nam mô Tịch Diệt Phật.","Nam mô Đức Tụ Phật.","Nam mô Thiên Vương Phật.","Nam mô Diệu Âm Thanh Phật.","Nam mô Diệu Hoa Phật.","Nam mô Trú Nghĩa Phật.","Nam mô Công Đức Oai Tụ Phật.","Nam mô Trí Vô Đẳng Phật.","Nam mô Cam Lồ Âm Phật.","Nam mô Thiện Thủ Phật.","Nam mô Lợi Huệ Phật.","Nam mô Tư Giải Thoát Nghĩa Phật.","Nam mô Thắng Âm Phật.","Nam mô Lê Đà Hạnh Phật.","Nam mô Thiện Nghĩa Phật.","Nam mô Vô Quá Phật.","Nam mô Hành Thiện Phật.","Nam mô Kiên Dõng Tinh Tấn Bồ Tát.","Nam mô Kim Cang Huệ Bồ Tát.","Nam mô Địa Tạng Vương Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, đồng gia tâm cứu hộ, nguyện cho hết thảy chúng sanh hiện đang chịu khổ trong những địa ngục uống nước đồng sôi v.v... hết thảy tội chướng đều được tiêu trừ, hết thảy khổ não đều được giải thoát, từ nay về sau không còn đọa lại trong các địa ngục, không sinh vào địa ngục, sinh về Tịnh độ, bỏ mạng địa ngục được mạng trí huệ, tứ vô lượng tâm, lục ba la mật thường được hiện tiền, bốn vô ngại trí, sáu sức thần thông, tự tại như ý; ra khỏi địa ngục, được vào Niết bàn, đồng như chư Phật, thành đẳng Chánh giác."]],"p":"Quyển Thứ Chín"},{"t":"Chương Thứ Ba Mươi Lễ Phật Thế Chúng Sanh trong các Địa Ngục Đao Binh, Đồng Phủ V.v...","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại chí thành đảnh lễ, nguyện vì hết thảy chúng sinh khắp mười phương, tận hư không giới, hiện đang chịu khổ trong các địa ngục:"],["v",["Địa ngục tưởng tượng,","Địa ngục hắc sa,","Địa ngục đóng đinh vào thân,","Địa ngục giếng lửa,","Địa ngục cối đá,","Địa ngục sỏi bay,","Địa ngục đao binh,","Địa ngục đói khát,","Địa ngục chảo đồng sôi, v.v..."]],["p","Những địa ngục như thế ấy vô lượng vô biên. Ngày nay chúng con nguyện xin vì hết thảy chúng sanh trong các địa ngục ấy, đem sức Bồ đề tâm thay thế các chúng sanh ấy mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Hoa Tạng Phật.","Nam mô Diệu Quang Phật.","Nam mô Nhạo Thuyết Phật.","Nam mô Thiện Tế Phật.","Nam mô Chúng Vương Phật.","Nam mô Ly Úy Phật.","Nam mô Biện Tài Nhật Phật.","Nam mô Danh Văn Phật.","Nam mô Bảo Nguyệt Minh Phật.","Nam mô Thượng Ý Phật.","Nam mô Vô Úy Phật.","Nam mô Đại Kiến Phật.","Nam mô Phạm Âm Phật.","Nam mô Thiện Âm Phật.","Nam mô Huệ Tế Phật.","Nam mô Vô Đẳng Ý Phật.","Nam mô Kim Cang Quân Phật.","Nam mô Bồ Đề Ý Phật.","Nam mô Thọ Vương Phật.","Nam mô Bàn Đà Âm Phật.","Nam mô Phước Đức Lực Phật.","Nam mô Thế Đức Phật.","Nam mô Thánh Ái Phật.","Nam mô Thế Hạnh Phật.","Nam mô Hổ Phách Phật.","Nam mô Lạc Tri Phật.","Nam mô Khí Ấm Cái Bồ Tát.","Nam mô Tịch Căn Bồ Tát.","Nam mô Địa Tạng Bồ Vương Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo dùng sức từ bi, đồng gia tâm cứu hộ, xin cho hết thảy chúng sanh hiện đang chịu khổ trong các địa ngục đao binh v.v... và trong hết thảy địa ngục quyến thuộc, ngày nay liền được giải thoát, bao nhiêu khổ não đều được đoạn trừ, không sinh vào địa ngục, được sinh về Tịnh độ; bỏ sống địa ngục được sống trí huệ, nhớ địa ngục khổ phát Bồ đề tâm, tu Bồ Tát hạnh không thôi không nghỉ; vào đạo Nhất thừa, đủ hạnh Thập địa, dùng sức thần thông, tiếp độ chúng sanh, đồng lên đạo tràng, thành bậc Chánh giác."]],"p":"Quyển Thứ Chín"},{"t":"Chương Thứ Ba Mươi Mốt Lễ Phật Thế Chúng Sanh trong các Địa Ngục Hỏa Thành Đao Sơn V.v...","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nguyện vì hết thảy chúng sinh trong các địa ngục cùng khắp mười phương tận hư không giới mà chí thành đảnh lễ Tam Bảo."],["v",["Địa ngục thành lửa,","Địa ngục hang đá,","Địa ngục nước sôi,","Địa ngục núi đao,","Địa ngục hổ lang,","Địa ngục giường sắt,","Địa ngục gió nóng,","Địa ngục phun lửa."]],["p","Những địa ngục ấy có vô lượng vô biên địa ngục khác làm quyến thuộc."],["p","Ngày nay chúng con nguyện vì hết thảy chúng sinh đang chịu khổ trong các địa ngục ấy, đem sức Bồ Đề tâm mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Lôi Âm Vân Phật.","Nam mô Thiện Ái Mục Phật.","Nam mô Thiện Trí Phật.","Nam mô Cụ Túc Phật.","Nam mô Đức Tích Phật.","Nam mô Đại Âm Phật.","Nam mô Pháp Tướng Phật.","Nam mô Trí Âm Phật.","Nam mô Vô Hư Không Phật.","Nam mô Từ Âm Phật.","Nam mô Huệ Âm Sai Biệt Phật.","Nam mô Công Đức Quang Phật.","Nam mô Thánh Vương Phật.","Nam mô Chúng Ý Phật.","Nam mô Biện Tài Luân Phật.","Nam mô Thiện Tịch Phật.","Nam mô Nguyệt Diện Phật.","Nam mô Nhật Danh Phật.","Nam mô Vô Cấu Phật.","Nam mô Công Đức Tập Phật.","Nam mô Hoa Đức Tướng Phật.","Nam mô Biện Tài Quốc Phật.","Nam mô Bảo Thí Phật.","Nam mô Ái Nguyệt Phật.","Nam mô Bất Cao Phật.","Nam mô Huệ Thượng Bồ Tát.","Nam mô Thường Bất Ly Thế Bồ Tát.","Nam mô Địa Tạng Vương Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, đồng gia tâm nhiếp thọ; cho những chúng sinh hiện đang chịu khổ trong những địa ngục trên ấy, liền được giải thoát, rộng ra cho đến hết thảy chúng sinh hiện đang chịu khổ trong những địa ngục nhiều không thể kể xiết ở khắp mười phương đều nhờ Phật lực, Pháp lực, Bồ Tát lực, và Hiền Thánh lực, khiến các chúng sanh ấy liền được giải thoát, hằng đoạn trừ hết nghiệp địa ngục trong mười phương."],["p","Từ nay trở đi cho đến ngày thành Phật, rốt ráo không đọa lại trong ba đường ác, xả thân thọ thân, thường được gặp chư Phật, đầy đủ trí huệ, thanh tịnh tự tại, dõng mãnh tinh tấn, không thôi, không nghỉ, tu lên cho đến mãn hạnh Thập địa, vào tâm Kim cang, viên thành giống trí, do thần lực của Phật tùy tâm tự tại."]],"p":"Quyển Thứ Chín"},{"t":"Chương Thứ Ba Mươi Hai Lễ Phật Thế Chúng Sanh trong Đường Ngạ Quỷ","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại chí thành đảnh lễ, nguyện vì mười phương tận hư không giới hết thảy thần ngạ quỷ, ngạ quỷ và quyến thuộc của ngạ quỷ trong đường quỷ đói đem sức tâm Bồ đề mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Sư Tử Lực Phật.","Nam mô Tự Tại Vương Phật.","Nam mô Vô Lượng Tịnh Phật.","Nam mô Đẳng Định Phật.","Nam mô Bất Hoại Phật.","Nam mô Diệt Cấu Phật.","Nam mô Bất Thất Phương Tiện Phật.","Nam mô Vô Nhiêu Phật.","Nam mô Diệu Diện Phật.","Nam mô Trí Chế Trú Phật.","Nam mô Pháp Sư Vương Phật.","Nam mô Đại Thiên Phật.","Nam mô Thâm Ý Phật.","Nam mô Vô Lượng Phật.","Nam mô Pháp Lực Phật.","Nam mô Thế Cúng Dường Phật.","Nam mô Hoa Quang Phật.","Nam mô Tam Thế Cúng Phật.","Nam mô Ứng Nhật Tạng Phật.","Nam mô Thiên Cúng Dường Phật.","Nam mô Thượng Trí Nhơn Phật.","Nam mô Chơn Kế Phật.","Nam mô Tín Cam Lồ Phật.","Nam mô Kim Cang Phật.","Nam mô Kiên Cố Phật.","Nam mô Dược Vương Bồ Tát.","Nam mô Dược Thượng Bồ Tát.","Nam mô Địa Tạng Vương Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo dùng sức từ bi đồng gia tâm nhiếp thọ."],["p","Nguyện cho hết thảy thần ngạ quỷ, ngạ quỷ và quyến thuộc của ngạ quỷ, trong tất cả đường quỷ đói ở mười phương, tận hư không giới, bao nhiêu tội chướng đều được tiêu trừ; bao nhiêu khổ nạn đều được giải thoát, thân tâm thanh tịnh, không còn khổ não; thân tâm no đủ, không còn đói khát, được pháp vị cam lồ; mắt trí huệ mở; tứ vô lượng tâm, lục Ba la mật, thường được hiện tiền, sáu thức thần thông như ý tự tại, xa lìa đường ngạ quỷ, vào cõi Niết bàn, đồng với chư Phật thành bậc Chánh giác."]],"p":"Quyển Thứ Chín"},{"t":"Chương Thứ Ba Mươi Ba Lễ Phật Thế Chúng Sanh trong Đường Súc Sanh","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại chí thành đảnh lễ Tam Bảo, nguyện khắp vì mười phương tận hư không giới, hết thảy đường súc sinh trong bốn loài chúng sanh, hoặc lớn, hoặc nhỏ, dưới nước trên khô, giữa hư không; hết thảy súc sinh và quyến thuộc của tất cả chúng sanh ấy, ngày nay chúng con do sức của tâm Bồ đề mà đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Bảo Kiên Minh Phật.","Nam mô Lê Đà Bộ Phật.","Nam mô Tùy Nhật Phật.","Nam mô Thanh Tịnh Phật.","Nam mô Minh Lực Phật.","Nam mô Công Đức Tụ Phật.","Nam mô Cụ Túc Đức Phật.","Nam mô Sư Tử Hạnh Phật.","Nam mô Cao Xuất Phật.","Nam mô Hoa Thí Phật.","Nam mô Châu Minh Phật.","Nam mô Liên Hoa Phật.","Nam mô Ái Trí Phật.","Nam mô Quy Đà Nghiêm Phật.","Nam mô Bất Hư Hạnh Phật.","Nam mô Sinh Pháp Phật.","Nam mô Tướng Minh Phật.","Nam mô Tư Duy Nhạo Phật.","Nam mô Nhạo Giải Thoát Phật.","Nam mô Tri Đạo Lý Phật.","Nam mô Thường Tinh Tấn Bồ Tát.","Nam mô Bất Hưu Tức Bồ Tát.","Nam mô Địa Tạng Vương Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo dùng sức từ bi, đồng gia tâm nhiếp thọ, cho hết thảy súc sinh trong bốn loài và quyến thuộc của chúng, trong tất cả đường súc sinh ở khắp mười phương tận hư không giới, bao nhiêu tội chướng đều được tiêu trừ, bao nhiêu khổ não đều được giải thoát, đồng xả bỏ ác thú, đồng chứng được đạo quả; thân tâm an vui như ở đệ tam thiền; tứ vô lượng tâm, lục ba la mật, thường được hiện tiền; bốn vô ngại trí, sáu sức thần thông, như ý tự tại; xa lìa đường súc sinh, vào đường Niết bàn, nhập Kim cang tâm, thành bậc Chánh giác."]],"p":"Quyển Thứ Chín"},{"t":"Chương Thứ Ba Mươi Bốn Vì Sáu Đường Chúng Sanh Mà Phát Nguyện","b":[["p","Chúng con ngày nay xin nhờ công đức nhân duyên lễ Phật, sám hối thế cho các vị Trời, các vị Tiên, Long thần, Bát bộ; nguyện xin cho hết thảy chúng sinh trong bốn loài sáu đường, khắp mười phương, tận hư không giới, cùng tận đời vị lai, từ nay trở đi cho đến ngày thành Phật, không thọ thân hình cách lầm lạc, oan uổng, không chịu các khổ sở độc hại, không tạo năm tội nghịch, mười tội ác, không đọa vào ba đường ác nữa."],["p","Nhờ công đức nhân duyên lễ Phật, hôm nay đều được thân nghiệp thanh tịnh, khẩu nghiệp thanh tịnh, như chư đại Bồ Tát ma ha tát, đều như chư đại Bồ Tát Ma ha tát được đại tâm, tâm như đại địa, sinh ra các căn lành, tâm như biển cả, giữ gìn pháp đại trí huệ của chư Phật; tâm như núi Tu Di, khiến tất cả chúng sinh đều an trú nơi Vô thượng Bồ đề, tâm như ngọc báu ma ni, xa lìa tất cả phiền não, tâm như ngọc báu kim cang, quyết định được tất cả các pháp; tâm kiên cố tà ma ngoại đạo không thể ngăn trở phá hoại; tâm như liên hoa, hết thảy các pháp không thể làm nhiễm nhớp; tâm như hoa Ưu đàm bát, trong bao nhiêu kiếp, khó gặp được; tâm như hư không, hết thảy chúng sanh không thể lường được."],["p","Lại nguyện cho hết thảy chúng sanh trong bốn loài, sáu đường, từ nay trở đi, so lường được tánh biết của mình, so lường được tánh quyết định tin hiểu của mình, trừ bỏ hết các pháp giả dối, thường nghĩ nhớ lời pháp ngữ. Có của gì đều bố thí, tâm không luyến tiếc, tâm dõng mãnh, không sợ hãi. Công đức tu hành đều bố thí, cho tất cả chúng sanh, không đọa lại đường tà, chuyên tâm một bề Chánh đạo, thấy thiện như huyễn hóa, thấy ác như chiêm bao; xa lìa sinh tử, mau ra ba cõi, quán sát rõ ràng, thấu đáo pháp môn thậm thâm vi diệu của chư Phật; tất cả đều được cúng dường hết thảy chư Phật, lễ phẩm cúng dường đều được đầy đủ, tất cả đều được cúng dường hết thảy Tôn pháp, lễ phẩm cúng dường đều được đầy đủ, tất cả đều được cúng dường hết thảy Bồ Tát, lễ phẩm cúng dường đều được đầy đủ; tất cả đều được cúng dường hết thảy Hiền Thánh Tăng; lễ phẩm cúng dường đều được đầy đủ."],["p","Nếu tất cả chúng sanh đời vị lai trái với lời đại nguyện của chúng con hôm nay, đều xin nhờ ơn đức Tam Bảo, khiến tất cả chúng sanh ấy đồng được vào trong bể đại nguyện này, liền được thành tựu công đức trí huệ; nhờ thần lực của Phật mà tùy tâm tự tại, đồng như chư Phật đều thành Chánh giác."]],"p":"Quyển Thứ Chín"},{"t":"Chương Thứ Ba Mươi Lăm Cảnh Tỉnh Vô Thường","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đã cùng nhau lễ Phật, sám hối phát nguyện thế cho hết thảy chúng sanh trong lục đạo rồi; bây giờ cần phải tỉnh ngộ vô thường."],["p","Than ôi! Tội phước trong ba cõi, nhân quả sinh nhau ở ngay tại tâm, không rời đương niệm, nhân quả ảnh hưởng lẫn nhau, không ngoài thiện ác; không thể sai lầm."],["p","Nguyện xin đại chúng nên giác ngộ lý vô thường; phải siêng lo tu hành để tự cứu lấy bản thân, chớ sinh tâm lười biếng mà không cố gắng."],["p","Người trí thức thường than: “Giả sử người hưởng thú dục lạc trăm, ngàn, vạn, ức năm, rốt cuộc cũng không thể tránh được đau khổ trong ba đường ác”. Huống gì chúng ta trong khoảng thời gian ngắn ngủi một trăm năm, nhưng mấy ai sống được một nửa."],["p","Thế thì chúng ta không thể tự dung túng qua ngày không lo tu tập."],["p","Vả lại, thế gian huyễn hóa, rốt cuộc tất cả đều tiêu ma. Có rồi hoàn không, lên cao rồi phải xuống thấp; có sum họp phải có chia ly; có sinh quyết có tử; cha mẹ vợ con chồng bạn, anh em quyến thuộc, thương yêu đến tận cốt tủy, đến giờ phút lâm chung, không ai có thể chết thế cho ai."],["p","Quyền cao chức trọng, vinh hoa phú quý, tiền tài bảo vật cũng không thể kéo dài đời sống, cũng không thể dùng lời lẽ, ăn uống cầu chúc để mong thoát khỏi tử thần. Sống chết là việc vô hình, không ai có thể lưu lại được!"],["p","Kinh dạy rằng: “Chết là hết”. Tắt hơi thở rồi, thần thức thoát ly, thân hình tan rã, nhơn vật như nhau, không ai sống mà không chết. Nhưng trong lúc bỏ thân mạng sống này, khổ não vô cùng. Sáu dòng bà con, nội ngoại, vây quanh khóc lóc. Người chết khi ấy sợ lắm; không biết nương nhờ ai."],["p","Lúc hơi thở cuối cùng sắp tàn, người chết nhớ lại hết thảy việc thiện ác mình đã làm trong một đời qua, hành tướng quả báo sum la hiện ra trước mắt."],["p","Người làm lành được thiên thần (thần trời) phù hộ. Người làm ác có ngưu đầu ngục tốt xua đuổi. Ngục tốt la sát hằng không khoan dung tha thứ. Từ thân, hiếu tử không thể cứu giúp, vợ chồng ân ái chỉ nhìn nhau xem cái chết đến. Gió phong đao xẻ thân đau khổ không thể nói được."],["p","Người chết lúc ấy ruột đau như dao cắt, bao nhiêu thống khổ đồng thời dồn dập; tinh thần hoảng hốt như điên như cuồng. Dầu muốn khởi tâm nghĩ một niệm lành, làm một mảy phước, lễ Phật một lạy cũng không thể được. Lòng càng hối hận, khổ não như vậy, không ai chịu thế cho ai."],["p","Kinh Niết Bàn dạy rằng: “Người chết ở nơi chốn hiểm nạn, không có lương thực; đường đi mờ mịt xa xăm, lại không có bạn bè; ngày đêm đi mãi không biết về đâu, không có phương hướng; thâm thúy tối tăm, không có ánh sáng; vào vô gián địa ngục, đến rồi không thoát ra được."],["p","Sống không tu phước chết về chỗ khổ, sầu thảm chua cay, không thể liệu trị."],["p","Việc ấy không có hình sắc nên không thể biết trước mà lo sợ”."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đã biết quả báo của sự sống chết như sợi dây xích, không có mối manh, không bao giờ cùng tận. Chết rồi thần hồn đi ngơ ngác, thui thủi một mình, không biết về đâu, không ai thấy biết, không thể tìm kiếm, không thể ghi nhớ. Chỉ mỗi người tự nỗ lực siêng năng chịu khổ, chăm lo tu tập, thực hành lục độ, tứ vô lượng tâm v.v... để làm tư lương riêng về xứ sở. Chớ ỷ mình còn mạnh khỏe mà tự yên tâm. Phải nên hết lòng tha thiết, đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Đa Văn Hải Phật.","Nam mô Trì Hoa Phật.","Nam mô Bất Tùy Thế Phật.","Nam mô Hỷ Chúng Phật.","Nam mô Khổng Tước Âm Phật.","Nam mô Bất Thối Một Phật.","Nam mô Đoạn Hữu Ái Cấu Phật.","Nam mô Oai Nghi Tế Phật.","Nam mô Vô Động Phật.","Nam mô Chư Thiên Lưu Bố Phật.","Nam mô Bảo Bộ Phật.","Nam mô Hoa Thủ Phật.","Nam mô Oai Đức Phật.","Nam mô Phá Oán Tặc Phật.","Nam mô Phú Đa Văn Phật.","Nam mô Diệu Quốc Phật.","Nam mô Hoa Minh Phật.","Nam mô Sư Tử Trí Phật.","Nam mô Nguyệt Xuất Phật.","Nam mô Diệt Âm Phật.","Nam mô Sư Tử Du Hý Bồ Tát.","Nam mô Sư Tử Phấn Tấn Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo đồng gia tâm che chở, nguyện cho đại chúng đồng sám hối trong đạo tràng từ nay trở đi cho đến ngày thành Phật, bao nhiêu tội nhân, vô lượng khổ quả đều được đoạn trừ, phiền não kết nghiệp hoàn toàn thanh tịnh."],["p","Thường được đích thân tham dự các hội thuyết pháp của chư Phật, tu đạo Bồ Tát, tự tại thọ sinh, tứ đẳng lục độ như pháp tu hành; tứ biện lục thông hoàn toàn đầy đủ, trăm ngàn tam muội, ứng niệm hiện tiền, các môn tổng trì đều hay chứng nhập, chóng lên đạo tràng, thành bậc Chánh giác."]],"p":"Quyển Thứ Chín"},{"t":"Chương Thứ Ba Mươi Sáu Lễ Phật Thế Người Làm Công Quả Ở Chùa","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng lại chí thành đảnh lễ Tam Bảo, khởi tâm từ bi, không phân biệt oán thân; nguyện vì những người ngày nay chuyển thân trở lại vào chùa làm việc nấu ăn, gánh nước, bửa củi, tùy hỷ công đức, vận hết năng lực làm giúp công việc về phước nghiệp khó nhọc, nguyện khắp vì bà con quyến thuộc các người ấy, lại nguyện vì hết thảy những người hiện đời này bị lao ngục, ách nạn khốn khổ, giam cầm trói buộc và những người bị hành phạt khổ sở."],["p","Nghĩ thương các người ấy, ở đời tuy được làm người, nhưng vui ít khổ nhiều, gông cùm xiềng xích chưa thể lìa thân; hoặc là đời nay tạo ác, hoặc là đời trước tạo ác, nghiệp báo còn theo dõi, hoặc đáng được phóng thích rồi, nhưng không biết do đâu giãi bày, tội nặng bị xử tử, không người cứu."],["p","Chúng con tên... ngày nay do tâm từ bi nguyện vì các người ấy và quyến thuộc của các người ấy, mà quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Thứ Đệ Hành Phật.","Nam mô Phước Đức Đăng Phật.","Nam mô Âm Thanh Trị Phật.","Nam mô Kiều Đàm Phật.","Nam mô Thế Lực Phật.","Nam mô Thân Tâm Trú Phật.","Nam mô Thiện Nguyệt Phật.","Nam mô Giác Ý Hoa Phật.","Nam mô Thượng Cát Phật.","Nam mô Thiện Oai Đức Phật.","Nam mô Trí Lực Đức Phật.","Nam mô Thiện Đăng Phật.","Nam mô Kiên Hạnh Phật.","Nam mô Thiệm Âm Phật.","Nam mô An Lạc Phật.","Nam mô Nhật Diện Phật.","Nam mô Nhạo Giải Thoát Phật.","Nam mô Giới Minh Phật.","Nam mô Trú Giới Phật.","Nam mô Vô Cấu Phật.","Nam mô Sư Tử Phan Bồ Tát.","Nam mô Sư Tử Tác Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo dùng sức từ bi, đồng gia tâm nhiếp thọ, nguyện cho những người chấp lao phục dịch (gánh nước, bửa củi), tùy hỷ công đức và quyến thuộc của các người ấy, từ nay trở đi cho đến ngày thành Phật, hết thảy tội chướng đều được tiêu trừ, hết thảy khổ não đều được giải thoát, thọ mạng diên trường, thân tâm an lạc, hằng lìa tai ách, không có phiền não chướng ngại nữa, phát tâm Đại thừa, tu Bồ Tát đạo, lục độ, tứ đẳng đều được hoàn toàn, xả ly sinh tử, đồng được an vui Niết Bàn."],["p","Lại nguyện trong thiên hạ những người bị hình phạt tù đày, cầm cố trói trăn, ách nạn khốn khổ, những người tật bệnh, không được tự tại, và quyến thuộc của các người ấy, đều nhờ oai lực công đức của chúng con lễ Phật, sám hối hôm nay mà được giải thoát khổ não, những nghiệp nhân độc ác hoàn toàn đoạn trừ; ra khỏi lao ngục, vào thiện pháp môn; thọ mạng vô cùng, trí tuệ vô tận, thân tâm an lạc như ở đệ tam thiền; nhớ lao ngục khổ, tưởng báo ơn Phật; cải ác tùng thiện, phát tâm Đại thừa hành đạo Bồ Tát, vào tâm Kim cang, trở lại độ thoát hết thảy chúng sanh, đồng thành Chánh giác, thần lực tự tại."]],"p":"Quyển Thứ Chín"},{"t":"Chương Thứ Ba Mươi Bảy Phát Nguyện Hồi Hướng","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đã phát tâm rồi, công việc sám hối đã xong. Thứ lại nên đem công đức này phát nguyện hồi hướng cho hết thảy chúng sanh."],["p","Vì sao vậy?"],["p","Vì hết thảy chúng sanh sở dĩ không được giải thoát đều do đắm trước quả báo, không thể xả bỏ. Nếu có chút thiện, mảy phước mà hay hồi hướng được thì đối với quả báo không sinh tâm đắm trước, liền được giải thoát, thong thả tự tại."],["p","Vì vậy nên trong Kinh tán thán sự tu hành biết hồi hướng là việc đại lợi ích, cho nên bây giờ đại chúng cũng phải phát nguyện hồi hướng và khuyến khích mọi người không nên đắm trước quả báo."],["p","Chúng con cùng nhau trước hết là chí tâm đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Kiên Xuất Phật.","Nam mô An Xà Na Phật.","Nam mô Tăng Ích Phật.","Nam mô Hương Minh Phật.","Nam mô Vi Lam Minh Phật.","Nam mô Niệm Vương Phật.","Nam mô Mật Bát Phật.","Nam mô Vô Ngại Tướng Phật.","Nam mô Tín Giới Phật.","Nam mô Chí Diệu Đạo Phật.","Nam mô Nhạo Thật Phật.","Nam mô Minh Pháp Phật.","Nam mô Cụ Oai Đức Phật.","Nam mô Chí Tịch Diệt Phật.","Nam mô Thượng Từ Phật.","Nam mô Đại Từ Phật.","Nam mô Cam Lồ Vương Phật.","Nam mô Di Lâu Minh Phật.","Nam mô Thánh Tán Phật.","Nam mô Quảng Chiếu Phật.","Nam mô Văn Thù Sư Lợi Bồ Tát.","Nam mô Phổ Hiền Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo dùng sức từ bi, đồng gia tâm phù hộ cho chúng con hết thảy hạnh nguyện đều được viên mãn."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng, từ nay cho đến ngày thành Phật tu Bồ Tát đạo không thôi không nghỉ, trước độ chúng sanh, sau sẽ thành Phật."],["p","Nếu trong lúc chưa đắc đạo, còn đọa sinh tử, xin nhờ nguyện lực này, khiến chúng con sinh ra nơi nào ba nghiệp thân, khẩu, ý đều được thanh tịnh, thường phát tâm nhu nhuyến, tâm điều hòa, tâm không buông lung, tâm tịch diệt, tâm chân thật, tâm không tạp loạn, tâm không tham lam, tâm không keo rít, tâm đại thù thắng, tâm đại từ bi, tâm an trú, tâm hoan hỷ, tâm độ hết thảy chúng sanh, tâm giữ gìn Bồ đề, tâm thề đồng như tâm chư Phật, phát những tâm nhiệm mầu thù thắng rộng lớn như vậy để chuyên cầu nghe nhiều, tu định ly dục, lợi ích an lạc hết thảy chúng sanh, nguyện không bỏ đạo Bồ đề, thành bậc Chánh giác."],["h","✵ Phát Nguyện Hồi Hướng Thế cho Chúng Sanh"],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng chí thành đảnh lễ, quỳ gối chắp tay, tâm niệm miệng nói theo lời này:"],["p","- Mười phương chư Thiên, chư Tiên có công đức hạnh nghiệp gì, chúng con nay xin hồi hướng thế, đồng quy Chánh giác đạo."],["p","- Mười phương Long vương, quỷ thần có thiện nghiệp gì thù thắng, chúng con nay xin hồi hướng thế, đồng quy Nhất thừa đạo."],["p","- Mười phương các Nhân vương có tu hạnh nghiệp gì về đạo Bồ đề, chúng con nay xin hồi hướng thế, đồng quy y Vô thượng đạo."],["p","- Các loài chúng sanh trong lục đạo có mảy may thiện nghiệp gì, chúng con nay xin hồi hướng thế, đồng quy y Vô thượng đạo."],["p","- Mười phương đệ tử Phật, thiện lai chúng Tỳ kheo, vô trước tứ Sa môn và những vị cầu Duyên Giác thừa, ẩn hiện hóa chúng sanh, hiểu rõ pháp nhân duyên như vậy và hết thảy đều hồi hướng Phật đạo."],["p","- Mười phương chư Bồ Tát, đọc tụng thọ trì Kinh, nhập thiền, xuất thiền, khuyến hóa chúng sanh làm hết thảy điều phước thiện như vậy, hết thảy Tam thừa Thánh chúng, có bao nhiêu cội phước đức, đều xin hồi hướng cho tất cả chúng sanh đồng quy y vô thượng đạo."],["p","- Các vị trên trời và dưới nhân gian, tu Thánh đạo có bao nhiêu công đức thiện nghiệp, nay chúng con khuyên hồi hướng vô thượng đạo."],["p","- Những vị phát tâm và sám hối, tự mình tu và khuyên người tu, dầu được mảy may phước như vi trần, cũng đem thí hết cho chúng sanh. Nếu chúng sanh không thành Phật, chúng con thề không bỏ Bồ đề nguyện."],["p","- Bao giờ chúng sanh thành Phật hết, chúng con mới chứng quả Vô thượng Bồ đề."],["p","- Nguyện xin chư Phật, chư Đại Bồ Tát, vô lậu các Thánh nhơn, đời này và đời sau, duy nguyện xin nhiếp thọ."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng cùng nhau chí tâm đảnh lễ Tam Bảo, nguyện xin thay thế các vị quốc chủ và quyến thuộc của quốc chủ mà hồi hướng; nguyện xin thay thế cha mẹ và bà con mà hồi hướng."],["p","- Nguyện xin thay thế Sư trưởng và chư vị đồng học mà hồi hướng."],["p","- Nguyện xin thay thế các nhà tín thí đàn việt, thiện ác tri thức mà hồi hướng."],["p","- Nguyện xin thay thế Hộ thế tứ Thiên vương mà hồi hướng."],["p","- Nguyện xin thay thế ma vương trong mười phương mà hồi hướng."],["p","- Nguyện xin thay thế các vị thông minh chánh trực, thiên địa hư không, chủ thiện phạt ác, thủ hộ trì chú, ngũ phương Long vương, Long thần Bát bộ mà hồi hướng."],["p","- Nguyện xin thay thế các vị Linh kỳ, u hiển mà hồi hướng."],["p","- Nguyện xin hồi hướng thế cho mười phương tận hư không giới hết thảy chúng sanh."],["p","- Nguyện xin chư Thiên, chư Tiên, Long thần Bát bộ, hết thảy chúng sanh, từ nay trở đi cho đến ngày chứng quả Bồ đề, hằng thể hội được pháp môn vô tướng, không còn có tâm đắm trước quả báo nữa."],["v",["Lương Hoàng Bảo Sám,","Tận thị Phật ngôn,","Văn từ xán lạn tại lương hàm,","Quả báo nhất siêu nhiên,","Lợi ích nhơn thiên,","Vạn cổ vĩnh lưu truyền."]],["v",["Lương Hoàng Bảo Sám,","Vạn đức hồng danh,","Linh văn cửu quyển tối hoằng thâm,","Tự tự miễn tai truân,","Đảnh lễ Phật danh,","Tiêu tai bảo an ninh."]],["p","Nam mô Thiện Huệ Địa Bồ Tát Ma Ha Tát. (3 lần)"],["h","Cung Văn"],["p","Cửu phẩm Đạo sư, cửu chấp lục thiên nhi thị vệ. Cửu giới Từ phụ, cửu chủng La hán dĩ tham tùy. Ngưỡng nguyện Thánh quyến vĩnh hưởng ư cửu trùng khuyết nội, cực tế quần sinh đồng đăng ư cửu liên đài bạn; công siêu cửu hữu, đạo việt cửu thiên. Ngưỡng đầu Đại giác, chứng minh sám hối. Thượng lai phụng vì cầu sám đệ tử đẳng... huân tu Lương Hoàng Bảo Sám, phi duyệt Hải tạng linh văn. Kim đương đệ cửu quyển xuất nhập nhị thời, công hoàn cáo tất."],["p","Cung đối Thánh tượng, khể thủ quy y."],["p","Phàn hải ngạn chi chiên đàn, hiến danh viên chi dị quả. Trà luân tỉnh hôn trầm chi vị. Đăng nhiên phá hắc ám chi quang."],["p","Kỳ hoa diệu đoạt ư thiên cơ, phạm hưởng thanh truyền ư tiên nhạc. Chí thành lục niệm, thiền quán nhất tâm; giảo kế trù lượng, giai tất hồi hướng A nậu Bồ đề tát đỏa. Thanh Văn La Hán chư thiên, thiên kinh địa vĩ, chưởng ác âm dương, quyền hoành cập tạo hóa. Bát bộ chúng long thần, tịnh nguyện giám thử tâm, phổ huân chơn thường lạc."],["p","Phụng vì cầu sám đệ tử đẳng... sám trừ chủng chủng chi nghiệp chướng, đắc hoạch vĩnh vĩnh chi trinh tường. Đốn siêu cửu phẩm, tảo chứng Bồ đề. Phục nguyện cửu kiết tội khiên, tự thử thời nhi giải thích; cửu u khổ thú, thừa tư sám dĩ khai minh; bất trệ cửu địa, cửu tư chi kiến hoặc; tốc đạt cửu liên cửu phẩm chi Tịnh bang, hàm siêu cửu công tư nghiêm cửu đức. Nhiên tắc tái tứ phi trần thành khủng tình do sai hộ, tái lao Tôn chúng trùng trùng sám hối."],["p","Nam mô Sám Hối Sư Bồ Tát Ma Ha Tát. (3 lần)"],["p","Lương Hoàng Bảo Sám cửu quyển công đức lực, nguyện diệt đệ tử đẳng... chư tội chướng, thân chứng Bồ Tát Thiện Huệ Địa."],["v",["Sám văn cử xứ, tội hoa phi,","Giải liễu oan, sám liễu tội,","Tiêu diêu trực nhập Long Hoa hội.","Long Hoa tam hội nguyện tương"]],["v",["phùng.","Di Lặc Phật tiền thân thọ ký.","Nam mô Long Hoa Hội Bồ Tát Ma Ha Tát. (3 lần)"]],["v",["Lương Hoàng Bảo Sám,","Cửu quyển dĩ toàn châu,","Hồi hướng tứ ân tịnh tam hữu,","Bái sám chúng đẳng tăng phước thọ.","Nguyện tương pháp thủy tẩy khiên"]],["v",["vưu.","Duy nguyện vong giả vãng Tây du.","Thiện Huệ Địa Bồ Tát,","Duy nguyện ai nạp thọ.","Nam Mô Đăng Vân Lộ Bồ Tát Ma Ha Tát. (3 lần)"]],["p","Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh..."],["v",["Hiệu Chính: HT. THÍCH TRÍ TỊNH","Dịch Giả: HT. THÍCH VIÊN GIÁC"]]],"p":"Quyển Thứ Chín"},{"t":"Đầu Quyển Mười","b":[["p","Y phụng hiến lăng la cẩm tú, sa quyến, kim quải tứ nan miêu họa. Long nữ chức tựu kim ty mạt, Ba Tư Nặc vương xả cà sa, Mã Minh Vương Bồ Tát thệ nguyện thần thông hóa."],["p","Nam mô Phổ Hiền Vương Bồ Tát Ma Ha Tát. (3 lần)"],["h","Cung Văn"],["p","Thập hiệu Năng Nhân tọa bảo liên hoa, thành Đẳng chánh giác. Thập thân Điều Ngự tại vi trần lý, chuyển Đại pháp luân. Quang minh biến chiếu ư thập phương, phương tiện toàn siêu ư Thập địa. Cụ túc thập ba la mật, cố xưng thập Đại nguyện vương. Ngưỡng khấu Hồng Từ, phủ thùy đổng giám."],["p","Thượng lai phụng vì cầu sám đệ tử đẳng... tu kiến Từ Bi Đạo Tràng Sám Pháp, tư đương đệ thập quyển, nhập đàn duyên khởi, đoan khác nhất tâm, tinh trần thập cúng, phụng hiến thập phương Tam Bảo, huân tu thập trục nghi văn. Y thập khoa chi sám pháp, giải thập triền chi tội khiên. Thiết niệm cầu sám đệ tử đẳng... nhân tứ nẳng kiếp, quả cảm kim sinh, muội thập thiện chi chánh nhơn, tạo thập ác chi nghiệp chướng. Thập triền tự nhiễu tợ câu tỏa chi liên hoàn."],["p","Thập tập tự huân, loại phi nga chi phó hỏa. Tiệm cập bách thiên chi chướng cấu, phục thành vô lượng chi tội đoan. Ái kiến vị vong, tham tâm nan mãn, sân hỏa diệm diệm thiêu tận Bồ đề chi quả. Nghiệp phong hao hao điêu tàn công đức chi lâm."],["p","Tuế nguyệt ta đà, phương chi quá cựu."],["p","Quang âm thúc hốt, thủy giác tiền phi."],["p","Kim tắc thừa sám hối chi huyền môn, hạnh huân tu chi hữu tự. Bằng chư truy lữ, phi duyệt kim văn, tu Phật dĩ châu long, tác vô cùng phi pháp lợi. Khắc niệm nhiếp niệm, dĩ trùng trùng; ý phi kiền thành nhi nhất nhất, vọng Phật thùy từ, minh huân gia bị. Nhất niệm phổ quán vô lượng kiếp, vô khứ vô lai, duyệt vô trú."],["p","Như thị liễu chi Tam thế Phật, siêu chư phương tiện thành Thập lực."],["p","Khải vận Từ Bi Đạo Tràng Sám Pháp, nhất tâm quy mạng tam thế chư Phật:"],["v",["Nam mô Quá Khứ Tỳ Bà Thi Phật.","Nam mô Thi Khí Phật.","Nam mô Tỳ Xá Phù Phật.","Nam mô Câu Lưu Tôn Phật.","Nam mô Câu Na Hàm Mâu Ni Phật.","Nam mô Ca Diếp Phật.","Nam mô Bổn Sư Thích Ca Mâu Ni"]],["v",["Phật.","Nam mô Đương Lai Hạ Sinh Di Lặc"]],["p","Tôn Phật."]],"p":"Quyển Thứ Mười"},{"t":"Chương Thứ Ba Mươi Tám Bồ Tát Hồi Hướng","b":[["p","Ngày nay đại chúng đã cùng nhau chịu khó nhọc, chịu cực khổ tu tập được vô lượng căn lành như vậy, bây giờ mỗi người lại nên suy nghĩ như thế này:"],["p","Chúng con tên... đã tu tập được bao nhiêu căn lành đều vì lợi ích cho hết thảy chúng sanh, khiến các chúng sanh hoàn toàn thanh tịnh."],["p","Chúng con nhờ các căn lành tu tập, sám hối khiến chúng sanh trừ diệt được vô lượng khổ não ở các cảnh địa ngục, Ngạ quỷ, súc sinh, Diêm la vương v.v..."],["p","Nguyện đem công đức sám hối này làm nhà cửa rộng lớn cho chúng sanh, khiến chúng sanh diệt trừ được khổ ấm, làm việc đại cứu hộ, khiến chúng sanh thoát phiền não; làm chỗ đại quy y; khiến chúng sanh xa lìa sợ hãi; làm chỗ đại chỉ thú, khiến chúng sanh được trí huệ; làm chỗ đại an ổn, khiến chúng sanh được chỗ cứu cánh an ổn; làm đuốc lớn soi sáng; khiến chúng sanh diệt trừ si ám; làm ngọn đèn đại minh đăng, khiến chúng sanh được an trú hoàn toàn cảnh giới thanh tịnh; làm vị đại đạo sư, khiến chúng sanh vào pháp môn phương tiện, được thân trí thanh tịnh."],["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng nhận thấy các pháp như vậy là các vị Bồ Tát Ma ha tát vì kẻ oán người thân mà tu hành, đem các căn lành đồng chung hồi hướng cho tất cả chúng sanh, đối với các chúng sanh bình đẳng, không sai khác, vào pháp quán bình đẳng, không có tư tưởng oán thân, thường đem con mắt từ ái mà ngó chúng sanh. Nếu chúng sanh ôm lòng oán giận Bồ Tát, sinh tâm ác nghịch, thì Bồ Tát là bậc thiện tri thức chịu khó điều phục tâm tánh của chúng sanh, bằng cách khéo nói pháp thâm diệu. Ví như biển cả, các thứ độc hại của chúng sanh không thể phá hoại."],["p","Tâm Bồ Tát cũng vậy, những chúng sanh ngu si, không trí huệ, không biết báo ơn, không thể phá hoại tâm của Bồ Tát."],["p","Những chúng sanh ấy sinh ra vô lượng ác độc cũng không thể làm động loạn đạo tâm của Bồ Tát. Ví như mặt trời sáng chiếu khắp tất cả chúng sanh, mặt trời không vì kẻ mắt mù mà không chiếu."],["p","Đạo tâm của Bồ Tát cũng vậy, không vì người ác mà thối tâm. Bồ Tát không vì chúng sanh khó điều phục mà thối bỏ căn lành."],["p","Bồ Tát Ma ha tát đối với các căn lành, lòng tin rất thanh tịnh, trưởng dưỡng đại bi, đem các căn lành ấy, dùng thâm tâm mà hồi hướng khắp cho hết thảy chúng sanh."],["p","Bồ Tát không phải nói suông nơi miệng mà đối với các chúng sanh đều phát tâm hoan hỷ, tâm minh tịnh, tâm nhu nhuyến, tâm từ bi, tâm ái niệm, tâm nhiếp thủ, tâm nhiêu ích, tâm an lạc, tâm tối thắng, đem các căn lành hồi hướng cho chúng sanh."],["p","Bồ Tát Ma ha tát phát tâm hồi hướng căn lành như vậy, chúng con nay cũng phải mong học phương pháp hồi hướng ấy, cho nên tâm niệm miệng nói lời này: “Nếu chúng con có bao nhiêu công đức đều hồi hướng cho chúng sanh; khiến chúng sanh đồng được thanh tịnh thú, được thanh tịnh sinh, đầy đủ công đức, hết thảy các pháp thế gian không thể phá hoại, công đức trí huệ vô cùng, vô tận, thân khẩu ý nghiệp hoàn toàn trang nghiêm, thường thấy chư Phật đem hết lòng tin, kiên cố lãnh thọ Chánh pháp; xa lìa các điều nghi ngờ; nhớ giữ không quên Chánh pháp, thân, khẩu, ý nghiệp thanh tịnh, tâm thường an trú nơi thiện căn thắng diệu, hằng xa lìa sự nghèo thiếu, đầy đủ thất thánh tài; tu học hết thảy các pháp Bồ Tát đã học, được các căn lành; thành tựu pháp bình đẳng được pháp giải thoát nhiệm mầu Nhất thiết chủng trí."],["p","Đối với các chúng sanh được mắt từ ái, thân căn thanh tịnh, lời nói biện tài, trí huệ sáng suốt, phát sinh các phép lành, tâm không đắm nhiễm; vào pháp thậm thâm, thâu nhiếp hết thảy chúng sanh, đồng an trú nơi cảnh vô sở trú của chư Phật."],["p","Những điều hồi hướng đồng như mười phương Bồ Tát Ma ha tát đã hồi hướng, rộng lớn như pháp tánh, cứu cánh như hư không."],["p","Nguyện xin cho chúng con tên... đồng được như sở nguyện mãn Bồ đề nguyện... tứ sinh, lục đạo, chúng sanh cũng đồng được như sở nguyện."],["p","Lại nguyện xin chí thành đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Oai Đức Phật.","Nam mô Kiến Minh Phật.","Nam mô Thiện Hành Báo Phật.","Nam mô Thiện Hỷ Phật.","Nam mô Vô Ưu Phật.","Nam mô Bảo Minh Phật.","Nam mô Oai Nghi Phật.","Nam mô Nhạo Phước Đức Phật.","Nam mô Công Đức Hải Phật.","Nam mô Tận Tướng Phật.","Nam mô Đoạn Ma Phật.","Nam mô Tận Ma Phật.","Nam mô Quá Suy Đạo Phật.","Nam mô Bất Hoại Ý Phật.","Nam mô Thủy Vương Phật.","Nam mô Tịch Ma Phật.","Nam mô Chúng Thượng Vương Phật.","Nam mô Ái Minh Phật.","Nam mô Phước Đăng Phật.","Nam mô Bồ Đề Tướng Phật.","Nam mô Trí Âm Phật.","Nam mô Thường Tinh Tấn Bồ Tát.","Nam mô Bất Hưu Tức Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo dùng sức từ bi, đồng gia tâm nhiếp thọ khiến cho tâm hồi hướng của chúng con được thành tựu hoàn toàn."],["p","Chúng con tên... nếu có đủ vô lượng tội đại ác nghiệp, đáng thọ vô lượng vô biên thống khổ trong đường ác, không thể thoát được, trái với tâm Bồ đề, trái với hạnh Bồ đề, trái với nguyện Bồ đề, nguyện xin mười phương chư đại Bồ Tát, hết thảy Thánh Hiền, vì từ bi tâm, không trái với bổn nguyện, giúp đỡ chúng con tên... ở trong ba đường ác kia cứu các chúng sanh làm cho các chúng sanh đều được giải thoát, thề không vì khổ mà bỏ chúng sanh."],["p","Nguyện xin Bồ Tát gánh nặng cho chúng con, chúng con được mãn nguyện bình đẳng, độ thoát hết thảy chúng sanh, khỏi sanh lão bệnh tử, ưu bi khổ não, vô lượng ách nạn."],["p","Nguyện khiến các chúng sanh đều được thanh tịnh, đầy đủ căn lành, rốt ráo giải thoát, xả bỏ ma quân, xa lìa bạn ác gần gũi bạn lành, chân thật quyến thuộc, thành tựu tịnh nghiệp, diệt hết các khổ, đầy đủ vô lượng hạnh nguyện của Bồ Tát, thấy Phật hoan hỷ, chứng nhất thiết trí, trở lại độ thoát hết thảy chúng sanh."]],"p":"Quyển Thứ Mười"},{"t":"Chương Thứ Ba Mươi Chín Phát Nguyện","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đã phát tâm hồi hướng rồi, thứ lại phải phát nguyện như thế này:"],["p","Luận ra: Các điều ác phát sinh đều do sáu căn. Vậy biết sáu căn là cội gốc của tai họa. Tuy vậy nếu biết dùng sáu căn, thì sáu căn cũng hay chiêu tập vô lượng phước nghiệp, cho nên Kinh Thắng Man dạy rằng: “Giữ gìn sáu căn, cho trong sạch thân khẩu ý”."],["p","Căn cứ vào lẽ ấy để chứng minh sáu căn là cội gốc sinh ra các điều lành."],["p","Vậy nên đối với sáu căn mà phát đại thệ nguyện:"],["p","TRƯỚC HẾT PHÁT NGUYỆN VỀ NHÃN"]],"p":"Quyển Thứ Mười"},{"t":"Căn (Con Mắt)","b":[["p","Nguyện ngày nay đại chúng đồng nghiệp trong đạo tràng và hết thảy chúng sinh trong bốn loài sáu đường ở khắp mười phương, từ nay trở đi cho đến ngày thành Phật:"],["p","- Mắt thường không thấy sắc huyễn hoăc̣\u0001 dối trá, tham dục không nhàm chán."],["p","- Mắt không thấy sắc siểm nịnh khuất khúc ủy mỵ, không thấy sắc xanh vàng trắng đỏ v.v... mê hoặc người đời."],["p","- Mắt không thấy sắc có hình trạng xấu xa, sân hận đấu tranh, không thấy sắc đánh đập làm tổn hại người khác."],["p","- Mắt không thấy sắc làm người ngu si, không tin mà nghi ngờ ám muội."],["p","- Mắt không thấy sắc kiêu mạn, không khiêm tốn, không kính nhường."],["p","- Mắt không thấy sắc tà kiến của chín mươi sáu món ngoại đạo."],["p","Nguyện cho hết thảy chúng sanh từ nay trở đi:"],["p","- Mắt thường thấy sắc vắng lặng Pháp thân thường trú của mười phương chư Phật"],["p","- Mắt thường thấy ba mươi hai tướng tốt, tử ma kim sắc và tám mươi vẻ đẹp của chư Phật."],["p","- Mắt thường thấy sắc của chư Thiên, chư Tiên dâng ngọc báu, rải hoa trời cúng Phật."],["p","- Mắt thường thấy năm sắc hào quang trong miệng Phật tuôn ra thuyết pháp độ người."],["p","- Mắt thường thấy sắc Phật, phân thân tán thể cùng khắp mười phương."],["p","- Mắt thường thấy chư Phật phóng hào quang trên nhục kế cảm triệu người có duyên đến pháp hội."],["p","- Mắt thường thấy sắc của mười phương Bồ Tát, Bích Chi, La hán, Thánh chúng."],["p","- Mắt thường được cùng với chúng sanh và quyến thuộc, quan sát sắc thân của Phật."],["v",["- Mắt thường thấy chúng thiện vô giáo giả sắc.","- Mắt thường thấy sắc thất giác tịnh hoa.","- Mắt thường thấy sắc diệu quả giải thoát."]],["p","- Mắt thường thấy sắc của đại chúng trong đạo tràng ngày nay hoan hỷ tán thán Phật pháp, đảnh lễ thọ trì."],["p","- Mắt thường thấy tứ chúng vây quanh Phật để nghe Pháp, sinh tâm khát ngưỡng."],["p","- Mắt thường thấy hết thảy người tu bố thí, trì giới, nhẫn nhục, tinh tấn."],["p","- Mắt thường thấy hết thảy các vị tịnh mạc, thiền tư, tu tập trí huệ."],["p","- Mắt thường thấy sắc của hết thảy chúng sanh được pháp vô sanh nhẫn, hiện tiền được thọ ký thì sinh tâm hoan hỷ."],["p","- Mắt thường thấy sắc bổ xứ của hết thảy các vị chứng được Kim cang huệ, đoạn trừ vô minh, u ám."],["p","- Mắt thường thấy hết thảy sắc mộc dục pháp lưu bất thối."],["p","Đã phát nguyện về mắt rồi, đại chúng cùng nhau chí thành đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Thiện Diệt Phật.","Nam mô Phạm Tướng Phật.","Nam mô Trí Hỷ Phật.","Nam mô Thần Tướng Phật.","Nam mô Như Chúng Vương Phật.","Nam mô Trì Địa Phật.","Nam mô Ái Nhật Phật.","Nam mô La Hầu Nguyệt Phật.","Nam mô Hoa Minh Phật.","Nam mô Dược Sư Thượng Phật.","Nam mô Trì Thế Lực Phật.","Nam mô Phước Đức Minh Phật.","Nam mô Hỷ Minh Phật.","Nam mô Hảo Âm Phật.","Nam mô Pháp Tự Tại Phật.","Nam mô Phạm Âm Phật.","Nam mô Diệu Âm Bồ Tát.","Nam mô Đại Thế Chí Bồ tát","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo dùng sức từ bi, đồng gia tâm che chở, khiến đệ tử tên... được như sở nguyện mãn Bồ đề nguyện."]],"p":"Quyển Thứ Mười"},{"t":"Thứ Lại Phát Nguyện Về Nhĩ Căn (Lỗ Tai)","b":[["p","Lại nguyện ngày nay đại chúng đồng nghiệp trong đạo tràng và rộng ra khắp hết thảy chúng sanh trong bốn loài sáu đường, ở khắp mười phương từ nay trở đi cho đến ngày thành đạo:"],["p","- Tai thường không nghe tiếng khóc lóc buồn rầu đau khổ."],["p","- Tai không nghe tiếng kêu la thống thiết trong địa ngục."],["p","- Tai không nghe tiếng vạc nước sôi trào vọt trong địa ngục."],["p","- Tai không nghe tiếng cắt xẻ, mũi nhọn, núi đao, rừng kiếm."],["p","- Tai không nghe tiếng vô lượng khổ sở trong mười tám ngăn địa ngục."],["p","- Tai không nghe tiếng nhiệt não đói khát của ngạ quỷ kiếm ăn không được."],["p","- Tai không nghe tiếng ngạ quỷ hành động, thân thể chi tiết bị lửa đốt vang dội như tiếng năm trăm cỗ xe kêu."],["p","- Tai không nghe tiếng của súc sinh, thân dài năm trăm do tuần bị các sâu trùng nhỏ rúc rỉa khổ sở."],["p","- Tai không nghe tiếng kêu la đau khổ của trâu, ngựa, lừa, lạc đà v.v... thường chở nặng đi xa, bị roi, gậy đánh đập bởi kiếp trước mắc nợ người không trả."],["p","- Tai không nghe tiếng đau thương của các cảnh ái ân ly biệt, của oán thù gặp gỡ, của tám nỗi khổ v.v... hành hạ kiếp người."],["p","- Tai không nghe tiếng rên siết của khổ báo do bốn trăm lẻ bốn bệnh hành hạ thân thể."],["p","- Tai không nghe tiếng của hết thảy điều ác hành hạ chúng sanh."],["p","- Tai không nghe tiếng chuông, linh, ốc, trống, cầm, sắc, không hầu, lâm, lang, ngọc bội làm mê hoặc chúng sanh."],["p","Nguyện xin hết thảy chúng sanh từ nay trở đi:"],["p","- Tai thường nghe được tám thứ âm thanh của chư Phật thuyết pháp."],["p","- Tai thường nghe được những tiếng: “Khổ, không, vô thường, vô ngã”."],["p","- Tai thường nghe được tám mươi bốn ngàn pháp ba la mật."],["p","- Tai thường được nghe nói các pháp chỉ là giả danh, không có thật thể, không có tự tánh."],["p","- Tai thường nghe chư Phật thuyết pháp chỉ dùng một âm thanh, mà vô lượng chúng sanh tùy theo nghiệp báo của mỗi loài mà tự hiểu."],["p","- Tai thường nghe nói hết thảy chúng sanh đều có Phật tánh. Phật tánh ấy là Pháp thân thường trú bất diệt."],["p","Thường nghe tiếng mười phương Bồ Tát tu hạnh nhẫn nhục, tinh tấn."],["p","- Tai thường nghe nói: được pháp vô sinh giải, khéo nhập Phật huệ, vượt ra ba cõi."],["p","- Tai thường nghe tiếng các vị Pháp thân Bồ Tát vào dòng pháp lưu, chơn tục đồng quán, niệm niệm đầy đủ muôn hạnh."],["p","- Tai thường nghe tiếng của các vị Bích Chi, La Hán và bốn quả Thanh Văn thuyết pháp."],["p","- Tai thường nghe trời Đế Thích thuyết Bát Nhã."],["p","- Tai thường nghe các vị đại sĩ trên hàng Thập địa bổ xứ trên cung trời Đâu Suất thuyết pháp, bất thối chuyển địa hạnh."],["p","- Tai thường nghe nói vạn hạnh đồng quy về cõi Phật."],["p","- Tai thường nghe chư Phật khen ngợi hết thảy chúng sanh hay tu hạnh thập thiện, tùy hỷ."],["p","Nguyện xin cho chúng sanh thường được nghe tiếng chư Phật khen ngợi: “Lành thay! Người ấy không bao lâu sẽ thành Phật”."],["p","Đã phát nguyện về nhĩ căn rồi, đại chúng cùng nhau chí thành đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Thiện Nghiệp Phật.","Nam mô Ý Vô Mậu Phật.","Nam mô Đại Thí Phật.","Nam mô Minh Tán Phật.","Nam mô Chúng Tướng Phật.","Nam mô Đức Lưu Bố Phật.","Nam mô Thế Tự Tại Phật.","Nam mô Đức Thọ Phật.","Nam mô Đoạn Nghi Phật.","Nam mô Vô Lượng Phật.","Nam mô Thiện Nguyệt Phật.","Nam mô Vô Biên Biện Tướng Phật.","Nam mô Bảo Nguyệt Bồ Tát.","Nam mô Nguyệt Quang Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam bảo dùng sức từ bi, đồng gia tâm nhiếp thọ, khiến đệ tử chúng con tên... được như sở nguyện, mãn Bồ đề nguyện."],["p","KẾ ĐẾN NGUYỆN VỀ TỶ CĂN (LỖ MŨI)"],["p","Ngày nay nguyện xin đại chúng đồng nghiệp trong đạo tràng rộng ra khắp hết thảy chúng sanh trong bốn loài sáu đường, cùng tận mười phương, từ nay trở đi cho đến ngày thành Phật:"],["p","- Mũi thường không nghe mùi ăn uống ngon lành do sự sát sinh hại mạng."],["p","- Mũi thường không nghe mùi săn bắn, thiêu đốt, sát hại chúng sanh."],["p","- Mũi thường không nghe mùi ba mươi sáu vật trong thân thể như đãy da hôi thối."],["p","- Mũi thường không nghe mùi gấm vóc lụa là mê hoặc lòng người."],["p","- Mũi thường không nghe mùi lột da, xẻ thịt, thui nướng trong địa ngục."],["p","- Mũi thường không nghe mùi ngạ quỷ đói khát ăn uống phẩn uế máu mủ tanh hôi."],["p","- Mũi thường không nghe mùi tanh tao bất tịnh của súc sinh."],["p","- Mũi thường không nghe mùi hôi hám của bệnh nhân lở loét nằm trên giường chiếu ô uế, không người trông nom săn sóc, không thể lại gần."],["p","- Mũi thường không nghe mùi hôi thối của thây ma sình chướng lên, sâu dòi rứt rỉa thối nát."],["p","Nguyện xin chúng sanh trong sáu đường từ nay trở đi:"],["p","- Mũi thường được ngửi mùi hương chiên đàn vô giá, thơm khắp mười phương thế giới."],["p","- Mũi thường được ngửi mùi hương thơm của hoa ưu đàm bát năm sắc."],["p","- Mũi thường được ngửi mùi hương thơm của các thứ hoa trong vườn hoan hỷ của chư thiên."],["p","- Mũi thường được ngửi mùi hương thơm trong thời thuyết pháp ở cung trời Đâu Suất."],["p","- Mũi thường được ngửi mùi hương trong khi chư Thiên chơi giỡn ở Diệu Pháp đường."],["p","- Mũi thường được ngửi mùi hương ngũ giới, thập thiện, lục niệm của chúng sanh tu hành ở mười phương."],["p","- Mũi thường được ngửi mùi hương của những người tu hành thất phương tiện, thập lục hạnh."],["p","- Mũi thường được ngửi mùi hương phước đức của các vị Bích Chi Phật, của các bậc hữu học, vô học trong mười phương."],["p","- Mũi thường được ngửi mùi hương của các bậc Tứ Hướng, Tứ Quả chứng pháp vô lậu."],["p","- Mũi thường được ngửi mùi hương của vô lượng Bồ Tát lên các địa vị Hoan Hỷ, Ly Cấu, Phát Quang, Diệm Huệ, Nan thắng, Hiện Tiền, Viễn Hành, Bất động, Thiện Huệ, Pháp Vân."],["p","- Mũi thường được ngửi mùi hương năm phần Pháp thân: Giới, định, huệ, giải thoát, giải thoát tri kiến của các Thánh nhân."],["p","- Mũi thường được ngửi mùi hương Bồ đề của chư Phật."],["p","- Mũi thường được ngửi mùi hương của ba mươi bảy phẩm trợ đạo, mười hai nhân duyên quán, và sáu pháp Ba la mật."],["p","- Mũi thường được ngửi mùi hương của các pháp đại bi, tam niệm, thập lực, tứ vô sở úy và mười tám pháp bất cộng của chư Phật."],["p","- Mũi thường được ngửi mùi hương của tám vạn bốn ngàn pháp Ba la mật."],["p","- Mũi thường được ngửi mùi hương của Pháp thân thường trú vô lượng nhiệm mầu cùng khắp mười phương của chư Phật."],["p","Đã phát nguyện về tỷ căn rồi, đại chúng cùng nhau chí thành đảnh lễ Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Lê Đà Pháp Phật.","Nam mô Ứng Cúng Dường Phật.","Nam mô Độ Ưu Phật.","Nam mô Nhạo An Phật.","Nam mô Thế Ý Phật.","Nam mô Ái Thân Phật.","Nam mô Diệu Túc Phật.","Nam mô Ưu Bác La Phật.","Nam mô Hoa Anh Phật.","Nam mô Vô Biên Biện Quang Phật.","Nam mô Tín Thánh Phật.","Nam mô Đức Tinh Tấn Phật.","Nam mô Diệu Đức Bồ Tát.","Nam mô Kim Cang Tạng Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo. Nguyện xin Tam Bảo dùng sức từ bi, đồng gia tâm nhiếp thọ, khiến cho đệ tử tên... được như sở nguyện, mãn Bồ đề nguyện."],["p","THỨ LẠI PHÁT NGUYỆN VỀ THIỆT CĂN"]],"p":"Quyển Thứ Mười"},{"t":"(Lưỡi)","b":[["p","Lại nguyện xin ngày nay đại chúng đồng nghiệp trong đạo tràng, rộng ra cho đến hết thảy chúng sanh trong sáu đường khắp mười phương, từ nay trở đi cho đến ngày thành đạo:"],["p","- Lưỡi không nếm vị nơi thân thể của hết thảy chúng sanh bị thương hay bị giết."],["v",["- Lưỡi không nếm hết thảy vị bị tự tử.","- Lưỡi không nếm vị huyết tủy của các loài chúng sanh.","- Lưỡi không nếm vị thuốc độc của oan gia đối đầu.","- Lưỡi không nếm vị ngon lành hay sinh tham ái phiền não.","Nguyện xin:","- Lưỡi thường nếm trăm món cam lồ mỹ vị.","- Lưỡi thường hay nếm vị ăn uống tự nhiên của chư Thiên."]],["p","- Lưỡi thường hay nếm vị cơm thơm ngon ở cõi Phật Hương Tích."],["p","- Lưỡi thường hay nếm các vị ăn uống của chư Phật."],["p","- Lưỡi thường hay nếm các vị đồ ăn do sức huân tu giới, định, huệ, của Pháp thân hiện ra."],["p","- Lưỡi thường hay nếm pháp hỷ, thiền duyệt thực."],["p","- Lưỡi thường hay nếm vị ngon ngọt điều hòa của vô lượng công đức bồi bổ tư nhuần huệ mạng."],["p","- Lưỡi thường hay nếm vị giải thoát bình đẳng một màu."],["p","- Lưỡi thường hay nếm vị thù thắng nhiệm mầu, tối thượng an vui Niết Bàn của chư Phật."],["p","Đã phát nguyện về thiệt căn rồi, đại chúng cùng nhau chí thành đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Chơn Thật Phật.","Nam mô Thiên Chủ Phật.","Nam mô Lạc Cao Âm Phật.","Nam mô Tín Tịnh Phật.","Nam mô Bà Kỳ La Đà Phật.","Nam mô Phước Đức Ý Phật.","Nam mô Diệm Xí Phật.","Nam mô Vô Biên Đức Phật.","Nam mô Tụ Thành Phật.","Nam mô Sư Tử Du Phật.","Nam mô Bất Động Phật.","Nam mô Tín Thanh Tịnh Phật.","Nam mô Hư Không Tạng Bồ Tát.","Nam mô Tát Đà Ba Luân Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin tam Bảo rũ lòng từ bi, thương xót che chở, khiến chúng con tên... được như sở nguyện, mãn Bồ đề nguyện."],["p","THỨ LẠI PHÁT NGUYỆN VỀ THÂN CĂN"],["p","Lại nguyện, ngày nay đại chúng đồng nghiệp trong đạo tràng, rộng ra cho đến hết thảy chúng sanh trong bốn loài, sáu đường ở khắp mười phương, từ nay trở đi cho đến ngày thành Phật:"],["p","- Thân thường không giác xúc các cảnh ngũ dục tà mỵ."],["p","- Thân thường không giác xúc các cảnh vạc nước sôi lò than nóng, nước giá lạnh trong các địa ngục."],["p","- Thân thường không giác xúc các cảnh ngạ quỷ đói khát, trên đầu lửa đốt, miệng nuốt nước đồng sôi, cháy nát tâm can, thân thể."],["p","- Thân thường không giác xúc các cảnh súc sinh bị lột da xẻ thịt đau đớn khổ sở."],["p","- Thân thường không giác xúc các cảnh khổ não, do bốn trăm lẻ bốn bệnh hoành hành."],["p","- Thân thường không giác xúc các cảnh đại hàn, đại nhiệt, không thể kham chịu."],["p","- Thân thường không giác xúc các cảnh muỗi, mòng, rận, chí, sâu, trùng cắn rứt."],["p","- Thân thường không giác xúc các cảnh dao gậy, thuốc độc làm hại."],["p","- Thân thường không giác xúc các cảnh đói khát khốn khổ đủ điều."],["v",["Nguyện xin:","- Thân thường giác xúc y phục nhiệm mầu của chư thiên.","- Thân thường giác xúc vị cam lồ tự nhiên."]],["p","- Thân thường giác xúc cảnh thanh lương, không lạnh, không nóng."],["p","- Thân thường giác xúc cảnh không đói, không khát, không bệnh, không não."],["p","- Thân thường giác xúc cảnh không dao gậy khổ sở."],["p","- Thân thường giác xúc cảnh thức ngủ đều yên ổn, không lo không sợ."],["p","- Thân thường giác xúc cảnh gió nhẹ thổi mát ở các cõi Tịnh độ của mười phương Phật."],["p","- Thân thường giác xúc cảnh tắm rửa thân tâm trong ao thất bảo ở các cõi Tịnh độ của mười phương Phật."],["p","- Thân thường giác xúc cảnh không đau khổ vì sinh, già, bệnh, chết."],["p","- Thân thường giác xúc cảnh thân bay đi nghe pháp với chư vị Bồ Tát một cách tự tại."],["p","- Thân thường giác xúc cảnh chư Phật nhập Niết Bàn cách tự tại."],["p","Đã phát nguyện về thân căn rồi, đại chúng cùng nhau chí thành đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Hạnh Minh Phật.","Nam mô Long Âm Phật.","Nam mô Trì Luân Phật.","Nam mô Tài Thành Phật.","Nam mô Thế Ái Phật.","Nam mô Pháp Danh Phật.","Nam mô Vô Lượng Bảo Minh Phật.","Nam mô Vân Tướng Phật.","Nam mô Huệ Đạo Phật.","Nam mô Diệu Hương Phật.","Nam mô Hư Không Âm Phật.","Nam mô Hư Không Phật.","Nam mô Việt Tam Giới Bồ Tát.","Nam mô Bạt Đà Bà La Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, đồng gia tâm phù hộ, nhiếp thọ, khiến chúng con tên... được như sở nguyện, mãn Bồ đề nguyện."]],"p":"Quyển Thứ Mười"},{"t":"Thứ Lại Phát Nguyện Về Ý Căn","b":[["p","Lại nguyện ngày nay đại chúng đồng nghiệp trong đạo tràng, rộng ra cho đến hết thảy chúng sanh trong bốn loài, sáu đường, ở khắp mười phương, từ nay trở đi cho đến ngày thành đạo:"],["p","- Ý thường được biết: Thân sát, đạo, dâm; khẩu vọng ngôn, ỷ ngữ, lưỡng thiệt, ác khẩu là hoạn nạn."],["p","- Ý thường được biết giết cha hại mẹ, giết A La Hán, làm thân Phật xuất huyết, phá sự hòa hiệp của chúng Tăng, hủy báng Tam Bảo, không tin nhân quả đều là tội đọa vô gián địa ngục."],["p","- Ý thường được biết người chết rồi không mất."],["p","- Ý tin có nhân quả và sự ứng báo."],["p","- Ý thường được biết xa ác tri thức, ưa gần thiện tri thức."],["p","- Ý thường được biết theo tà sư ngoại đạo là phi pháp."],["p","- Ý thường được biết các pháp tam lậu ngũ cái thập triền là hay chướng ngại đạo."],["p","- Ý thường được biết tam đồ là chỗ khổ báo kịch liệt, tàn khốc của sinh tử đáng sợ."],["p","Nguyện xin:"],["p","- Ý thường biết hết thảy chúng sanh đều có Phật tánh (tánh cách làm Phật)."],["p","- Ý thường biết chư Phật là Đấng Cha lành, là Đấng Đại Từ bi, là Đấng Vô thượng Y vương."],["p","- Ý thường biết hết thảy Tôn pháp là thuốc hay dùng trị bệnh của chúng sanh."],["p","- Ý thường biết hết thảy Hiền Thánh là mẹ lành săn sóc bệnh hoạn cho chúng sanh."],["p","- Ý thường biết quy y Tam Bảo, thọ năm cấm giới, rồi tu thập thiện là những pháp hay chiêu tập quả báo tốt đẹp ở cõi người và cõi Trời."],["p","- Ý thường biết chưa khỏi sinh tử nên tu theo bảy pháp phương tiện, nên quán sát các pháp noãn đảnh v.v..."],["p","- Ý thường biết nên tu các pháp vô lậu, khổ nhẫn, mười sáu Thánh tâm thì trước phải tu mười sáu quán hạnh quán sát Tứ đế."],["p","- Ý thường biết Tứ đế là bình đẳng vô tướng cho nên chứng được tứ quả."],["p","- Ý thường biết tổng tướng biệt tướng của tất cả các pháp."],["p","- Ý thường biết mười hai nhân duyên, nhân quả ba đời, xoay vần luân chuyển không bao giờ ngừng."],["p","- Ý thường biết tu hành lục độ, tám vạn tế hạnh."],["p","- Ý thường biết đoạn trừ tám vạn bốn ngàn trần lao."],["p","- Ý thường biết thể nhập được vô sinh nhẫn thì quyết định dứt được sinh tử."],["p","- Ý thường biết được thứ lớp, đầy đủ phẩm vị, giai cấp của các bậc Thập trụ Bồ Tát."],["p","- Ý thường biết dùng tâm Kim cang đoạn trừ si ám vô minh mà chứng được quả Phật vô thượng."],["p","- Ý thường biết thể tánh một phen chiếu sáng cùng cực rồi thì muôn đức đầy đủ hoạn lụy nhiều kiếp đều sạch hết, chứng quả Đại Niết Bàn."],["p","- Ý thường biết được mười trí lực, bốn vô úy, mười tám bất cộng, vô lượng công đức, vô lượng trí huệ, vô lượng thiện pháp của chư Phật."],["p","Đã phát nguyện về ý căn rồi, đại chúng cùng nhau chí thành đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Thiên Vương Phật.","Nam mô Châu Tịnh Phật.","Nam mô Thiện Tài Phật.","Nam mô Đăng Diệm Phật.","Nam mô Bảo Âm Thanh Phật.","Nam mô Nhơn Chủ Vương Phật.","Nam mô La Hầu Thủ Phật.","Nam mô An Ẩn Phật.","Nam mô Sư Tử Ý Phật.","Nam mô Bảo Danh Văn Phật.","Nam mô Đắc Lợi Phật.","Nam mô Biến Kiến Phật.","Nam mô Mã Minh Bồ Tát.","Nam mô Long Thọ Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, đồng gia tâm che chở nhiếp thọ, khiến chúng con tên... được như sở nguyện, mãn bồ đề nguyện."]],"p":"Quyển Thứ Mười"},{"t":"Thứ Lại Phát Nguyện Về Khẩu Nghiệp","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng, rộng ra cho đến hết thảy chúng sanh trong bốn loài, sáu đường khắp mười phương, từ nay trở đi cho đến ngày thành Phật:"],["p","- Miệng thường không hủy báng Tam Bảo."],["p","- Miệng không hủy báng người hoằng thông giáo pháp, không nói việc xấu ác của người ấy."],["p","- Miệng không nói làm lành không được quả báo an vui, làm ác không được quả báo khổ sở."],["p","- Miệng không nói người chết mất hẳn, không chuyển sinh, không luân hồi."],["p","- Miệng không nói việc không lợi ích, có tổn hại cho người."],["p","- Miệng không nói kinh sách của tà ma, ngoại đạo làm ra."],["p","- Miệng không dạy người làm mười ác nghiệp, không dạy người tạo tội ngũ nghịch."],["p","- Miệng không tán dương người làm ác."],["p","- Miệng không nói việc chơi cười giỡn cợt, không lý thú của thế tục."],["p","- Miệng không dạy người tin theo thầy tà, quỷ thần, đồng bóng."],["p","- Miệng không bình luận nhân vật xấu tốt."],["p","- Miệng không giận hờn mắng nhiếc cha mẹ, Sư trưởng, thiện tri thức."],["p","- Miệng không khuyên người tạo tội, không cấm người làm phước."],["p","Nguyện xin:"],["p","- Miệng thường tán thán Tam Bảo, tán thán người hoằng thông giáo pháp, nêu cao công đức truyền giáo ấy, chỉ bày quả báo thiện ác lành dữ cho người."],["p","- Miệng thường giác ngộ cho người biết rằng thân này chết rồi, thần thức không mất."],["p","- Miệng thường thốt ra lời lành khiến người nghe được lợi ích."],["p","- Miệng thường diễn nói mười hai bộ Kinh của Phật."],["p","- Miệng thường nói hết thảy chúng sanh đều có Phật tánh, sẽ được thường, lạc, ngã, tịnh."],["p","- Miệng thường dạy người hiếu dưỡng cha mẹ, kính thờ Sư trưởng."],["p","- Miệng thường khuyên người quy y Tam Bảo, thọ trì năm giới, thập thiện, lục niệm."],["p","- Miệng thường tán tụng Kinh điển, nói các việc lành."],["p","- Miệng thường dạy người gần thiện tri thức, xa ác tri thức."],["p","- Miệng thường nói vô lượng công đức của hàng Thập trụ Bồ Tát và Phật địa."],["p","- Miệng thường khuyên người tu hạnh Tịnh độ trang nghiêm quả Phật."],["p","- Miệng thường dạy người lễ bái Tam Bảo."],["p","- Miệng thường dạy người xây dựng hình tượng, làm các việc cúng dường."],["p","- Miệng thường dạy người làm các việc thiện gấp như cứu lửa cháy đầu."],["p","- Miệng thường dạy người cứu giúp người nghèo khổ, không tạm nghỉ."],["p","Đã phát nguyện về miệng rồi, đại chúng cùng nhau chí thành đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Thế Hoa Phật.","Nam mô Cao Đảnh Phật.","Nam mô Vô Biên Biện Tài Thành"]],["v",["Phật.","Nam mô Sai Biệt Tri Kiến Phật.","Nam mô Sư Tử Nha Phật.","Nam mô Lê Đà Bộ Phật.","Nam mô Phước Đức Phật.","Nam mô Pháp Đăng Cái Phật.","Nam mô Mục Kiền Liên Phật.","Nam mô Vô Ưu Quốc Phật.","Nam mô Ý Tư Phật.","Nam mô Lạc Bồ Đề Phật.","Nam mô Sư Tử Du Hí Bồ Tát.","Nam mô Sư Tử Phấn Tấn Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo, rũ lòng từ bi che chở nhiếp thọ, khiến chúng con tên... được như sở nguyện, mãn Bồ đề nguyện."]],"p":"Quyển Thứ Mười"},{"t":"Chư Hạnh Pháp Môn","b":[["p","Lại nguyện xin hết thảy chúng sanh trong bốn loài sáu đường khắp mười phương, từ khi phát nguyện này về sau, tất cả chúng sanh đều đầy đủ chư hạnh pháp môn:"],["p","- Muốn có lòng tin Tam Bảo cương quyết thì có cung kỉnh pháp môn."],["p","- Muốn không lòng nghi ngờ thì có kiên cố pháp môn."],["p","- Muốn đoạn sự sinh tâm làm ác thì có Sám hối pháp môn."],["p","- Muốn lời nguyện được thanh tịnh thì có niệm hối pháp môn."],["v",["- Muốn không hủy phá ba nghiệp thì có hộ thân pháp môn.","- Muốn tịnh bốn nghiệp thì có hộ khẩu pháp môn.","- Muốn tâm thanh tịnh thì có hộ ý pháp môn.","- Muốn nguyện vọng được đầy đủ thì có Bồ đề pháp môn.","- Muốn tất cả không hại thì có bi tâm pháp môn.","- Muốn lập đức hóa độ thì có từ tâm pháp môn.","- Muốn không hủy báng người khác thì có hoan hỷ pháp môn."]],["p","- Muốn không khinh dễ người khác thì có chí thành pháp môn."],["v",["- Muốn diệt ba đường ác thì có Tam Bảo pháp môn.","- Muốn hoàn toàn không giả dối thì có chơn thật pháp môn.","- Muốn không lòng bỉ ngã thì có xả hại pháp môn.","- Muốn không do dự thì có tâm bỏ sự ràng buộc pháp môn."]],["p","- Muốn diệt trừ đấu tranh, kiện tụng thì có ý vô tránh pháp môn."],["p","- Muốn tu hạnh bình đẳng thì có ứng chánh pháp môn."],["p","Lại nguyện xin cho hết thảy chúng sanh đầy đủ vô lượng pháp môn sau này:"],["v",["- Tâm xu hướng pháp môn là quán tâm như huyễn.","- Ý đoạn pháp môn là xả bỏ cội gốc bất thiện.","- Thần túc pháp môn là thân tâm đều khinh tiện.","- Tín căn pháp môn là nguyện không thối chuyển.","- Tấn căn pháp môn là không xả pháp lành.","- Niệm căn pháp môn là khéo tạo đạo nghiệp.","- Định căn pháp môn là nhiếp tâm vào chánh đạo."]],["p","- Huệ căn pháp môn là quán lý vô thường, khổ, không v.v..."],["v",["- Tín lực pháp môn là vượt hẳn oai thế của ma vương.","- Tấn lực pháp môn, là một phen tới không bao giờ lui.","- Niệm lực pháp môn là chưa từng bỏ quên thiện niệm.","- Định lực pháp môn là diệt các vọng tưởng."]],["p","- Huệ lực pháp môn là xoay vần qua lại (vận chuyển tư tưởng)."],["p","- Truy giác pháp môn là tích cực tu hành Phật đạo."],["p","- Chánh định pháp môn là nhập được tam muội."],["p","- Tịnh tánh pháp môn là không ưa tu theo các thừa giáo pháp khác."],["p","Nguyện xin cho chúng sanh đều được một trăm lẻ tám pháp môn như vậy của Bồ Tát Ma ha tát; thanh tịnh Phật độ, khuyến hóa người xan tham, tật đố, thảy đều thoát khỏi tám nạn; thảy đều nhiếp phục được người tranh tụng, sân nhuế; siêng làm các việc lành, khéo nhiếp phục người lười biếng; thảy đều được định ý thần thông; thâu nhiếp các loạn tưởng, không cho vọng động."],["p","Đã phát nguyện về ý căn rồi, đại chúng lại cùng nhau chí thành đảnh lễ quy y Thế gian Đại Từ Bi phụ:"],["v",["Nam mô Di Lặc Phật.","Nam mô Thích Ca Mâu Ni Phật.","Nam mô Pháp Thiên Kỉnh Phật.","Nam mô Đoạn Thế Lực Phật.","Nam mô Cực Thế Lực Phật.","Nam mô Huệ Hoa Phật.","Nam mô Kiên Âm Phật.","Nam mô An Lạc Phật.","Nam mô Diệu Nghĩa Phật.","Nam mô Ái Tịnh Phật.","Nam mô Tàm Quý Nhan Phật.","Nam mô Diệu Kế Phật.","Nam mô Dục Lạc Phật.","Nam mô Lâu Chí Phật.","Nam mô Dược Vương Bồ Tát.","Nam mô Dược Thượng Bồ Tát.","Nam mô Vô Biên Thân Bồ Tát.","Nam mô Quán Thế Âm Bồ Tát."]],["p","Lại quy y như vậy mười phương tận hư không giới hết thảy Tam Bảo."],["p","Nguyện xin Tam Bảo rũ lòng từ bi, cứu hộ nhiếp thọ khiến các chúng sanh trong bốn loài, sáu đường, khắp ba cõi, nhờ sức công đức nhân duyên phát tâm, phát nguyện của đạo tràng sám hối này, đều đầy đủ phước đức trí huệ, nhờ sức thần thông mà được tùy tâm tự tại."]],"p":"Quyển Thứ Mười"},{"t":"Chương Thứ Bốn Mươi Phần Chúc Lụy","b":[["p","Ngày nay đại chúng đồng nghiệp trong đạo tràng đã vì chúng sanh trong bốn loài, sáu đường mà phát thệ nguyện rồi, thứ lại xin đem các chúng sanh ấy phó chúc cho các vị đại Bồ Tát. Nguyện xin chư đại Bồ Tát rũ lòng từ bi, đồng gia tâm nhiếp thọ cho chúng sanh được nhờ công đức sám hối phát nguyện này."],["p","Lại nguyện xin rũ lòng từ bi niệm lực khiến hết thảy chúng sanh ấy đều muốn cầu vô thượng phước điền, hết lòng tin rằng: “Cúng dường Phật được vô lượng phước báu”. Khiến biết hết thảy chúng sanh một lòng hướng về Đức Phật được vô lượng quả báo thù thắng thanh tịnh, nguyện xin cho chúng sanh đối với các Phật sự không có tâm keo rít mà phát tâm đại bố thí, không luyến tiếc gì."],["p","Lại nguyện xin hết thảy chúng sanh đối với hết thảy cơ sở Phật giáo, phát tâm làm các việc phước điền Vô thượng, xa lìa hạnh nguyện của Tiểu thừa, tu Bồ Tát đạo được vô ngại giải thoát, thành nhất thiết chủng trí của chư Phật."],["p","Lại nguyện xin hết thảy chúng sanh đối với các cơ sở Phật giáo trồng vô lượng căn lành, được vô lượng phước đức, trí huệ của Phật."],["p","Lại nguyện cho hết thảy chúng sanh thâu nhiếp lấy trí huệ sâu xa, nhìn vào Vô thượng trí vương được đầy đủ thanh tịnh."],["p","Lại nguyện cho hết thảy chúng sanh được thần lực vô ngại tự tại, dạo chơi khắp hết thảy chỗ của chư Phật đã đến."],["p","Lại nguyện cho hết thảy chúng sanh nhiếp thủ lấy giáo lý Đại thừa, được vô lượng chủng trí, an trú bất động."],["p","Lại nguyện cho hết thảy chúng sanh thành tựu hoàn toàn phước điền đệ nhất, hay xuất sinh ra hết thảy trí huệ."],["p","Lại nguyện cho hết thảy, chúng sanh đối với hết thảy chư Phật không có tâm hiềm khích, ân hận mà lại trồng các căn lành, tham cầu trí huệ của Phật."],["p","Lại nguyện cho hết thảy chúng sanh dùng được phương tiện nhiệm mầu, đi đến hết thảy cõi nước trang nghiêm của chư Phật; trong một niệm đã đi sâu vào pháp giới không biết mỏi mệt."],["p","Lại nguyện cho hết thảy chúng sanh được thân tướng trang nghiêm, không ai có thể so sánh kịp, hay đi khắp hết thảy mười phương thế giới không nhàm chán."],["p","Lại nguyện cho hết thảy chúng sanh đều thành tựu được thân tướng rộng lớn, đi lại tùy ý; đều được thần lực của Phật trang nghiêm hoàn toàn cảnh giới giải thoát, trong khoảng một niệm thực hiện được rõ ràng sức thần thông tự tại của chư Phật khắp hư không pháp giới."],["p","Đã phát những đại nguyện như thế ấy rồi, rộng lớn như pháp tánh, cứu cánh như hư không; nguyện cho các chúng sanh đồng được như sở nguyện, mãn Bồ đề nguyện. Đại chúng cùng nhau chí thành đảnh lễ Tam Bảo."],["p","Thoảng hoăc̣ như đệ tử tên... bị các quả báo khổ sở không thể cứu chúng sanh, nguyện xin đem các chúng sanh ấy phó thác cho:"],["p","- Vô lượng vô biên, tận hư không giới Pháp thân Bồ Tát."],["p","- Vô lượng vô biên, tận hư không giới vô lậu sắc thân Bồ Tát."],["v",["- Vô lượng vô biên, tận hư không giới phát tâm Bồ Tát.","- Hưng Chánh Pháp Mã Minh Đại sư Bồ Tát.","- Hưng Tượng Pháp Long Thọ Đại sư Bồ Tát.","- Mười phương tận hư không giới Vô Biên Thân Bồ Tát.","- Mười phương tận hư không giới Quán Thế Âm Bồ Tát.","Văn Thù Sư Lợi Bồ Tát.","Phổ Hiền Bồ Tát.","Sư Tử Du Hí Bồ Tát.","Sư Tử Phấn Tấn Bồ Tát.","Sư Tử Phan Bồ Tát.","Sư Tử Tác Bồ Tát.","Kiện Dõng Tinh Tấn Bồ Tát.","Kim Cang Huệ Bồ Tát.","Khí Ấm Cái Bồ Tát.","Tịch Căn Bồ Tát.","Huệ Thượng Bồ Tát.","Thường Bất Ly Thế Bồ Tát.","Dược Vương Bồ Tát.","Dược Thượng Bồ Tát.","Hư Không Tạng Bồ Tát.","Kim Cang Tạng Bồ Tát.","Thường Tinh Tấn Bồ Tát.","Bất Hưu Tức Bồ Tát.","Diệu Âm Bồ Tát.","Diệu Đức Bồ Tát.","Bảo Nguyệt Bồ Tát.","Nguyệt Quang Bồ Tát.","Bạt Đà Ba Luân Bồ Tát.","Việt Tam Giới Bồ Tát."]],["p","Lại xin phú chúc hết thảy chúng sanh ấy cho tất cả mười phương tận hư không giới chư đại Bồ Tát."],["p","Nguyện xin chư đại Bồ Tát Ma ha tát dùng bổn thệ nguyện lực, thế độ chúng sanh lực mà nhiếp thọ mười phương vô cùng, vô tận hết thảy chúng sanh; nguyện xin chư Bồ Tát Ma ha tát không xả bỏ chúng sanh, xem chúng sanh đồng như thiện tri thức, không có quan niệm chia rẽ; nguyện xin cho chúng sanh biết ơn chư Bồ Tát, thân cận cúng dường chư Bồ Tát. Nguyện xin chư Bồ Tát thương xót nhiếp thọ, khiến các chúng sanh ấy được tâm ngay thẳng, theo dõi Bồ Tát, không xa lìa Bồ Tát. Nguyện xin cho chúng sanh biết vâng lời Bồ Tát dạy bảo, không dám trái nghịch; được tâm kiên cố, không bỏ thiện tri thức, xa lìa tội lỗi tâm không thối chuyển; khiến chúng sanh vì thiện tri thức, không tiếc thân mạng, xả bỏ hết thảy, không trái ý thiện tri thức. Nguyện cho chúng sanh tu tập đại từ, xa lìa các điều ác, nghe Chánh pháp của Phật đều hay thọ trì; nguyện khiến chúng sanh thiện căn nghiệp báo đồng như Bồ Tát; hạnh nguyện đồng như Bồ Tát; rốt ráo thanh tịnh, đầy đủ thần thông, tùy ý tự tại; tu đạo Đại thừa cho đến khi chứng được hoàn toàn nhất thiết chủng trí; ở trong thời gian ấy không có lười biếng; cỡi nghiệp trí huệ đến chỗ an ổn, được vô ngại đạo, hoàn toàn tự tại. Trước hết là quy y Tam Bảo, đoạn nghi, sinh tín, sám hối, phát tâm, hiển quả báo, xuất địa ngục, giải oan, tự khánh (vui mừng) phát nguyện, hồi hướng, cho đến cuối cùng là phần chúc lụy này, như thế, có bao nhiêu công đức đều đem bố thí cho hết thảy chúng sanh, tận hư không giới, khắp mười phương. Nguyện xin Đức Di Lặc Thế Tôn chứng giám cho chúng con, mười phương chư Phật, thương xót che chở cho chúng con. Những điều chúng con sám hối đều được thành tựu; nguyện cho chúng sanh đồng với Từ Bi phụ, sinh đến cõi này tham dự hội Phật thuyết pháp đầu tiên; nghe pháp ngộ đạo, công đức trí huệ hết thảy đều đầy đủ, cùng với chư Bồ Tát, bình đẳng không sai khác, nhập Kim cang tâm, thành bậc Chánh giác."]],"p":"Quyển Thứ Mười"},{"t":"Tán Phật Chú Nguyện","b":[["p","Đa già a già độ, a la ha tam miệu tam Phật đà, mười hiệu đầy đủ, độ người vô lượng, dứt sạch sinh tử."],["p","Nguyện xin nhờ công đức nhân duyên sám hối hôm nay cho các chúng sanh và mọi người đều được hoàn toàn như sở nguyện, mãn bồ đề nguyện:"],["p","1) Đệ tử chúng con tên... những lời thệ nguyện hôm nay đã phát ra, nguyện xin nguyện nào cũng đồng như mười phương tận hư không giới hết thảy chư Phật, chư đại Bồ Tát đã phát thệ nguyện."],["p","2) Chư Phật, chư đại Bồ Tát đã có phát thệ nguyện không thể cùng tận, chúng con hôm nay thệ nguyện cũng như vậy, rộng như pháp tánh, cứu cánh như hư không; cùng tận đời vị lai, hết thảy số kiếp, chúng sanh không thể tận, chúng con nguyện cũng không thể tận."],["p","3) Thế giới không thể tận, chúng con nguyện cũng không thể tận."],["p","4) Hư không không thể tận, chúng con nguyện cũng không thể tận."],["p","5) Pháp tánh cũng không thể tận, chúng con nguyện cũng không thể tận."],["p","6) Niết bàn không thể tận, chúng con nguyện cũng không thể tận."],["p","7) Phật ra đời không thể tận, chúng con nguyện cũng không thể tận."],["p","8) Trí huệ của chư Phật không thể tận, chúng con nguyện cũng không thể tận."],["p","9) Tâm tưởng biết không thể tận, chúng con nguyện cũng không thể tận."],["p","10) Trí sinh khởi không thể tận, chúng con nguyện cũng không thể tận, thế gian đạo chủng, pháp đạo chủng, trí huệ đạo chủng không thể tận, chúng con nguyện cũng không thể tận."],["p","Nếu mười điều ấy có thể cùng tận, lời nguyện của chúng con mới có thể cùng tận."],["p","Mười điều ấy không cùng tận, nguyện chúng con không bao giờ cùng tận."],["p","Hết thảy đều Hòa nam Tam thừa Thánh chúng."],["v",["Lương Hoàng Bảo Sám,","Vạn đức hồng danh,","Linh văn thập quyển tối hoằng thâm, Tự tự miễn tai truân,","Đảnh lễ Phật danh,","Tiêu tai bảo an ninh.","Nam mô Pháp Vân Địa Bồ Tát Ma Ha Tát. (3 lần)"]],["h","Cung Văn"],["p","Thập thân tướng hảo, nguy nguy bất động tử kim sơn, thập hiệu Năng Nhân, đản đản thường viên ngân hán nguyệt."],["p","Thần cơ phổ ứng, diệu hóa vô phương."],["p","Nguyện thử vô ngại chi đại bi, chứng thử hậu thời chi Phật sự."],["p","Thượng lai phụng vì cầu sám đệ tử đẳng... tu sùng Từ Bi Đạo Tràng Sám Pháp kim đương đệ thập quyển, thiện quả châu long, chúng đẳng ư kỳ đàn nội, nhiên đăng phát diệm, tán hoa trang nghiêm, thước minh hiến quả, thiết cúng vận tâm."],["p","Phu dương chủng chủng chi công huân, kỉnh lễ trần trần chi Phật sự. Phát ân trọng tâm, bỉnh thành hồi hướng. Thập phương Tam thế Phật hoa tạng chúng hồng văn, ngũ nhãn Bích Chi ca, lục thông A La Hán, thiên chơn địa Thánh, thủy triết dương hiền, tứ phủ Diêm La, thập phương huyền tạo tịnh nguyện thùy giám thắng nhân."],["p","Thượng lai phụng vì cầu sám đệ tử đẳng... tẩy không vi tế tội khiên, thành tựu vô biên phước lợi. Phục nguyện đốn khử thập sự, hánh thoát thập triền, viên phát thập tâm. Thập nguyện mãn nhi chơn không nguyệt lãng, tu hành thập địa, thập chướng đoạn, nhi giác uyển hoa khai. Trần trần lao giải thoát chi huyền môn, xứ xứ xiển Tỳ lô chi tánh hải. Oan thân phổ lợi, phàm Thánh đồng tư, câu thừa sám hối chi thiện duyên cộng chứng chơn thường chi diệu lý. Tuy tắc vi văn sám hối, thành khủng tế hoặc vị trừ, tái lao tôn chúng, câu trần sám hối."],["p","Nam mô Sám Hối Sư Bồ Tát Ma Ha Tát. (3 lần)"],["p","Lương Hoàng Bảo Sám, thập quyển công đức lực nguyện diệt đệ tử đẳng... thập phương tội, thân chứng Bồ Tát Pháp Vân Địa."],["v",["Sám văn cử xứ tội hoa phi.","Giải liễu oan, sám liễu tội,","Tiêu tai tăng phước thọ,","Thoát khổ sinh Đao Lợi.","Giải liễu oan, sám liễu tội,","Tiêu diêu trực nhập Long Hoa Hội.","Long Hoa tam hội nguyện tương"]],["v",["phùng.","Di Lặc Phật tiền thân thọ ký.","Nam mô Long Hoa Hội Bồ Tát Ma Ha Tát. (3 lần)"]],["v",["Lương Hoàng Bảo Sám,","Thập quyển dĩ toàn châu,","Hồi hướng tứ ân tịnh tam hữu,","Bái sám chúng đẳng... tăng phước"]],["v",["thọ.","Nguyện tương pháp thủy tẩy khiên"]],["v",["vưu.","Duy nguyện vong giả vãng Tây du.","Pháp Vân Địa Bồ Tát","Duy nguyện ai nạp thọ.","Nam mô Pháp Vân Địa Bồ Tát Ma Ha Tát. (3 lần)"]],["p","Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh..."]],"p":"Quyển Thứ Mười"},{"t":"Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh","b":[["p","Quán Tự Tại Bồ Tát hành thâm Bát Nhã Ba La Mật Đa thời, chiếu kiến ngũ uẩn giai không độ nhứt thiết khổ ách."],["p","Xá Lợi Tử! Sắc bất dị không, không bất dị sắc, sắc tức thị không, không tức thị sắc, thọ, tưởng, hành, thức diệc phục như thị."],["p","Xá Lợi Tử! Thị chư pháp không tướng, bất sanh, bất diệt, bất cấu, bất tịnh, bất tăng, bất giảm. Thị cố không trung vô sắc, vô thọ, tưởng, hành, thức, vô nhãn, nhĩ, tỷ, thiệt, thân, ý, vô sắc, thinh, hương, vị, xúc, pháp, vô nhãn giới, nãi chí vô ý thức giới, vô vô minh diệc vô vô minh tận, nãi chí vô lão tử diệc, vô lão tử tận, vô khổ, tập, diệt, đạo, vô trí diệc vô đắc. Dĩ vô sở đắc cố, Bồ đề tát đỏa y Bát Nhã Ba La Mật Đa cố, tâm vô quái ngại, vô quái ngại cố, vô hữu khủng bố, viễn ly điên đảo mộng tưởng cứu cánh Niết Bàn. Tam thế chư Phật y Bát Nhã Ba La Mật Đa cố, đắc a nậu đa la tam miệu tam bồ đề. Cố tri Bát Nhã Ba La Mật Đa, thị đại thần chú, thị đại minh chú, thị vô thượng chú, thị vô đẳng đẳng chú, năng trừ nhứt thiết khổ, chơn thật bất hư. Cố thuyết Bát Nhã Ba La Mật Đa chú. Tức thuyết chú viết:"],["p","“Yết đế yết đế, ba la yết đế, ba la tăng yết đế, bồ đề tát bà ha.” (3 lần)"]],"p":"Quyển Thứ Mười"},{"t":"Vãng Sanh Quyết Định Chơn Ngôn","b":[["p","Nam mô a di đa bà dạ, đa tha già đa dạ, đa địa dạ tha. A di rị đô bà tỳ, a di rị đa tất đam bà tỳ, a di rị đa tỳ ca lan đế, a di rị đa tỳ ca lan đa, dà di nị dà dà na, chỉ đa ca lệ ta bà ha. (3 lần)"],["v",["A Di Đà Phật thân kim sắc,","Tướng hảo quang minh vô đẳng luân,","Bạch hào uyển chuyển ngũ Tu di,","Cám mục trừng thanh tứ đại hải,","Quang trung hóa Phật vô số ức,","Hóa Bồ tát chúng diệc vô biên,","Tứ thập bát nguyện độ chúng sinh,","Cửu phẩm hàm linh đăng bỉ ngạn.","Nam mô Tây phương Cực Lạc thế giới, đại"]],["v",["từ, đại bi A Di Đà Phật.","Nam mô A Di Đà Phật. (108 lần)","Nam mô Quán Thế Âm Bồ Tát. (3 lần)","Nam mô Đại Thế Chí Bồ Tát. (3 lần)","Nam mô Địa Tạng Vương Bồ Tát. (3 lần)","Nam mô Thanh Tịnh Đại Hải Chúng Bồ"]],["p","Tát. (3 lần)"]],"p":"Quyển Thứ Mười"},{"t":"Sám Thập Phương","b":[["v",["Thập phương tam thế Phật,","A Di Đà đệ nhất,","Cửu phẩm độ chúng sanh,","Oai đức vô cùng cực,","Ngã kim đại quy y,","Sám hối tam nghiệp tội.","Phàm hữu chư phước thiện.","Chí tâm dụng hồi hướng.","Nguyện đồng niệm Phật nhơn,","Cảm ứng tùy thời hiện.","Lâm chung Tây phương cảnh,","Phân minh tại mục tiền.","Kiến văn giai tinh tấn,","Đồng sanh Cực Lạc quốc,","Kiến Phật liễu sanh tử,","Như Phật độ nhứt thiết.","Vô biên phiền não đoạn,","Vô lượng pháp môn tu,","Thệ nguyện độ chúng sanh,","Tổng giai thành Phật đạo.","Hư không hữu tận, ngã nguyện vô cùng,","Tình dữ vô tình, đồng viên chủng trí."]]],"p":"Quyển Thứ Mười"},{"t":"Hồi Hướng","b":[["v",["Sám hối công đức thù thắng hạnh,","Vô biên thắng phước giai hồi hướng.","Phổ nguyện pháp giới chư chúng sanh,","Tốc vãng vô lượng quang Phật sát.","Nguyện tiêu tan chướng trừ phiền não,","Nguyện đắc trí tuệ chơn minh liễu.","Phổ nguyện tội chướng tất tiêu trừ,","Thế thế thường hành Bồ tát đạo.","Nguyện sanh Tây phương Tịnh độ trung,","Cửu phẩm liên hoa vi phụ mẫu,","Hoa khai kiến Phật ngộ vô sanh.","Bất thối Bồ tát vi bạn lữ,","Nguyện dĩ thử công đức,","Phổ cập ư nhứt thiết,","Ngã đẳng dữ chúng sanh,","Giai cộng thành Phật đạo."]],["h","Phục Nguyện"],["p","Phật nhựt tăng huy, Pháp luân thường chuyển, phong điều võ thuận, quốc thới dân an, thế giới hòa bình, Việt Nam thạnh trị."],["p","Kỳ nguyện: Hiện tại phụ mẫu, quá khứ phụ mẫu, pháp giới đa sanh phụ mẫu, tùng tư nhập Thánh siêu phàm; lụy thế oan thân từ thử thừa ân câu mông giải thoát. Cánh kỳ thân duyên tín thí, viễn cận đàn na, Sư trưởng, lương bằng, cửu huyền thất tổ, huynh đệ tỷ muội, nam nữ nội ngoại, bá thúc cô di, hiện tiền tội diệt phước sanh, một hậu vãng sanh Cực Lạc quốc, tứ sanh cửu hữu, lục đạo tam đồ câu triêm thắng ích. Lao ngục hệ bế, tù cấm già tỏa, tật bệnh tai ách, tận tiêu trừ, thân tâm an lạc, thường hoạch cát tường, viễn ly khổ ách."],["p","Phổ nguyện: Nhất thiết Phật tử xuất gia tại tục, phát tâm phát nguyện, xuất bản cập tái bản ấn tống. Lương Hoàng Bảo Sám Pháp văn, thân tâm an lạc, phước thọ tăng long, Bồ đề kiên cố, đạo nghiệp viên thành, đồng đăng giác ngạn..."],["p","Nam mô A Di Đà Phật. (đồng niệm)"],["p","Tự quy y Phật, đương nguyện chúng sanh, thể giải đại đạo, phát Vô thượng tâm."],["p","Tự quy y pháp, đương nguyện chúng sanh, thâm nhập Kinh tạng, trí huệ như hải."],["p","Tự quy y Tăng, đương nguyện chúng sanh, thống lý đại chúng, nhứt thiết vô ngại."]],"p":"Quyển Thứ Mười"},{"t":"Cụ Đàm Huyền Sám Hối","b":[["p","Năm 1957, cụ Đàm Huyền 90 tuổi. Cụ là thân sinh của đạo hữu Phạm Ất, tức là bác Mật, chủ tiệm Liên Phát, 20 đường Độc Lập, Nha Trang. Cụ đau bệnh già. Một hôm đang nằm nghỉ, bỗng nhiên cụ dạ lên ba tiếng thật lớn. Bác Mật dậy liền chạy đến hỏi."],["p","Cụ bảo: \"Con có nghe không? Phật đứng ngoài của sổ gọi ba, bảo ba có tội với bà nội của con, cho nên Phật chưa rước đi. Cần phải sám hối cho ba đã, đến ngày mai đúng bảy giờ sáng, Phật sẽ đến rước. Con nhớ lên chùa Hải Đức mời thầy Cả, (tức là Hòa thượng Hải Đức) hộ niệm cho ba."],["p","Cụ nói xong bác Mật cho các anh em đồng đạo biết và tổ chức đạo tràng Lương Hoàng Sám ngay. Từ ngày cụ yếu trong nhà bác Mật cũng đã có tụng kinh suốt đêm ngày. Vả lại, bình nhật cụ là đệ tử của Hòa thượng Hải Đức, cụ có niệm Phật nhiều. Chính tôi (dịch giả), cũng đã có khuyên cụ niệm Phật từ năm 1954."],["p","Các Phật tử luân phiên tụng niệm đến bảy giờ sáng. Cụ thoát thần cách nhẹ nhàng như lời Phật dạy, trước sự chứng minh và hộ niệm của Đại Đức Thích Chánh Trực (Đại diện cho Hòa thượng) mùi hương lạ thơm khắp nhà. Mọi người đều vui mừng, thấy việc chưa từng có."],["p","Riêng đạo hữu Hồi Xuân Đường, vị Đông y đã từng săn sóc cụ lâu nay, liền phát tâm Bồ đề, thỉnh tượng về nhà thờ Phật và bái sám."],["p","Dịch giả tường thuật."]],"p":"Quyển Thứ Mười"},{"t":"Mười Công Đức Ấn Tống Kinh","b":[["p","1. Đã lỡ phạm tội, nếu tội nhẹ thì liền được tiêu"],["v",["tan, nếu tội nặng thì được chuyển thành nhẹ.","2. Thường được thiện thần ủng hộ, tránh khỏi"]],["p","tất cả ôn dịch, đao binh, giặc cướp, tù tội, lửa cháy, nước trôi v.v..."],["p","3. Nhờ chánh pháp mà những kẻ oán thù với"],["p","mình trong kiếp trước được giải thoát nên tránh được sự khổ sở về tội báo thù."],["p","4. Ác quỷ Dạ xoa không thể xâm phạm, cọp đói,"],["v",["rắn độc không hại được.","5. Tâm được yên ổn, ngày không có sự nguy"]],["p","hiểm, đêm không có ác mộng, nhan sắc sáng sủa tươi tắn, khí lực dồi dào, việc làm tốt, lợi."],["p","6. Hết lòng phụng sự chánh pháp, tuy không"],["p","mong cầu nhưng cơm ăn áo mặc tự nhiên đầy đủ, gia đình hòa thuận phước thọ miên trường."],["p","7. Lời nói và việc làm, trời, người đều hoan hỷ;"],["p","đến nơi nào cũng được nhiều người kính mến. 8. Nếu ngu si thì chuyển thành trí huệ, bệnh tật"],["p","chuyển thành lành mạnh, nguy hiểm chuyển thành yên ổn, nếu là đàn bà sau khi chết sẽ chuyển thành đàn ông."],["p","9. Xa lìa các đường dữ (địa ngục, ngạ quỷ, súc"],["p","sanh), được sanh vào các cõi thiện (người, trời) tướng mạo đoan chánh, thông minh, xuất chúng phước lộc hơn người."],["p","10. Đủ năng lực để gây căn lành cho chúng sanh,"],["p","lấy tâm chúng sanh làm ruộng phước và sẽ thâu hoạch được nhiều quả tốt. Sanh vào chỗ nào cũng được thấy phật, nghe pháp, ba thứ trí huệ (văn, tư, tu) mở rộng, chứng được sáu thần thông (thiên nhãn, thiên nhĩ, tha tâm, thần túc, túc mạng, và lậu tận thông). Ấn tống kinh, tượng được nhiều công đức thù thắng như thế, cho nên, gặp khi chúc thọ, cầu an, sám hối, cầu siêu, nên hoan hỷ cố gắng ấn tống."]],"p":"Quyển Thứ Mười"}]};
